INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38443, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "激しい", "is_correct": true, "explanation": "連体形で「痛み」を修飾し、夜眠れなかった理由として文の意味に合う。"}, {"text": "激しくて", "is_correct": false, "explanation": "て形は「痛み」を直接修飾できず、「激しくて痛み」の形では文が成り立たない。"}, {"text": "激しければ", "is_correct": false, "explanation": "仮定形は節を作るため、名詞「痛み」の前には置けない。"}, {"text": "強さ", "is_correct": false, "explanation": "名詞の「強さ」は「痛み」を直接修飾できず、「強さ痛み」は不自然。"}], "explanations": {"激しい": "連体形で「痛み」を修飾し、夜眠れなかった理由として文の意味に合う。", "激しくて": "て形は「痛み」を直接修飾できず、「激しくて痛み」の形では文が成り立たない。", "激しければ": "仮定形は節を作るため、名詞「痛み」の前には置けない。", "強さ": "名詞の「強さ」は「痛み」を直接修飾できず、「強さ痛み」は不自然。"}, "sentence_index": 6, "correct_answer": "激しい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "激しい勢いで、ボールが壁に当たって跳ね返った。", "explanation": "ここは〈勢いが強い〉の意味。動きの力強さを言う別義で、程度の大きさとは違う。"}, {"text": "激しい水しぶきが上がって、服がぬれた。", "explanation": "ここも〈勢いが強い〉の意味。水の勢いを言う別義で、程度の大きさとは違う。"}, {"text": "激しい雷が落ちて、木が真っ二つに割れた。", "explanation": "ここも〈勢いが強い〉の意味。雷の力の強さを言う別義で、程度の大きさとは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38443, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "激しく試合で、選手たちは汗をかいた。", "corrected_sentence": "激しい試合で、選手たちは汗をかいた。", "error_description": "「試合」を修飾するには連体形の「激しい」が必要。副詞の「激しく」は名詞を修飾できない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "激しい", "is_correct": true, "explanation": "連体形で「言い争い」を修飾し、激しい争いになったという文の意味に合う。"}, {"text": "激しく", "is_correct": false, "explanation": "副詞形は名詞「言い争い」を直接修飾できず、ここでは形が合わない。"}, {"text": "激しくて", "is_correct": false, "explanation": "て形は名詞「言い争い」を直接修飾できず、「激しくて言い争い」は成り立たない。"}, {"text": "激しければ", "is_correct": false, "explanation": "仮定形は名詞「言い争い」の前には置けず、条件節にしかならない。"}], "correct_form": "激しい", "base_form": "激しい", "form_label": "連体形", "sentence_index": 1, "explanations": {"激しい": "連体形で「言い争い」を修飾し、激しい争いになったという文の意味に合う。", "激しく": "副詞形は名詞「言い争い」を直接修飾できず、ここでは形が合わない。", "激しくて": "て形は名詞「言い争い」を直接修飾できず、「激しくて言い争い」は成り立たない。", "激しければ": "仮定形は名詞「言い争い」の前には置けず、条件節にしかならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38443, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は激しさ怒りを抱えて、席を立った。", "corrected_sentence": "彼は激しい怒りを抱えて、席を立った。", "error_description": "名詞「激しさ」は「怒り」を直接修飾できない。連体形の「激しい」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "激しい", "is_correct": true, "explanation": "連体形で「怒り」を修飾し、激しい怒りを感じたという文の意味に合う。"}, {"text": "激しくなく", "is_correct": false, "explanation": "中止形で名詞「怒り」を直接修飾できず、「激しくなく怒り」は成り立たない。"}, {"text": "激しかろう", "is_correct": false, "explanation": "推量形は「激しかろう怒り」と名詞を修飾できず、文の形に合わない。"}, {"text": "激しければ", "is_correct": false, "explanation": "仮定形は名詞「怒り」の前には置けず、条件節にしかならない。"}], "correct_form": "激しい", "base_form": "激しい", "form_label": "連体形", "sentence_index": 7, "explanations": {"激しい": "連体形で「怒り」を修飾し、激しい怒りを感じたという文の意味に合う。", "激しくなく": "中止形で名詞「怒り」を直接修飾できず、「激しくなく怒り」は成り立たない。", "激しかろう": "推量形は「激しかろう怒り」と名詞を修飾できず、文の形に合わない。", "激しければ": "仮定形は名詞「怒り」の前には置けず、条件節にしかならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38444, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「鍵は何ですか」で、主題を示す「は」が入ります。"}, {"text": "を", "is_correct": false, "explanation": "「鍵を何ですか」では述語「何ですか」と合いません。"}, {"text": "に", "is_correct": false, "explanation": "「鍵に何ですか」では述語につながりません。"}, {"text": "へ", "is_correct": false, "explanation": "「鍵へ何ですか」は方向を表す助詞が合わず、文になりません。"}], "correct_answer": "は", "explanations": {"は": "「鍵は何ですか」で、主題を示す「は」が入ります。", "を": "「鍵を何ですか」では述語「何ですか」と合いません。", "に": "「鍵に何ですか」では述語につながりません。", "へ": "「鍵へ何ですか」は方向を表す助詞が合わず、文になりません。"}, "error_tags": {"を": "object_marker", "に": "target_marker", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38444, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「鍵になる」で、結果を表す「に」が入ります。"}, {"text": "を", "is_correct": false, "explanation": "「鍵をなる」では「なる」と結びつきません。"}, {"text": "が", "is_correct": false, "explanation": "「鍵がなる」では「なる」の使い方が合いません。"}, {"text": "へ", "is_correct": false, "explanation": "「鍵へなる」は方向を表す助詞が合わず、文になりません。"}], "correct_answer": "に", "explanations": {"に": "「鍵になる」で、結果を表す「に」が入ります。", "を": "「鍵をなる」では「なる」と結びつきません。", "が": "「鍵がなる」では「なる」の使い方が合いません。", "へ": "「鍵へなる」は方向を表す助詞が合わず、文になりません。"}, "error_tags": {"を": "object_marker", "が": "subject_marker", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38444, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "問題を解いたり、目標を達成するために、とても大切なものやこと。", "primary_collocate": null, "pronunciation": "かぎ", "ipa": "kaɡi", "syllable_count": 2, "sentences": [{"text": "上達の鍵は練習です。", "target_word": "鍵", "complexity_tier": "T2", "furigana": "上達[じょうたつ]の鍵[かぎ]は練習[れんしゅう]です。", "sentence_source": "generated"}, {"text": "答えを見つける鍵は何ですか。", "target_word": "鍵", "complexity_tier": "T2", "furigana": "答[こた]えを見[み]つける鍵[かぎ]は何[なん]ですか。", "sentence_source": "generated"}, {"text": "この言葉が謎を解く鍵です。", "target_word": "鍵", "complexity_tier": "T2", "furigana": "この言葉[ことば]が謎[なぞ]を解[と]く鍵[かぎ]です。", "sentence_source": "generated"}, {"text": "協力することが、成功の鍵だ。", "target_word": "鍵", "complexity_tier": "T2", "furigana": "協力[きょうりょく]することが、成功[せいこう]の鍵[かぎ]だ。", "sentence_source": "generated"}, {"text": "まず、問題を解く鍵を探してみよう。", "target_word": "鍵", "complexity_tier": "T3", "furigana": "まず、問題[もんだい]を解[と]く鍵[かぎ]を探[さが]してみよう。", "sentence_source": "generated"}, {"text": "大切な鍵は、最初の一歩を踏み出すことだ。", "target_word": "鍵", "complexity_tier": "T3", "furigana": "大切[たいせつ]な鍵[かぎ]は、最初[さいしょ]の一歩[いっぽ]を踏[ふ]み出[だ]すことだ。", "sentence_source": "generated"}, {"text": "睡眠が元気の鍵だと医者に言われた。", "target_word": "鍵", "complexity_tier": "T4", "furigana": "睡眠[すいみん]が元気[げんき]の鍵[かぎ]だと医者[いしゃ]に言[い]われた。", "sentence_source": "generated"}, {"text": "この手紙が事件を解決する鍵になるかもしれない。", "target_word": "鍵", "complexity_tier": "T4", "furigana": "この手紙[てがみ]が事件[じけん]を解決[かいけつ]する鍵[かぎ]になるかもしれない。", "sentence_source": "generated"}, {"text": "彼の発言には、会社を変える鍵が隠されている。", "target_word": "鍵", "complexity_tier": "T4", "furigana": "彼[かれ]の発言[はつげん]には、会社[かいしゃ]を変[か]える鍵[かぎ]が隠[かく]されている。", "sentence_source": "generated"}, {"text": "目標を達成するための鍵は、計画ではなく、続ける力にある。", "target_word": "鍵", "complexity_tier": "T5", "furigana": "目標[もくひょう]を達成[たっせい]するための鍵[かぎ]は、計画[けいかく]ではなく、続[つづ]ける力[ちから]にある。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 問題解決や目標達成に大切なこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db2de57a-18ef-4f7c-9bcb-060880e83e4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38444, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鍵", "is_correct": true, "explanation": "見出し語の「かぎ」そのものです。"}, {"text": "貝", "is_correct": false, "explanation": "「かい」で、最後の一音だけが違う別の語です。"}, {"text": "垣", "is_correct": false, "explanation": "「かき」で、ぎ→きの清濁だけが違う別の語です。"}, {"text": "影", "is_correct": false, "explanation": "「かげ」で、ぎ→げの一音だけが違う別の語です。"}], "explanations": {"鍵": "見出し語の「かぎ」そのものです。", "貝": "「かい」で、最後の一音だけが違う別の語です。", "垣": "「かき」で、ぎ→きの清濁だけが違う別の語です。", "影": "「かげ」で、ぎ→げの一音だけが違う別の語です。"}, "sentence_index": null, "correct_answer": "鍵"}, "level_3": {"options": [{"text": "鍵", "is_correct": true, "explanation": "「上達の鍵は練習です」で、上達に大切なことが練習だという意味になります。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。「上達の天気は練習です」は意味が通りません。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが意味が合わない。「上達の季節は練習です」は意味が通りません。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが意味が合わない。「上達の値段は練習です」は意味が通りません。"}], "explanations": {"鍵": "「上達の鍵は練習です」で、上達に大切なことが練習だという意味になります。", "天気": "形は合うが意味が合わない。「上達の天気は練習です」は意味が通りません。", "季節": "形は合うが意味が合わない。「上達の季節は練習です」は意味が通りません。", "値段": "形は合うが意味が合わない。「上達の値段は練習です」は意味が通りません。"}, "sentence_index": 0, "correct_answer": "鍵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鍵を飲んで、元気になりました。", "explanation": "「鍵」は飲むものではなく、「飲む」の対象として使えません。"}, {"text": "この鍵は、三時にバスで着きます。", "explanation": "「鍵」は大切なことを表す語で、バスで到着する人のようには使えません。"}, {"text": "私は昨日の鍵を歌いました。", "explanation": "「鍵」は歌う対象ではなく、「歌う」とは結びつきません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38444, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "鍵", "is_correct": true, "explanation": "見出し語の「かぎ」そのものです。"}, {"text": "牡蠣", "is_correct": false, "explanation": "「かき」で、ぎ→きの清濁だけが違う別の語です。"}, {"text": "籠", "is_correct": false, "explanation": "「かご」で、最後の一音だけが違う別の語です。"}, {"text": "嗅ぐ", "is_correct": false, "explanation": "「かぐ」で、ぎ→ぐの一音だけが違う別の語です。"}, {"text": "髪", "is_correct": false, "explanation": "「かみ」で、最後の一音だけが違う別の語です。"}], "explanations": {"鍵": "見出し語の「かぎ」そのものです。", "牡蠣": "「かき」で、ぎ→きの清濁だけが違う別の語です。", "籠": "「かご」で、最後の一音だけが違う別の語です。", "嗅ぐ": "「かぐ」で、ぎ→ぐの一音だけが違う別の語です。", "髪": "「かみ」で、最後の一音だけが違う別の語です。"}, "sentence_index": null, "correct_answer": "鍵"}, "level_3": {"options": [{"text": "鍵", "is_correct": true, "explanation": "「元気の鍵」で、元気に欠かせない大切なことを表します。"}, {"text": "色", "is_correct": false, "explanation": "形は合うが意味が合わない。睡眠と元気の関係を説明できません。"}, {"text": "場所", "is_correct": false, "explanation": "形は合うが意味が合わない。「元気の場所」は意味が通りません。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが意味が合わない。睡眠が元気の季節だとは言えません。"}], "explanations": {"鍵": "「元気の鍵」で、元気に欠かせない大切なことを表します。", "色": "形は合うが意味が合わない。睡眠と元気の関係を説明できません。", "場所": "形は合うが意味が合わない。「元気の場所」は意味が通りません。", "季節": "形は合うが意味が合わない。睡眠が元気の季節だとは言えません。"}, "sentence_index": 6, "correct_answer": "鍵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "計画の鍵は、毎朝七時に起きて走ります。", "explanation": "「鍵」は抽象的な要素で、起きて走る主体にはなれません。"}, {"text": "彼女は鍵という友達と、公園で遊んだ。", "explanation": "「鍵」を人の名前のように使っていますが、そのような意味はありません。"}, {"text": "勝利の鍵を、昼ごはんに食べた。", "explanation": "「鍵」は食べるものではなく、「食べる」の対象として使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_val