INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38445, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を成し遂げるために、必要不可欠であり、重要な役割を果たすもの。", "primary_collocate": null, "pronunciation": "かぎ", "ipa": "kaɡi", "syllable_count": 2, "sentences": [{"text": "成功の鍵は、商品の魅力を伝える写真の工夫と、ターゲット層に届けるマーケティングです。", "target_word": "鍵", "complexity_tier": "T6", "furigana": "成功[せいこう]の鍵[かぎ]は、商品[しょうひん]の魅力[みりょく]を伝[つた]える写真[しゃしん]の工夫[くふう]と、ターゲット層[そう]に届[とど]けるマーケティングです。", "sentence_source": "mined"}, {"text": "成功の鍵は努力です。", "target_word": "鍵", "complexity_tier": "T2", "furigana": "成功[せいこう]の鍵[かぎ]は努力[どりょく]です。", "sentence_source": "generated"}, {"text": "健康の鍵は、毎日の食事にある。", "target_word": "鍵", "complexity_tier": "T2", "furigana": "健康[けんこう]の鍵[かぎ]は、毎日[まいにち]の食事[しょくじ]にある。", "sentence_source": "generated"}, {"text": "この問題を解く鍵が見つかりました。", "target_word": "鍵", "complexity_tier": "T3", "furigana": "この問題[もんだい]を解[と]く鍵[かぎ]が見[み]つかりました。", "sentence_source": "generated"}, {"text": "チームワークが勝利の鍵だと思う。", "target_word": "鍵", "complexity_tier": "T3", "furigana": "チームワークが勝利[しょうり]の鍵[かぎ]だと思[おも]う。", "sentence_source": "generated"}, {"text": "話し合いが、解決の鍵になった。", "target_word": "鍵", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いが、解決[かいけつ]の鍵[かぎ]になった。", "sentence_source": "generated"}, {"text": "彼女の笑顔が、店の人気の鍵を握っている。", "target_word": "鍵", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の笑顔[えがお]が、店[みせ]の人気[にんき]の鍵[かぎ]を握[にぎ]っている。", "sentence_source": "generated"}, {"text": "英語が上達する鍵は、毎日少しずつ続けることだ。", "target_word": "鍵", "complexity_tier": "T4", "furigana": "英語[えいご]が上達[じょうたつ]する鍵[かぎ]は、毎日[まいにち]少[すこ]しずつ続[つづ]けることだ。", "sentence_source": "generated"}, {"text": "この研究が、病気を治す鍵となるかもしれない。", "target_word": "鍵", "complexity_tier": "T4", "furigana": "この研究[けんきゅう]が、病気[びょうき]を治[なお]す鍵[かぎ]となるかもしれない。", "sentence_source": "generated"}, {"text": "時間をどう使うかが、これからの成功の鍵を握ると言われている。", "target_word": "鍵", "complexity_tier": "T5", "furigana": "時間[じかん]をどう使[つか]うかが、これからの成功[せいこう]の鍵[かぎ]を握[にぎ]ると言[い]われている。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 物事の成否を決める重要な要素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db2de57a-18ef-4f7c-9bcb-060880e83e4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38445, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鍵", "is_correct": true, "explanation": "見出し語の「かぎ」そのものです。"}, {"text": "柿", "is_correct": false, "explanation": "「かき」で、ぎ→きの清濁だけが違う別の語です。"}, {"text": "影", "is_correct": false, "explanation": "「かげ」で、最後の一音だけが違う別の語です。"}, {"text": "家具", "is_correct": false, "explanation": "「かぐ」で、ぎ→ぐの一音だけが違う別の語です。"}, {"text": "傘", "is_correct": false, "explanation": "「かさ」で、最後の一音だけが違う別の語です。"}], "explanations": {"鍵": "見出し語の「かぎ」そのものです。", "柿": "「かき」で、ぎ→きの清濁だけが違う別の語です。", "影": "「かげ」で、最後の一音だけが違う別の語です。", "家具": "「かぐ」で、ぎ→ぐの一音だけが違う別の語です。", "傘": "「かさ」で、最後の一音だけが違う別の語です。"}, "sentence_index": null, "correct_answer": "鍵"}, "level_3": {"options": [{"text": "鍵", "is_correct": true, "explanation": "「成功の鍵」で、成功に欠かせない重要な要素を表し、文意に合います。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。成功と天気は結びつきません。"}, {"text": "大きさ", "is_correct": false, "explanation": "形は合うが意味が合わない。「成功の大きさ」では文の流れが通りません。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが意味が合わない。成功の季節がマーケティングだとは言えません。"}], "explanations": {"鍵": "「成功の鍵」で、成功に欠かせない重要な要素を表し、文意に合います。", "天気": "形は合うが意味が合わない。成功と天気は結びつきません。", "大きさ": "形は合うが意味が合わない。「成功の大きさ」では文の流れが通りません。", "季節": "形は合うが意味が合わない。成功の季節がマーケティングだとは言えません。"}, "sentence_index": 0, "correct_answer": "鍵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "成功の鍵は、とても甘くておいしいです。", "explanation": "「鍵」は抽象的な要素なので、味を表す「甘い」「おいしい」とは使えません。"}, {"text": "鍵を食べて、問題が解決しました。", "explanation": "「鍵」は食べるものではなく、「食べる」という動作の対象にできません。"}, {"text": "昨日の鍵は、雨が降って寒かったです。", "explanation": "「鍵」を天気や日の意味で使っていますが、そのような意味はありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38445, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "鍵", "is_correct": true, "explanation": "見出し語の「かぎ」そのものです。"}, {"text": "紙", "is_correct": false, "explanation": "「かみ」で、最後の一音だけが違う別の語です。"}, {"text": "金", "is_correct": false, "explanation": "「かね」で、最後の一音だけが違う別の語です。"}, {"text": "壁", "is_correct": false, "explanation": "「かべ」で、最後の一音だけが違う別の語です。"}, {"text": "亀", "is_correct": false, "explanation": "「かめ」で、最後の一音だけが違う別の語です。"}], "explanations": {"鍵": "見出し語の「かぎ」そのものです。", "紙": "「かみ」で、最後の一音だけが違う別の語です。", "金": "「かね」で、最後の一音だけが違う別の語です。", "壁": "「かべ」で、最後の一音だけが違う別の語です。", "亀": "「かめ」で、最後の一音だけが違う別の語です。"}, "sentence_index": null, "correct_answer": "鍵"}, "level_3": {"options": [{"text": "鍵", "is_correct": true, "explanation": "「人気の鍵を握る」で、人気を左右する重要な要素を表します。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。「人気の天気を握る」は意味が通りません。"}, {"text": "重さ", "is_correct": false, "explanation": "形は合うが意味が合わない。笑顔と店の人気の関係を表せません。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが意味が合わない。「人気の季節を握る」は不自然です。"}], "explanations": {"鍵": "「人気の鍵を握る」で、人気を左右する重要な要素を表します。", "天気": "形は合うが意味が合わない。「人気の天気を握る」は意味が通りません。", "重さ": "形は合うが意味が合わない。笑顔と店の人気の関係を表せません。", "季節": "形は合うが意味が合わない。「人気の季節を握る」は不自然です。"}, "sentence_index": 6, "correct_answer": "鍵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は人気の鍵を歩いて、駅まで行った。", "explanation": "「鍵」は場所ではないので、歩く対象にはなりません。"}, {"text": "成功の鍵は、冷蔵庫で冷やすとおいしいです。", "explanation": "抽象的な「鍵」を食べ物のように扱っており、意味が合いません。"}, {"text": "彼の鍵は五十歳で、とても元気な人だ。", "explanation": "「鍵」を人や年齢を表す語として使っていますが、そのような意味はありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLU