INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38446, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「わからない」は対象を「が」で示すので、状況が「わからず」の主語になり「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「わからない」は「が」を取るので、「を」は使えない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示し、わかる対象の主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示し、わかるものを示せない。"}], "correct_answer": "が", "explanations": {"が": "「わからない」は対象を「が」で示すので、状況が「わからず」の主語になり「が」が正しい。", "を": "「わからない」は「が」を取るので、「を」は使えない。", "に": "「に」は方向や相手を示し、わかる対象の主語にはならない。", "で": "「で」は場所や手段を示し、わかるものを示せない。"}, "error_tags": {"を": "目的語", "に": "相手・方向", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38446, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いま、どんなようすなのかをあらわす言葉。", "primary_collocate": null, "pronunciation": "じょうきょう", "ipa": "dʑoːkʲoː", "syllable_count": 4, "sentences": [{"text": "工事の状況を、毎日メールで知らせてください。", "target_word": "状況", "complexity_tier": "T3", "furigana": "工事[こうじ]の状況[じょうきょう]を、毎日[まいにち]メールで知[し]らせてください。", "sentence_source": "generated"}, {"text": "川の水が増えている状況なので、近づかないでください。", "target_word": "状況", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]が増[ふ]えている状況[じょうきょう]なので、近[ちか]づかないでください。", "sentence_source": "generated"}, {"text": "今の状況を簡単に説明すると、まだ準備中です。", "target_word": "状況", "complexity_tier": "T3", "furigana": "今[いま]の状況[じょうきょう]を簡単[かんたん]に説明[せつめい]すると、まだ準備中[じゅんびちゅう]です。", "sentence_source": "generated"}, {"text": "電話で道路の状況を聞いてから、家を出ました。", "target_word": "状況", "complexity_tier": "T3", "furigana": "電話[でんわ]で道路[どうろ]の状況[じょうきょう]を聞[き]いてから、家[いえ]を出[で]ました。", "sentence_source": "generated"}, {"text": "部屋の中の状況を見て、母は何があったのか気づいた。", "target_word": "状況", "complexity_tier": "T3", "furigana": "部屋[へや]の中[なか]の状況[じょうきょう]を見[み]て、母[はは]は何[なに]があったのか気[き]づいた。", "sentence_source": "generated"}, {"text": "宿題の状況はどうですか。", "target_word": "状況", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]の状況[じょうきょう]はどうですか。", "sentence_source": "generated"}, {"text": "先生は、クラスの状況を見ながら授業を進めている。", "target_word": "状況", "complexity_tier": "T3", "furigana": "先生[せんせい]は、クラスの状況[じょうきょう]を見[み]ながら授業[じゅぎょう]を進[すす]めている。", "sentence_source": "generated"}, {"text": "大雨の中、山の状況がよくわからず、登山は中止になった。", "target_word": "状況", "complexity_tier": "T3", "furigana": "大雨[おおあめ]の中[なか]、山[やま]の状況[じょうきょう]がよくわからず、登山[とざん]は中止[ちゅうし]になった。", "sentence_source": "generated"}, {"text": "店の状況が厳しく、来月で閉めることになった。", "target_word": "状況", "complexity_tier": "T3", "furigana": "店[みせ]の状況[じょうきょう]が厳[きび]しく、来月[らいげつ]で閉[し]めることになった。", "sentence_source": "generated"}, {"text": "友だちに今の状況を聞いたら、もう家に着いたそうだ。", "target_word": "状況", "complexity_tier": "T3", "furigana": "友[とも]だちに今[いま]の状況[じょうきょう]を聞[き]いたら、もう家[いえ]に着[つ]いたそうだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "状況", "label": "基本形"}], "register": "中立", "sense_fingerprint": "いまの進み具合やようすを知らせるときに使う言葉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33db208a-4ad2-4e69-a0ee-68818b305fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38446, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性格", "is_correct": false, "explanation": "性格は人の性質を指す語で、工事の進み具合には合わない。"}, {"text": "好み", "is_correct": false, "explanation": "好みは人の好き嫌いを指す語で、工事には使わない。"}, {"text": "状況", "is_correct": true, "explanation": "工事の現在の進み具合を表すので〈状況〉が入る。"}, {"text": "人気", "is_correct": false, "explanation": "人気は世間の評判を指す語で、工事の進み具合を知らせる文には合わない。"}], "explanations": {"性格": "性格は人の性質を指す語で、工事の進み具合には合わない。", "好み": "好みは人の好き嫌いを指す語で、工事には使わない。", "状況": "工事の現在の進み具合を表すので〈状況〉が入る。", "人気": "人気は世間の評判を指す語で、工事の進み具合を知らせる文には合わない。"}, "sentence_index": 0, "correct_answer": "状況"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このピアノは状況が美しく、深みのある響きがする。", "explanation": "ここは〈音色〉の意味。楽器の響きの質には〈音色〉を使い、〈状況〉は当てはまらない。"}, {"text": "この店は状況が近く、歩いてすぐ着く。", "explanation": "ここは〈距離〉の意味。道のりの近さには〈距離〉を使い、〈状況〉は当てはまらない。"}, {"text": "窓を開けると、焼きたてパンの状況が流れてきた。", "explanation": "ここは〈匂い〉の意味。香りには〈匂い〉を使い、〈状況〉は香りを表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38446, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "予算", "is_correct": false, "explanation": "予算は使えるお金の計画で、クラスのようすを見る文には合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は人が生きてきた年数で、授業の進め方を見る文には合わない。"}, {"text": "状況", "is_correct": true, "explanation": "クラスの現在のようすを見るので〈状況〉が入る。"}, {"text": "体重", "is_correct": false, "explanation": "体重は人の重さを表す語で、クラスのようすを見る文には合わない。"}], "explanations": {"予算": "予算は使えるお金の計画で、クラスのようすを見る文には合わない。", "年齢": "年齢は人が生きてきた年数で、授業の進め方を見る文には合わない。", "状況": "クラスの現在のようすを見るので〈状況〉が入る。", "体重": "体重は人の重さを表す語で、クラスのようすを見る文には合わない。"}, "sentence_index": 6, "correct_answer": "状況"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は状況が見事で、料理がみるみる仕上がっていく。", "explanation": "ここは〈手際〉の意味。作業の速さややり方には〈手際〉を使い、〈状況〉とは言わない。"}, {"text": "この自転車は状況が快適で、長い距離も疲れにくい。", "explanation": "ここは〈乗り心地〉の意味。乗ったときの快適さには〈乗り心地〉を使い、〈状況〉は当てはまらない。"}, {"text": "階段の下から、だれかの状況が近づいてきた。", "explanation": "ここは〈足音〉の意味。歩く音には〈足音〉を使い、〈状況〉は音を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38446, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来週の作業の状況に、毎朝チームに報告してください。", "corrected_sentence": "来週の作業の状況を、毎朝チームに報告してください。", "error_description": "「状況」の後の助詞が「に」になっている。「報告する」は報告の内容に「を」を取るので、正しくは「状況を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38446, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日の試合の状況が、監督が選手に詳しく説明した。", "corrected_sentence": "昨日の試合の状況を、監督が選手に詳しく説明した。", "error_description": "「状況」の後の助詞が「が」になっている。「説明する」は説明の内容に「を」を取るので、正しくは「状況を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38447, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、状況は確認される対象なので主語にはならず、ここには入らない。"}, {"text": "を", "is_correct": true, "explanation": "「確認する」は確認の対象を「を」で示すので、ここに入る。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や方向を示すので、「状況に確認する」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、状況を目的語にできず「状況で確認する」は不自然。"}], "correct_answer": "を", "explanations": {"が": "「が」は主語を示すが、状況は確認される対象なので主語にはならず、ここには入らない。", "を": "「確認する」は確認の対象を「を」で示すので、ここに入る。", "に": "「に」は相手や方向を示すので、「状況に確認する」は成り立たない。", "で": "「で」は場所や手段を示すので、状況を目的語にできず「状況で確認する」は不自然。"}, "error_tags": {"が": "主語", "に": "相手・方向", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38447, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「報告された」は受け身で、報告される内容の状況が主語になるので「が」が必要。"}, {"text": "を", "is_correct": false, "explanation": "「報告された」は受け身なので、目的語を「を」で示す形は取れない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や方向を示すが、状況は報告の相手ではないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示し、報告される内容の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「報告された」は受け身で、報告される内容の状況が主語になるので「が」が必要。", "を": "「報告された」は受け身なので、目的語を「を」で示す形は取れない。", "に": "「に」は相手や方向を示すが、状況は報告の相手ではないので合わない。", "で": "「で」は場所や手段を示し、報告される内容の主語にはならない。"}, "error_tags": {"を": "目的語", "に": "相手・方向", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38447, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある時点での、周りのようすや状態のこと。", "primary_collocate": null, "pronunciation": "じょうきょう", "ipa": "dʑoːkʲoː", "syllable_count": 4, "sentences": [{"text": "これは、作物の生育状況を細かく把握し、必要な水や肥料を的確に与える仕組みです。", "target_word": "状況", "complexity_tier": "T4", "furigana": "これは、作物[さくもつ]の生育[せいいく]状況[じょうきょう]を細[こま]かく把握[はあく]し、必要[ひつよう]な水[みず]や肥料[ひりょう]を的確[てきかく]に与[あた]える仕組[しく]みです。", "sentence_source": "mined"}, {"text": "事故の現場に着いた警察は、まず周りの状況を確認した。", "target_word": "状況", "complexity_tier": "T3", "furigana": "事故[じこ]の現場[げんば]に着[つ]いた警察[けいさつ]は、まず周[まわ]りの状況[じょうきょう]を確認[かくにん]した。", "sentence_source": "generated"}, {"text": "今の状況では、予定どおりに工事を進めるのは難しい。", "target_word": "状況", "complexity_tier": "T3", "furigana": "今[いま]の状況[じょうきょう]では、予定[よてい]どおりに工事[こうじ]を進[すす]めるのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "電車が止まったため、駅は混乱した状況になっていた。", "target_word": "状況", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が止[と]まったため、駅[えき]は混乱[こんらん]した状況[じょうきょう]になっていた。", "sentence_source": "generated"}, {"text": "彼は忙しい状況でも、いつも笑顔で話してくれる。", "target_word": "状況", "complexity_tier": "T3", "furigana": "彼[かれ]は忙[いそが]しい状況[じょうきょう]でも、いつも笑顔[えがお]で話[はな]してくれる。", "sentence_source": "generated"}, {"text": "医者は患者に、病気の状況をわかりやすく説明した。", "target_word": "状況", "complexity_tier": "T3", "furigana": "医者[いしゃ]は患者[かんじゃ]に、病気[びょうき]の状況[じょうきょう]をわかりやすく説明[せつめい]した。", "sentence_source": "generated"}, {"text": "天気が悪い状況が続いているので、試合は延期になった。", "target_word": "状況", "complexity_tier": "T3", "furigana": "天気[てんき]が悪[わる]い状況[じょうきょう]が続[つづ]いているので、試合[しあい]は延期[えんき]になった。", "sentence_source": "generated"}, {"text": "会議では、各店の売り上げの状況が報告された。", "target_word": "状況", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、各店[かくてん]の売[う]り上[あ]げの状況[じょうきょう]が報告[ほうこく]された。", "sentence_source": "generated"}, {"text": "状況が変わったら、すぐに連絡してください。", "target_word": "状況", "complexity_tier": "T3", "furigana": "状況[じょうきょう]が変[か]わったら、すぐに連絡[れんらく]してください。", "sentence_source": "generated"}, {"text": "災害の状況を伝えるニュースが、一日中流れていた。", "target_word": "状況", "complexity_tier": "T3", "furigana": "災害[さいがい]の状況[じょうきょう]を伝[つた]えるニュースが、一日中[いちにちじゅう]流[なが]れていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "状況", "label": "基本形"}], "register": "中立", "sense_fingerprint": "ある時点での周囲のようすや物事の状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 5 words above tier T1 (max 2): 作物 (Zipf 3.65), 生育 (Zipf 3.38), 細かく (Zipf 3.88), 肥料 (Zipf 3.65), 的確 (Zipf 3.76)']::text[], '33db208a-4ad2-4e69-a0ee-68818b305fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38447, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "期限", "is_correct": false, "explanation": "期限は締め切りの日時を指す語で、作物の生育を把握する文には合わない。"}, {"text": "状況", "is_correct": true, "explanation": "ここでは作物の生育の状態を指すので〈状況〉が入る。"}, {"text": "方針", "is_correct": false, "explanation": "方針は取り組みの考え方を指す語で、作物の生育の様子には合わない。"}, {"text": "金額", "is_correct": false, "explanation": "金額は値段の合計を指す語で、作物の生育を把握する文には合わない。"}], "explanations": {"期限": "期限は締め切りの日時を指す語で、作物の生育を把握する文には合わない。", "状況": "ここでは作物の生育の状態を指すので〈状況〉が入る。", "方針": "方針は取り組みの考え方を指す語で、作物の生育の様子には合わない。", "金額": "金額は値段の合計を指す語で、作物の生育を把握する文には合わない。"}, "sentence_index": 0, "correct_answer": "状況"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は状況が優しく、誰からも慕われている。", "explanation": "ここは〈人柄〉の意味。人の性格や人間性には〈人柄〉を使い、〈状況〉は周囲の事情を指すので合わない。"}, {"text": "この部屋は状況が広く、家具をたくさん置ける。", "explanation": "ここは〈広さ〉の意味。空間の大きさには〈広さ〉を使い、〈状況〉は当てはまらない。"}, {"text": "この布は状況がよく、何度洗ってもへたらない。", "explanation": "ここは〈品質〉の意味。布の出来ばえには〈品質〉を使い、〈状況〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38447, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "予算", "is_correct": false, "explanation": "予算は使えるお金の計画を指す語で、天気の様子には合わない。"}, {"text": "状況", "is_correct": true, "explanation": "「天気が悪い」状態が続くという意味で〈状況〉が入る。"}, {"text": "順番", "is_correct": false, "explanation": "順番は並ぶ順序を指す語で、天気が続くことには合わない。"}, {"text": "料金", "is_correct": false, "explanation": "料金は支払うお金を指す語で、天気の様子には合わない。"}], "explanations": {"予算": "予算は使えるお金の計画を指す語で、天気の様子には合わない。", "状況": "「天気が悪い」状態が続くという意味で〈状況〉が入る。", "順番": "順番は並ぶ順序を指す語で、天気が続くことには合わない。", "料金": "料金は支払うお金を指す語で、天気の様子には合わない。"}, "sentence_index": 6, "correct_answer": "状況"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓から見える状況がとても美しく、思わず写真を撮った。", "explanation": "ここは〈景色〉の意味。眺めの美しさには〈景色〉を使い、〈状況〉は当てはまらない。"}, {"text": "このスープは状況が濃く、少し塩辛い。", "explanation": "ここは〈味〉の意味。料理の味の濃さには〈味〉を使い、〈状況〉とは言わない。"}, {"text": "このパンは外がカリッとして、中の状況がもちもちしている。", "explanation": "ここは〈食感〉の意味。口に入れたときの歯ごたえには〈食感〉を使い、〈状況〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38447, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "事故の現場の状況で確認した警察は、救急車を呼んだ。", "corrected_sentence": "事故の現場の状況を確認した警察は、救急車を呼んだ。", "error_description": "「状況」の後の助詞が「で」になっている。「確認する」は目的語に「を」を取るので、正しくは「状況を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38447, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "台風の進路と被害の状況が、テレビで繰り返し伝えていた。", "corrected_sentence": "台風の進路と被害の状況を、テレビで繰り返し伝えていた。", "error_description": "「状況」の後の助詞が「が」になっている。「伝える」は目的語に「を」を取るので、正しくは「状況を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
