INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38450, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "何かがたくさんあること。", "primary_collocate": null, "pronunciation": "とむ", "ipa": "tomɯ", "syllable_count": 2, "sentences": [{"text": "この本は、変化に富んだ物語で、最後まで飽きなかった。", "target_word": "富んだ", "complexity_tier": "T3", "furigana": "この本[ほん]は、変化[へんか]に富[と]んだ物語[ものがたり]で、最後[さいご]まで飽[あ]きなかった。", "sentence_source": "generated"}, {"text": "彼は経験に富んでいるので、頼りになる。", "target_word": "富んでいる", "complexity_tier": "T3", "furigana": "彼[かれ]は経験[けいけん]に富[と]んでいるので、頼[たよ]りになる。", "sentence_source": "generated"}, {"text": "納豆はたんぱく質に富む食べ物です。", "target_word": "富む", "complexity_tier": "T3", "furigana": "納豆[なっとう]はたんぱく質[しつ]に富[と]む食[た]べ物[もの]です。", "sentence_source": "generated"}, {"text": "先生の話はユーモアに富んでいて、とても楽しかった。", "target_word": "富んで", "complexity_tier": "T3", "furigana": "先生[せんせい]の話[はなし]はユーモアに富[と]んでいて、とても楽[たの]しかった。", "sentence_source": "generated"}, {"text": "山の多いこの国は、自然に富んだ美しい土地だ。", "target_word": "富んだ", "complexity_tier": "T3", "furigana": "山[やま]の多[おお]いこの国[くに]は、自然[しぜん]に富[と]んだ美[うつく]しい土地[とち]だ。", "sentence_source": "generated"}, {"text": "想像力に富む子どもは、お話を作るのが上手だ。", "target_word": "富む", "complexity_tier": "T3", "furigana": "想像力[そうぞうりょく]に富[と]む子[こ]どもは、お話[はなし]を作[つく]るのが上手[じょうず]だ。", "sentence_source": "generated"}, {"text": "彼女は才能に富んでいるが、努力も忘れない。", "target_word": "富んでいる", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は才能[さいのう]に富[と]んでいるが、努力[どりょく]も忘[わす]れない。", "sentence_source": "generated"}, {"text": "栄養に富んだ食事を続けたら、体の調子がよくなった。", "target_word": "富んだ", "complexity_tier": "T3", "furigana": "栄養[えいよう]に富[と]んだ食事[しょくじ]を続[つづ]けたら、体[からだ]の調子[ちょうし]がよくなった。", "sentence_source": "generated"}, {"text": "この地方は温泉に富み、観光客が多い。", "target_word": "富み", "complexity_tier": "T3", "furigana": "この地方[ちほう]は温泉[おんせん]に富[と]み、観光客[かんこうきゃく]が多[おお]い。", "sentence_source": "generated"}, {"text": "この町は見どころに富んでいて、一日中飽きない。", "target_word": "富んでいて", "complexity_tier": "T3", "furigana": "この町[まち]は見[み]どころに富[と]んでいて、一日中[いちにちじゅう]飽[あ]きない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "富む", "label": "終止形"}, {"form": "富まない", "label": "未然形＋ない"}, {"form": "富み", "label": "連用形"}, {"form": "富んで", "label": "て形"}, {"form": "富んだ", "label": "た形"}, {"form": "富めば", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "ある物事が豊富にある（〜に富む）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8ffa2-2cf2-4e73-9794-a9ba40cd3a71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38450, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "富んだ", "is_correct": true, "explanation": "「変化に富んだ物語」の〈富んだ〉で、変化が多いことを表し、〈に富む〉の連体形として入る。"}, {"text": "悩んだ", "is_correct": false, "explanation": "「変化に悩んだ物語」では意味が通らず、〈悩む〉は〈に〉の後に合わないので合わない。"}, {"text": "眠った", "is_correct": false, "explanation": "「変化に眠った物語」では意味が通らないので合わない。"}, {"text": "走った", "is_correct": false, "explanation": "「変化に走った物語」では意味が通らないので合わない。"}], "explanations": {"富んだ": "「変化に富んだ物語」の〈富んだ〉で、変化が多いことを表し、〈に富む〉の連体形として入る。", "悩んだ": "「変化に悩んだ物語」では意味が通らず、〈悩む〉は〈に〉の後に合わないので合わない。", "眠った": "「変化に眠った物語」では意味が通らないので合わない。", "走った": "「変化に走った物語」では意味が通らないので合わない。"}, "sentence_index": 0, "correct_answer": "富んだ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "あの国は石油の輸出で富んで、国民の暮らしが豊かになった。", "explanation": "ここは〈財産が多くなる〉の語義。〈たくさんある〉の語義とは別なので合わない。"}, {"text": "祖父は商売で富んで、大きな家に住んでいる。", "explanation": "ここは〈財産が多くなる〉の語義。〈たくさんある〉の語義とは別なので合わない。"}, {"text": "彼は若いころ貧しかったが、事業に成功して富んだ。", "explanation": "ここは〈財産が多くなる〉の語義。〈たくさんある〉の語義とは別なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38450, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "富んでいる", "is_correct": true, "explanation": "「才能に富んでいるが」の〈富んでいる〉で、才能が豊かにあることを表すので入る。"}, {"text": "争っている", "is_correct": false, "explanation": "「才能に争っている」では意味が通らず、〈争う〉は〈に〉を取らないので合わない。"}, {"text": "怯えている", "is_correct": false, "explanation": "「才能に怯えている」では意味が通らないので合わない。"}, {"text": "眺めている", "is_correct": false, "explanation": "「才能に眺めている」では意味が通らないので合わない。"}], "explanations": {"富んでいる": "「才能に富んでいるが」の〈富んでいる〉で、才能が豊かにあることを表すので入る。", "争っている": "「才能に争っている」では意味が通らず、〈争う〉は〈に〉を取らないので合わない。", "怯えている": "「才能に怯えている」では意味が通らないので合わない。", "眺めている": "「才能に眺めている」では意味が通らないので合わない。"}, "sentence_index": 6, "correct_answer": "富んでいる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は事業に成功して富んだと、皆が噂している。", "explanation": "ここは〈財産が多くなる〉の語義。〈たくさんある〉の語義とは別なので合わない。"}, {"text": "この港町は貿易で富んで、大きな商館が並んでいた。", "explanation": "ここは〈財産が多くなる〉の語義。〈たくさんある〉の語義とは別なので合わない。"}, {"text": "若いころは貧しかったが、今では富んで暮らしに困らない。", "explanation": "ここは〈財産が多くなる〉の語義。〈たくさんある〉の語義とは別なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38450, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この料理は香辛料を富んでいて、とても香りがよい。", "corrected_sentence": "この料理は香辛料に富んでいて、とても香りがよい。", "error_description": "「富む」の前につく助詞の誤り。〈〜に富む〉は〈に〉を取る。〈を〉は目的語につく助詞なので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "富んでいる", "is_correct": true, "explanation": "「経験に富んでいるので」の〈富んでいる〉で、現在の状態を表すので入る。"}, {"text": "富んだ", "is_correct": false, "explanation": "連体形で、文の述語にはならず〈富んだので〉では文が成り立たないので合わない。"}, {"text": "富まない", "is_correct": false, "explanation": "否定形で、〈富んでいる〉の肯定の状態と逆になるので合わない。"}, {"text": "富めば", "is_correct": false, "explanation": "仮定形で、〈ので〉で続く理由の文には合わない。"}], "correct_form": "富んでいる", "base_form": "富む", "form_label": "〜ている形", "sentence_index": 1, "explanations": {"富んでいる": "「経験に富んでいるので」の〈富んでいる〉で、現在の状態を表すので入る。", "富んだ": "連体形で、文の述語にはならず〈富んだので〉では文が成り立たないので合わない。", "富まない": "否定形で、〈富んでいる〉の肯定の状態と逆になるので合わない。", "富めば": "仮定形で、〈ので〉で続く理由の文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38450, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この森は動物の種類を富んでいる。", "corrected_sentence": "この森は動物の種類に富んでいる。", "error_description": "「富んでいる」の前につく助詞の誤り。〈〜に富む〉は〈に〉を取る。〈を〉は目的語につく助詞なので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "富んだ", "is_correct": true, "explanation": "「栄養に富んだ食事」の〈富んだ〉で、後ろの名詞を修飾する連体形なので入る。"}, {"text": "富んで", "is_correct": false, "explanation": "て形で、後ろの名詞を修飾できず、〈食事〉を説明する形には合わない。"}, {"text": "富み", "is_correct": false, "explanation": "連用形で、後ろの名詞を直接修飾できないので合わない。"}, {"text": "富もう", "is_correct": false, "explanation": "意志の形で、〈食事〉を説明する文には合わない。"}], "correct_form": "富んだ", "base_form": "富む", "form_label": "た形（連体形）", "sentence_index": 7, "explanations": {"富んだ": "「栄養に富んだ食事」の〈富んだ〉で、後ろの名詞を修飾する連体形なので入る。", "富んで": "て形で、後ろの名詞を修飾できず、〈食事〉を説明する形には合わない。", "富み": "連用形で、後ろの名詞を直接修飾できないので合わない。", "富もう": "意志の形で、〈食事〉を説明する文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d49c0cf-5edc-4d8e-aec2-22ce975072f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38452, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「よく分かる」の対象を示す「が」で、地形がよく分かるという意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「分かる」は目的語に「を」を取らないので、「地形をよく分かる」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "方向や相手を示す「に」は、この文の「分かる」の対象にならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐだけで、述語「分かります」の前には置けない。"}], "correct_answer": "が", "explanations": {"が": "「よく分かる」の対象を示す「が」で、地形がよく分かるという意味になる。", "を": "「分かる」は目的語に「を」を取らないので、「地形をよく分かる」は成り立たない。", "に": "方向や相手を示す「に」は、この文の「分かる」の対象にならない。", "の": "「の」は名詞どうしをつなぐだけで、述語「分かります」の前には置けない。"}, "error_tags": {"を": "目的語", "に": "方向・相手", "の": "名詞修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
