INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38452, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面の形のことです。山や谷、平らな場所など、土地の様子を表します。", "primary_collocate": null, "pronunciation": "ちけい", "ipa": "t͡ɕikeː", "syllable_count": 3, "sentences": [{"text": "この山は地形が複雑なので、道に迷いやすいです。", "target_word": "地形", "complexity_tier": "T3", "furigana": "この山[やま]は地形[ちけい]が複雑[ふくざつ]なので、道[みち]に迷[まよ]いやすいです。", "sentence_source": "generated"}, {"text": "地図を見れば、その町の地形がよく分かります。", "target_word": "地形", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]れば、その町[まち]の地形[ちけい]がよく分[わ]かります。", "sentence_source": "generated"}, {"text": "地形に合わせて、家を建てる場所を決めました。", "target_word": "地形", "complexity_tier": "T3", "furigana": "地形[ちけい]に合[あ]わせて、家[いえ]を建[た]てる場所[ばしょ]を決[き]めました。", "sentence_source": "generated"}, {"text": "日本は地形が険しいので、広い畑が少ないです。", "target_word": "地形", "complexity_tier": "T3", "furigana": "日本[にほん]は地形[ちけい]が険[けわ]しいので、広[ひろ]い畑[はたけ]が少[すく]ないです。", "sentence_source": "generated"}, {"text": "川の流れは地形によって変わります。", "target_word": "地形", "complexity_tier": "T3", "furigana": "川[かわ]の流[なが]れは地形[ちけい]によって変[か]わります。", "sentence_source": "generated"}, {"text": "私たちは古い地図で昔の地形を調べました。", "target_word": "地形", "complexity_tier": "T3", "furigana": "私[わたし]たちは古[ふる]い地図[ちず]で昔[むかし]の地形[ちけい]を調[しら]べました。", "sentence_source": "generated"}, {"text": "地形を知らない人は、山を歩くと危ないです。", "target_word": "地形", "complexity_tier": "T3", "furigana": "地形[ちけい]を知[し]らない人[ひと]は、山[やま]を歩[ある]くと危[あぶ]ないです。", "sentence_source": "generated"}, {"text": "この辺りは地形が平らで、自転車で走りやすいです。", "target_word": "地形", "complexity_tier": "T3", "furigana": "この辺[あた]りは地形[ちけい]が平[たい]らで、自転車[じてんしゃ]で走[はし]りやすいです。", "sentence_source": "generated"}, {"text": "雨が降ると、地形のせいで水が低い所に集まります。", "target_word": "地形", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ると、地形[ちけい]のせいで水[みず]が低[ひく]い所[ところ]に集[あつ]まります。", "sentence_source": "generated"}, {"text": "大きな工事で、この町の地形が変わってしまいました。", "target_word": "地形", "complexity_tier": "T3", "furigana": "大[おお]きな工事[こうじ]で、この町[まち]の地形[ちけい]が変[か]わってしまいました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地形", "label": "基本形"}], "register": "普通", "sense_fingerprint": "山や谷や平地など、土地の形や様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '847a26b2-bc5c-40d3-bf20-a353d66c43ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38452, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地形", "is_correct": true, "explanation": "土地の表面の形を表し、複雑な地形だから道に迷いやすいという文脈に合う。"}, {"text": "気温", "is_correct": false, "explanation": "温度を表す語で、道の複雑さを言う文には合わず、道に迷う理由にならない。"}, {"text": "面積", "is_correct": false, "explanation": "広さを表す語で、形の複雑さを言うには合わない。"}, {"text": "標高", "is_correct": false, "explanation": "高さを表す語で、複雑さの説明にはならない。"}], "explanations": {"地形": "土地の表面の形を表し、複雑な地形だから道に迷いやすいという文脈に合う。", "気温": "温度を表す語で、道の複雑さを言う文には合わず、道に迷う理由にならない。", "面積": "広さを表す語で、形の複雑さを言うには合わない。", "標高": "高さを表す語で、複雑さの説明にはならない。"}, "sentence_index": 0, "correct_answer": "地形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅前は地形が便利で、お店を出すのに向いている。", "explanation": "ここは〈立地〉の意味。地形は土地の形のことで、場所の便利さは言わない。"}, {"text": "この山は地形が硬いので、岩を掘るのが大変だ。", "explanation": "ここは〈地質〉の意味。地形は表面の形や起伏を指し、岩の硬さは言わない。"}, {"text": "地形が太陽の周りを一年かけて回っている。", "explanation": "ここは〈地球〉の意味。地形は土地の表面の形で、天体の動きには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38452, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地形", "is_correct": true, "explanation": "土地の形を表し、地形を知らない人は山で危ないという文脈に合う。"}, {"text": "湿度", "is_correct": false, "explanation": "空気の湿り気を表す語で、山を歩く危険とは結びつかない。"}, {"text": "海流", "is_correct": false, "explanation": "海の流れを表す語で、山を歩く文脈には合わない。"}, {"text": "人口", "is_correct": false, "explanation": "人の数を表す語で、山を歩く危険の説明にはならない。"}], "explanations": {"地形": "土地の形を表し、地形を知らない人は山で危ないという文脈に合う。", "湿度": "空気の湿り気を表す語で、山を歩く危険とは結びつかない。", "海流": "海の流れを表す語で、山を歩く文脈には合わない。", "人口": "人の数を表す語で、山を歩く危険の説明にはならない。"}, "sentence_index": 6, "correct_answer": "地形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの地形の人たちは、みんな親切で話しやすい。", "explanation": "ここは〈地域〉の意味。地形は土地の表面の形で、そこに住む人を指すことはない。"}, {"text": "夏は地形が蒸し暑くて、毎日汗が止まらない。", "explanation": "ここは〈気候〉の意味。地形は表面の形で、気温や湿度の状態は指さない。"}, {"text": "父は地形の出身で、方言がとても面白い。", "explanation": "ここは〈地元〉の意味。地形は土地の形で、人の出身地を表すことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38452, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この谷は地形で険しいので、登るのが大変だ。", "corrected_sentence": "この谷は地形が険しいので、登るのが大変だ。", "error_description": "「険しい」の主語は「地形が」と「が」で示す。「地形で」は誤りで、主語を表す「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38452, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大きな地震で、山の地形を変わってしまいました。", "corrected_sentence": "大きな地震で、山の地形が変わってしまいました。", "error_description": "自動詞「変わる」の主語は「が」で示す。「地形を」は誤りで、「地形が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38454, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38454, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「砂漠でも」の「で」。雨が少ない砂漠でも、という譲歩の形として正しい。"}, {"text": "が", "is_correct": false, "explanation": "「砂漠が〜も」とは続かず、譲歩の「でも」の形にならない。"}, {"text": "は", "is_correct": false, "explanation": "「砂漠はも」と助詞が重なって不自然で、「でも」の形にならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を結ぶ助詞で、「砂漠のも」は「でも」の形にならない。"}], "correct_answer": "で", "explanations": {"で": "「砂漠でも」の「で」。雨が少ない砂漠でも、という譲歩の形として正しい。", "が": "「砂漠が〜も」とは続かず、譲歩の「でも」の形にならない。", "は": "「砂漠はも」と助詞が重なって不自然で、「でも」の形にならない。", "の": "「の」は名詞を結ぶ助詞で、「砂漠のも」は「でも」の形にならない。"}, "error_tags": {"が": "主語", "は": "主題", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38454, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "砂がたくさんあって、水がほとんどない場所。", "primary_collocate": null, "pronunciation": "さばく", "ipa": "sabaku", "syllable_count": 3, "sentences": [{"text": "砂漠には水がほとんどないので、木が育ちません。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "砂漠[さばく]には水[みず]がほとんどないので、木[き]が育[そだ]ちません。", "sentence_source": "generated"}, {"text": "昼の砂漠はとても暑いですが、夜は寒くなります。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "昼[ひる]の砂漠[さばく]はとても暑[あつ]いですが、夜[よる]は寒[さむ]くなります。", "sentence_source": "generated"}, {"text": "ラクダに乗って、砂漠を旅行しました。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "ラクダに乗[の]って、砂漠[さばく]を旅行[りょこう]しました。", "sentence_source": "generated"}, {"text": "砂漠で道に迷ったら、水がなくて大変です。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "砂漠[さばく]で道[みち]に迷[まよ]ったら、水[みず]がなくて大変[たいへん]です。", "sentence_source": "generated"}, {"text": "私はいつか、砂漠で星を見てみたいです。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "私[わたし]はいつか、砂漠[さばく]で星[ほし]を見[み]てみたいです。", "sentence_source": "generated"}, {"text": "砂漠の真ん中に、小さな泉がありました。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "砂漠[さばく]の真[ま]ん中[なか]に、小[ちい]さな泉[いずみ]がありました。", "sentence_source": "generated"}, {"text": "風が強い日は、砂漠全体が砂煙に包まれることもある。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]い日[ひ]は、砂漠[さばく]全体[ぜんたい]が砂煙[すなけむり]に包[つつ]まれることもある。", "sentence_source": "generated"}, {"text": "雨が少ない砂漠でも、生きている動物がいます。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "雨[あめ]が少[すく]ない砂漠[さばく]でも、生[い]きている動物[どうぶつ]がいます。", "sentence_source": "generated"}, {"text": "砂漠を歩くときは、帽子と水を忘れないでください。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "砂漠[さばく]を歩[ある]くときは、帽子[ぼうし]と水[みず]を忘[わす]れないでください。", "sentence_source": "generated"}, {"text": "砂漠の町では、夏の昼間は外に出る人が少ないです。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "砂漠[さばく]の町[まち]では、夏[なつ]の昼間[ひるま]は外[そと]に出[で]る人[ひと]が少[すく]ないです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "砂漠", "label": "基本形"}], "register": "普通", "sense_fingerprint": "砂が多く水がほとんどない暑くて乾いた場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: 砂煙 (Zipf 1.51)']::text[], '847a26b2-bc5c-40d3-bf20-a353d66c43ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38454, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "砂漠", "is_correct": true, "explanation": "水がほとんどなく木が育たない場所を指す「砂漠」が入り、文の内容に合う。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽は場所ではないので、「〜には水がほとんどない」と続かず文が成り立たない。"}, {"text": "感情", "is_correct": false, "explanation": "感情は場所ではないので、水や木の生育を説明する文の主語にならない。"}, {"text": "時間", "is_correct": false, "explanation": "時間は場所ではないので、水がほとんどないという説明の主語にならない。"}], "explanations": {"砂漠": "水がほとんどなく木が育たない場所を指す「砂漠」が入り、文の内容に合う。", "音楽": "音楽は場所ではないので、「〜には水がほとんどない」と続かず文が成り立たない。", "感情": "感情は場所ではないので、水や木の生育を説明する文の主語にならない。", "時間": "時間は場所ではないので、水がほとんどないという説明の主語にならない。"}, "sentence_index": 0, "correct_answer": "砂漠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私たちは砂漠を一つ見つけて、その頂上で写真を撮った。", "explanation": "ここは〈砂丘〉の意味。砂丘は一つずつ数えて頂上に登れる地形だが、砂漠は広い地域の名で、一つ見つけて登る対象ではない。"}, {"text": "ホームセンターで砂漠を一袋買い、庭の植木鉢に入れた。", "explanation": "ここは〈砂〉の意味。砂は袋に入れて買い、植木鉢に入れる材料だが、砂漠は乾燥した広い地域を指すので、袋で買えるものとしては使わない。"}, {"text": "夏休み、砂漠で波の音を聞きながら昼寝をした。", "explanation": "ここは〈砂浜〉の意味。波の音は海辺の情景で、水がほとんどない砂漠の描写には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38454, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "砂漠", "is_correct": true, "explanation": "広い砂の地域を指す「砂漠」が入り、風の日に全体が砂煙に包まれるという文に合う。"}, {"text": "数学", "is_correct": false, "explanation": "数学は教科の名前で、砂煙に包まれるものではないので文が成り立たない。"}, {"text": "合図", "is_correct": false, "explanation": "合図は信号や知らせで、砂煙に包まれるものではないので文の意味が通らない。"}, {"text": "名前", "is_correct": false, "explanation": "名前は砂煙に包まれるものではなく、「全体が」の主語にならない。"}], "explanations": {"砂漠": "広い砂の地域を指す「砂漠」が入り、風の日に全体が砂煙に包まれるという文に合う。", "数学": "数学は教科の名前で、砂煙に包まれるものではないので文が成り立たない。", "合図": "合図は信号や知らせで、砂煙に包まれるものではないので文の意味が通らない。", "名前": "名前は砂煙に包まれるものではなく、「全体が」の主語にならない。"}, "sentence_index": 6, "correct_answer": "砂漠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昼の砂漠で、人々が場所取りをして、浮き輪を膨らませていた。", "explanation": "ここは〈海水浴場〉の意味。場所取りや浮き輪は海水浴の情景で、水がほとんどない砂漠の描写には合わない。"}, {"text": "砂漠の沖で、漁師が網を引いて大漁を喜んでいた。", "explanation": "ここは〈海〉の意味。沖や網、大漁は海の漁の情景で、水がほとんどない砂漠の描写には合わない。"}, {"text": "砂漠には水がよどみ、水草が一面に茂っていた。", "explanation": "ここは〈湿地〉の意味。水がよどんで水草が茂るのは湿地の特徴で、降水量が少ない砂漠には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38454, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明日、砂漠で行く予定です。", "corrected_sentence": "明日、砂漠へ行く予定です。", "error_description": "「行く」は移動先を「へ」で示す。「砂漠で」は場所での動作を表す「で」なので誤りで、正しくは「砂漠へ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38454, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "砂漠が歩く人は、水を多く持つべきだ。", "corrected_sentence": "砂漠を歩く人は、水を多く持つべきだ。", "error_description": "「歩く」の対象は「を」で示す。「砂漠が」は主語になってしまうので誤りで、正しくは「砂漠を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38455, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「砂漠が広がっている」の「が」。広大な砂漠が主語として広がる、という意味で正しい。"}, {"text": "を", "is_correct": false, "explanation": "「広がる」は自動詞なので「を」は取らず、「砂漠を広がっている」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「砂漠と広がっている」は名詞を並べるだけで主語にならず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「砂漠の広がっている」は名詞修飾のまま終わり、文として成立しない。"}], "correct_answer": "が", "explanations": {"が": "「砂漠が広がっている」の「が」。広大な砂漠が主語として広がる、という意味で正しい。", "を": "「広がる」は自動詞なので「を」は取らず、「砂漠を広がっている」は成り立たない。", "と": "「砂漠と広がっている」は名詞を並べるだけで主語にならず、文が成り立たない。", "の": "「砂漠の広がっている」は名詞修飾のまま終わり、文として成立しない。"}, "error_tags": {"を": "対象", "と": "並列", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
