INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38455, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "降水量が非常に少なく、砂や岩石で覆われた乾燥した地域。", "primary_collocate": null, "pronunciation": "さばく", "ipa": "sabaku", "syllable_count": 3, "sentences": [{"text": "砂漠は年間の降水量が非常に少ない地域だ。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "砂漠[さばく]は年間[ねんかん]の降水量[こうすいりょう]が非常[ひじょう]に少[すく]ない地域[ちいき]だ。", "sentence_source": "generated"}, {"text": "アフリカ北部には、広大な砂漠が広がっている。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "アフリカ北部[ほくぶ]には、広大[こうだい]な砂漠[さばく]が広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "砂漠では昼夜の気温差が大きく、岩が割れることもある。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "砂漠[さばく]では昼夜[ちゅうや]の気温差[きおんさ]が大[おお]きく、岩[いわ]が割[わ]れることもある。", "sentence_source": "generated"}, {"text": "過度な放牧が原因で、草原が砂漠に変わる地域がある。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "過度[かど]な放牧[ほうぼく]が原因[げんいん]で、草原[そうげん]が砂漠[さばく]に変[か]わる地域[ちいき]がある。", "sentence_source": "generated"}, {"text": "砂漠に生きる植物は、根を深く伸ばして水を集める。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "砂漠[さばく]に生[い]きる植物[しょくぶつ]は、根[ね]を深[ふか]く伸[の]ばして水[みず]を集[あつ]める。", "sentence_source": "generated"}, {"text": "砂漠は砂ばかりではなく、岩石に覆われた場所も多い。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "砂漠[さばく]は砂[すな]ばかりではなく、岩石[がんせき]に覆[おお]われた場所[ばしょ]も多[おお]い。", "sentence_source": "generated"}, {"text": "研究者は砂漠の地下から古代の水を発見した。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は砂漠[さばく]の地下[ちか]から古代[こだい]の水[みず]を発見[はっけん]した。", "sentence_source": "generated"}, {"text": "砂漠が広がるのを防ぐため、各国が植林を進めている。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "砂漠[さばく]が広[ひろ]がるのを防[ふせ]ぐため、各国[かっこく]が植林[しょくりん]を進[すす]めている。", "sentence_source": "generated"}, {"text": "冷たい海流が近くを流れる海岸には、砂漠ができやすい。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "冷[つめ]たい海流[かいりゅう]が近[ちか]くを流[なが]れる海岸[かいがん]には、砂漠[さばく]ができやすい。", "sentence_source": "generated"}, {"text": "砂漠の遺跡は、乾燥した空気のおかげで保存状態がよい。", "target_word": "砂漠", "complexity_tier": "T3", "furigana": "砂漠[さばく]の遺跡[いせき]は、乾燥[かんそう]した空気[くうき]のおかげで保存状態[ほぞんじょうたい]がよい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "砂漠", "label": "基本形"}], "register": "普通", "sense_fingerprint": "降水量が極めて少なく砂や岩石に覆われた乾燥地域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '847a26b2-bc5c-40d3-bf20-a353d66c43ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38455, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "砂漠", "is_correct": true, "explanation": "降水量が非常に少ない広い乾燥地域を指す「砂漠」が入り、文の説明に合う。"}, {"text": "教室", "is_correct": false, "explanation": "教室は学ぶ場所で、降水量が非常に少ない地域という説明には当てはまらない。"}, {"text": "病院", "is_correct": false, "explanation": "病院は治療の場所で、年間の降水量を論じる文の主語にはならない。"}, {"text": "図書館", "is_correct": false, "explanation": "図書館は本を置く施設で、降水量の少ない地域という説明とは合わない。"}], "explanations": {"砂漠": "降水量が非常に少ない広い乾燥地域を指す「砂漠」が入り、文の説明に合う。", "教室": "教室は学ぶ場所で、降水量が非常に少ない地域という説明には当てはまらない。", "病院": "病院は治療の場所で、年間の降水量を論じる文の主語にはならない。", "図書館": "図書館は本を置く施設で、降水量の少ない地域という説明とは合わない。"}, "sentence_index": 0, "correct_answer": "砂漠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "砂漠は高さ三十メートルの盛り上がりで、風が吹くたびに形を変える。", "explanation": "ここは〈砂丘〉の意味。風で形を変える砂の盛り上がりは砂丘のことで、広い地域を指す砂漠とは別物。"}, {"text": "砂漠を一つ拾って、お土産の箱に入れた。", "explanation": "ここは〈石〉の意味。石は拾って箱に入れられるが、砂漠は広い地域を指す語で、拾って持ち帰れるものには使わない。"}, {"text": "砂漠には波が寄せて、貝殻が一面に散らばっている。", "explanation": "ここは〈海岸〉の意味。波が寄せて貝殻が散らばるのは海辺の描写で、雨の少ない砂漠の説明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38455, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "砂漠", "is_correct": true, "explanation": "乾燥した砂の地域を指す「砂漠」が入り、地下から古代の水を発見した場所として成り立つ。"}, {"text": "机", "is_correct": false, "explanation": "机は家具で、地下から古代の水を発見するという場所にはならない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は空にあるもので、地下から水を発見する場所としては合わない。"}, {"text": "靴", "is_correct": false, "explanation": "靴は履く物で、地下から古代の水を発見する場所としては合わない。"}], "explanations": {"砂漠": "乾燥した砂の地域を指す「砂漠」が入り、地下から古代の水を発見した場所として成り立つ。", "机": "机は家具で、地下から古代の水を発見するという場所にはならない。", "雲": "雲は空にあるもので、地下から水を発見する場所としては合わない。", "靴": "靴は履く物で、地下から古代の水を発見する場所としては合わない。"}, "sentence_index": 6, "correct_answer": "砂漠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "砂漠の雨林で、猿が木の枝を渡っている。", "explanation": "ここは〈熱帯雨林〉の意味。木の枝を猿が渡る情景は雨の多い熱帯のもので、降水量が極めて少ない砂漠の説明には合わない。"}, {"text": "砂漠の田んぼに水が張られ、カエルの鳴き声がにぎやかだった。", "explanation": "ここは〈田んぼ〉の意味。水を張った田やカエルの声は水の豊かな農地の情景で、降水量が極めて少ない砂漠には合わない。"}, {"text": "砂漠の山頂で、スキー客が雪の斜面を滑り降りていた。", "explanation": "ここは〈雪山〉の意味。雪の斜面を滑るのは雪山の情景で、砂や岩石に覆われた乾燥地帯の砂漠には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38455, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "砂漠を植物が育ちにくい。", "corrected_sentence": "砂漠で植物が育ちにくい。", "error_description": "「育つ」は場所を「で」で示す。「砂漠を」は動作の対象になってしまうので誤りで、正しくは「砂漠で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38455, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "砂漠が遺跡は、乾燥した空気のおかげで保存されている。", "corrected_sentence": "砂漠の遺跡は、乾燥した空気のおかげで保存されている。", "error_description": "「砂漠」と「遺跡」は所属を表す関係なので「の」でつなぐ。「砂漠が」は主語を示してしまうので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38456, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「近くに住む」の「に」。住む場所を示して文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「住む」は場所を「を」で取らず、「近くを住んで」は不自然。"}, {"text": "が", "is_correct": false, "explanation": "「近くが住んで」は近くを主語にしてしまい、住む主体が成り立たないので不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は人を相手にするときに使うので、場所を示す「近く」には合わない。"}], "correct_answer": "に", "explanations": {"に": "「近くに住む」の「に」。住む場所を示して文が成り立つ。", "を": "「住む」は場所を「を」で取らず、「近くを住んで」は不自然。", "が": "「近くが住んで」は近くを主語にしてしまい、住む主体が成り立たないので不自然。", "と": "「と」は人を相手にするときに使うので、場所を示す「近く」には合わない。"}, "error_tags": {"を": "対象", "が": "主語", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38456, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「日本に住む」の「に」。住む場所を示して文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「日本が住む」は日本を主語にしてしまい、場所として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「日本より住む」と続かず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「日本の住む」は名詞修飾にならず、文が続かない。"}], "correct_answer": "に", "explanations": {"に": "「日本に住む」の「に」。住む場所を示して文が成り立つ。", "が": "「日本が住む」は日本を主語にしてしまい、場所として成り立たない。", "より": "比較の「より」は「日本より住む」と続かず、文が成り立たない。", "の": "「日本の住む」は名詞修飾にならず、文が続かない。"}, "error_tags": {"が": "主語", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38456, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人がどこかに生活すること。", "primary_collocate": null, "pronunciation": "すむ", "ipa": "sɯmɯ", "syllable_count": 2, "sentences": [{"text": "私は東京に住んでいます。", "target_word": "住んで", "complexity_tier": "T3", "furigana": "私[わたし]は東京[とうきょう]に住[す]んでいます。", "sentence_source": "generated"}, {"text": "祖父母は海の近くに住んでいます。", "target_word": "住んで", "complexity_tier": "T3", "furigana": "祖父母[そふぼ]は海[うみ]の近[ちか]くに住[す]んでいます。", "sentence_source": "generated"}, {"text": "大学を出たら、大きい町に住みたいです。", "target_word": "住み", "complexity_tier": "T3", "furigana": "大学[だいがく]を出[で]たら、大[おお]きい町[まち]に住[す]みたいです。", "sentence_source": "generated"}, {"text": "この家には、四人の家族が住んでいます。", "target_word": "住んで", "complexity_tier": "T3", "furigana": "この家[いえ]には、四人[よにん]の家族[かぞく]が住[す]んでいます。", "sentence_source": "generated"}, {"text": "昔、この島には漁師の家族が住んでいました。", "target_word": "住んで", "complexity_tier": "T3", "furigana": "昔[むかし]、この島[しま]には漁師[りょうし]の家族[かぞく]が住[す]んでいました。", "sentence_source": "generated"}, {"text": "以前住んでいた町は、静かでよかったです。", "target_word": "住んで", "complexity_tier": "T3", "furigana": "以前[いぜん]住[す]んでいた町[まち]は、静[しず]かでよかったです。", "sentence_source": "generated"}, {"text": "田中さんはどこに住んでいますか。", "target_word": "住んで", "complexity_tier": "T3", "furigana": "田中[たなか]さんはどこに住[す]んでいますか。", "sentence_source": "generated"}, {"text": "日本に住むなら、日本語を勉強したほうがいいです。", "target_word": "住む", "complexity_tier": "T3", "furigana": "日本[にほん]に住[す]むなら、日本語[にほんご]を勉強[べんきょう]したほうがいいです。", "sentence_source": "generated"}, {"text": "兄は結婚してから、駅の近くに住むようになりました。", "target_word": "住む", "complexity_tier": "T3", "furigana": "兄[あに]は結婚[けっこん]してから、駅[えき]の近[ちか]くに住[す]むようになりました。", "sentence_source": "generated"}, {"text": "友達の隣に住んでいるので、毎朝いっしょに学校へ行きます。", "target_word": "住んで", "complexity_tier": "T3", "furigana": "友達[ともだち]の隣[となり]に住[す]んでいるので、毎朝[まいあさ]いっしょに学校[がっこう]へ行[い]きます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "住む", "label": "辞書形"}, {"form": "住み", "label": "連用形"}, {"form": "住んで", "label": "て形"}, {"form": "住んだ", "label": "た形"}, {"form": "住まない", "label": "ない形"}, {"form": "住める", "label": "可能形"}], "register": "丁寧", "sense_fingerprint": "人がある場所で毎日の生活をしている", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '847a26b2-bc5c-40d3-bf20-a353d66c43ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38456, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "住んで", "is_correct": true, "explanation": "生活の拠点として住むことを表す「住んで」が入り、「東京に住んでいます」と自然につながる。"}, {"text": "食べて", "is_correct": false, "explanation": "「東京に食べています」では意味が通らず、住んでいる場所を表せない。"}, {"text": "泳いで", "is_correct": false, "explanation": "泳ぐは水中での動作で、「東京に泳いでいます」とは言えない。"}, {"text": "歌って", "is_correct": false, "explanation": "歌うは声を出す動作で、東京に生活の拠点を持つことを表さない。"}], "explanations": {"住んで": "生活の拠点として住むことを表す「住んで」が入り、「東京に住んでいます」と自然につながる。", "食べて": "「東京に食べています」では意味が通らず、住んでいる場所を表せない。", "泳いで": "泳ぐは水中での動作で、「東京に泳いでいます」とは言えない。", "歌って": "歌うは声を出す動作で、東京に生活の拠点を持つことを表さない。"}, "sentence_index": 0, "correct_answer": "住んで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は駅前に住んでいて、夜十時まで開いています。", "explanation": "ここは〈ある〉の意味。住むは人や動物が生活する意味で、店のような建物には使わない。"}, {"text": "出張で三日間、この旅館に住んでいました。", "explanation": "ここは〈滞在〉の意味。短い宿泊は滞在と言い、生活の拠点を持つ住むとは言わない。"}, {"text": "この畑には、二十年前から稲が住んでいます。", "explanation": "ここは〈育つ〉の意味。住むは人や動物の生活に使い、植物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38456, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "住んで", "is_correct": true, "explanation": "「どこに住んでいますか」で住所をたずねる表現として、住んでが入る。"}, {"text": "笑って", "is_correct": false, "explanation": "「どこに笑っていますか」では場所をたずねる文として成り立たない。"}, {"text": "泣いて", "is_correct": false, "explanation": "「どこに泣いていますか」は意味が通らず、住所をたずねる文に合わない。"}, {"text": "洗って", "is_correct": false, "explanation": "「どこに洗っていますか」は場所をたずねる文として不自然で、住所の意味にならない。"}], "explanations": {"住んで": "「どこに住んでいますか」で住所をたずねる表現として、住んでが入る。", "笑って": "「どこに笑っていますか」では場所をたずねる文として成り立たない。", "泣いて": "「どこに泣いていますか」は意味が通らず、住所をたずねる文に合わない。", "洗って": "「どこに洗っていますか」は場所をたずねる文として不自然で、住所の意味にならない。"}, "sentence_index": 6, "correct_answer": "住んで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、学校に住んで、友達と一緒に授業を受けます。", "explanation": "ここは〈通う〉の意味。学校は毎日通う場所で、生活の拠点として住むとは言わない。"}, {"text": "毎朝、この電車に住んで、会社へ行きます。", "explanation": "ここは〈乗る〉の意味。電車は乗り物で、住む場所ではないので合わない。"}, {"text": "毎週末、友達の家に住んで、おしゃべりを楽しみました。", "explanation": "ここは〈訪ねる〉の意味。週末ごとに遊びに行くのは訪ねるで、生活の拠点として住むとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38456, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は大阪を住んでいます。", "corrected_sentence": "祖母は大阪に住んでいます。", "error_description": "「住む」の場所には「に」を付ける。「大阪を」は動作の対象を示すので誤りで、正しくは「大阪に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "住んで", "is_correct": true, "explanation": "て形で「住んでいます」と継続を表し、文に合う。"}, {"text": "住んだ", "is_correct": false, "explanation": "た形は過去の完了を表し、「住んだいます」の形にならない。"}, {"text": "住もう", "is_correct": false, "explanation": "意志形の「住もう」は「住もういます」と続かず、文に合わない。"}, {"text": "住み", "is_correct": false, "explanation": "連用形の「住み」は「住みています」と続かず、文に合わない。"}], "correct_form": "住んで", "base_form": "住む", "form_label": "て形", "sentence_index": 1, "explanations": {"住んで": "て形で「住んでいます」と継続を表し、文に合う。", "住んだ": "た形は過去の完了を表し、「住んだいます」の形にならない。", "住もう": "意志形の「住もう」は「住もういます」と続かず、文に合わない。", "住み": "連用形の「住み」は「住みています」と続かず、文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38456, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は駅の近くを住んでいます。", "corrected_sentence": "兄は駅の近くに住んでいます。", "error_description": "「住む」の場所には「に」を付ける。「近くを」は動作の対象を示すので誤りで、正しくは「近くに」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "住む", "is_correct": true, "explanation": "辞書形の「住む」で、「日本に住むなら」と条件を表し文に合う。"}, {"text": "住ませ", "is_correct": false, "explanation": "使役の語幹で、「なら」と続かず条件の文として成り立たないので不正解。"}, {"text": "住め", "is_correct": false, "explanation": "命令形の「住め」は「住めなら」と続かず、条件の文として成り立たない。"}, {"text": "住まわせ", "is_correct": false, "explanation": "使役の語幹で、「なら」と続けても条件の文にならないので不正解。"}], "correct_form": "住む", "base_form": "住む", "form_label": "辞書形", "sentence_index": 7, "explanations": {"住む": "辞書形の「住む」で、「日本に住むなら」と条件を表し文に合う。", "住ませ": "使役の語幹で、「なら」と続かず条件の文として成り立たないので不正解。", "住め": "命令形の「住め」は「住めなら」と続かず、条件の文として成り立たない。", "住まわせ": "使役の語幹で、「なら」と続けても条件の文にならないので不正解。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38457, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「郊外に住み」の「に」。住む場所を示して文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「郊外を住み」は「を」が対象を示すことになり、住む場所を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、居住する場所を表す文には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手を示すので、「郊外と住み」では場所を表せない。"}], "correct_answer": "に", "explanations": {"に": "「郊外に住み」の「に」。住む場所を示して文が成り立つ。", "を": "「郊外を住み」は「を」が対象を示すことになり、住む場所を表せない。", "へ": "「へ」は方向を示すので、居住する場所を表す文には合わない。", "と": "「と」は相手を示すので、「郊外と住み」では場所を表せない。"}, "error_tags": {"を": "対象", "へ": "方向", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38457, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38457, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある場所を自分の生活の拠点として、そこにいること。", "primary_collocate": null, "pronunciation": "すむ", "ipa": "sɯmɯ", "syllable_count": 2, "sentences": [{"text": "仕事の都合で、三年間だけ大阪に住むことになった。", "target_word": "住む", "complexity_tier": "T3", "furigana": "仕事[しごと]の都合[つごう]で、三年間[さんねんかん]だけ大阪[おおさか]に住[す]むことになった。", "sentence_source": "generated"}, {"text": "彼は家賃が安い郊外に住み、電車で都心へ通っている。", "target_word": "住み", "complexity_tier": "T3", "furigana": "彼[かれ]は家賃[やちん]が安[やす]い郊外[こうがい]に住[す]み、電車[でんしゃ]で都心[としん]へ通[かよ]っている。", "sentence_source": "generated"}, {"text": "一度は外国に住んでみたいと思っている。", "target_word": "住んで", "complexity_tier": "T3", "furigana": "一度[いちど]は外国[がいこく]に住[す]んでみたいと思[おも]っている。", "sentence_source": "generated"}, {"text": "学生のころは、寮に住んでいたため食事の心配がなかった。", "target_word": "住んで", "complexity_tier": "T3", "furigana": "学生[がくせい]のころは、寮[りょう]に住[す]んでいたため食事[しょくじ]の心配[しんぱい]がなかった。", "sentence_source": "generated"}, {"text": "通勤が楽なので、会社の近くに住むことにした。", "target_word": "住む", "complexity_tier": "T3", "furigana": "通勤[つうきん]が楽[らく]なので、会社[かいしゃ]の近[ちか]くに住[す]むことにした。", "sentence_source": "generated"}, {"text": "彼女は両親と離れて、一人で住んでいる。", "target_word": "住んで", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は両親[りょうしん]と離[はな]れて、一人[ひとり]で住[す]んでいる。", "sentence_source": "generated"}, {"text": "長く住んだ町を離れるのは寂しい。", "target_word": "住んだ", "complexity_tier": "T3", "furigana": "長[なが]く住[す]んだ町[まち]を離[はな]れるのは寂[さび]しい。", "sentence_source": "generated"}, {"text": "家賃が高すぎて、この町には住めない。", "target_word": "住め", "complexity_tier": "T3", "furigana": "家賃[やちん]が高[たか]すぎて、この町[まち]には住[す]めない。", "sentence_source": "generated"}, {"text": "都会に住む人の多くは、庭のない家で暮らしている。", "target_word": "住む", "complexity_tier": "T3", "furigana": "都会[とかい]に住[す]む人[ひと]の多[おお]くは、庭[にわ]のない家[いえ]で暮[く]らしている。", "sentence_source": "generated"}, {"text": "結婚したら、妻の実家の近くに住むつもりだ。", "target_word": "住む", "complexity_tier": "T3", "furigana": "結婚[けっこん]したら、妻[つま]の実家[じっか]の近[ちか]くに住[す]むつもりだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "住む", "label": "辞書形"}, {"form": "住み", "label": "連用形"}, {"form": "住んで", "label": "て形"}, {"form": "住んだ", "label": "た形"}, {"form": "住まない", "label": "ない形"}, {"form": "住める", "label": "可能形"}], "register": "普通", "sense_fingerprint": "ある場所を自分の生活の拠点にして居続ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '847a26b2-bc5c-40d3-bf20-a353d66c43ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38457, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "住む", "is_correct": true, "explanation": "生活の拠点とする意味の「住む」が入り、「大阪に住むことになった」と自然につながる。"}, {"text": "食べる", "is_correct": false, "explanation": "「大阪に食べることになった」では意味が通らず、住む場所の話にならない。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "泳ぐは水中での動作で、「大阪に泳ぐことになった」とは言えない。"}, {"text": "歌う", "is_correct": false, "explanation": "歌うは声を出す動作で、大阪での生活の拠点を表さない。"}], "explanations": {"住む": "生活の拠点とする意味の「住む」が入り、「大阪に住むことになった」と自然につながる。", "食べる": "「大阪に食べることになった」では意味が通らず、住む場所の話にならない。", "泳ぐ": "泳ぐは水中での動作で、「大阪に泳ぐことになった」とは言えない。", "歌う": "歌うは声を出す動作で、大阪での生活の拠点を表さない。"}, "sentence_index": 0, "correct_answer": "住む"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この倉庫には、二十年前から古い機械が住んでいる。", "explanation": "ここは〈ある〉の意味。住むは人や動物の生活に使い、機械や物には言わない。"}, {"text": "週末は、遊園地に住んで一日中乗り物に乗った。", "explanation": "ここは〈遊ぶ〉の意味。遊園地は遊びに行く場所で、生活の拠点として住むとは言わない。"}, {"text": "毎週、祖父母の家に住んで、昼ご飯を一緒に食べる。", "explanation": "ここは〈訪ねる〉の意味。食事のために毎週通うのは訪ねるで、生活の拠点として住むとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38457, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "住んだ", "is_correct": true, "explanation": "過去に生活した町を表す「住んだ」が入り、「長く住んだ町」として文に合う。"}, {"text": "笑った", "is_correct": false, "explanation": "「長く笑った町」では意味が通らず、生活した町の話にならない。"}, {"text": "泣いた", "is_correct": false, "explanation": "「長く泣いた町」は意味が通らず、町を離れる文に合わない。"}, {"text": "叩いた", "is_correct": false, "explanation": "「長く叩いた町」は意味が通らず、生活の拠点を表す文に合わない。"}], "explanations": {"住んだ": "過去に生活した町を表す「住んだ」が入り、「長く住んだ町」として文に合う。", "笑った": "「長く笑った町」では意味が通らず、生活した町の話にならない。", "泣いた": "「長く泣いた町」は意味が通らず、町を離れる文に合わない。", "叩いた": "「長く叩いた町」は意味が通らず、生活の拠点を表す文に合わない。"}, "sentence_index": 6, "correct_answer": "住んだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来年、この飛行機に住んで世界を回るつもりだ。", "explanation": "ここは〈乗る〉の意味。飛行機は乗り物で、生活の拠点となる住む場所ではない。"}, {"text": "来年、この定食屋に住んで毎日食事をするつもりだ。", "explanation": "ここは〈食べる〉の意味。定食屋は食事をする場所で、生活の拠点として住むとは言わない。"}, {"text": "彼は毎年、この大会に住んでいるほど熱心だ。", "explanation": "ここは〈参加する〉の意味。大会は住む場所ではなく、参加する場なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38457, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来年は札幌を住むつもりだ。", "corrected_sentence": "来年は札幌に住むつもりだ。", "error_description": "「住む」の場所には「に」を付ける。「札幌を」は動作の対象を示すので誤りで、正しくは「札幌に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "住み", "is_correct": true, "explanation": "連用形の「住み、」で後ろへ続け、郊外に住みつつ通勤する文に合う。"}, {"text": "住む", "is_correct": false, "explanation": "終止形の「住む、」では後ろへ続けにくく、文の流れに合わない。"}, {"text": "住んだ", "is_correct": false, "explanation": "た形は過去を表し、「住んだ、電車で」では現在の生活の文の意味が変わる。"}, {"text": "住まない", "is_correct": false, "explanation": "ない形は否定で、郊外に住んで通うという文の意味と反対になる。"}], "correct_form": "住み", "base_form": "住む", "form_label": "連用形", "sentence_index": 1, "explanations": {"住み": "連用形の「住み、」で後ろへ続け、郊外に住みつつ通勤する文に合う。", "住む": "終止形の「住む、」では後ろへ続けにくく、文の流れに合わない。", "住んだ": "た形は過去を表し、「住んだ、電車で」では現在の生活の文の意味が変わる。", "住まない": "ない形は否定で、郊外に住んで通うという文の意味と反対になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38457, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三年間、妻の実家の近くを住むことにした。", "corrected_sentence": "三年間、妻の実家の近くに住むことにした。", "error_description": "「住む」の場所には「に」を付ける。「近くを」は動作の対象を示すので誤りで、正しくは「近くに」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "住めた", "is_correct": false, "explanation": "可能形の過去「住めた」は「住めたない」とは続かず、可能の否定の文に合わない。"}, {"text": "住めば", "is_correct": false, "explanation": "仮定形「住めば」は「住めばない」とは続かず、可能の否定の文にならない。"}, {"text": "住め", "is_correct": true, "explanation": "可能形「住める」の未然形「住め」に「ない」が続き、「住めない」で家賃の理由から住めないという意味になる。"}, {"text": "住もう", "is_correct": false, "explanation": "意志形の「住もう」は「住もうない」と続かず、否定の文にならない。"}], "correct_form": "住め", "base_form": "住める", "form_label": "未然形", "sentence_index": 7, "explanations": {"住めた": "可能形の過去「住めた」は「住めたない」とは続かず、可能の否定の文に合わない。", "住めば": "仮定形「住めば」は「住めばない」とは続かず、可能の否定の文にならない。", "住め": "可能形「住める」の未然形「住め」に「ない」が続き、「住めない」で家賃の理由から住めないという意味になる。", "住もう": "意志形の「住もう」は「住もうない」と続かず、否定の文にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '148da555-7802-40ca-8a7d-3b13af3aaca7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38458, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38458, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「集落の真ん中」と場所の名詞を修飾する「の」で文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「集落を真ん中に」と目的語にすると文が崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "「集落へ真ん中に」は方向を示すが、文が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「集落と真ん中に」は並列の意味になり、不自然。"}], "correct_answer": "の", "explanations": {"の": "「集落の真ん中」と場所の名詞を修飾する「の」で文が成り立つ。", "を": "「集落を真ん中に」と目的語にすると文が崩れる。", "へ": "「集落へ真ん中に」は方向を示すが、文が通らない。", "と": "「集落と真ん中に」は並列の意味になり、不自然。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38458, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人がたくさん集まって住んでいる小さな町や村のことです。", "primary_collocate": null, "pronunciation": "しゅうらく", "ipa": "ɕɯːɾakɯ", "syllable_count": 4, "sentences": [{"text": "山のふもとに、小さな集落がある。", "target_word": "集落", "complexity_tier": "T3", "furigana": "山[やま]のふもとに、小[ちい]さな集落[しゅうらく]がある。", "sentence_source": "generated"}, {"text": "この集落には、二十軒ほどの家がある。", "target_word": "集落", "complexity_tier": "T3", "furigana": "この集落[しゅうらく]には、二十軒[にじゅっけん]ほどの家[いえ]がある。", "sentence_source": "generated"}, {"text": "集落の人たちは、みんな顔見知りだ。", "target_word": "集落", "complexity_tier": "T3", "furigana": "集落[しゅうらく]の人[ひと]たちは、みんな顔見知[かおみし]りだ。", "sentence_source": "generated"}, {"text": "川に沿って、いくつもの集落が並んでいる。", "target_word": "集落", "complexity_tier": "T3", "furigana": "川[かわ]に沿[そ]って、いくつもの集落[しゅうらく]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "雪で道がふさがれ、集落は孤立した。", "target_word": "集落", "complexity_tier": "T3", "furigana": "雪[ゆき]で道[みち]がふさがれ、集落[しゅうらく]は孤立[こりつ]した。", "sentence_source": "generated"}, {"text": "バスは一日に二回だけ、その集落に来る。", "target_word": "集落", "complexity_tier": "T3", "furigana": "バスは一日[いちにち]に二回[にかい]だけ、その集落[しゅうらく]に来[く]る。", "sentence_source": "generated"}, {"text": "祖父が生まれた集落は、海のそばにあった。", "target_word": "集落", "complexity_tier": "T3", "furigana": "祖父[そふ]が生[う]まれた集落[しゅうらく]は、海[うみ]のそばにあった。", "sentence_source": "generated"}, {"text": "集落の真ん中に、古い神社が立っている。", "target_word": "集落", "complexity_tier": "T3", "furigana": "集落[しゅうらく]の真[ま]ん中[なか]に、古[ふる]い神社[じんじゃ]が立[た]っている。", "sentence_source": "generated"}, {"text": "古い集落には、昔ながらの茅葺きの家が残っている。", "target_word": "集落", "complexity_tier": "T3", "furigana": "古[ふる]い集落[しゅうらく]には、昔[むかし]ながらの茅葺[かやぶ]きの家[いえ]が残[のこ]っている。", "sentence_source": "generated"}, {"text": "山を二つ越えると、別の集落に着く。", "target_word": "集落", "complexity_tier": "T3", "furigana": "山[やま]を二[ふた]つ越[こ]えると、別[べつ]の集落[しゅうらく]に着[つ]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集落", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人々が集まって暮らす小さな町や村", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea8104bb-358f-42db-9a79-a76080280153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38458, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集落", "is_correct": true, "explanation": "山のふもとにある、人が住む小さな村、という意味に合う。"}, {"text": "旋律", "is_correct": false, "explanation": "「小さな旋律がある」は場所の説明に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「小さな季節がある」は場所の文脈で成り立たない。"}, {"text": "時差", "is_correct": false, "explanation": "「小さな時差がある」は場所の説明にならない。"}], "explanations": {"集落": "山のふもとにある、人が住む小さな村、という意味に合う。", "旋律": "「小さな旋律がある」は場所の説明に合わない。", "季節": "「小さな季節がある」は場所の文脈で成り立たない。", "時差": "「小さな時差がある」は場所の説明にならない。"}, "sentence_index": 0, "correct_answer": "集落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この集落は三階建てで、屋上に庭がある。", "explanation": "ここは〈建物〉の意味。集落は人が住む町や村のことで、建物一つは指さない。"}, {"text": "彼は集落に勤めていて、毎日新しい製品を開発している。", "explanation": "ここは〈会社〉の意味。集落は場所を指し、勤め先の組織は指さない。"}, {"text": "この集落は一日三本しか止まらない小さな駅だ。", "explanation": "ここは〈鉄道の停留所〉の意味。集落は人が住む町や村のことで、停留所は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38458, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集落", "is_correct": true, "explanation": "祖父が生まれた、人の住む村、という意味に合う。"}, {"text": "歌", "is_correct": false, "explanation": "「生まれた歌は海のそばにあった」は意味が通らない。"}, {"text": "名前", "is_correct": false, "explanation": "「生まれた名前は海のそばにあった」は文として成り立たない。"}, {"text": "教科書", "is_correct": false, "explanation": "「生まれた教科書は海のそばにあった」は意味をなさない。"}], "explanations": {"集落": "祖父が生まれた、人の住む村、という意味に合う。", "歌": "「生まれた歌は海のそばにあった」は意味が通らない。", "名前": "「生まれた名前は海のそばにあった」は文として成り立たない。", "教科書": "「生まれた教科書は海のそばにあった」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "集落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は、この集落の試験に合格した。", "explanation": "ここは〈考査〉の意味。集落は人が住む町や村で、合否を決める考査の対象にはならない。"}, {"text": "この集落は、夏になると病気にかかった。", "explanation": "ここは〈疾患〉の意味。疾患に冒されるのは人や生き物で、集落は冒されない。"}, {"text": "父の集落は、今年で六十歳になる。", "explanation": "ここは〈年齢〉の意味。集落は年齢を持たないので、六十歳になるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38458, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "集落を人たちは、雪かきを手伝い合う。", "corrected_sentence": "集落の人たちは、雪かきを手伝い合う。", "error_description": "「集落の人たち」は所有や所属を表す「の」が正しい。「を」だと集落を目的語にして文が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38458, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "若者が去り、集落は空っぽにした。", "corrected_sentence": "若者が去り、集落は空っぽになった。", "error_description": "集落は主語で、「空っぽになった」と変化を表す。「空っぽにした」は誰かが何かを空にする意味で、主語の集落と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38459, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「集落」が「分かれている」の主語なので、主語を示す「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語に付く。「分かれる」は自動詞なので、「集落を分かれている」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や帰着を表す。「集落に谷ごとに分かれている」では主語が示されず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を表す。「集落と谷ごとに分かれている」は主語の関係が不明で、意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「集落」が「分かれている」の主語なので、主語を示す「が」が正しい。", "を": "「を」は他動詞の目的語に付く。「分かれる」は自動詞なので、「集落を分かれている」は成り立たない。", "に": "「に」は場所や帰着を表す。「集落に谷ごとに分かれている」では主語が示されず、文が成り立たない。", "と": "「と」は相手や並列を表す。「集落と谷ごとに分かれている」は主語の関係が不明で、意味が通らない。"}, "error_tags": {"を": "目的語の格", "に": "位置・帰着", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38459, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38459, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人々が集まって生活している、家の集まりや地域のこと。", "primary_collocate": null, "pronunciation": "しゅうらく", "ipa": "ɕɯːɾakɯ", "syllable_count": 4, "sentences": [{"text": "発掘で、二千年前の集落の跡が見つかった。", "target_word": "集落", "complexity_tier": "T3", "furigana": "発掘[はっくつ]で、二千年前[にせんねんまえ]の集落[しゅうらく]の跡[あと]が見[み]つかった。", "sentence_source": "generated"}, {"text": "この地域では、集落が谷ごとに分かれている。", "target_word": "集落", "complexity_tier": "T3", "furigana": "この地域[ちいき]では、集落[しゅうらく]が谷[たに]ごとに分[わ]かれている。", "sentence_source": "generated"}, {"text": "島の集落は、風を避けるために低い場所にある。", "target_word": "集落", "complexity_tier": "T3", "furigana": "島[しま]の集落[しゅうらく]は、風[かぜ]を避[さ]けるために低[ひく]い場所[ばしょ]にある。", "sentence_source": "generated"}, {"text": "集落の外れに、小さな畑が広がっている。", "target_word": "集落", "complexity_tier": "T3", "furigana": "集落[しゅうらく]の外[はず]れに、小[ちい]さな畑[はたけ]が広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "人口が減って、消えてしまった集落も多い。", "target_word": "集落", "complexity_tier": "T3", "furigana": "人口[じんこう]が減[へ]って、消[き]えてしまった集落[しゅうらく]も多[おお]い。", "sentence_source": "generated"}, {"text": "その集落では、毎年秋に祭りを開く。", "target_word": "集落", "complexity_tier": "T3", "furigana": "その集落[しゅうらく]では、毎年[まいとし]秋[あき]に祭[まつ]りを開[ひら]く。", "sentence_source": "generated"}, {"text": "川の近くに集落をつくるのは、水が便利だからだ。", "target_word": "集落", "complexity_tier": "T3", "furigana": "川[かわ]の近[ちか]くに集落[しゅうらく]をつくるのは、水[みず]が便利[べんり]だからだ。", "sentence_source": "generated"}, {"text": "集落ごとに、言葉が少しずつ違う。", "target_word": "集落", "complexity_tier": "T3", "furigana": "集落[しゅうらく]ごとに、言葉[ことば]が少[すこ]しずつ違[ちが]う。", "sentence_source": "generated"}, {"text": "市は、山間の集落に新しい診療所を作った。", "target_word": "集落", "complexity_tier": "T3", "furigana": "市[し]は、山間[やまあい]の集落[しゅうらく]に新[あたら]しい診療所[しんりょうじょ]を作[つく]った。", "sentence_source": "generated"}, {"text": "地図を見ると、集落は道に沿って細長く広がっている。", "target_word": "集落", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]ると、集落[しゅうらく]は道[みち]に沿[そ]って細長[ほそなが]く広[ひろ]がっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集落", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "家々が集まり人々が共同で生活している一まとまりの地域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea8104bb-358f-42db-9a79-a76080280153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38459, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手紙", "is_correct": false, "explanation": "「二千年前の手紙の跡」とは言わない。発掘で跡として残るのは人が暮らした場所なので、ここには入らない。"}, {"text": "集落", "is_correct": true, "explanation": "人々が暮らしていた地域の跡を指すので、「二千年前の集落の跡」として自然に入る。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、遺跡として跡が見つかるものではないので合わない。"}, {"text": "給料", "is_correct": false, "explanation": "給料は賃金のことで、発掘で跡が見つかるものではないので合わない。"}], "explanations": {"手紙": "「二千年前の手紙の跡」とは言わない。発掘で跡として残るのは人が暮らした場所なので、ここには入らない。", "集落": "人々が暮らしていた地域の跡を指すので、「二千年前の集落の跡」として自然に入る。", "天気": "天気は空模様のことで、遺跡として跡が見つかるものではないので合わない。", "給料": "給料は賃金のことで、発掘で跡が見つかるものではないので合わない。"}, "sentence_index": 0, "correct_answer": "集落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この集落には高層ビルが立ち並び、地下鉄が三路線通っている。", "explanation": "集落に〈都市〉の意味はなく、高層ビルや地下鉄が並ぶ大都市の描写には合わない。"}, {"text": "この集落は国連に加盟して、外交使節を派遣した。", "explanation": "集落に〈国〉の意味はなく、国連に加盟して使節を送る国家の文脈では使わない。"}, {"text": "この集落では、二百人の工員が夜通し機械を動かしている。", "explanation": "集落に〈工場〉の意味はなく、工員が機械を動かす場所の文脈では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38459, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "返事", "is_correct": false, "explanation": "「川の近くに返事をつくる」とは言わない。つくるのは場所や物で、返事には使わない。"}, {"text": "感情", "is_correct": false, "explanation": "感情は「つくる」ものではないので、「川の近くに感情をつくる」は合わない。"}, {"text": "集落", "is_correct": true, "explanation": "人が住んで暮らす場所なので、「川の近くに集落をつくる」として自然に入る。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は体の状態で、場所として「つくる」対象にはならないので合わない。"}], "explanations": {"返事": "「川の近くに返事をつくる」とは言わない。つくるのは場所や物で、返事には使わない。", "感情": "感情は「つくる」ものではないので、「川の近くに感情をつくる」は合わない。", "集落": "人が住んで暮らす場所なので、「川の近くに集落をつくる」として自然に入る。", "眠気": "眠気は体の状態で、場所として「つくる」対象にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "集落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この集落では、毎朝ホームに通勤客があふれて電車を待つ。", "explanation": "集落に〈駅〉の意味はなく、電車を待つ通勤客の場面には合わない。"}, {"text": "この集落では毎年春に、新入生が入学式で講義を受ける。", "explanation": "集落に〈大学〉の意味はなく、入学式や講義の場面には合わない。"}, {"text": "この集落は株式を上場し、来月の株主総会で配当を決める。", "explanation": "集落に〈会社〉の意味はなく、株式の上場や株主総会の文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38459, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山あいでは、集落を谷ごとに分かれている。", "corrected_sentence": "山あいでは、集落が谷ごとに分かれている。", "error_description": "「分かれている」の主語は「集落」なので、助詞は「を」ではなく「が」が正しい。「を」は他動詞の目的語に付く助詞で、自動詞「分かれる」の文には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38459, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "川沿いの集落は、道に沿って細長く広げている。", "corrected_sentence": "川沿いの集落は、道に沿って細長く広がっている。", "error_description": "「広がる」は自動詞で、主語の「集落」が広がる文になる。「広げる」は他動詞で目的語が必要なため、この文では誤りで、正しくは「広がっている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d5c9a02-7692-4926-8bf4-1afd2867ece1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38460, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「流れる」は通過する場所を「を」で示すので、山間を流れるという文が自然になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」だと山間が流れることになり、川が流れるという内容と合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、山間と流れるという文は成り立たない。"}, {"text": "か", "is_correct": false, "explanation": "「か」は選択を示すので、「山間か流れる」では文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「流れる」は通過する場所を「を」で示すので、山間を流れるという文が自然になる。", "が": "主語を示す「が」だと山間が流れることになり、川が流れるという内容と合わない。", "と": "「と」は並列や相手を示すので、山間と流れるという文は成り立たない。", "か": "「か」は選択を示すので、「山間か流れる」では文が成り立たない。"}, "error_tags": {"が": "主語", "と": "並列・相手", "か": "選択"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38460, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「山間の」は後ろの「あちこち」を修飾し、山間の中の各所という意味になる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示すので、ここでは「山間へあちこち」という形が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「山間よりあちこち」では文の意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「咲く」は目的語を取らないので、「山間をあちこちで咲く」は不自然。"}], "correct_answer": "の", "explanations": {"の": "「山間の」は後ろの「あちこち」を修飾し、山間の中の各所という意味になる。", "へ": "「へ」は移動の方向を示すので、ここでは「山間へあちこち」という形が成り立たない。", "より": "「より」は比較を示すので、「山間よりあちこち」では文の意味が通らない。", "を": "「咲く」は目的語を取らないので、「山間をあちこちで咲く」は不自然。"}, "error_tags": {"へ": "方向", "より": "比較", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38460, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "山と山の間の場所のことです。", "primary_collocate": null, "pronunciation": "さんかん", "ipa": "saŋkaɴ", "syllable_count": 4, "sentences": [{"text": "山間に小さな村があり、朝は霧が深い。", "target_word": "山間", "complexity_tier": "T3", "furigana": "山間(さんかん)に小(ちい)さな村(むら)があり、朝(あさ)は霧(きり)が深(ふか)い。", "sentence_source": "generated"}, {"text": "山間を流れる川の水はとても冷たい。", "target_word": "山間", "complexity_tier": "T3", "furigana": "山間(さんかん)を流(なが)れる川(かわ)の水(みず)はとても冷(つめ)たい。", "sentence_source": "generated"}, {"text": "山間の道は雪が降ると通れなくなるので、冬は隣の町へ行くのが大変だ。", "target_word": "山間", "complexity_tier": "T3", "furigana": "山間(さんかん)の道(みち)は雪(ゆき)が降(ふ)ると通(とお)れなくなるので、冬(ふゆ)は隣(となり)の町(まち)へ行(い)くのが大変(たいへん)だ。", "sentence_source": "generated"}, {"text": "電車は長いトンネルを出て、山間の駅に着いた。", "target_word": "山間", "complexity_tier": "T3", "furigana": "電車(でんしゃ)は長(なが)いトンネルを出(で)て、山間(さんかん)の駅(えき)に着(つ)いた。", "sentence_source": "generated"}, {"text": "山間の空気はきれいで、深く息を吸うと気持ちがいい。", "target_word": "山間", "complexity_tier": "T3", "furigana": "山間(さんかん)の空気(くうき)はきれいで、深(ふか)く息(いき)を吸(す)うと気持(きも)ちがいい。", "sentence_source": "generated"}, {"text": "祖父は山間で生まれ、子どもの時から山道を歩いて学校に通った。", "target_word": "山間", "complexity_tier": "T3", "furigana": "祖父(そふ)は山間(さんかん)で生(う)まれ、子(こ)どもの時(とき)から山道(やまみち)を歩(ある)いて学校(がっこう)に通(かよ)った。", "sentence_source": "generated"}, {"text": "山間に入ると、携帯電話がつながらなくなった。", "target_word": "山間", "complexity_tier": "T3", "furigana": "山間(さんかん)に入(はい)ると、携帯電話(けいたいでんわ)がつながらなくなった。", "sentence_source": "generated"}, {"text": "春になると、山間のあちこちで桜が咲く。", "target_word": "山間", "complexity_tier": "T3", "furigana": "春(はる)になると、山間(さんかん)のあちこちで桜(さくら)が咲(さ)く。", "sentence_source": "generated"}, {"text": "山間の天気は変わりやすいので、雨具を持って行く。", "target_word": "山間", "complexity_tier": "T3", "furigana": "山間(さんかん)の天気(てんき)は変(か)わりやすいので、雨具(あまぐ)を持(も)って行(い)く。", "sentence_source": "generated"}, {"text": "山間から見える星は、町で見るより数が多い。", "target_word": "山間", "complexity_tier": "T3", "furigana": "山間(さんかん)から見(み)える星(ほし)は、町(まち)で見(み)るより数(かず)が多(おお)い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "山間", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "山と山の間にある場所(地形としての山の間)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0df70395-f463-48c9-9f7b-eb53760b6965') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38460, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "山間", "is_correct": true, "explanation": "山と山の間の土地を指し、小さな村があって朝に霧が深いという文脈に合う。"}, {"text": "都心", "is_correct": false, "explanation": "大都市の中心部を指すので、小さな村があり朝霧が深いという描写と合わない。"}, {"text": "月面", "is_correct": false, "explanation": "月の表面を指すので、村があって霧が出るという文脈と矛盾する。"}, {"text": "南極", "is_correct": false, "explanation": "氷に覆われた大陸を指すので、村があって朝に霧が深いという内容と合わない。"}], "explanations": {"山間": "山と山の間の土地を指し、小さな村があって朝に霧が深いという文脈に合う。", "都心": "大都市の中心部を指すので、小さな村があり朝霧が深いという描写と合わない。", "月面": "月の表面を指すので、村があって霧が出るという文脈と矛盾する。", "南極": "氷に覆われた大陸を指すので、村があって朝に霧が深いという内容と合わない。"}, "sentence_index": 0, "correct_answer": "山間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この山間の頂に立つと、遠くの海まで見渡せる。", "explanation": "ここは〈山間〉の意味。山間は山と山の間の土地で、山の頂上は指さないので合わない。"}, {"text": "山間の海岸線は、夏になると観光客でにぎわう。", "explanation": "ここは〈山間〉の意味。山間は山に挟まれた内陸の土地で、〈海辺〉のように海に面した場所とは合わない。"}, {"text": "山間は北から南へ長く連なり、国境をなしている。", "explanation": "ここは〈山間〉の意味。山間は山に挟まれた谷あいの土地で、山が長く連なる〈山脈〉を指すのとは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38460, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "山間", "is_correct": true, "explanation": "山あいの土地で、携帯電話がつながりにくくなる場所に入るという文脈に合う。"}, {"text": "大都会", "is_correct": false, "explanation": "電波が強く届く場所なので、携帯電話がつながらなくなるという内容と矛盾する。"}, {"text": "繁華街", "is_correct": false, "explanation": "人通りが多く電波も届きやすい場所なので、電話がつながらなくなるという内容と合わない。"}, {"text": "駅前広場", "is_correct": false, "explanation": "開けた屋外で電波が届きやすいので、電話がつながらなくなる描写と矛盾する。"}], "explanations": {"山間": "山あいの土地で、携帯電話がつながりにくくなる場所に入るという文脈に合う。", "大都会": "電波が強く届く場所なので、携帯電話がつながらなくなるという内容と矛盾する。", "繁華街": "人通りが多く電波も届きやすい場所なので、電話がつながらなくなるという内容と合わない。", "駅前広場": "開けた屋外で電波が届きやすいので、電話がつながらなくなる描写と矛盾する。"}, "sentence_index": 6, "correct_answer": "山間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山間は見渡す限りの砂漠で、昼は焼けつくように暑い。", "explanation": "ここは〈山間〉の意味。乾いた砂地が一面に広がる土地とは違い、山間は山に挟まれた谷あいの土地を指す。"}, {"text": "山間の河口には、大きな港が広がっている。", "explanation": "ここは〈山間〉の意味。川が海に流れ出る出口のような海辺の場所とは違い、山間は山に挟まれた内陸の土地を指す。"}, {"text": "仕事の山間を片付けて、ようやく家に帰れた。", "explanation": "ここは〈山〉の「仕事が積み重なった状態」の意味。山間は地形を指す語で、この比喩には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38460, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は山間を暮らしていたので、冬の雪には慣れている。", "corrected_sentence": "祖父は山間で暮らしていたので、冬の雪には慣れている。", "error_description": "「暮らす」の場所は「で」で示す。「を」は他動詞の目的語に付くので「山間を暮らす」は不自然。正しくは「山間で暮らす」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38460, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山間な夜は冷えるので、薄い毛布が欠かせない。", "corrected_sentence": "山間の夜は冷えるので、薄い毛布が欠かせない。", "error_description": "「山間」が「夜」を修飾するには「の」が必要。「な」は形容動詞の語尾なので、「山間な夜」は不自然。正しくは「山間の夜」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38461, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「住む」は住む場所を「に」で示すので、山間に住む人たちという文になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、山間が住むという文は成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「住む」は目的語を取らないので、「山間を住む」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手を示すが、「山間と住む」では場所の意味が出ず文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「住む」は住む場所を「に」で示すので、山間に住む人たちという文になる。", "が": "「が」は主語を示すが、山間が住むという文は成り立たない。", "を": "「住む」は目的語を取らないので、「山間を住む」は不自然。", "と": "「と」は相手を示すが、「山間と住む」では場所の意味が出ず文が成り立たない。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38461, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「広がる」は広がる場所を「に」で示すので、山間に広がる茶畑という文になる。"}, {"text": "を", "is_correct": false, "explanation": "「広がる」は自動詞で目的語を取れないので、「山間を広がる」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作の場所を示すが、広がる範囲や場所は「に」で示すのが自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「山間より広がる茶畑」では意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「広がる」は広がる場所を「に」で示すので、山間に広がる茶畑という文になる。", "を": "「広がる」は自動詞で目的語を取れないので、「山間を広がる」は不自然。", "で": "「で」は動作の場所を示すが、広がる範囲や場所は「に」で示すのが自然。", "より": "「より」は比較を示すので、「山間より広がる茶畑」では意味が通らない。"}, "error_tags": {"を": "目的語", "で": "場所（動作）", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38461, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "山と山に挟まれた地域。谷間や山あいのことを指す。", "primary_collocate": null, "pronunciation": "さんかん", "ipa": "saŋkaɴ", "syllable_count": 4, "sentences": [{"text": "この山間では、冬になると雪で道が閉ざされる。", "target_word": "山間", "complexity_tier": "T3", "furigana": "この山間(さんかん)では、冬(ふゆ)になると雪(ゆき)で道(みち)が閉(と)ざされる。", "sentence_source": "generated"}, {"text": "山間に住む人たちは、昔から畑で野菜を作ってきた。", "target_word": "山間", "complexity_tier": "T3", "furigana": "山間(さんかん)に住(す)む人(ひと)たちは、昔(むかし)から畑(はたけ)で野菜(やさい)を作(つく)ってきた。", "sentence_source": "generated"}, {"text": "山間の町では、若い人が減って学校が閉まった。", "target_word": "山間", "complexity_tier": "T3", "furigana": "山間(さんかん)の町(まち)では、若(わか)い人(ひと)が減(へ)って学校(がっこう)が閉(し)まった。", "sentence_source": "generated"}, {"text": "山間は平地より日が当たる時間が短く、夏でも涼しい。", "target_word": "山間", "complexity_tier": "T3", "furigana": "山間(さんかん)は平地(へいち)より日(ひ)が当(あ)たる時間(じかん)が短(みじか)く、夏(なつ)でも涼(すず)しい。", "sentence_source": "generated"}, {"text": "山間の小さな盆地に、古い温泉宿が三軒ある。", "target_word": "山間", "complexity_tier": "T3", "furigana": "山間(さんかん)の小(ちい)さな盆地(ぼんち)に、古(ふる)い温泉宿(おんせんやど)が三軒(さんげん)ある。", "sentence_source": "generated"}, {"text": "大雨で山間の集落が孤立し、救助隊が向かった。", "target_word": "山間", "complexity_tier": "T3", "furigana": "大雨(おおあめ)で山間(さんかん)の集落(しゅうらく)が孤立(こりつ)し、救助隊(きゅうじょたい)が向(む)かった。", "sentence_source": "generated"}, {"text": "山間では平野より気温が低いので、米の育ちが遅い。", "target_word": "山間", "complexity_tier": "T3", "furigana": "山間(さんかん)では平野(へいや)より気温(きおん)が低(ひく)いので、米(こめ)の育(そだ)ちが遅(おそ)い。", "sentence_source": "generated"}, {"text": "山間に広がる茶畑を見に、観光客が訪れる。", "target_word": "山間", "complexity_tier": "T3", "furigana": "山間(さんかん)に広(ひろ)がる茶畑(ちゃばたけ)を見(み)に、観光客(かんこうきゃく)が訪(おとず)れる。", "sentence_source": "generated"}, {"text": "山間の暮らしは不便だが、自然が好きなので満足している。", "target_word": "山間", "complexity_tier": "T3", "furigana": "山間(さんかん)の暮(く)らしは不便(ふべん)だが、自然(しぜん)が好(す)きなので満足(まんぞく)している。", "sentence_source": "generated"}, {"text": "この山間には、昔から続く祭りが残っている。", "target_word": "山間", "complexity_tier": "T3", "furigana": "この山間(さんかん)には、昔(むかし)から続(つづ)く祭(まつ)りが残(のこ)っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "山間", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "山に挟まれた地域(人が暮らす谷間・山あいの土地)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0df70395-f463-48c9-9f7b-eb53760b6965') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38461, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "山間", "is_correct": true, "explanation": "山に挟まれた谷間や山あいの地域で、冬に雪で道が閉ざされるという文脈に合う。"}, {"text": "大都市", "is_correct": false, "explanation": "大都市では冬に道が雪で閉ざされることはまれで、文脈に合わない。"}, {"text": "砂漠", "is_correct": false, "explanation": "乾燥した砂漠では雪が積もって道が閉ざされることはなく、文の内容と矛盾する。"}, {"text": "熱帯雨林", "is_correct": false, "explanation": "熱帯では雪が降らないので、冬に道が雪で閉ざされるという文脈と合わない。"}], "explanations": {"山間": "山に挟まれた谷間や山あいの地域で、冬に雪で道が閉ざされるという文脈に合う。", "大都市": "大都市では冬に道が雪で閉ざされることはまれで、文脈に合わない。", "砂漠": "乾燥した砂漠では雪が積もって道が閉ざされることはなく、文の内容と矛盾する。", "熱帯雨林": "熱帯では雪が降らないので、冬に道が雪で閉ざされるという文脈と合わない。"}, "sentence_index": 0, "correct_answer": "山間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山間は潮風が心地よく、夏は海水浴客でにぎわう。", "explanation": "ここは〈山間〉の意味。海辺は海に面した地域で、山に挟まれた谷間とは合わない。"}, {"text": "山間は見渡す限りの砂丘が続き、風で形が変わる。", "explanation": "ここは〈山間〉の意味。乾いた砂の丘が連なる地形とは違い、山間は山に挟まれた谷あいの土地を指すので合わない。"}, {"text": "一夜漬けの前に、試験の山間を確認した。", "explanation": "ここは〈山間〉の意味。試験の要点を指すのは「ヤマ」の意味で、山間とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38461, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "山間", "is_correct": true, "explanation": "山間は平野より気温が低く、米の育ちが遅くなるという文脈に合う。"}, {"text": "南国", "is_correct": false, "explanation": "南国は気温が高い地域で、平野より気温が低いという前提と合わない。"}, {"text": "赤道直下", "is_correct": false, "explanation": "年中気温が高い地域で、気温が低いので米の育ちが遅いという内容と矛盾する。"}, {"text": "都心部", "is_correct": false, "explanation": "都心部はヒートアイランドで平野より気温が高くなりやすく、文の内容と合わない。"}], "explanations": {"山間": "山間は平野より気温が低く、米の育ちが遅くなるという文脈に合う。", "南国": "南国は気温が高い地域で、平野より気温が低いという前提と合わない。", "赤道直下": "年中気温が高い地域で、気温が低いので米の育ちが遅いという内容と矛盾する。", "都心部": "都心部はヒートアイランドで平野より気温が高くなりやすく、文の内容と合わない。"}, "sentence_index": 6, "correct_answer": "山間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この山間は湖の岸に沿って続き、ボートが並んでいる。", "explanation": "ここは〈山間〉の意味。湖畔は水辺の地域で、山と山の間の谷間とは別の場所を指す。"}, {"text": "この山間は火口を持つ火山で、噴煙が上がっている。", "explanation": "ここは〈山間〉の意味。山そのものを指す語とは違い、山間は山と山の間の谷あいを表すので合わない。"}, {"text": "この山間は海に囲まれ、船でしか行けない島だ。", "explanation": "ここは〈山間〉の意味。水に囲まれた陸地を指す語で、山に挟まれた谷あいの土地とは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38461, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山間が村では、夏も朝晩は冷え込む。", "corrected_sentence": "山間の村では、夏も朝晩は冷え込む。", "error_description": "「山間」が「村」を修飾するには「の」が必要。「が」は主語を示すので、「山間が村では」は不自然。正しくは「山間の村では」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38461, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は山間から住んでいて、冬の雪には慣れている。", "corrected_sentence": "祖母は山間に住んでいて、冬の雪には慣れている。", "error_description": "「住む」の場所は「に」で示す。「から」は出発点を示すので、「山間から住む」は意味が通らない。正しくは「山間に住む」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38462, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「雨がやむ」で雨が主語になる格助詞。ここに合う。"}, {"text": "を", "is_correct": false, "explanation": "「やむ」は自動詞なので目的語の「を」は取れない（「雨をやむ」は不自然）。"}, {"text": "に", "is_correct": false, "explanation": "「雨にやむ」では「やむ」の相手として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「雨とやむ」は並列を作る助詞で、やむの主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「雨がやむ」で雨が主語になる格助詞。ここに合う。", "を": "「やむ」は自動詞なので目的語の「を」は取れない（「雨をやむ」は不自然）。", "に": "「雨にやむ」では「やむ」の相手として成り立たない。", "と": "「雨とやむ」は並列を作る助詞で、やむの主語にはならない。"}, "error_tags": {"を": "目的格", "に": "位置・相手", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38462, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「雨になる」で結果を表す「に」。ここに合う。"}, {"text": "を", "is_correct": false, "explanation": "「なる」は目的語を取らないので「を」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「雨でなる」は手段や場所として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「雨へなる」は方向を表すが、結果の意味にならない。"}], "correct_answer": "に", "explanations": {"に": "「雨になる」で結果を表す「に」。ここに合う。", "を": "「なる」は目的語を取らないので「を」は不自然。", "で": "「雨でなる」は手段や場所として成り立たない。", "へ": "「雨へなる」は方向を表すが、結果の意味にならない。"}, "error_tags": {"を": "目的格", "で": "手段・場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38462, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空から落ちてくる水のこと。", "primary_collocate": null, "pronunciation": "あめ", "ipa": "ame", "syllable_count": 2, "sentences": [{"text": "朝から雨が降っていたので、傘を持って出かけました。", "target_word": "雨", "complexity_tier": "T3", "furigana": "朝[あさ]から雨[あめ]が降[ふ]っていたので、傘[かさ]を持[も]って出[で]かけました。", "sentence_source": "generated"}, {"text": "雨がやむまで、駅の中で待つことにした。", "target_word": "雨", "complexity_tier": "T3", "furigana": "雨[あめ]がやむまで、駅[えき]の中[なか]で待[ま]つことにした。", "sentence_source": "generated"}, {"text": "昨日は雨だったから、洗濯物が乾かなかった。", "target_word": "雨", "complexity_tier": "T3", "furigana": "昨日[きのう]は雨[あめ]だったから、洗濯物[せんたくもの]が乾[かわ]かなかった。", "sentence_source": "generated"}, {"text": "雨に濡れて、かばんの中の本まで湿ってしまった。", "target_word": "雨", "complexity_tier": "T3", "furigana": "雨[あめ]に濡[ぬ]れて、かばんの中[なか]の本[ほん]まで湿[しめ]ってしまった。", "sentence_source": "generated"}, {"text": "窓の外では、雨が静かに降り続けている。", "target_word": "雨", "complexity_tier": "T3", "furigana": "窓[まど]の外[そと]では、雨[あめ]が静[しず]かに降[ふ]り続[つづ]けている。", "sentence_source": "generated"}, {"text": "遠足の日は雨になり、みんなでがっかりした。", "target_word": "雨", "complexity_tier": "T3", "furigana": "遠足[えんそく]の日[ひ]は雨[あめ]になり、みんなでがっかりした。", "sentence_source": "generated"}, {"text": "雨の音を聞きながら、温かいお茶を飲んだ。", "target_word": "雨", "complexity_tier": "T3", "furigana": "雨[あめ]の音[おと]を聞[き]きながら、温[あたた]かいお茶[ちゃ]を飲[の]んだ。", "sentence_source": "generated"}, {"text": "天気予報では、午後から雨になるそうです。", "target_word": "雨", "complexity_tier": "T3", "furigana": "天気予報[てんきよほう]では、午後[ごご]から雨[あめ]になるそうです。", "sentence_source": "generated"}, {"text": "雨が強くなってきたので、試合は中止になった。", "target_word": "雨", "complexity_tier": "T3", "furigana": "雨[あめ]が強[つよ]くなってきたので、試合[しあい]は中止[ちゅうし]になった。", "sentence_source": "generated"}, {"text": "雨の日は道が滑りやすいから、気をつけてください。", "target_word": "雨", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は道[みち]が滑[すべ]りやすいから、気[き]をつけてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雨", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "空から降る水。日常の天気としての雨", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89bcd18f-d47f-4b0f-88fb-abadee0257a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38462, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雨", "is_correct": true, "explanation": "文の主語で、朝からの降り続きが傘を持つ理由に合う。"}, {"text": "電車", "is_correct": false, "explanation": "電車は乗り物で降るものではないので、「降っていた」の主語にならない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は降らないので、天気の文の主語として成り立たない。"}, {"text": "道", "is_correct": false, "explanation": "道は降る対象ではないので、この空欄に入らない。"}], "explanations": {"雨": "文の主語で、朝からの降り続きが傘を持つ理由に合う。", "電車": "電車は乗り物で降るものではないので、「降っていた」の主語にならない。", "窓": "窓は降らないので、天気の文の主語として成り立たない。", "道": "道は降る対象ではないので、この空欄に入らない。"}, "sentence_index": 0, "correct_answer": "雨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜のうちに雨が積もり、庭が真っ白になった。", "explanation": "雨は積もって白くなることはないので不自然。白く積もるのは雪。"}, {"text": "おやつに雨をなめて、口がべたべたになった。", "explanation": "ここは〈飴〉（同じ読み）の意味。雨は食べたりなめたりできないので合わない。"}, {"text": "夜の冷えで雨が草の葉に生まれ、朝まで白く残っていた。", "explanation": "草の葉に生じる水滴は露で、雨は空から降るものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38462, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨", "is_correct": true, "explanation": "「雨の音」で、音を立てる天気の雨。音を聞く文脈に合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は「〇〇の音を聞く」の対象にならず、文が成り立たない。"}, {"text": "毛布", "is_correct": false, "explanation": "毛布は音を立てる物ではなく、「〜の音」として文が成り立たない。"}, {"text": "綿", "is_correct": false, "explanation": "綿は音を立てる物ではなく、「〜の音」として文が成り立たない。"}], "explanations": {"雨": "「雨の音」で、音を立てる天気の雨。音を聞く文脈に合う。", "砂糖": "砂糖は「〇〇の音を聞く」の対象にならず、文が成り立たない。", "毛布": "毛布は音を立てる物ではなく、「〜の音」として文が成り立たない。", "綿": "綿は音を立てる物ではなく、「〜の音」として文が成り立たない。"}, "sentence_index": 6, "correct_answer": "雨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蛇口をひねると、水道の雨が勢いよく出た。", "explanation": "水道から出るのは水で、雨とは言わないので合わない。"}, {"text": "悲しい映画を見て、頬を伝う雨が止まらなかった。", "explanation": "頬を伝って出るのは涙で、雨は空から降るものなので合わない。"}, {"text": "朝、谷から雨が白く立ちのぼって、景色が見えなくなった。", "explanation": "白く立ちのぼって谷を包むのは霧で、雨は上へ立ちのぼらず降るものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38462, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "午後になって雨を強く降り出した。", "corrected_sentence": "午後になって雨が強く降り出した。", "error_description": "主語の雨には「が」が正しい。「を」は「降る」の目的語にならず、この文では不自然（助詞の誤り）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38462, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今夜は北の空から雨をなると聞きました。", "corrected_sentence": "今夜は北の空から雨になると聞きました。", "error_description": "「〜になる」の結果を示すのは「に」。「を」は他動詞の目的語用で、「なる」とは合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38463, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「雨を降らせる」の目的語で、降らせる対象を示す。ここに合う。"}, {"text": "が", "is_correct": false, "explanation": "「雨が降らせる」は主語と動詞が結びつかず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「雨に降らせる」は相手や位置として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「雨で降らせる」は手段の意味にならず不自然。"}], "correct_answer": "を", "explanations": {"を": "「雨を降らせる」の目的語で、降らせる対象を示す。ここに合う。", "が": "「雨が降らせる」は主語と動詞が結びつかず不自然。", "に": "「雨に降らせる」は相手や位置として成り立たない。", "で": "「雨で降らせる」は手段の意味にならず不自然。"}, "error_tags": {"が": "主格", "に": "位置・相手", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38463, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「雨は〜現象の一つだ」の主題を示す。ここに合う。"}, {"text": "を", "is_correct": false, "explanation": "「雨を〜の一つだ」は目的語になるが、定義の文として続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「雨へ〜の一つだ」は方向を示し、定義文の主題にならない。"}, {"text": "で", "is_correct": false, "explanation": "「雨で〜の一つだ」は手段の意味になり、定義文として不自然。"}], "correct_answer": "は", "explanations": {"は": "「雨は〜現象の一つだ」の主題を示す。ここに合う。", "を": "「雨を〜の一つだ」は目的語になるが、定義の文として続かない。", "へ": "「雨へ〜の一つだ」は方向を示し、定義文の主題にならない。", "で": "「雨で〜の一つだ」は手段の意味になり、定義文として不自然。"}, "error_tags": {"を": "目的格", "へ": "方向", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38463, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "大気中の水蒸気が雲となり、水滴となって地上に降るもの。", "primary_collocate": null, "pronunciation": "あめ", "ipa": "ame", "syllable_count": 2, "sentences": [{"text": "水蒸気が冷えて雲になり、やがて雨となって地上に降る。", "target_word": "雨", "complexity_tier": "T3", "furigana": "水蒸気[すいじょうき]が冷[ひ]えて雲[くも]になり、やがて雨[あめ]となって地上[ちじょう]に降[ふ]る。", "sentence_source": "generated"}, {"text": "山の斜面では、湿った空気が上昇して雨を降らせる。", "target_word": "雨", "complexity_tier": "T3", "furigana": "山[やま]の斜面[しゃめん]では、湿[しめ]った空気[くうき]が上昇[じょうしょう]して雨[あめ]を降[ふ]らせる。", "sentence_source": "generated"}, {"text": "雲の中の水滴が大きくなると、雨として落ちてくる。", "target_word": "雨", "complexity_tier": "T3", "furigana": "雲[くも]の中[なか]の水滴[すいてき]が大[おお]きくなると、雨[あめ]として落[お]ちてくる。", "sentence_source": "generated"}, {"text": "この地域は一年を通して雨が少なく、農業には水の確保が欠かせない。", "target_word": "雨", "complexity_tier": "T3", "furigana": "この地域[ちいき]は一年[いちねん]を通[とお]して雨[あめ]が少[すく]なく、農業[のうぎょう]には水[みず]の確保[かくほ]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "台風の接近で、広い範囲に激しい雨が予想されています。", "target_word": "雨", "complexity_tier": "T3", "furigana": "台風[たいふう]の接近[せっきん]で、広[ひろ]い範囲[はんい]に激[はげ]しい雨[あめ]が予想[よそう]されています。", "sentence_source": "generated"}, {"text": "雨が降ると、川の水かさが増えて流れが速くなる。", "target_word": "雨", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ると、川[かわ]の水[みず]かさが増[ふ]えて流[なが]れが速[はや]くなる。", "sentence_source": "generated"}, {"text": "冷たい空気と暖かい空気がぶつかると、雲ができて雨になりやすい。", "target_word": "雨", "complexity_tier": "T3", "furigana": "冷[つめ]たい空気[くうき]と暖[あたた]かい空気[くうき]がぶつかると、雲[くも]ができて雨[あめ]になりやすい。", "sentence_source": "generated"}, {"text": "雨は、海や川から蒸発した水が再び地上に戻る現象の一つだ。", "target_word": "雨", "complexity_tier": "T3", "furigana": "雨[あめ]は、海[うみ]や川[かわ]から蒸発[じょうはつ]した水[みず]が再[ふたた]び地上[ちじょう]に戻[もど]る現象[げんしょう]の一[ひと]つだ。", "sentence_source": "generated"}, {"text": "夏の午後には、強い日差しのせいで雲が発達し、雨が降ることがある。", "target_word": "雨", "complexity_tier": "T3", "furigana": "夏[なつ]の午後[ごご]には、強[つよ]い日差[ひざ]しのせいで雲[くも]が発達[はったつ]し、雨[あめ]が降[ふ]ることがある。", "sentence_source": "generated"}, {"text": "気象台では、降った雨の量を毎日記録している。", "target_word": "雨", "complexity_tier": "T3", "furigana": "気象台[きしょうだい]では、降[ふ]った雨[あめ]の量[りょう]を毎日[まいにち]記録[きろく]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雨", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "水蒸気から雲、水滴を経て降る気象現象としての雨", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: 水かさ (Zipf 1.84)']::text[], '89bcd18f-d47f-4b0f-88fb-abadee0257a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38463, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雨", "is_correct": true, "explanation": "雲から水滴となって地上に降るものとして、この文の主語に合う。"}, {"text": "煙", "is_correct": false, "explanation": "煙は立ちのぼるもので、地上に降るものではないので合わない。"}, {"text": "空気", "is_correct": false, "explanation": "空気は降らないので、「地上に降る」の主語にならない。"}, {"text": "石", "is_correct": false, "explanation": "石は自然に降る現象の対象ではなく、この文の流れに合わない。"}], "explanations": {"雨": "雲から水滴となって地上に降るものとして、この文の主語に合う。", "煙": "煙は立ちのぼるもので、地上に降るものではないので合わない。", "空気": "空気は降らないので、「地上に降る」の主語にならない。", "石": "石は自然に降る現象の対象ではなく、この文の流れに合わない。"}, "sentence_index": 0, "correct_answer": "雨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもたちは、おやつに雨を一袋買った。", "explanation": "ここは〈飴〉（同じ読み）の意味。雨は袋で買うものではないので合わない。"}, {"text": "空一面に雨が綿のように広がり、山がまったく見えない。", "explanation": "空一面に広がって山を隠すのは雲で、雨は降るものなので合わない。"}, {"text": "真夏の山道で、額から雨がしたたり落ちた。", "explanation": "額からしたたるのは汗で、雨は空から降るものなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38463, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨", "is_correct": true, "explanation": "「雨になりやすい」で、雲から降る水として文に合う。"}, {"text": "紙", "is_correct": false, "explanation": "紙は雨になることはなく、文脈に合わない。"}, {"text": "電池", "is_correct": false, "explanation": "電池は雨にならないので、この空欄に入らない。"}, {"text": "布", "is_correct": false, "explanation": "布は雨にならず、文の意味が通らない。"}], "explanations": {"雨": "「雨になりやすい」で、雲から降る水として文に合う。", "紙": "紙は雨になることはなく、文脈に合わない。", "電池": "電池は雨にならないので、この空欄に入らない。", "布": "布は雨にならず、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "雨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お茶に雨を少し入れて、甘くして飲んだ。", "explanation": "お茶を甘くするのは砂糖で、雨は甘みを出さないので合わない。"}, {"text": "湯のみから雨がふわりと立ちのぼった。", "explanation": "湯のみから立ちのぼるのは湯気で、雨は上へ立ちのぼらず降るものなので合わない。"}, {"text": "財布から雨をひとつ落とした。", "explanation": "財布から落ちるのは硬貨で、雨は財布に入るものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38463, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海から来た暖かい空気のせいで、夜になると雨を降りやすくなる。", "corrected_sentence": "海から来た暖かい空気のせいで、夜になると雨が降りやすくなる。", "error_description": "主語の雨には「が」が正しい。「を」は目的語の印で、「降りやすい」の主語にならない（助詞の誤り）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38463, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先週の雨を、朝から夕方まで降り続いた。", "corrected_sentence": "先週の雨は、朝から夕方まで降り続いた。", "error_description": "雨は主題として「は」で示すのが自然。「を」は目的語の印で、自動詞の「降り続く」とは合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
