INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38464, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「導水の方法」で、導水に関する方法であることを示す。ここに合う。"}, {"text": "が", "is_correct": false, "explanation": "「導水が方法」は成り立たず、所属を示す「の」が必要。"}, {"text": "を", "is_correct": false, "explanation": "「導水を方法には」は目的語にならず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「導水で方法には」は手段の意味にならず、ここには入らない。"}], "correct_answer": "の", "explanations": {"の": "「導水の方法」で、導水に関する方法であることを示す。ここに合う。", "が": "「導水が方法」は成り立たず、所属を示す「の」が必要。", "を": "「導水を方法には」は目的語にならず不自然。", "で": "「導水で方法には」は手段の意味にならず、ここには入らない。"}, "error_tags": {"が": "主格", "を": "目的格", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38464, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "水を、ある場所から別の場所へと、道をつくって流すことです。", "primary_collocate": null, "pronunciation": "どうすい", "ipa": "doːsɯi", "syllable_count": 4, "sentences": [{"text": "村では山の泉から田んぼへ導水する工事が始まった。", "target_word": "導水", "complexity_tier": "T3", "furigana": "村[むら]では山[やま]の泉[いずみ]から田[た]んぼへ導水[どうすい]する工事[こうじ]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "昔の人は、竹を使って川の水を家まで導水していた。", "target_word": "導水", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、竹[たけ]を使[つか]って川[かわ]の水[みず]を家[いえ]まで導水[どうすい]していた。", "sentence_source": "generated"}, {"text": "導水のために、山の中に長い溝が掘られた。", "target_word": "導水", "complexity_tier": "T3", "furigana": "導水[どうすい]のために、山[やま]の中[なか]に長[なが]い溝[みぞ]が掘[ほ]られた。", "sentence_source": "generated"}, {"text": "乾燥した土地では、遠くの川から導水しなければ作物は育たない。", "target_word": "導水", "complexity_tier": "T3", "furigana": "乾燥[かんそう]した土地[とち]では、遠[とお]くの川[かわ]から導水[どうすい]しなければ作物[さくもつ]は育[そだ]たない。", "sentence_source": "generated"}, {"text": "導水が成功したおかげで、村の畑に水が届くようになった。", "target_word": "導水", "complexity_tier": "T3", "furigana": "導水[どうすい]が成功[せいこう]したおかげで、村[むら]の畑[はたけ]に水[みず]が届[とど]くようになった。", "sentence_source": "generated"}, {"text": "町は、ダムの水を浄水場へ導水する計画を発表した。", "target_word": "導水", "complexity_tier": "T3", "furigana": "町[まち]は、ダムの水[みず]を浄水場[じょうすいじょう]へ導水[どうすい]する計画[けいかく]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "大雨の後、あふれそうな川の水を別の池に導水して被害を防いだ。", "target_word": "導水", "complexity_tier": "T3", "furigana": "大雨[おおあめ]の後[あと]、あふれそうな川[かわ]の水[みず]を別[べつ]の池[いけ]に導水[どうすい]して被害[ひがい]を防[ふせ]いだ。", "sentence_source": "generated"}, {"text": "導水の方法には、溝を掘るやり方と、管を通すやり方がある。", "target_word": "導水", "complexity_tier": "T3", "furigana": "導水[どうすい]の方法[ほうほう]には、溝[みぞ]を掘[ほ]るやり方[かた]と、管[くだ]を通[とお]すやり方[かた]がある。", "sentence_source": "generated"}, {"text": "古い城では、堀へ導水するために川の流れを変えていた。", "target_word": "導水", "complexity_tier": "T3", "furigana": "古[ふる]い城[しろ]では、堀[ほり]へ導水[どうすい]するために川[かわ]の流[なが]れを変[か]えていた。", "sentence_source": "generated"}, {"text": "工事が遅れたため、庭の池への導水はまだできていない。", "target_word": "導水", "complexity_tier": "T3", "furigana": "工事[こうじ]が遅[おく]れたため、庭[にわ]の池[いけ]への導水[どうすい]はまだできていない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "導水", "label": "基本形"}, {"form": "導水する", "label": "サ変動詞"}], "register": "neutral", "sense_fingerprint": "水の通り道をつくって、別の場所へ水を流すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89bcd18f-d47f-4b0f-88fb-abadee0257a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38464, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "導水", "is_correct": true, "explanation": "泉から田へ水を送る工事の名称として、この文に合う。"}, {"text": "排水", "is_correct": false, "explanation": "排水は水を外へ抜く意味で、泉から田へ送る工事とは逆になる。"}, {"text": "田植え", "is_correct": false, "explanation": "田植えは稲を植えることで、水を送る工事の内容として合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩くことで、工事の内容として成り立たない。"}], "explanations": {"導水": "泉から田へ水を送る工事の名称として、この文に合う。", "排水": "排水は水を外へ抜く意味で、泉から田へ送る工事とは逆になる。", "田植え": "田植えは稲を植えることで、水を送る工事の内容として合わない。", "散歩": "散歩は歩くことで、工事の内容として成り立たない。"}, "sentence_index": 0, "correct_answer": "導水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ふくらんだ風船を導水して、空気を抜いた。", "explanation": "風船の空気を抜く動作に、水を流す導水は使えない。"}, {"text": "先生は迷った生徒を正しい道へ導水した。", "explanation": "人を正しい方へ案内することに、水を流す導水は使えない。"}, {"text": "ハンドルを右へ導水して、車線を変えた。", "explanation": "ハンドルを切る動作に、水を流す導水は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38464, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "導水", "is_correct": true, "explanation": "川の水を別の池へ流して被害を防ぐ行為として、この文に合う。"}, {"text": "掃除", "is_correct": false, "explanation": "掃除は場所を清める行為で、別の池へ水を送る行為の空欄には合わない。"}, {"text": "読書", "is_correct": false, "explanation": "読書は本を読むことで、水の移動の文脈には入らない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩くことで、川の水を池に送る文には入らない。"}], "explanations": {"導水": "川の水を別の池へ流して被害を防ぐ行為として、この文に合う。", "掃除": "掃除は場所を清める行為で、別の池へ水を送る行為の空欄には合わない。", "読書": "読書は本を読むことで、水の移動の文脈には入らない。", "散歩": "散歩は歩くことで、川の水を池に送る文には入らない。"}, "sentence_index": 6, "correct_answer": "導水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "断水の間、市は給水車で住民へ導水した。", "explanation": "給水車で住民に水を配ることは、水路や管で流す導水ではない。"}, {"text": "消防車が火元へ導水して、火が消えた。", "explanation": "消火の水を火元へ勢いよく吹きかけるのは放水で、水路で送る導水ではない。"}, {"text": "重い箱を、ベルトコンベアで倉庫へ導水した。", "explanation": "箱は水ではないので、水を流す導水は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38464, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は、ため池の水を畑へ導水しる計画を発表した。", "corrected_sentence": "市は、ため池の水を畑へ導水する計画を発表した。", "error_description": "「導水する」の「する」を「しる」と誤っている。動詞の活用の誤りで、正しくは「する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38464, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大雨に備えて、導水へ必要な管を用意した。", "corrected_sentence": "大雨に備えて、導水に必要な管を用意した。", "error_description": "「〜に必要」の「に」が正しい。「へ」は方向を表すので、必要な条件を示せない（助詞の誤り）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38465, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「導水が止まった」で、止まる主体を示す格助詞。ここに合う。"}, {"text": "を", "is_correct": false, "explanation": "「導水を止まった」は「止まる」が自動詞で目的語を取れないので不自然。"}, {"text": "に", "is_correct": false, "explanation": "「導水に止まった」は相手や場所を示すが、止まる主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「導水へ止まった」は方向を示すが、止まる主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「導水が止まった」で、止まる主体を示す格助詞。ここに合う。", "を": "「導水を止まった」は「止まる」が自動詞で目的語を取れないので不自然。", "に": "「導水に止まった」は相手や場所を示すが、止まる主語にはならない。", "へ": "「導水へ止まった」は方向を示すが、止まる主語にならない。"}, "error_tags": {"を": "目的格", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38465, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38465, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "水を、水路や管などを使って、必要な場所へと送り届けること。", "primary_collocate": null, "pronunciation": "どうすい", "ipa": "doːsɯi", "syllable_count": 4, "sentences": [{"text": "工場では、パイプを使って川の水を敷地内のタンクへ導水している。", "target_word": "導水", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、パイプを使[つか]って川[かわ]の水[みず]を敷地内[しきちない]のタンクへ導水[どうすい]している。", "sentence_source": "generated"}, {"text": "導水が止まったせいで、町の一部で水が出なくなった。", "target_word": "導水", "complexity_tier": "T3", "furigana": "導水[どうすい]が止[と]まったせいで、町[まち]の一部[いちぶ]で水[みず]が出[で]なくなった。", "sentence_source": "generated"}, {"text": "山の湧き水を、細い管で畑まで導水する仕組みを作った。", "target_word": "導水", "complexity_tier": "T3", "furigana": "山[やま]の湧[わ]き水[みず]を、細[ほそ]い管[くだ]で畑[はたけ]まで導水[どうすい]する仕組[しく]みを作[つく]った。", "sentence_source": "generated"}, {"text": "水路が古くなったため、導水の効率が悪くなっている。", "target_word": "導水", "complexity_tier": "T3", "furigana": "水路[すいろ]が古[ふる]くなったため、導水[どうすい]の効率[こうりつ]が悪[わる]くなっている。", "sentence_source": "generated"}, {"text": "夏の渇水に備えて、別の川から貯水池へ導水することが決まった。", "target_word": "導水", "complexity_tier": "T3", "furigana": "夏[なつ]の渇水[かっすい]に備[そな]えて、別[べつ]の川[かわ]から貯水池[ちょすいち]へ導水[どうすい]することが決[き]まった。", "sentence_source": "generated"}, {"text": "導水の量を調整するために、入口に水門が設けられている。", "target_word": "導水", "complexity_tier": "T3", "furigana": "導水[どうすい]の量[りょう]を調整[ちょうせい]するために、入口[いりぐち]に水門[すいもん]が設[もう]けられている。", "sentence_source": "generated"}, {"text": "市は、新しい水源から浄水場への導水を来月から始める予定だ。", "target_word": "導水", "complexity_tier": "T3", "furigana": "市[し]は、新[あたら]しい水源[すいげん]から浄水場[じょうすいじょう]への導水[どうすい]を来月[らいげつ]から始[はじ]める予定[よてい]だ。", "sentence_source": "generated"}, {"text": "農家の人たちは、田植えの時期に合わせて田へ導水する。", "target_word": "導水", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]たちは、田植[たう]えの時期[じき]に合[あ]わせて田[た]へ導水[どうすい]する。", "sentence_source": "generated"}, {"text": "地下の管で導水すれば、水が蒸発して減ることも少ない。", "target_word": "導水", "complexity_tier": "T3", "furigana": "地下[ちか]の管[くだ]で導水[どうすい]すれば、水[みず]が蒸発[じょうはつ]して減[へ]ることも少[すく]ない。", "sentence_source": "generated"}, {"text": "寒い地方では、凍結を防ぐために導水の管を地中深くに埋める。", "target_word": "導水", "complexity_tier": "T3", "furigana": "寒[さむ]い地方[ちほう]では、凍結[とうけつ]を防[ふせ]ぐために導水[どうすい]の管[くだ]を地中[ちちゅう]深[ふか]くに埋[う]める。", "sentence_source": "generated"}], "morphological_forms": [{"form": "導水", "label": "基本形"}, {"form": "導水する", "label": "サ変動詞"}], "register": "neutral", "sense_fingerprint": "水路や管で、必要な場所へ水を送り届けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89bcd18f-d47f-4b0f-88fb-abadee0257a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38465, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "導水", "is_correct": true, "explanation": "パイプで川の水をタンクへ送る行為として、この文に合う。"}, {"text": "掃除", "is_correct": false, "explanation": "掃除は汚れを落とす行為で、水を送る文の空欄には合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩くことで、水を送る行為として成り立たない。"}, {"text": "読書", "is_correct": false, "explanation": "読書は本を読むことで、水を送る文脈には入らない。"}], "explanations": {"導水": "パイプで川の水をタンクへ送る行為として、この文に合う。", "掃除": "掃除は汚れを落とす行為で、水を送る文の空欄には合わない。", "散歩": "散歩は歩くことで、水を送る行為として成り立たない。", "読書": "読書は本を読むことで、水を送る文脈には入らない。"}, "sentence_index": 0, "correct_answer": "導水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "コップに水を導水して、一気に飲んだ。", "explanation": "コップに水を入れる動作は注ぐことで、水路や管で送る導水は使わない。"}, {"text": "大雨で川の水が畑へ導水して、作物が流された。", "explanation": "水が意図せず流れ込む話で、人が道をつくって送る導水とは違う。"}, {"text": "工場が有害な煙を導水して、空が黄色くなった。", "explanation": "煙は水ではないので、水を送る導水は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38465, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "導水", "is_correct": true, "explanation": "新しい水源から浄水場へ水を送る計画の語として、この文に合う。"}, {"text": "洗濯", "is_correct": false, "explanation": "洗濯は衣類を洗うことで、水源から浄水場への水の送りには合わない。"}, {"text": "採点", "is_correct": false, "explanation": "採点は答案に点数をつけることで、浄水場へ水を送る予定の空欄には合わない。"}, {"text": "試食", "is_correct": false, "explanation": "試食は料理の味を確かめることで、水を浄水場へ送る予定の文には合わない。"}], "explanations": {"導水": "新しい水源から浄水場へ水を送る計画の語として、この文に合う。", "洗濯": "洗濯は衣類を洗うことで、水源から浄水場への水の送りには合わない。", "採点": "採点は答案に点数をつけることで、浄水場へ水を送る予定の空欄には合わない。", "試食": "試食は料理の味を確かめることで、水を浄水場へ送る予定の文には合わない。"}, "sentence_index": 6, "correct_answer": "導水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "断水の時、市は給水所で住民へ導水しはじめた。", "explanation": "住民に水を配る話で、水路や管で流す導水とは違う。"}, {"text": "先生は迷った生徒を正しい道へ導水した。", "explanation": "人を正しい方へ案内する話に、水を送る導水は使えない。"}, {"text": "重い荷物を、地下室へ導水して運んだ。", "explanation": "荷物は水ではないので、水を流す導水は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38465, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ダムの水は、長い管を通って浄水場へ導水しられる。", "corrected_sentence": "ダムの水は、長い管を通って浄水場へ導水される。", "error_description": "「導水する」の受け身は「導水される」。「導水しられる」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38465, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "凍える冬には、導水をの管を地中深くに埋めておく。", "corrected_sentence": "凍える冬には、導水の管を地中深くに埋めておく。", "error_description": "「導水の管」の「の」の前に余計な「を」が入っている（助詞の誤り）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38466, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「流れて」は通り道を「を」で示すので、チャンネルを流れて池に集まる文に合う。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す「で」だが、通り道として流れる動作は「を」で表すので、ここでは合わない。"}, {"text": "の", "is_correct": false, "explanation": "名詞を修飾する「の」は、動詞「流れて」の前には置けないので文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す「と」は、動詞「流れて」の目的語の位置には使えないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「流れて」は通り道を「を」で示すので、チャンネルを流れて池に集まる文に合う。", "で": "場所や手段を示す「で」だが、通り道として流れる動作は「を」で表すので、ここでは合わない。", "の": "名詞を修飾する「の」は、動詞「流れて」の前には置けないので文が成り立たない。", "と": "並列や相手を示す「と」は、動詞「流れて」の目的語の位置には使えないので合わない。"}, "error_tags": {"で": "手段・場所", "の": "連体修飾", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38466, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "作る対象を示す「を」で、「チャンネルを作っている」と成り立つので正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」を置くと主語が二つになり、「作っている」の目的語が立たないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "目的地や相手を示す「に」は、作る対象を表せないので文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、作る対象にはならないので、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "作る対象を示す「を」で、「チャンネルを作っている」と成り立つので正しい。", "が": "主語を示す「が」を置くと主語が二つになり、「作っている」の目的語が立たないので合わない。", "に": "目的地や相手を示す「に」は、作る対象を表せないので文が成り立たない。", "へ": "方向を示す「へ」は、作る対象にはならないので、文が成り立たない。"}, "error_tags": {"が": "主語", "に": "目的地・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38466, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "水を遠くへ運ぶための、細長い道のことです。", "primary_collocate": null, "pronunciation": "ちゃんねる", "ipa": "tɕaɲneɾɯ", "syllable_count": 4, "sentences": [{"text": "川から畑まで水を運ぶために、長いチャンネルを掘った。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "川[かわ]から畑[はたけ]まで水[みず]を運[はこ]ぶために、長[なが]いチャンネルを掘[ほ]った。", "sentence_source": "generated"}, {"text": "雨水は石でできたチャンネルを流れて、池に集まる。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "雨水[あまみず]は石[いし]でできたチャンネルを流[なが]れて、池[いけ]に集[あつ]まる。", "sentence_source": "generated"}, {"text": "村の人たちは、山の水を町へ送るチャンネルを作った。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "村[むら]の人[ひと]たちは、山[やま]の水[みず]を町[まち]へ送[おく]るチャンネルを作[つく]った。", "sentence_source": "generated"}, {"text": "チャンネルが土でふさがったので、水が畑に届かなくなった。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "チャンネルが土[つち]でふさがったので、水[みず]が畑[はたけ]に届[とど]かなくなった。", "sentence_source": "generated"}, {"text": "このチャンネルのおかげで、遠くの田んぼにも水が行く。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "このチャンネルのおかげで、遠[とお]くの田[た]んぼにも水[みず]が行[い]く。", "sentence_source": "generated"}, {"text": "古い城には、地下に水を通すチャンネルが残っている。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "古[ふる]い城[しろ]には、地下[ちか]に水[みず]を通[とお]すチャンネルが残[のこ]っている。", "sentence_source": "generated"}, {"text": "大雨のあとは、チャンネルのごみを取って水を流しやすくする。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "大雨[おおあめ]のあとは、チャンネルのごみを取[と]って水[みず]を流[なが]しやすくする。", "sentence_source": "generated"}, {"text": "工事の人が、道のわきに雨水用のチャンネルを作っている。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]が、道[みち]のわきに雨水[あまみず]用[よう]のチャンネルを作[つく]っている。", "sentence_source": "generated"}, {"text": "細いチャンネルを通って、水がゆっくり湖へ流れていく。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "細[ほそ]いチャンネルを通[とお]って、水[みず]がゆっくり湖[みずうみ]へ流[なが]れていく。", "sentence_source": "generated"}, {"text": "水が足りない土地では、チャンネルを長くのばして川の水を引く。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "水[みず]が足[た]りない土地[とち]では、チャンネルを長[なが]くのばして川[かわ]の水[みず]を引[ひ]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "チャンネル", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "水を遠くへ運ぶ細長い水の通り道(水路)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e41a0f0-a380-46ef-b279-79ccdfb5e191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38466, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "チャンネル", "is_correct": true, "explanation": "〈水を遠くへ運ぶ細長い水路〉の意味で、掘って作るものなので文に合う。"}, {"text": "ポンプ", "is_correct": false, "explanation": "水を汲み上げる機械で、掘って作るものではないので「長い___を掘った」に入らない。"}, {"text": "バルブ", "is_correct": false, "explanation": "水の流れを止める部品で、掘る対象にはならないので文が成り立たない。"}, {"text": "扇風機", "is_correct": false, "explanation": "風を送る家電で、長く掘るものではないので、水を畑へ運ぶ文脈に合わない。"}], "explanations": {"チャンネル": "〈水を遠くへ運ぶ細長い水路〉の意味で、掘って作るものなので文に合う。", "ポンプ": "水を汲み上げる機械で、掘って作るものではないので「長い___を掘った」に入らない。", "バルブ": "水の流れを止める部品で、掘る対象にはならないので文が成り立たない。", "扇風機": "風を送る家電で、長く掘るものではないので、水を畑へ運ぶ文脈に合わない。"}, "sentence_index": 0, "correct_answer": "チャンネル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台所の水が止まらないので、チャンネルの蛇口を閉めた。", "explanation": "ここは〈蛇口〉の意味。水を出し止める器具を指すので、水が流れる細長い道のチャンネルとは合わない。"}, {"text": "夜は、チャンネルを変えて好きな番組を見た。", "explanation": "ここは〈テレビの放送局〉の意味。番組を選ぶ放送の区分で、水が流れる細長い道のチャンネルとは違うので合わない。"}, {"text": "問題を解くチャンネルは、三つ考えられる。", "explanation": "ここは〈方法〉の意味。問題の解き方を指すもので、水を送る細長い道とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38466, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "チャンネル", "is_correct": true, "explanation": "〈水が流れる細長い水路〉の意味で、ごみを取って水を流しやすくする文脈に合う。"}, {"text": "ピアノ", "is_correct": false, "explanation": "楽器で、水を流す仕組みにはならないので、ごみを取る対象として文が成り立たない。"}, {"text": "ソファ", "is_correct": false, "explanation": "家具で、水の通り道ではないので、ごみを取って水を流しやすくする話に合わない。"}, {"text": "ラジオ", "is_correct": false, "explanation": "電化製品で、水を流す通路ではないので、大雨のあとの掃除の文脈に合わない。"}], "explanations": {"チャンネル": "〈水が流れる細長い水路〉の意味で、ごみを取って水を流しやすくする文脈に合う。", "ピアノ": "楽器で、水を流す仕組みにはならないので、ごみを取る対象として文が成り立たない。", "ソファ": "家具で、水の通り道ではないので、ごみを取って水を流しやすくする話に合わない。", "ラジオ": "電化製品で、水を流す通路ではないので、大雨のあとの掃除の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "チャンネル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "掃除機のプラグを壁のチャンネルに差し込んだ。", "explanation": "ここは〈電源の差し込み口〉の意味。水の通り道を指すチャンネルに電気プラグは差せないので合わない。"}, {"text": "夕方は、テレビのチャンネルを変えて野球を見た。", "explanation": "ここは〈テレビの放送局〉の意味。番組を選ぶ放送の区分で、水を通す道のチャンネルとは違うので合わない。"}, {"text": "夏の夜はチャンネルを閉めて、冷房を入れた。", "explanation": "ここは〈窓〉の意味。開け閉めする窓を指し、水を通す細長い通路のチャンネルとは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38466, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山の水を町へ送るために、チャンネルに作った。", "corrected_sentence": "山の水を町へ送るために、チャンネルを作った。", "error_description": "「作る」の目的語は「を」で示す。「チャンネルに作った」は助詞「に」が誤り。正しくは「チャンネルを作った」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38466, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "川の岸に、水を通すチャンネルを掘るている。", "corrected_sentence": "川の岸に、水を通すチャンネルを掘っている。", "error_description": "動詞「掘る」の「ている」形は「掘っている」。「掘るている」は活用の誤りで、正しい形は「掘っている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38467, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「古くなって水がもれている」の主語を示す「が」で、チャンネルが主語になるので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」を置くと、直後に目的語を取る動詞がなく、「古くなって」と続くので成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "名詞を修飾する「の」は、「古くなって水がもれている」という文の主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す「と」は二つの名詞をつなぐ用法で、ここでは主語を示せないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「古くなって水がもれている」の主語を示す「が」で、チャンネルが主語になるので正しい。", "を": "「を」を置くと、直後に目的語を取る動詞がなく、「古くなって」と続くので成り立たない。", "の": "名詞を修飾する「の」は、「古くなって水がもれている」という文の主語にはならない。", "と": "並列を示す「と」は二つの名詞をつなぐ用法で、ここでは主語を示せないので合わない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38467, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38467, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "水や情報などを送るための、細長い通路や経路のこと。", "primary_collocate": null, "pronunciation": "ちゃんねる", "ipa": "tɕaɲneɾɯ", "syllable_count": 4, "sentences": [{"text": "会社は、お客さんに情報を送るチャンネルを三つ持っている。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、お客[きゃく]さんに情報[じょうほう]を送[おく]るチャンネルを三[みっ]つ持[も]っている。", "sentence_source": "generated"}, {"text": "水を畑に送るチャンネルが、古くなって水がもれている。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "水[みず]を畑[はたけ]に送[おく]るチャンネルが、古[ふる]くなって水[みず]がもれている。", "sentence_source": "generated"}, {"text": "連絡のチャンネルが一つしかないと、事故のときに困る。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "連絡[れんらく]のチャンネルが一[ひと]つしかないと、事故[じこ]のときに困[こま]る。", "sentence_source": "generated"}, {"text": "商品を売るチャンネルは、ネットと店の二つだ。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "商品[しょうひん]を売[う]るチャンネルは、ネットと店[みせ]の二[ふた]つだ。", "sentence_source": "generated"}, {"text": "町の水は、地下のチャンネルを通って工場に届く。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "町[まち]の水[みず]は、地下[ちか]のチャンネルを通[とお]って工場[こうじょう]に届[とど]く。", "sentence_source": "generated"}, {"text": "先生への連絡は、メールというチャンネルで行う。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "先生[せんせい]への連絡[れんらく]は、メールというチャンネルで行[おこな]う。", "sentence_source": "generated"}, {"text": "水を流すチャンネルがせまいと、大雨のとき水があふれる。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "水[みず]を流[なが]すチャンネルがせまいと、大雨[おおあめ]のとき水[みず]があふれる。", "sentence_source": "generated"}, {"text": "市は、住民に災害の情報を伝えるチャンネルを増やした。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "市[し]は、住民[じゅうみん]に災害[さいがい]の情報[じょうほう]を伝[つた]えるチャンネルを増[ふ]やした。", "sentence_source": "generated"}, {"text": "意見を伝えるチャンネルがないので、社員は不満をためている。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "意見[いけん]を伝[つた]えるチャンネルがないので、社員[しゃいん]は不満[ふまん]をためている。", "sentence_source": "generated"}, {"text": "工場では、冷たい水を機械に送るチャンネルを新しく作った。", "target_word": "チャンネル", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、冷[つめ]たい水[みず]を機械[きかい]に送[おく]るチャンネルを新[あたら]しく作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "チャンネル", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "水や情報を送り届けるための通路・経路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e41a0f0-a380-46ef-b279-79ccdfb5e191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38467, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "チャンネル", "is_correct": true, "explanation": "〈情報を送る経路〉の意味で、会社が三つ持つ連絡の経路として文に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "家電で、情報を送る経路ではないので「三つ持っている」の対象にならない。"}, {"text": "座布団", "is_correct": false, "explanation": "布製の敷物で、情報を送る役目はないので、お客さんに情報を送る文に合わない。"}, {"text": "ペンギン", "is_correct": false, "explanation": "動物で、情報を送る経路にはなれないので、会社が持つという文が成り立たない。"}], "explanations": {"チャンネル": "〈情報を送る経路〉の意味で、会社が三つ持つ連絡の経路として文に合う。", "冷蔵庫": "家電で、情報を送る経路ではないので「三つ持っている」の対象にならない。", "座布団": "布製の敷物で、情報を送る役目はないので、お客さんに情報を送る文に合わない。", "ペンギン": "動物で、情報を送る経路にはなれないので、会社が持つという文が成り立たない。"}, "sentence_index": 0, "correct_answer": "チャンネル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "エレベーターのチャンネルを押して、五階に上がった。", "explanation": "ここは〈ボタン〉の意味。押して機械を動かす部品を指し、情報を送る経路の意味では合わない。"}, {"text": "夕方は、テレビのチャンネルを変えて、料理番組を見た。", "explanation": "ここは〈テレビの放送局〉の意味。番組を選ぶ放送の区分で、物や情報を送る経路とは違うので合わない。"}, {"text": "ラジオのチャンネルを合わせて、天気予報を聞いた。", "explanation": "ここは〈周波数〉の意味。電波を選ぶ数字のことで、物や情報の通り道とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38467, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "チャンネル", "is_correct": true, "explanation": "〈水を流す細長い通路〉の意味で、せまいと水があふれるという文脈に合う。"}, {"text": "ベッド", "is_correct": false, "explanation": "寝るための家具で、水を流す通路ではないので、せまいと水があふれる話にならない。"}, {"text": "テント", "is_correct": false, "explanation": "布製の住居で、水を流す役目はないので、大雨で水があふれる文に合わない。"}, {"text": "本棚", "is_correct": false, "explanation": "本を置く家具で、水を流す役目がないので、文の意味が通らない。"}], "explanations": {"チャンネル": "〈水を流す細長い通路〉の意味で、せまいと水があふれるという文脈に合う。", "ベッド": "寝るための家具で、水を流す通路ではないので、せまいと水があふれる話にならない。", "テント": "布製の住居で、水を流す役目はないので、大雨で水があふれる文に合わない。", "本棚": "本を置く家具で、水を流す役目がないので、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "チャンネル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕飯のあと、チャンネルを変えてドラマを見た。", "explanation": "ここは〈テレビの放送局〉の意味。番組を選ぶ区分で、物や情報の通り道とは違うので合わない。"}, {"text": "洗った服を、チャンネルに干した。", "explanation": "ここは〈物干し〉の意味。服を干す道具を指すもので、水や情報の通り道の意味では合わない。"}, {"text": "友だちにチャンネルをかけた。", "explanation": "ここは〈電話〉の意味。電話をかける動作の対象で、通り道の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38467, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "連絡のチャンネルに増やすことで、お客さんの不満が減った。", "corrected_sentence": "連絡のチャンネルを増やすことで、お客さんの不満が減った。", "error_description": "「増やす」の対象は「を」で示す。「チャンネルに増やす」は助詞「に」が誤り。正しくは「チャンネルを増やす」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38467, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しいチャンネルを作るたので、情報がすぐ届くようになった。", "corrected_sentence": "新しいチャンネルを作ったので、情報がすぐ届くようになった。", "error_description": "動詞「作る」の過去形は「作った」。「作るた」は活用の誤りで、正しい形は「作った」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38468, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「水源は」で、水源が文の主題になる。「町の水道の水源は、大きなダムだ」と自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "「水源を、大きなダムだ」では目的語になり、断定の「ダムだ」と続かない。"}, {"text": "で", "is_correct": false, "explanation": "「水源で、大きなダムだ」は場所や手段を表す助詞で、断定の文に合わない。"}, {"text": "から", "is_correct": false, "explanation": "「水源から、大きなダムだ」は起点を表す助詞で、主題を示す文に合わない。"}], "correct_answer": "は", "explanations": {"は": "「水源は」で、水源が文の主題になる。「町の水道の水源は、大きなダムだ」と自然につながる。", "を": "「水源を、大きなダムだ」では目的語になり、断定の「ダムだ」と続かない。", "で": "「水源で、大きなダムだ」は場所や手段を表す助詞で、断定の文に合わない。", "から": "「水源から、大きなダムだ」は起点を表す助詞で、主題を示す文に合わない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38468, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「水源が」で、見つかったものが主語になる。「見つかった」と自然に合う。"}, {"text": "に", "is_correct": false, "explanation": "「に見つかる」は人などに発見される意味で、水源を主語にできない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう先を表すので、「見つかった」の主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表し、「見つかった」の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「水源が」で、見つかったものが主語になる。「見つかった」と自然に合う。", "に": "「に見つかる」は人などに発見される意味で、水源を主語にできない。", "へ": "「へ」は向かう先を表すので、「見つかった」の主語にはならない。", "と": "「と」は並列や相手を表し、「見つかった」の主語を示せない。"}, "error_tags": {"に": "相手・対象", "へ": "方向", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38468, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "水のもとになる場所のことです。", "primary_collocate": null, "pronunciation": "すいげん", "ipa": "sɯiɡeɴ", "syllable_count": 4, "sentences": [{"text": "この川の水源は、北の山の奥にあります。", "target_word": "水源", "complexity_tier": "T3", "furigana": "この川[かわ]の水源[すいげん]は、北[きた]の山[やま]の奥[おく]にあります。", "sentence_source": "generated"}, {"text": "町の水道の水源は、大きなダムだ。", "target_word": "水源", "complexity_tier": "T3", "furigana": "町[まち]の水道[すいどう]の水源[すいげん]は、大[おお]きなダムだ。", "sentence_source": "generated"}, {"text": "水源を守るために、山の木を切ることが禁じられている。", "target_word": "水源", "complexity_tier": "T3", "furigana": "水源[すいげん]を守[まも]るために、山[やま]の木[き]を切[き]ることが禁[きん]じられている。", "sentence_source": "generated"}, {"text": "水源が汚れると、下流の町の人々が困ってしまう。", "target_word": "水源", "complexity_tier": "T3", "furigana": "水源[すいげん]が汚[よご]れると、下流[かりゅう]の町[まち]の人々[ひとびと]が困[こま]ってしまう。", "sentence_source": "generated"}, {"text": "私たちは地図を見ながら、川の水源を探して歩いた。", "target_word": "水源", "complexity_tier": "T3", "furigana": "私[わたし]たちは地図[ちず]を見[み]ながら、川[かわ]の水源[すいげん]を探[さが]して歩[ある]いた。", "sentence_source": "generated"}, {"text": "干ばつが続き、村の水源が枯れてしまった。", "target_word": "水源", "complexity_tier": "T3", "furigana": "干[かん]ばつが続[つづ]き、村[むら]の水源[すいげん]が枯[か]れてしまった。", "sentence_source": "generated"}, {"text": "水源の近くでは、ごみを捨ててはいけません。", "target_word": "水源", "complexity_tier": "T3", "furigana": "水源[すいげん]の近[ちか]くでは、ごみを捨[す]ててはいけません。", "sentence_source": "generated"}, {"text": "新しい水源が見つかったおかげで、町は水不足から救われた。", "target_word": "水源", "complexity_tier": "T3", "furigana": "新[あたら]しい水源[すいげん]が見[み]つかったおかげで、町[まち]は水不足[みずぶそく]から救[すく]われた。", "sentence_source": "generated"}, {"text": "水源から離れるほど、川の幅は広くなる。", "target_word": "水源", "complexity_tier": "T3", "furigana": "水源[すいげん]から離[はな]れるほど、川[かわ]の幅[はば]は広[ひろ]くなる。", "sentence_source": "generated"}, {"text": "この地域は水源に恵まれているので、米作りが盛んだ。", "target_word": "水源", "complexity_tier": "T3", "furigana": "この地域[ちいき]は水源[すいげん]に恵[めぐ]まれているので、米作[こめづく]りが盛[さか]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水源", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "生活に使う水のもとになる場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89bcd18f-d47f-4b0f-88fb-abadee0257a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38468, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水源", "is_correct": true, "explanation": "「この川の水源」は川の水のもとになる場所を指し、「北の山の奥にあります」と自然につながる。"}, {"text": "水質", "is_correct": false, "explanation": "水質は水の性質を表す語で、場所として「北の山の奥にあります」とは結びつかない。"}, {"text": "水量", "is_correct": false, "explanation": "水量は水の量を表す語で、場所の所在を述べる文の主語にはならない。"}, {"text": "水温", "is_correct": false, "explanation": "水温は水の温度を表す語で、「北の山の奥にある」と言える対象ではない。"}], "explanations": {"水源": "「この川の水源」は川の水のもとになる場所を指し、「北の山の奥にあります」と自然につながる。", "水質": "水質は水の性質を表す語で、場所として「北の山の奥にあります」とは結びつかない。", "水量": "水量は水の量を表す語で、場所の所在を述べる文の主語にはならない。", "水温": "水温は水の温度を表す語で、「北の山の奥にある」と言える対象ではない。"}, "sentence_index": 0, "correct_answer": "水源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春になったので、水源を耕して稲の苗を植えた。", "explanation": "ここは〈水田〉の意味。耕して苗を植えるのは水田で、水源は水のもとになる場所を指すので合わない。"}, {"text": "この地域の地下には、水源が網の目のように広がっている。", "explanation": "ここは〈水脈〉の意味。地下水が網の目状に広がる様子は水脈で、水源は一つの地点を指すので合わない。"}, {"text": "この水源は畑の脇を流れ、田んぼへ水を運んでいる。", "explanation": "ここは〈水路〉の意味。畑の脇を流れて田へ水を運ぶのは水路で、水源は水の出てくる起点を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38468, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水源", "is_correct": true, "explanation": "「水源の近くでは、ごみを捨ててはいけません」は、水源を守るための注意として自然。"}, {"text": "水害", "is_correct": false, "explanation": "水害は洪水などの災害を指し、場所の近くを表せないので「の近くでは」と続かない。"}, {"text": "水圧", "is_correct": false, "explanation": "水圧は水が押す力を表す語で、場所の近くを示せない。"}, {"text": "水力", "is_correct": false, "explanation": "水力は水の力を利用するエネルギーを指し、場所としての「近く」は表せない。"}], "explanations": {"水源": "「水源の近くでは、ごみを捨ててはいけません」は、水源を守るための注意として自然。", "水害": "水害は洪水などの災害を指し、場所の近くを表せないので「の近くでは」と続かない。", "水圧": "水圧は水が押す力を表す語で、場所の近くを示せない。", "水力": "水力は水の力を利用するエネルギーを指し、場所としての「近く」は表せない。"}, "sentence_index": 6, "correct_answer": "水源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この湾は魚が多く、水源での漁業が盛んだ。", "explanation": "ここは〈水域〉の意味。魚がすむ海や湖の一定の範囲は水域で、水源は水が出てくる起点を指すので合わない。"}, {"text": "朝の湖は静かで、水源がきらきらと光っている。", "explanation": "ここは〈水面〉の意味。きらきら光るのは水の表面で、水源は水が出てくる場所を指すので合わない。"}, {"text": "台風で川が増水し、水源が町中に広がった。", "explanation": "ここは〈水害〉の意味。町中に広がるのは洪水の被害で、水源は水が出てくる場所なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38468, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山の奥にある水源へ、清らかな水が流れ出している。", "corrected_sentence": "山の奥にある水源から、清らかな水が流れ出している。", "error_description": "「水源から」が正しい。水が流れ出す起点は「から」で表す。「へ」は向かう先を示すので、流れ出る動きと合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38468, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水源を水が汚れないよう、町は畑に農薬を使わない。", "corrected_sentence": "水源の水が汚れないよう、町は畑に農薬を使わない。", "error_description": "「水源の水」の「の」が正しい。「水源」は「水」を修飾する名詞なので「の」でつなぐ。「を」にすると「水が汚れない」と文がつながらない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
