INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38469, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「水源になる」の「に」。なる結果を示す。「湖が水源になっている」と自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "「水源を、なっている」は目的語になり、「なる」の結果を表せない。"}, {"text": "で", "is_correct": false, "explanation": "「水源で、なっている」は場所や手段を表し、「なる」の結果にならない。"}, {"text": "から", "is_correct": false, "explanation": "「水源から、なっている」は起点を表し、変化の結果を示せない。"}], "correct_answer": "に", "explanations": {"に": "「水源になる」の「に」。なる結果を示す。「湖が水源になっている」と自然につながる。", "を": "「水源を、なっている」は目的語になり、「なる」の結果を表せない。", "で": "「水源で、なっている」は場所や手段を表し、「なる」の結果にならない。", "から": "「水源から、なっている」は起点を表し、変化の結果を示せない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38469, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "水がわき出る、またはためられている場所。川や湖の始まりとなる場所。", "primary_collocate": null, "pronunciation": "すいげん", "ipa": "sɯiɡeɴ", "syllable_count": 4, "sentences": [{"text": "利根川の水源は、群馬県の山の中にある。", "target_word": "水源", "complexity_tier": "T3", "furigana": "利根川[とねがわ]の水源[すいげん]は、群馬県[ぐんまけん]の山[やま]の中[なか]にある。", "sentence_source": "generated"}, {"text": "岩の間から水がわき出ている場所が、この川の水源だ。", "target_word": "水源", "complexity_tier": "T3", "furigana": "岩[いわ]の間[あいだ]から水[みず]がわき出[で]ている場所[ばしょ]が、この川[かわ]の水源[すいげん]だ。", "sentence_source": "generated"}, {"text": "この湖の水源は、山からの雪解け水と地下の泉である。", "target_word": "水源", "complexity_tier": "T3", "furigana": "この湖[みずうみ]の水源[すいげん]は、山[やま]からの雪解[ゆきど]け水[みず]と地下[ちか]の泉[いずみ]である。", "sentence_source": "generated"}, {"text": "水源まで登ると、小さな泉から冷たい水が出ていた。", "target_word": "水源", "complexity_tier": "T3", "furigana": "水源[すいげん]まで登[のぼ]ると、小[ちい]さな泉[いずみ]から冷[つめ]たい水[みず]が出[で]ていた。", "sentence_source": "generated"}, {"text": "大きな川も、水源をたどれば細い流れから始まっている。", "target_word": "水源", "complexity_tier": "T3", "furigana": "大[おお]きな川[かわ]も、水源[すいげん]をたどれば細[ほそ]い流[なが]れから始[はじ]まっている。", "sentence_source": "generated"}, {"text": "このダムは、街の水源として大切に管理されている。", "target_word": "水源", "complexity_tier": "T3", "furigana": "このダムは、街[まち]の水源[すいげん]として大切[たいせつ]に管理[かんり]されている。", "sentence_source": "generated"}, {"text": "水源の森を守る活動に、地元の子どもたちも参加している。", "target_word": "水源", "complexity_tier": "T3", "furigana": "水源[すいげん]の森[もり]を守[まも]る活動[かつどう]に、地元[じもと]の子[こ]どもたちも参加[さんか]している。", "sentence_source": "generated"}, {"text": "湖が水源になっているため、この町の水はとても澄んでいる。", "target_word": "水源", "complexity_tier": "T3", "furigana": "湖[みずうみ]が水源[すいげん]になっているため、この町[まち]の水[みず]はとても澄[す]んでいる。", "sentence_source": "generated"}, {"text": "川の水源を示す石碑が、山道のわきに立っている。", "target_word": "水源", "complexity_tier": "T3", "furigana": "川[かわ]の水源[すいげん]を示[しめ]す石碑[せきひ]が、山道[やまみち]のわきに立[た]っている。", "sentence_source": "generated"}, {"text": "雪の多い年は、水源の水量も増える。", "target_word": "水源", "complexity_tier": "T3", "furigana": "雪[ゆき]の多[おお]い年[とし]は、水源[すいげん]の水量[すいりょう]も増[ふ]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水源", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "水がわき出る場所や水をためる場所。川や湖の始まりの地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89bcd18f-d47f-4b0f-88fb-abadee0257a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38469, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水源", "is_correct": true, "explanation": "「利根川の水源は、群馬県の山の中にある」は、川の始まりの場所の所在として自然。"}, {"text": "流量", "is_correct": false, "explanation": "流量は流れる水の量を表し、場所として「山の中にある」とは結びつかない。"}, {"text": "水圧", "is_correct": false, "explanation": "水圧は水が押す力を表し、場所の所在を述べる主語にならない。"}, {"text": "水質", "is_correct": false, "explanation": "水質は水の性質を表し、「群馬県の山の中にある」と言える対象ではない。"}], "explanations": {"水源": "「利根川の水源は、群馬県の山の中にある」は、川の始まりの場所の所在として自然。", "流量": "流量は流れる水の量を表し、場所として「山の中にある」とは結びつかない。", "水圧": "水圧は水が押す力を表し、場所の所在を述べる主語にならない。", "水質": "水質は水の性質を表し、「群馬県の山の中にある」と言える対象ではない。"}, "sentence_index": 0, "correct_answer": "水源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "川の流れで水源を回し、粉をひいた。", "explanation": "ここは〈水車〉の意味。流れで回り粉をひく装置は水車で、水源は水が出てくる場所なので合わない。"}, {"text": "大雨の日は水源を閉じて、川の水が増えないようにした。", "explanation": "ここは〈水門〉の意味。川の水を止める門は水門で、水源は水の出てくる起点なので合わない。"}, {"text": "雨のあと、道の水源に子どもが入って遊んだ。", "explanation": "ここは〈水溜まり〉の意味。雨で道にできた溜まりは水溜まりで、水源は地面から水が湧く起点を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38469, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水源", "is_correct": true, "explanation": "「水源の森」は水源を守るための森で、守る活動の対象として自然。"}, {"text": "騒音", "is_correct": false, "explanation": "騒音は音の大きさを表す語で、「の森」の形では成り立たない。"}, {"text": "水害", "is_correct": false, "explanation": "水害は洪水などの災害を指し、守る活動の対象の森の名前にはならない。"}, {"text": "水温", "is_correct": false, "explanation": "水温は水の温度を表す語で、森の名前として成り立たない。"}], "explanations": {"水源": "「水源の森」は水源を守るための森で、守る活動の対象として自然。", "騒音": "騒音は音の大きさを表す語で、「の森」の形では成り立たない。", "水害": "水害は洪水などの災害を指し、守る活動の対象の森の名前にはならない。", "水温": "水温は水の温度を表す語で、森の名前として成り立たない。"}, "sentence_index": 6, "correct_answer": "水源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春は水源が早く解けて、川の水が急に増える。", "explanation": "ここは〈雪解け〉の意味。解けるのは雪で、水源は水が湧く場所を指すので合わない。"}, {"text": "滝の下では、水源が大きくはね上がって虹がかかった。", "explanation": "ここは〈水しぶき〉の意味。落ちる水が跳ね上がって散るのは水しぶきで、水源は水が出てくる場所なので合わない。"}, {"text": "窓に水源がついて、ガラスが曇った。", "explanation": "ここは〈水滴〉の意味。窓につく小さな水の粒は水滴で、水源は水のもとになる場所なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38469, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この岩の割れ目は、水源へ水がわき出す場所だ。", "corrected_sentence": "この岩の割れ目は、水源から水がわき出す場所だ。", "error_description": "「水源から」が正しい。水がわき出す起点は「から」で表す。「へ」は向かう先を示すので、わき出る動きと合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38469, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山の奥の泉が、この川の水源をなっている。", "corrected_sentence": "山の奥の泉が、この川の水源になっている。", "error_description": "「水源になっている」の「に」が正しい。「なる」は「Aが Bになる」の形で、結果を「に」で表す。「を」は使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38470, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "登る先や場所を示す「に」で、高地に登るという文に合う。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す「で」は、登る先を表す文には合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を表す「と」は、登る先を示せない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は、動詞の目標を示す位置に入らない。"}], "correct_answer": "に", "explanations": {"に": "登る先や場所を示す「に」で、高地に登るという文に合う。", "で": "場所や手段を示す「で」は、登る先を表す文には合わない。", "と": "相手や並列を表す「と」は、登る先を示せない。", "の": "連体修飾の「の」は、動詞の目標を示す位置に入らない。"}, "error_tags": {"で": "場所・手段の格", "と": "相手・並列の格", "の": "連体修飾の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38470, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "場所を示す「で」で、「高地では」の形として文に合う。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は、場所を示す位置では不自然になる。"}, {"text": "を", "is_correct": false, "explanation": "対象を示す「を」は、場所の位置には入らない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」は、「は」と重ねて使うと文の形が崩れる。"}], "correct_answer": "で", "explanations": {"で": "場所を示す「で」で、「高地では」の形として文に合う。", "へ": "方向を表す「へ」は、場所を示す位置では不自然になる。", "を": "対象を示す「を」は、場所の位置には入らない。", "が": "主語を示す「が」は、「は」と重ねて使うと文の形が崩れる。"}, "error_tags": {"へ": "方向の格", "を": "対象の格", "が": "主語の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38470, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面が高くなっている場所のことです。", "primary_collocate": null, "pronunciation": "こうち", "ipa": "koːtɕi", "syllable_count": 3, "sentences": [{"text": "この村は高地にあるので、夏でも涼しい。", "target_word": "高地", "complexity_tier": "T3", "furigana": "この村[むら]は高地[こうち]にあるので、夏[なつ]でも涼[すず]しい。", "sentence_source": "generated"}, {"text": "高地に登ると、町全体がよく見えた。", "target_word": "高地", "complexity_tier": "T3", "furigana": "高地[こうち]に登[のぼ]ると、町[まち]全体[ぜんたい]がよく見[み]えた。", "sentence_source": "generated"}, {"text": "川の水があふれたので、みんな高地へ逃げた。", "target_word": "高地", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]があふれたので、みんな高地[こうち]へ逃[に]げた。", "sentence_source": "generated"}, {"text": "高地は空気がうすいから、走るとすぐ疲れる。", "target_word": "高地", "complexity_tier": "T3", "furigana": "高地[こうち]は空気[くうき]がうすいから、走[はし]るとすぐ疲[つか]れる。", "sentence_source": "generated"}, {"text": "私たちは高地にテントを張って、朝を待った。", "target_word": "高地", "complexity_tier": "T3", "furigana": "私[わたし]たちは高地[こうち]にテントを張[は]って、朝[あさ]を待[ま]った。", "sentence_source": "generated"}, {"text": "低地は水に浸かったが、高地は無事だった。", "target_word": "高地", "complexity_tier": "T3", "furigana": "低地[ていち]は水[みず]に浸[つ]かったが、高地[こうち]は無事[ぶじ]だった。", "sentence_source": "generated"}, {"text": "高地で育った野菜は、甘みが強い。", "target_word": "高地", "complexity_tier": "T3", "furigana": "高地[こうち]で育[そだ]った野菜[やさい]は、甘[あま]みが強[つよ]い。", "sentence_source": "generated"}, {"text": "高地では朝晩の気温差が大きい。", "target_word": "高地", "complexity_tier": "T3", "furigana": "高地[こうち]では朝晩[あさばん]の気温差[きおんさ]が大[おお]きい。", "sentence_source": "generated"}, {"text": "地図を見ると、この道は高地へ続いている。", "target_word": "高地", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]ると、この道[みち]は高地[こうち]へ続[つづ]いている。", "sentence_source": "generated"}, {"text": "彼は高地の小さな町で生まれた。", "target_word": "高地", "complexity_tier": "T3", "furigana": "彼[かれ]は高地[こうち]の小[ちい]さな町[まち]で生[う]まれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高地", "label": "基本形"}], "register": "中立", "sense_fingerprint": "標高が高い場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '725786b7-83d1-4185-8797-adecf4153e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38470, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高地", "is_correct": true, "explanation": "地面が高くなっている場所で、村の位置を述べる文脈に合う。"}, {"text": "季節", "is_correct": false, "explanation": "「村は季節にある」は意味が通らず、場所を表さない。"}, {"text": "手紙", "is_correct": false, "explanation": "「村は手紙にある」は意味が通らず、場所を表さない。"}, {"text": "試験", "is_correct": false, "explanation": "「村は試験にある」は意味が通らず、場所を表さない。"}], "explanations": {"高地": "地面が高くなっている場所で、村の位置を述べる文脈に合う。", "季節": "「村は季節にある」は意味が通らず、場所を表さない。", "手紙": "「村は手紙にある」は意味が通らず、場所を表さない。", "試験": "「村は試験にある」は意味が通らず、場所を表さない。"}, "sentence_index": 0, "correct_answer": "高地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "高地は四国の県で、かつおが有名だ。", "explanation": "ここは県名の〈高知〉の意味（同じこうち）。標高が高い場所という意味ではない。"}, {"text": "高地が上がると、気温は下がる。", "explanation": "ここは〈高度〉の意味。高地は場所を指すので、上がるものとしては使わない。"}, {"text": "彼女の高地はとても澄んでいる。", "explanation": "ここは〈高音〉の意味。声の高い音域は高音と言い、高地は場所なので声の質には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38470, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高地", "is_correct": true, "explanation": "「高地で育った野菜」の形で、育つ場所を示す文脈に合う。"}, {"text": "教科書", "is_correct": false, "explanation": "「教科書で育った野菜」は意味が通らず、場所を表さない。"}, {"text": "名刺", "is_correct": false, "explanation": "「名刺で育った野菜」は意味が通らず、場所を表さない。"}, {"text": "調味料", "is_correct": false, "explanation": "「調味料で育った野菜」は意味が通らず、場所を表さない。"}], "explanations": {"高地": "「高地で育った野菜」の形で、育つ場所を示す文脈に合う。", "教科書": "「教科書で育った野菜」は意味が通らず、場所を表さない。", "名刺": "「名刺で育った野菜」は意味が通らず、場所を表さない。", "調味料": "「調味料で育った野菜」は意味が通らず、場所を表さない。"}, "sentence_index": 6, "correct_answer": "高地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この古い絵は、高地で売れた。", "explanation": "ここは〈高値〉の意味（高い値段で売れる）。高地は土地の高さを表すので、値段の意味では使わない。"}, {"text": "昨日から高地が出て、学校を休んだ。", "explanation": "ここは〈高熱〉の意味。高地は土地の高さなので、体温には使わない。"}, {"text": "テストで高地を取った。", "explanation": "ここは〈高得点〉の意味。高地は場所なので、点数の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38470, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町は高地へあるので、冬は寒い。", "corrected_sentence": "この町は高地にあるので、冬は寒い。", "error_description": "誤り：「高地へ」。正しくは「高地に」。存在する場所は「に」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38470, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "高地を育ったお茶は、香りがよい。", "corrected_sentence": "高地で育ったお茶は、香りがよい。", "error_description": "誤り：「高地を」。正しくは「高地で」。育つ場所は「で」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38471, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「高地の草原」のように「高地」と「草原」を結び、場所の修飾を作る。"}, {"text": "を", "is_correct": false, "explanation": "「高地を草原で」となり、目的語の役割がなく文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「高地に草原で」は場所の関係が成り立たず、不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すため「高地へ草原で」となり、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「高地の草原」のように「高地」と「草原」を結び、場所の修飾を作る。", "を": "「高地を草原で」となり、目的語の役割がなく文が成り立たない。", "に": "「高地に草原で」は場所の関係が成り立たず、不自然になる。", "へ": "方向を表すため「高地へ草原で」となり、意味が通らない。"}, "error_tags": {"を": "目的語", "に": "場所・時点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38471, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「高地のほうが」の形で、「高地」を名詞として「ほう」に続けて比べる文を作る。"}, {"text": "で", "is_correct": false, "explanation": "「高地でほうが」となり、比べる文の形が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「高地とほうが」となり、並列の意味にもならず不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すため「高地からほうが」となり、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「高地のほうが」の形で、「高地」を名詞として「ほう」に続けて比べる文を作る。", "で": "「高地でほうが」となり、比べる文の形が成り立たない。", "と": "「高地とほうが」となり、並列の意味にもならず不自然。", "から": "起点を表すため「高地からほうが」となり、文が成り立たない。"}, "error_tags": {"で": "場所・手段", "と": "並列", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38471, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "周囲よりも高くなっている土地。山や丘のような場所。", "primary_collocate": null, "pronunciation": "こうち", "ipa": "koːtɕi", "syllable_count": 3, "sentences": [{"text": "町の北には、広い高地が広がっている。", "target_word": "高地", "complexity_tier": "T3", "furigana": "町[まち]の北[きた]には、広[ひろ]い高地[こうち]が広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "高地の草原で、羊が草を食べていた。", "target_word": "高地", "complexity_tier": "T3", "furigana": "高地[こうち]の草原[そうげん]で、羊[ひつじ]が草[くさ]を食[た]べていた。", "sentence_source": "generated"}, {"text": "高地を越えると、急に海が見えてきた。", "target_word": "高地", "complexity_tier": "T3", "furigana": "高地[こうち]を越[こ]えると、急[きゅう]に海[うみ]が見[み]えてきた。", "sentence_source": "generated"}, {"text": "この高地は昔、城があった場所だ。", "target_word": "高地", "complexity_tier": "T3", "furigana": "この高地[こうち]は昔[むかし]、城[しろ]があった場所[ばしょ]だ。", "sentence_source": "generated"}, {"text": "高地から谷を見下ろすと、霧がかかっていた。", "target_word": "高地", "complexity_tier": "T3", "furigana": "高地[こうち]から谷[たに]を見下[みお]ろすと、霧[きり]がかかっていた。", "sentence_source": "generated"}, {"text": "冬になると、高地には早く雪が積もる。", "target_word": "高地", "complexity_tier": "T3", "furigana": "冬[ふゆ]になると、高地[こうち]には早[はや]く雪[ゆき]が積[つ]もる。", "sentence_source": "generated"}, {"text": "高地を走る鉄道は、景色がとてもきれいだ。", "target_word": "高地", "complexity_tier": "T3", "furigana": "高地[こうち]を走[はし]る鉄道[てつどう]は、景色[けしき]がとてもきれいだ。", "sentence_source": "generated"}, {"text": "低い土地より高地のほうが、洪水の心配が少ない。", "target_word": "高地", "complexity_tier": "T3", "furigana": "低[ひく]い土地[とち]より高地[こうち]のほうが、洪水[こうずい]の心配[しんぱい]が少[すく]ない。", "sentence_source": "generated"}, {"text": "私たちは高地でお茶を育てている。", "target_word": "高地", "complexity_tier": "T3", "furigana": "私[わたし]たちは高地[こうち]でお茶[ちゃ]を育[そだ]てている。", "sentence_source": "generated"}, {"text": "道は高地に入ると、急に細くなった。", "target_word": "高地", "complexity_tier": "T3", "furigana": "道[みち]は高地[こうち]に入[はい]ると、急[きゅう]に細[ほそ]くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高地", "label": "基本形"}], "register": "中立", "sense_fingerprint": "周囲より高い土地（山や丘）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '725786b7-83d1-4185-8797-adecf4153e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38471, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高地", "is_correct": true, "explanation": "「広い高地が広がっている」の空所に入り、周囲より高い土地を表す。"}, {"text": "高熱", "is_correct": false, "explanation": "熱は土地のように広がらないため、「広い高熱が広がっている」は成り立たない。"}, {"text": "高値", "is_correct": false, "explanation": "値段の高さを表す語で、「広い高値が広がっている」は意味をなさない。"}, {"text": "高層", "is_correct": false, "explanation": "高い階数の建物を指す語で、土地の広がりを表す文脈には合わない。"}], "explanations": {"高地": "「広い高地が広がっている」の空所に入り、周囲より高い土地を表す。", "高熱": "熱は土地のように広がらないため、「広い高熱が広がっている」は成り立たない。", "高値": "値段の高さを表す語で、「広い高値が広がっている」は意味をなさない。", "高層": "高い階数の建物を指す語で、土地の広がりを表す文脈には合わない。"}, "sentence_index": 0, "correct_answer": "高地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日から高地が出て、学校を休んだ。", "explanation": "ここは〈高熱〉の意味。高地は土地の高さを表すので、体温には使わない。"}, {"text": "飛行機は高地を保って飛んでいる。", "explanation": "ここは〈高度〉の意味。飛行機の高さは「高度を保つ」と言い、高地は場所の名前なので合わない。"}, {"text": "株価が高地を更新した。", "explanation": "ここは〈高値〉の意味。株価の最高値を更新すると言い、高地は土地を指すので使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38471, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高地", "is_correct": true, "explanation": "「高地を走る鉄道」の空所に入り、周囲より高い土地を走る意味になる。"}, {"text": "高僧", "is_correct": false, "explanation": "人を表す語で、鉄道が走る場所にはならない。"}, {"text": "高圧", "is_correct": false, "explanation": "電圧や気圧を表す語で、「〜を走る鉄道」の場所には入らない。"}, {"text": "高利", "is_correct": false, "explanation": "金利の高さを表す語で、場所を示す空所には合わない。"}], "explanations": {"高地": "「高地を走る鉄道」の空所に入り、周囲より高い土地を走る意味になる。", "高僧": "人を表す語で、鉄道が走る場所にはならない。", "高圧": "電圧や気圧を表す語で、「〜を走る鉄道」の場所には入らない。", "高利": "金利の高さを表す語で、場所を示す空所には合わない。"}, "sentence_index": 6, "correct_answer": "高地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この古い絵は、高地で売れた。", "explanation": "ここは〈高値〉の意味（高い値段で売れる）。高地は土地を表すので、値段の意味では使わない。"}, {"text": "彼女の高地はとても澄んでいる。", "explanation": "ここは〈高音〉の意味。声の高い音域は高音と言い、高地は場所を指すので声の質には使わない。"}, {"text": "父は高地なので、塩分を控えている。", "explanation": "ここは〈高血圧〉の意味。病気の状態を表す語で、高地は土地なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38471, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の北には、広い高地を広がっていた。", "corrected_sentence": "町の北には、広い高地が広がっていた。", "error_description": "助詞の誤り。「広がる」の主語になる「高地」には「が」を使う。「を」は目的語を示すので誤り（正：が）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38471, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "高地を走って鉄道は、景色がとても美しかった。", "corrected_sentence": "高地を走る鉄道は、景色がとても美しかった。", "error_description": "活用の誤り。名詞「鉄道」を修飾する「走る」は辞書形にする。「走って」では後ろの名詞に続かず、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38472, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「広がる」の場所を「に」で示すので、低地に田んぼが広がるという文になる。"}, {"text": "を", "is_correct": false, "explanation": "「広がる」は目的語を取らないので、「低地を広がる」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「低地と広がる」という文は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐので、「低地の、」と読点で文が切れてしまい不自然。"}], "correct_answer": "に", "explanations": {"に": "「広がる」の場所を「に」で示すので、低地に田んぼが広がるという文になる。", "を": "「広がる」は目的語を取らないので、「低地を広がる」は不自然。", "と": "「と」は並列や相手を示すので、「低地と広がる」という文は成り立たない。", "の": "「の」は名詞どうしをつなぐので、「低地の、」と読点で文が切れてしまい不自然。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "の": "修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38472, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「から」は起点を示すので、低地から高台までの距離を表す文になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、低地が歩くという文は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、低地より高台までの距離という文は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作の場所を示すが、距離の起点は「から」で示すのが自然。"}], "correct_answer": "から", "explanations": {"から": "「から」は起点を示すので、低地から高台までの距離を表す文になる。", "が": "「が」は主語を示すが、低地が歩くという文は成り立たない。", "より": "「より」は比較を示すので、低地より高台までの距離という文は意味が通らない。", "で": "「で」は動作の場所を示すが、距離の起点は「から」で示すのが自然。"}, "error_tags": {"が": "主語", "より": "比較", "で": "場所（動作）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38472, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面の高さが低い場所のことです。", "primary_collocate": null, "pronunciation": "ていち", "ipa": "teitɕi", "syllable_count": 3, "sentences": [{"text": "低地は雨が降ると水がたまりやすい。", "target_word": "低地", "complexity_tier": "T3", "furigana": "低地(ていち)は雨(あめ)が降(ふ)ると水(みず)がたまりやすい。", "sentence_source": "generated"}, {"text": "川の近くの低地に、広い田んぼが広がっている。", "target_word": "低地", "complexity_tier": "T3", "furigana": "川(かわ)の近(ちか)くの低地(ていち)に、広(ひろ)い田(た)んぼが広(ひろ)がっている。", "sentence_source": "generated"}, {"text": "台風の時、低地に住む人は高い場所へ避難した。", "target_word": "低地", "complexity_tier": "T3", "furigana": "台風(たいふう)の時(とき)、低地(ていち)に住(す)む人(ひと)は高(たか)い場所(ばしょ)へ避難(ひなん)した。", "sentence_source": "generated"}, {"text": "山を下りると、低地には大きな町があった。", "target_word": "低地", "complexity_tier": "T3", "furigana": "山(やま)を下(お)りると、低地(ていち)には大(おお)きな町(まち)があった。", "sentence_source": "generated"}, {"text": "高地は涼しいが、低地は夏に暑くなる。", "target_word": "低地", "complexity_tier": "T3", "furigana": "高地(こうち)は涼(すず)しいが、低地(ていち)は夏(なつ)に暑(あつ)くなる。", "sentence_source": "generated"}, {"text": "低地に家を建てるときは、水害に注意が必要だ。", "target_word": "低地", "complexity_tier": "T3", "furigana": "低地(ていち)に家(いえ)を建(た)てるときは、水害(すいがい)に注意(ちゅうい)が必要(ひつよう)だ。", "sentence_source": "generated"}, {"text": "この公園は低地にあるので、雨の後は池のようになる。", "target_word": "低地", "complexity_tier": "T3", "furigana": "この公園(こうえん)は低地(ていち)にあるので、雨(あめ)の後(あと)は池(いけ)のようになる。", "sentence_source": "generated"}, {"text": "低地から高台まで、歩いて十分ほどだ。", "target_word": "低地", "complexity_tier": "T3", "furigana": "低地(ていち)から高台(たかだい)まで、歩(ある)いて十分(じっぷん)ほどだ。", "sentence_source": "generated"}, {"text": "海に近い低地では、高潮の心配がある。", "target_word": "低地", "complexity_tier": "T3", "furigana": "海(うみ)に近(ちか)い低地(ていち)では、高潮(たかしお)の心配(しんぱい)がある。", "sentence_source": "generated"}, {"text": "水は高い所から低地へ流れていく。", "target_word": "低地", "complexity_tier": "T3", "furigana": "水(みず)は高(たか)い所(ところ)から低地(ていち)へ流(なが)れていく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "低地", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "地面の高さが低い場所(水がたまりやすい低い所)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0df70395-f463-48c9-9f7b-eb53760b6965') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38472, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低地", "is_correct": true, "explanation": "地面が低く水がたまりやすい土地を指し、雨が降ると水がたまるという文に合う。"}, {"text": "高台", "is_correct": false, "explanation": "高台は水が流れ落ちる高い場所なので、水がたまりやすいという内容と矛盾する。"}, {"text": "山頂", "is_correct": false, "explanation": "山頂は水が流れ去りやすい場所で、雨が降ると水がたまりやすいという文と合わない。"}, {"text": "高原", "is_correct": false, "explanation": "高原は傾斜があり水が引けやすいので、水がたまりやすいという文脈に合わない。"}], "explanations": {"低地": "地面が低く水がたまりやすい土地を指し、雨が降ると水がたまるという文に合う。", "高台": "高台は水が流れ落ちる高い場所なので、水がたまりやすいという内容と矛盾する。", "山頂": "山頂は水が流れ去りやすい場所で、雨が降ると水がたまりやすいという文と合わない。", "高原": "高原は傾斜があり水が引けやすいので、水がたまりやすいという文脈に合わない。"}, "sentence_index": 0, "correct_answer": "低地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この曲は低地の部分がとても美しく響く。", "explanation": "ここは〈低地〉の意味。低地は地面の低い土地で、音の高さには使わない（低音と言う）。"}, {"text": "この店は低地の値段で、いつも混んでいる。", "explanation": "ここは〈低地〉の意味。価格の安さは「安い」と言うので、低地は地形の語として使わない。"}, {"text": "彼は社会の低地にいたが、努力で今は上の地位にいる。", "explanation": "ここは〈低地〉の意味。低地は土地の高さを表す語なので、社会の階層や身分の高低には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38472, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低地", "is_correct": true, "explanation": "周囲より低く雨水が集まって池のようになる土地を指し、文の内容に合う。"}, {"text": "屋上", "is_correct": false, "explanation": "屋上は水がたまらないよう排水されるので、雨の後に池になるという文脈に合わない。"}, {"text": "海底", "is_correct": false, "explanation": "海底にある公園は想定しにくく、雨の後に池になるという内容と合わない。"}, {"text": "上空", "is_correct": false, "explanation": "上空には雨水が集まって池になることがなく、文脈と矛盾する。"}], "explanations": {"低地": "周囲より低く雨水が集まって池のようになる土地を指し、文の内容に合う。", "屋上": "屋上は水がたまらないよう排水されるので、雨の後に池になるという文脈に合わない。", "海底": "海底にある公園は想定しにくく、雨の後に池になるという内容と合わない。", "上空": "上空には雨水が集まって池になることがなく、文脈と矛盾する。"}, "sentence_index": 6, "correct_answer": "低地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この低地は高台の上にあり、見晴らしがよい。", "explanation": "ここは〈低地〉の意味。低地は周囲より低い土地なので、〈高地〉のように高い場所を指す使い方とは矛盾する。"}, {"text": "山の上の低地には、夏でも涼しい風が吹き抜ける。", "explanation": "ここは〈低地〉の意味。周囲より低い土地を指すので、〈高地〉の高い場所を表す使い方とは合わない。"}, {"text": "この小学校の低地のクラスは、算数が得意な子が集まる。", "explanation": "ここは〈低地〉の意味。低地は地形の語で、能力の段階には使わない（低学年や下位クラスと言う）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38472, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母の家は低地をあり、大雨のたびに床下が心配になる。", "corrected_sentence": "祖母の家は低地にあり、大雨のたびに床下が心配になる。", "error_description": "「ある」の場所は「に」で示す。「を」は目的語に付くので、「低地をあり」は不自然。正しくは「低地にあり」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38472, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "低地が水路は、雨の後に水があふれやすい。", "corrected_sentence": "低地の水路は、雨の後に水があふれやすい。", "error_description": "「低地」が「水路」を修飾するには「の」が必要。「が」は主語を示すので、「低地が水路は」は不自然。正しくは「低地の水路は」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
