INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38473, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "周囲よりも標高が低い土地。", "primary_collocate": null, "pronunciation": "ていち", "ipa": "teitɕi", "syllable_count": 3, "sentences": [{"text": "この町は川の近くの低地にあるため、洪水が多い。", "target_word": "低地", "complexity_tier": "T3", "furigana": "この町(まち)は川(かわ)の近(ちか)くの低地(ていち)にあるため、洪水(こうずい)が多(おお)い。", "sentence_source": "generated"}, {"text": "地図を見ると、東側は低地、西側は山地になっている。", "target_word": "低地", "complexity_tier": "T3", "furigana": "地図(ちず)を見(み)ると、東側(ひがしがわ)は低地(ていち)、西側(にしがわ)は山地(さんち)になっている。", "sentence_source": "generated"}, {"text": "低地の土は水を多く含み、稲作に向いている。", "target_word": "低地", "complexity_tier": "T3", "furigana": "低地(ていち)の土(つち)は水(みず)を多(おお)く含(ふく)み、稲作(いなさく)に向(む)いている。", "sentence_source": "generated"}, {"text": "低地と台地では、地震のときの揺れ方が違う。", "target_word": "低地", "complexity_tier": "T3", "furigana": "低地(ていち)と台地(だいち)では、地震(じしん)のときの揺(ゆ)れ方(かた)が違(ちが)う。", "sentence_source": "generated"}, {"text": "川沿いの低地には、昔から多くの人が住んできた。", "target_word": "低地", "complexity_tier": "T3", "furigana": "川沿(かわぞ)いの低地(ていち)には、昔(むかし)から多(おお)くの人(ひと)が住(す)んできた。", "sentence_source": "generated"}, {"text": "周囲の台地より低い低地に、古い町並みが残っている。", "target_word": "低地", "complexity_tier": "T3", "furigana": "周囲(しゅうい)の台地(だいち)より低(ひく)い低地(ていち)に、古(ふる)い町並(まちな)みが残(のこ)っている。", "sentence_source": "generated"}, {"text": "低地には冷たい空気がたまり、朝の霜が降りやすい。", "target_word": "低地", "complexity_tier": "T3", "furigana": "低地(ていち)には冷(つめ)たい空気(くうき)がたまり、朝(あさ)の霜(しも)が降(お)りやすい。", "sentence_source": "generated"}, {"text": "大雨のあと、低地だけが水に浸かった。", "target_word": "低地", "complexity_tier": "T3", "furigana": "大雨(おおあめ)のあと、低地(ていち)だけが水(みず)に浸(つ)かった。", "sentence_source": "generated"}, {"text": "低地を走る鉄道は、台地に入るとトンネルが多くなる。", "target_word": "低地", "complexity_tier": "T3", "furigana": "低地(ていち)を走(はし)る鉄道(てつどう)は、台地(だいち)に入(はい)るとトンネルが多(おお)くなる。", "sentence_source": "generated"}, {"text": "授業で、低地と高地の暮らしのちがいを調べた。", "target_word": "低地", "complexity_tier": "T3", "furigana": "授業(じゅぎょう)で、低地(ていち)と高地(こうち)の暮(く)らしのちがいを調(しら)べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "低地", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "周囲より標高が低い土地(地理・地形の用語)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0df70395-f463-48c9-9f7b-eb53760b6965') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38473, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低地", "is_correct": true, "explanation": "周囲より標高が低く、川の近くで洪水が多いという文脈に合う。"}, {"text": "高原", "is_correct": false, "explanation": "高原は標高が高い土地なので、洪水が多いという理由と合わない。"}, {"text": "山頂", "is_correct": false, "explanation": "山頂は川の近くにあることがほとんどなく、洪水の原因として合わない。"}, {"text": "屋上", "is_correct": false, "explanation": "屋上は川の近くの地形を表さず、洪水が多いという文脈に合わない。"}], "explanations": {"低地": "周囲より標高が低く、川の近くで洪水が多いという文脈に合う。", "高原": "高原は標高が高い土地なので、洪水が多いという理由と合わない。", "山頂": "山頂は川の近くにあることがほとんどなく、洪水の原因として合わない。", "屋上": "屋上は川の近くの地形を表さず、洪水が多いという文脈に合わない。"}, "sentence_index": 0, "correct_answer": "低地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "低地は山の尾根の上に続き、遠くまで見渡せる。", "explanation": "ここは〈低地〉の意味。低地は周囲より低い土地なので、〈高地〉のような高所とは矛盾する。"}, {"text": "低地の体温で、熱はないようだ。", "explanation": "ここは〈低地〉の意味。体温の低さは「低い」と言うので、低地は地形の語として使わない。"}, {"text": "試験の成績は低地で、もう少し努力が必要だ。", "explanation": "ここは〈低地〉の意味。成績の低さは「低い」と言うのが自然で、低地は地形の語として使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38473, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低地", "is_correct": true, "explanation": "周囲より低い土地に冷気がたまり、朝の霜が降りやすいという内容に合う。"}, {"text": "高台", "is_correct": false, "explanation": "高台は冷気が流れ去る場所なので、冷たい空気がたまるという文と合わない。"}, {"text": "屋根", "is_correct": false, "explanation": "屋根に冷たい空気がたまるという内容は不自然で、霜の文脈とも合わない。"}, {"text": "水平線", "is_correct": false, "explanation": "水平線は場所を指す語として使いにくく、冷気がたまる土地の文脈に合わない。"}], "explanations": {"低地": "周囲より低い土地に冷気がたまり、朝の霜が降りやすいという内容に合う。", "高台": "高台は冷気が流れ去る場所なので、冷たい空気がたまるという文と合わない。", "屋根": "屋根に冷たい空気がたまるという内容は不自然で、霜の文脈とも合わない。", "水平線": "水平線は場所を指す語として使いにくく、冷気がたまる土地の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "低地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この低地は標高が高く、冬は雪が積もりやすい。", "explanation": "ここは〈低地〉の意味。低地は周囲より低い土地なので、〈高地〉のような高い場所を指す語とは矛盾する。"}, {"text": "低地が近づき、午後から雨が強くなってきた。", "explanation": "ここは〈低地〉の意味。空気の圧力が低い〈低気圧〉を指す語で、地面の低い土地とは違う。"}, {"text": "その店は低地の値段で、いつも混んでいる。", "explanation": "ここは〈低地〉の意味。値段の安さは「安い」と言うので、低地は地形の語として使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38473, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "低地を広がる田んぼは、夏になると一面が緑になる。", "corrected_sentence": "低地に広がる田んぼは、夏になると一面が緑になる。", "error_description": "「広がる」の場所は「に」で示す。「を」は目的語に付くので「低地を広がる」は不自然。正しくは「低地に広がる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38473, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "低地に通る道は、雨の日はぬかるむ。", "corrected_sentence": "低地を通る道は、雨の日はぬかるむ。", "error_description": "「通る」は通過する場所を「を」で示す。「に」だと場所の意味になり、「低地に通る道」は不自然。正しくは「低地を通る道」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38474, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「遅滞が原因で」の主語。遅滞が原因になっている形にあたる。"}, {"text": "を", "is_correct": false, "explanation": "「遅滞を原因で」は、遅滞を目的語にする動詞がなく成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「遅滞と原因で」は並列の形にならず、文の骨組みが崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "「遅滞へ原因で」は方向を表すが、ここでは方向を示す動詞がなく不自然。"}], "correct_answer": "が", "explanations": {"が": "「遅滞が原因で」の主語。遅滞が原因になっている形にあたる。", "を": "「遅滞を原因で」は、遅滞を目的語にする動詞がなく成り立たない。", "と": "「遅滞と原因で」は並列の形にならず、文の骨組みが崩れる。", "へ": "「遅滞へ原因で」は方向を表すが、ここでは方向を示す動詞がなく不自然。"}, "error_tags": {"を": "目的語", "と": "並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38474, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「遅滞の理由」の連体修飾。遅滞を名詞として理由を修飾している。"}, {"text": "に", "is_correct": false, "explanation": "「遅滞に理由」は位置や相手を表すが、理由を修飾する形にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「遅滞で理由」は手段の意味になり、理由を修飾する形にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「遅滞から理由」は起点を表すが、理由を修飾する形にはならない。"}], "correct_answer": "の", "explanations": {"の": "「遅滞の理由」の連体修飾。遅滞を名詞として理由を修飾している。", "に": "「遅滞に理由」は位置や相手を表すが、理由を修飾する形にはならない。", "で": "「遅滞で理由」は手段の意味になり、理由を修飾する形にはならない。", "から": "「遅滞から理由」は起点を表すが、理由を修飾する形にはならない。"}, "error_tags": {"に": "位置・相手", "で": "手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38474, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするのがおそくなることです。", "primary_collocate": null, "pronunciation": "ちたい", "ipa": "tɕitai", "syllable_count": 3, "sentences": [{"text": "雪で電車の運行に遅滞が出た。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "雪(ゆき)で電車(でんしゃ)の運行(うんこう)に遅滞(ちたい)が出(で)た。", "sentence_source": "generated"}, {"text": "連絡の遅滞が原因で、会議の準備が間に合わなかった。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "連絡(れんらく)の遅滞(ちたい)が原因(げんいん)で、会議(かいぎ)の準備(じゅんび)が間(ま)に合(あ)わなかった。", "sentence_source": "generated"}, {"text": "工事は遅滞なく進み、予定どおり終わった。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "工事(こうじ)は遅滞(ちたい)なく進(すす)み、予定(よてい)どおり終(お)わった。", "sentence_source": "generated"}, {"text": "手続きの遅滞を防ぐために、書類は早めに出す。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "手続(てつづ)きの遅滞(ちたい)を防(ふせ)ぐために、書類(しょるい)は早(はや)めに出(だ)す。", "sentence_source": "generated"}, {"text": "荷物の配送に遅滞が生じ、お客さんに謝った。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "荷物(にもつ)の配送(はいそう)に遅滞(ちたい)が生(しょう)じ、お客(きゃく)さんに謝(あやま)った。", "sentence_source": "generated"}, {"text": "返事の遅滞は、相手に迷惑をかけることがある。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "返事(へんじ)の遅滞(ちたい)は、相手(あいて)に迷惑(めいわく)をかけることがある。", "sentence_source": "generated"}, {"text": "病気で仕事が遅滞し、同僚に助けてもらった。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "病気(びょうき)で仕事(しごと)が遅滞(ちたい)し、同僚(どうりょう)に助(たす)けてもらった。", "sentence_source": "generated"}, {"text": "遅滞の理由を、先生に正直に説明した。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "遅滞(ちたい)の理由(りゆう)を、先生(せんせい)に正直(しょうじき)に説明(せつめい)した。", "sentence_source": "generated"}, {"text": "部品が届かず、生産に遅滞が出ている。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "部品(ぶひん)が届(とど)かず、生産(せいさん)に遅滞(ちたい)が出(で)ている。", "sentence_source": "generated"}, {"text": "支払いの遅滞が続くと、利用が止まることがある。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "支払(しはら)いの遅滞(ちたい)が続(つづ)くと、利用(りよう)が止(と)まることがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遅滞", "label": "基本形"}, {"form": "遅滞する", "label": "サ変動詞"}, {"form": "遅滞した", "label": "過去形"}], "register": "formal", "sense_fingerprint": "物事をするのが遅くなること(作業・連絡・手続きなどの遅れ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0df70395-f463-48c9-9f7b-eb53760b6965') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38474, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遅滞", "is_correct": true, "explanation": "「運行に〜が出た」の空欄には、物事の遅れを表す「遅滞」が入る。"}, {"text": "満足", "is_correct": false, "explanation": "「運行に満足が出た」は意味が通らない。満足は気持ちが満たされることで、運行の遅れには使わない。"}, {"text": "契約", "is_correct": false, "explanation": "「契約」は取り決めのこと。電車の運行に契約が出るとは言わない。"}, {"text": "愛情", "is_correct": false, "explanation": "「愛情」は人へのあたたかい思いを表し、運行の状態には結びつかない。"}], "explanations": {"遅滞": "「運行に〜が出た」の空欄には、物事の遅れを表す「遅滞」が入る。", "満足": "「運行に満足が出た」は意味が通らない。満足は気持ちが満たされることで、運行の遅れには使わない。", "契約": "「契約」は取り決めのこと。電車の運行に契約が出るとは言わない。", "愛情": "「愛情」は人へのあたたかい思いを表し、運行の状態には結びつかない。"}, "sentence_index": 0, "correct_answer": "遅滞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "コーヒーの粉が遅滞して、カップの底に沈んでいた。", "explanation": "ここは〈沈殿〉の意味。液体の中の粒が底にたまることは沈殿。遅滞は物事の進みの遅れを表すので、粉のたまりには使わない。"}, {"text": "景気の遅滞が続き、給料はなかなか上がらない。", "explanation": "ここは〈停滞〉の意味。景気が動かずにとどまっている状態は停滞。遅滞は予定より進みが遅れることなので、景気の停滞には合わない。"}, {"text": "彼は遅滞の性格で、冗談が通じないことがよくある。", "explanation": "ここは〈遅鈍〉の意味。頭の働きや感覚がにぶいことは遅鈍。遅滞は物事の進みが遅いことを指すので、人の性格には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38474, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遅滞", "is_correct": true, "explanation": "仕事が遅れて進まなくなる状態を表す「遅滞」が入る。"}, {"text": "感謝", "is_correct": false, "explanation": "「仕事が感謝し」は成り立たない。感謝は相手への気持ちで、仕事の状態を表さない。"}, {"text": "誓約", "is_correct": false, "explanation": "「誓約」は固く約束すること。仕事が誓約するとは言えない。"}, {"text": "雑談", "is_correct": false, "explanation": "「雑談」は気楽な会話。仕事の進みの状態には当てはまらない。"}], "explanations": {"遅滞": "仕事が遅れて進まなくなる状態を表す「遅滞」が入る。", "感謝": "「仕事が感謝し」は成り立たない。感謝は相手への気持ちで、仕事の状態を表さない。", "誓約": "「誓約」は固く約束すること。仕事が誓約するとは言えない。", "雑談": "「雑談」は気楽な会話。仕事の進みの状態には当てはまらない。"}, "sentence_index": 6, "correct_answer": "遅滞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨水が遅滞して、道路に長いあいだたまっていた。", "explanation": "ここは〈滞留〉の意味。水などが流れずにとどまることは滞留。遅滞は物事の進行が遅れることで、水のたまりには使わない。"}, {"text": "チームの空気が遅滞して、誰も意見を言わなくなった。", "explanation": "ここは〈沈滞〉の意味。活気がなく重苦しくよどむことは沈滞。遅滞は物事の進みが遅れることで、場の雰囲気には使わない。"}, {"text": "売り上げの遅滞が続き、店の経営が苦しくなった。", "explanation": "ここは〈不振〉の意味。売り上げや成績がふるわないことは不振。遅滞は予定より進みが遅れることで、売れ行きの低迷には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38474, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作業の遅滞を続き、予定が大きくずれた。", "corrected_sentence": "作業の遅滞が続き、予定が大きくずれた。", "error_description": "「続く」は「が」で主語を取る自動詞なので、「遅滞を」ではなく「遅滞が」が正しい。遅滞に付く助詞の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38474, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "事故で遅滞が起こし、電車が止まった。", "corrected_sentence": "事故で遅滞が起き、電車が止まった。", "error_description": "「起こす」は他動詞で目的語を取るので、「遅滞が起こし」は誤り。自動詞「起きる」の連用形「起き」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38475, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「遅滞が出た」の主語。出るの主語は遅れを表す「遅滞」。"}, {"text": "を", "is_correct": false, "explanation": "「遅滞を出た」は、出るが自動詞なので目的語を取れず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「遅滞に出た」は位置や相手を表すが、出るの主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「遅滞と出た」は並列の形で、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「遅滞が出た」の主語。出るの主語は遅れを表す「遅滞」。", "を": "「遅滞を出た」は、出るが自動詞なので目的語を取れず不自然。", "に": "「遅滞に出た」は位置や相手を表すが、出るの主語にはならない。", "と": "「遅滞と出た」は並列の形で、文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38475, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「遅滞が出ない」の主語。出るの主語は遅滞。"}, {"text": "で", "is_correct": false, "explanation": "「遅滞で出ない」は手段の意味になり、出るの主語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「遅滞より出ない」は比較の意味になり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「遅滞へ出ない」は方向を表すが、出る主語としては不自然。"}], "correct_answer": "が", "explanations": {"が": "「遅滞が出ない」の主語。出るの主語は遅滞。", "で": "「遅滞で出ない」は手段の意味になり、出るの主語にはならない。", "より": "「遅滞より出ない」は比較の意味になり、文が成り立たない。", "へ": "「遅滞へ出ない」は方向を表すが、出る主語としては不自然。"}, "error_tags": {"で": "手段", "より": "比較", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38475, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の進行や行動が予定より遅れること。また、その遅れ。", "primary_collocate": null, "pronunciation": "ちたい", "ipa": "tɕitai", "syllable_count": 3, "sentences": [{"text": "計画の遅滞を取り戻すため、週末も作業を続けた。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "計画(けいかく)の遅滞(ちたい)を取(と)り戻(もど)すため、週末(しゅうまつ)も作業(さぎょう)を続(つづ)けた。", "sentence_source": "generated"}, {"text": "予定より三日の遅滞が出たが、品質は問題なかった。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "予定(よてい)より三日(みっか)の遅滞(ちたい)が出(で)たが、品質(ひんしつ)は問題(もんだい)なかった。", "sentence_source": "generated"}, {"text": "天候不良による遅滞で、船は夕方に港へ着いた。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "天候不良(てんこうふりょう)による遅滞(ちたい)で、船(ふね)は夕方(ゆうがた)に港(みなと)へ着(つ)いた。", "sentence_source": "generated"}, {"text": "事務の遅滞が続き、市民から苦情が出ている。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "事務(じむ)の遅滞(ちたい)が続(つづ)き、市民(しみん)から苦情(くじょう)が出(で)ている。", "sentence_source": "generated"}, {"text": "入学手続きに遅滞があると、授業が始まるまでに間に合わない。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "入学手続(にゅうがくてつづ)きに遅滞(ちたい)があると、授業(じゅぎょう)が始(はじ)まるまでに間(ま)に合(あ)わない。", "sentence_source": "generated"}, {"text": "遅滞なく連絡してください、と上司に言われた。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "遅滞(ちたい)なく連絡(れんらく)してください、と上司(じょうし)に言(い)われた。", "sentence_source": "generated"}, {"text": "工事の遅滞を知らせる張り紙が、入口に貼られていた。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "工事(こうじ)の遅滞(ちたい)を知(し)らせる張(は)り紙(がみ)が、入口(いりぐち)に貼(は)られていた。", "sentence_source": "generated"}, {"text": "全体の進行に遅滞が出ないよう、各自が役割を守る。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "全体(ぜんたい)の進行(しんこう)に遅滞(ちたい)が出(で)ないよう、各自(かくじ)が役割(やくわり)を守(まも)る。", "sentence_source": "generated"}, {"text": "資料の遅滞は、チーム全体の仕事を止めてしまう。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "資料(しりょう)の遅滞(ちたい)は、チーム全体(ぜんたい)の仕事(しごと)を止(と)めてしまう。", "sentence_source": "generated"}, {"text": "遅滞の原因を調べたところ、人手不足だとわかった。", "target_word": "遅滞", "complexity_tier": "T3", "furigana": "遅滞(ちたい)の原因(げんいん)を調(しら)べたところ、人手不足(ひとでぶそく)だとわかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遅滞", "label": "基本形"}, {"form": "遅滞する", "label": "サ変動詞"}, {"form": "遅滞した", "label": "過去形"}], "register": "formal", "sense_fingerprint": "予定より進行・行動が遅れること、またその遅れ(計画・工程の遅れ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0df70395-f463-48c9-9f7b-eb53760b6965') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38475, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遅滞", "is_correct": true, "explanation": "「計画の遅れ」を指す「遅滞」を取り戻す、という文脈に合う。"}, {"text": "相性", "is_correct": false, "explanation": "「計画の相性を取り戻す」は意味が通らない。相性は物同士の合い具合を言う。"}, {"text": "愛着", "is_correct": false, "explanation": "「愛着」は物や人へのいとしい気持ち。計画の遅れを取り戻す対象にはならない。"}, {"text": "親切", "is_correct": false, "explanation": "「親切」は人への思いやり。計画の遅れを取り戻す対象にはならない。"}], "explanations": {"遅滞": "「計画の遅れ」を指す「遅滞」を取り戻す、という文脈に合う。", "相性": "「計画の相性を取り戻す」は意味が通らない。相性は物同士の合い具合を言う。", "愛着": "「愛着」は物や人へのいとしい気持ち。計画の遅れを取り戻す対象にはならない。", "親切": "「親切」は人への思いやり。計画の遅れを取り戻す対象にはならない。"}, "sentence_index": 0, "correct_answer": "遅滞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は遅滞の気質で、冗談を言われてもしばらく気づかない。", "explanation": "ここは〈遅鈍〉の意味。頭の働きや感覚がにぶいことは遅鈍。遅滞は進みの遅れを表すので、人の気質には使わない。"}, {"text": "風邪のあと、味覚がすっかり遅滞してしまった。", "explanation": "ここは〈鈍る〉の意味。感覚がにぶくなることは鈍る。遅滞は予定より進みが遅れることを表すので、感覚の衰えには使わない。"}, {"text": "会議室の空気が遅滞して、誰も発言しなくなった。", "explanation": "ここは〈沈滞〉の意味。活気がなくよどむことは沈滞。遅滞は進みの遅れを表すので、場の空気には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38475, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遅滞", "is_correct": true, "explanation": "工事の進みが遅れていることを知らせる内容に「遅滞」が合う。"}, {"text": "歓声", "is_correct": false, "explanation": "「歓声」は喜びの声。工事の遅れを知らせる対象にはならない。"}, {"text": "笑顔", "is_correct": false, "explanation": "「笑顔」は表情。工事の遅れを知らせる対象にはならない。"}, {"text": "寝不足", "is_correct": false, "explanation": "「寝不足」は人の睡眠の状態。工事の遅れは表せない。"}], "explanations": {"遅滞": "工事の進みが遅れていることを知らせる内容に「遅滞」が合う。", "歓声": "「歓声」は喜びの声。工事の遅れを知らせる対象にはならない。", "笑顔": "「笑顔」は表情。工事の遅れを知らせる対象にはならない。", "寝不足": "「寝不足」は人の睡眠の状態。工事の遅れは表せない。"}, "sentence_index": 6, "correct_answer": "遅滞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "景気の遅滞が続き、給料はなかなか上がらない。", "explanation": "ここは〈停滞〉の意味。景気や状況が動かずにとどまることは停滞。遅滞は予定より進みが遅れることで、景気の停滞には合わない。"}, {"text": "排水が遅滞して、道路の隅に長いあいだ水がたまっていた。", "explanation": "ここは〈滞留〉の意味。水などが流れずにとどまることは滞留。遅滞は進行の遅れを表し、水のたまりには使わない。"}, {"text": "彼は遅滞の性格で、一度決めたら意見を曲げない。", "explanation": "ここは〈頑固〉の意味。意見を曲げずに押し通すことは頑固。遅滞は物事の進みが遅れることで、性格の強情さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38475, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工程の遅滞に取り戻すため、夜も作業を続けた。", "corrected_sentence": "工程の遅滞を取り戻すため、夜も作業を続けた。", "error_description": "「取り戻す」は他動詞で、取り戻す対象の「遅滞」には「を」を付ける。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38475, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工事の遅滞を取り消すため、夜は人を増やした。", "corrected_sentence": "工事の遅滞を取り戻すため、夜は人を増やした。", "error_description": "遅れは取り消せないもので、埋め合わせる「取り戻す」が正しい。「取り消す」は予定や契約を無効にする動詞で、ここでは合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38476, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「灌漑を始めた」の「を」で、始める動作の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「灌漑に始めた」は対象や時点を表す助詞で、始める動作の目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「始めた」の目的語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「灌漑の始めた」は名詞をつなぐ助詞で、動詞の目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "「灌漑を始めた」の「を」で、始める動作の目的語を示す。", "に": "「灌漑に始めた」は対象や時点を表す助詞で、始める動作の目的語にならない。", "へ": "「へ」は方向を表すので、「始めた」の目的語にはならない。", "の": "「灌漑の始めた」は名詞をつなぐ助詞で、動詞の目的語を示せない。"}, "error_tags": {"に": "相手・対象", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38476, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「灌漑に使われる」の「に」で、使われる先や用途を示す。"}, {"text": "と", "is_correct": false, "explanation": "「灌漑と使われる」は並列や相手を表し、用途の意味にならない。"}, {"text": "から", "is_correct": false, "explanation": "「灌漑から使われる」は起点を表し、用途を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の助詞で、「使われる」の用途は示せない。"}], "correct_answer": "に", "explanations": {"に": "「灌漑に使われる」の「に」で、使われる先や用途を示す。", "と": "「灌漑と使われる」は並列や相手を表し、用途の意味にならない。", "から": "「灌漑から使われる」は起点を表し、用途を示せない。", "より": "「より」は比較の助詞で、「使われる」の用途は示せない。"}, "error_tags": {"と": "並列・相手", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38476, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "田んぼや畑に水をやること。", "primary_collocate": null, "pronunciation": "かんがい", "ipa": "kaŋɡai", "syllable_count": 4, "sentences": [{"text": "雨が少ない年は、田んぼの灌漑が欠かせない。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "雨[あめ]が少[すく]ない年[とし]は、田[た]んぼの灌漑[かんがい]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "農家の人は朝早くから畑の灌漑を始めた。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]は朝早[あさはや]くから畑[はたけ]の灌漑[かんがい]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "川の水を引いて、畑を灌漑する。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]を引[ひ]いて、畑[はたけ]を灌漑[かんがい]する。", "sentence_source": "generated"}, {"text": "灌漑のおかげで、乾いた土地にも野菜が育つ。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "灌漑[かんがい]のおかげで、乾[かわ]いた土地[とち]にも野菜[やさい]が育[そだ]つ。", "sentence_source": "generated"}, {"text": "水が足りなくて、田んぼの灌漑ができなかった。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "水[みず]が足[た]りなくて、田[た]んぼの灌漑[かんがい]ができなかった。", "sentence_source": "generated"}, {"text": "村の人たちは交代で田んぼの灌漑をしている。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "村[むら]の人[ひと]たちは交代[こうたい]で田[た]んぼの灌漑[かんがい]をしている。", "sentence_source": "generated"}, {"text": "夏は暑いので、畑の灌漑を一日に二回行う。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "夏[なつ]は暑[あつ]いので、畑[はたけ]の灌漑[かんがい]を一日[いちにち]に二回[にかい]行[おこな]う。", "sentence_source": "generated"}, {"text": "この水路は、山の水を田んぼへ運んで灌漑に使われる。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "この水路[すいろ]は、山[やま]の水[みず]を田[た]んぼへ運[はこ]んで灌漑[かんがい]に使[つか]われる。", "sentence_source": "generated"}, {"text": "灌漑が終わったので、農家の人はやっと休んだ。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "灌漑[かんがい]が終[お]わったので、農家[のうか]の人[ひと]はやっと休[やす]んだ。", "sentence_source": "generated"}, {"text": "雨が降らなかったため、急いで畑を灌漑した。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]らなかったため、急[いそ]いで畑[はたけ]を灌漑[かんがい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "灌漑", "label": "基本形"}, {"form": "灌漑する", "label": "する動詞"}, {"form": "灌漑した", "label": "過去形"}], "register": "中立", "sense_fingerprint": "田んぼや畑に水を引いてやる農作業としての灌漑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89bcd18f-d47f-4b0f-88fb-abadee0257a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38476, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灌漑", "is_correct": true, "explanation": "田んぼに水を引く灌漑は、雨が少ない年に欠かせないという文脈に合う。"}, {"text": "害虫", "is_correct": false, "explanation": "害虫は作物を食べる虫で、田んぼに「欠かせない」ものではない。"}, {"text": "霜", "is_correct": false, "explanation": "霜は冷えて降りる氷の結晶で、田んぼに欠かせないものとは言えない。"}, {"text": "降雪", "is_correct": false, "explanation": "降雪は雪が降ることで、雨が少ない年の田んぼに欠かせない条件とは言えない。"}], "explanations": {"灌漑": "田んぼに水を引く灌漑は、雨が少ない年に欠かせないという文脈に合う。", "害虫": "害虫は作物を食べる虫で、田んぼに「欠かせない」ものではない。", "霜": "霜は冷えて降りる氷の結晶で、田んぼに欠かせないものとは言えない。", "降雪": "降雪は雪が降ることで、雨が少ない年の田んぼに欠かせない条件とは言えない。"}, "sentence_index": 0, "correct_answer": "灌漑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の午後、灌漑をして車をぴかぴかに洗った。", "explanation": "ここは〈洗車〉の意味。車の汚れを洗い流すのは洗車で、灌漑は田畑に水をやる作業なので合わない。"}, {"text": "畑の横の水槽に灌漑をして、水をいっぱいにためた。", "explanation": "ここは〈注水〉の意味。タンクや容器へ水を入れるのは注水で、灌漑は田畑に水をやる作業なので合わない。"}, {"text": "大雨のあとは、田んぼの灌漑をして余分な水を急いで外へ出した。", "explanation": "ここは〈排水〉の意味。余分な水を外へ抜くのは排水で、水を引く灌漑とは逆なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38476, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灌漑", "is_correct": true, "explanation": "畑に水を引いて水をやる灌漑を一日二回行うのは、暑い夏の作業として自然。"}, {"text": "脱穀", "is_correct": false, "explanation": "脱穀は収穫後に穀物を取り出す作業で、一日に二回行う畑の日課ではない。"}, {"text": "選果", "is_correct": false, "explanation": "選果は収穫物を選り分ける作業で、畑で一日二回行うものではない。"}, {"text": "苗床", "is_correct": false, "explanation": "苗床は苗を育てる場所で、「行う」の対象にはならない。"}], "explanations": {"灌漑": "畑に水を引いて水をやる灌漑を一日二回行うのは、暑い夏の作業として自然。", "脱穀": "脱穀は収穫後に穀物を取り出す作業で、一日に二回行う畑の日課ではない。", "選果": "選果は収穫物を選り分ける作業で、畑で一日二回行うものではない。", "苗床": "苗床は苗を育てる場所で、「行う」の対象にはならない。"}, "sentence_index": 6, "correct_answer": "灌漑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大雨で畑が灌漑され、作物が水に沈んだ。", "explanation": "ここは〈浸水〉の意味。雨で水が入り込む状態は浸水で、灌漑は人が水を引く作業なので合わない。"}, {"text": "害虫が増えたので、畑に農薬を灌漑した。", "explanation": "ここは〈散布〉の意味。農薬をまくのは散布で、水を供給する灌漑とは意味が違うので合わない。"}, {"text": "消防車が火事に灌漑して、火を消した。", "explanation": "ここは〈放水〉の意味。火に向けて水を勢いよく出すのは放水で、田畑へ水を引く灌漑とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38476, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方になると、農家の人は灌漑が終えて家へ帰る。", "corrected_sentence": "夕方になると、農家の人は灌漑を終えて家へ帰る。", "error_description": "「灌漑を終える」の「を」が正しい。「終える」は目的語を取る他動詞なので「を」を使う。「が」では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38476, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "干ばつの年は、畑の灌漑を毎日かけることにした。", "corrected_sentence": "干ばつの年は、畑の灌漑を毎日行うことにした。", "error_description": "「灌漑を行う」が正しい。灌漑は「行う」「する」と結びつく。「かける」は水をまく動作に使うので、灌漑の文では不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38477, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「灌漑によって」の「に」で、手段の根拠となる起点を示す。「砂漠の近くでは、灌漑によって小麦を作っている」と自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "「灌漑を、よって」では「によって」の形が成り立たず、手段を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「灌漑へ、よって」は方向を表し、手段の意味にならない。"}, {"text": "と", "is_correct": false, "explanation": "「灌漑と、よって」は並列や相手を表し、手段の意味にならない。"}], "correct_answer": "に", "explanations": {"に": "「灌漑によって」の「に」で、手段の根拠となる起点を示す。「砂漠の近くでは、灌漑によって小麦を作っている」と自然につながる。", "を": "「灌漑を、よって」では「によって」の形が成り立たず、手段を表せない。", "へ": "「灌漑へ、よって」は方向を表し、手段の意味にならない。", "と": "「灌漑と、よって」は並列や相手を表し、手段の意味にならない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38477, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「灌漑が進む」の「が」で、進んだ主体、つまり主語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「灌漑に進む」は方向や対象を表し、進むの主語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「灌漑より進んだ」は比較の助詞で、主語を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「灌漑から進んだ」は起点を表し、進むの主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「灌漑が進む」の「が」で、進んだ主体、つまり主語を示す。", "に": "「灌漑に進む」は方向や対象を表し、進むの主語にはならない。", "より": "「灌漑より進んだ」は比較の助詞で、主語を示せない。", "から": "「灌漑から進んだ」は起点を表し、進むの主語にはならない。"}, "error_tags": {"に": "方向・対象", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38477, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "農作物を育てるために、人工的に水を供給すること。", "primary_collocate": null, "pronunciation": "かんがい", "ipa": "kaŋɡai", "syllable_count": 4, "sentences": [{"text": "雨が少ない地域では、人工的な灌漑がなければ作物は育たない。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "雨[あめ]が少[すく]ない地域[ちいき]では、人工的[じんこうてき]な灌漑[かんがい]がなければ作物[さくもつ]は育[そだ]たない。", "sentence_source": "generated"}, {"text": "砂漠の近くでは、灌漑によって小麦を作っている。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "砂漠[さばく]の近[ちか]くでは、灌漑[かんがい]によって小麦[こむぎ]を作[つく]っている。", "sentence_source": "generated"}, {"text": "大きなダムができて、広い農地の灌漑が可能になった。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "大[おお]きなダムができて、広[ひろ]い農地[のうち]の灌漑[かんがい]が可能[かのう]になった。", "sentence_source": "generated"}, {"text": "灌漑の設備が古くなり、水がうまく届かなくなった。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "灌漑[かんがい]の設備[せつび]が古[ふる]くなり、水[みず]がうまく届[とど]かなくなった。", "sentence_source": "generated"}, {"text": "政府は農業を守るため、灌漑の工事に予算を出した。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "政府[せいふ]は農業[のうぎょう]を守[まも]るため、灌漑[かんがい]の工事[こうじ]に予算[よさん]を出[だ]した。", "sentence_source": "generated"}, {"text": "灌漑の水が不足すると、米の収穫は大きく減る。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "灌漑[かんがい]の水[みず]が不足[ふそく]すると、米[こめ]の収穫[しゅうかく]は大[おお]きく減[へ]る。", "sentence_source": "generated"}, {"text": "川から水路を作り、麦畑を灌漑する計画だ。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "川[かわ]から水路[すいろ]を作[つく]り、麦畑[むぎばたけ]を灌漑[かんがい]する計画[けいかく]だ。", "sentence_source": "generated"}, {"text": "灌漑が進んだ結果、収穫量が二倍になった。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "灌漑[かんがい]が進[すす]んだ結果[けっか]、収穫量[しゅうかくりょう]が二倍[にばい]になった。", "sentence_source": "generated"}, {"text": "乾燥した土地でも、灌漑すれば野菜を栽培できる。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "乾燥[かんそう]した土地[とち]でも、灌漑[かんがい]すれば野菜[やさい]を栽培[さいばい]できる。", "sentence_source": "generated"}, {"text": "古代の人々は、すでに高度な灌漑の技術を持っていた。", "target_word": "灌漑", "complexity_tier": "T3", "furigana": "古代[こだい]の人々[ひとびと]は、すでに高度[こうど]な灌漑[かんがい]の技術[ぎじゅつ]を持[も]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "灌漑", "label": "基本形"}, {"form": "灌漑する", "label": "する動詞"}, {"form": "灌漑すれば", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "水路やダムなどで人工的に農地へ水を供給する農業の仕組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89bcd18f-d47f-4b0f-88fb-abadee0257a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38477, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灌漑", "is_correct": true, "explanation": "人工的な灌漑は、雨の少ない地域で作物を育てる仕組みとして自然に入る。"}, {"text": "脱穀", "is_correct": false, "explanation": "脱穀は収穫後に穀物を取り出す作業で、作物を育てる条件にはならない。"}, {"text": "選果", "is_correct": false, "explanation": "選果は収穫した果物を選り分けることで、人工的に作物を育てる条件にはならない。"}, {"text": "収穫", "is_correct": false, "explanation": "収穫は育った作物を取り入れることで、「なければ育たない」条件にはならない。"}], "explanations": {"灌漑": "人工的な灌漑は、雨の少ない地域で作物を育てる仕組みとして自然に入る。", "脱穀": "脱穀は収穫後に穀物を取り出す作業で、作物を育てる条件にはならない。", "選果": "選果は収穫した果物を選り分けることで、人工的に作物を育てる条件にはならない。", "収穫": "収穫は育った作物を取り入れることで、「なければ育たない」条件にはならない。"}, "sentence_index": 0, "correct_answer": "灌漑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大雨のあと、灌漑の設備で余分な水を外へ出した。", "explanation": "ここは〈排水〉の意味。余分な水を外へ出すのは排水で、灌漑は水を農地へ引き入れる仕組みなので合わない。"}, {"text": "断水のあと、灌漑が町の家々に水を届けた。", "explanation": "ここは〈給水〉の意味。家庭や町へ水を届けるのは給水で、灌漑は農地へ水を送る仕組みなので合わない。"}, {"text": "大雨の日は灌漑を閉めて、川の水が増えすぎないようにした。", "explanation": "ここは〈水門〉の意味。川の水を遮る門は水門で、農地へ水を送る灌漑を閉めても川の水は止まらないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38477, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灌漑", "is_correct": true, "explanation": "麦畑に水路から水を引いて水をやる計画として、灌漑は自然に入る。"}, {"text": "換気", "is_correct": false, "explanation": "換気は空気を入れ替えることで、麦畑を対象にした計画の動詞としては合わない。"}, {"text": "防音", "is_correct": false, "explanation": "防音は音を遮ることで、麦畑を対象にする計画の動作として合わない。"}, {"text": "漂白", "is_correct": false, "explanation": "漂白は色を抜く処理で、麦畑を対象にする計画の動作ではない。"}], "explanations": {"灌漑": "麦畑に水路から水を引いて水をやる計画として、灌漑は自然に入る。", "換気": "換気は空気を入れ替えることで、麦畑を対象にした計画の動詞としては合わない。", "防音": "防音は音を遮ることで、麦畑を対象にする計画の動作として合わない。", "漂白": "漂白は色を抜く処理で、麦畑を対象にする計画の動作ではない。"}, "sentence_index": 6, "correct_answer": "灌漑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大雨の被害を防ぐため、川で灌漑をして増水をおさえた。", "explanation": "ここは〈治水〉の意味。洪水を防ぐ工事は治水で、灌漑は農地へ水を送る仕組みなので合わない。"}, {"text": "この湖では、灌漑の生け簀で稚魚を育てている。", "explanation": "ここは〈養殖〉の意味。魚を育てて増やすのは養殖で、灌漑は農地へ水を送る仕組みなので合わない。"}, {"text": "灌漑の設備で川の水から泥を除き、飲み水を作っている。", "explanation": "ここは〈浄水〉の意味。飲める水に浄化するのは浄水で、灌漑は農地へ水を送るだけなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38477, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この地域の農家は、ダムの水を引いて灌漑が続けている。", "corrected_sentence": "この地域の農家は、ダムの水を引いて灌漑を続けている。", "error_description": "「灌漑を続ける」の「を」が正しい。「続ける」は目的語を取る他動詞なので「を」を使う。「が」では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38477, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ダムの水は、灌漑を使われている。", "corrected_sentence": "ダムの水は、灌漑に使われている。", "error_description": "「灌漑に使われる」の「に」が正しい。用途は「に」で示す。「を」を付けると「使われる」と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38478, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「賛成する」は賛成の対象に「に」を付けるので、「建設に賛成」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「賛成」は目的語の「を」を取らないので、「建設を賛成」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐので、動詞「賛成している」とは続かず文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「建設が賛成している」では町の人の賛成を表せない。"}], "correct_answer": "に", "explanations": {"に": "「賛成する」は賛成の対象に「に」を付けるので、「建設に賛成」が正しい。", "を": "「賛成」は目的語の「を」を取らないので、「建設を賛成」は成り立たない。", "の": "「の」は名詞どうしをつなぐので、動詞「賛成している」とは続かず文が成り立たない。", "が": "「が」は主語を示すので、「建設が賛成している」では町の人の賛成を表せない。"}, "error_tags": {"を": "目的語", "の": "名詞どうし", "が": "主語"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破壊", "is_correct": true, "explanation": "「建設」の対義語。作り上げることと壊すことで、反対の意味になる。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行は各地を訪ねることで、建設の対義語ではない。"}, {"text": "料理", "is_correct": false, "explanation": "料理は食べ物を用意することで、建設と対になる関係ではない。"}, {"text": "運動", "is_correct": false, "explanation": "運動は体を動かすことで、建設の反対の意味にはならない。"}], "correct_answer": "破壊", "explanations": {"破壊": "「建設」の対義語。作り上げることと壊すことで、反対の意味になる。", "旅行": "旅行は各地を訪ねることで、建設の対義語ではない。", "料理": "料理は食べ物を用意することで、建設と対になる関係ではない。", "運動": "運動は体を動かすことで、建設の反対の意味にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38478, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破壊", "is_correct": true, "explanation": "「建設」の対義語。作り上げることと壊すことで、反対の意味になる。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様や気候の状態で、建設の対義語ではない。"}, {"text": "会議", "is_correct": false, "explanation": "会議は人が集まって話し合うことで、建設と対になる関係ではない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は気分転換に歩くことで、建設の反対の意味にはならない。"}], "correct_answer": "破壊", "explanations": {"破壊": "「建設」の対義語。作り上げることと壊すことで、反対の意味になる。", "天気": "天気は空模様や気候の状態で、建設の対義語ではない。", "会議": "会議は人が集まって話し合うことで、建設と対になる関係ではない。", "散歩": "散歩は気分転換に歩くことで、建設の反対の意味にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38478, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ビルや橋、道路などの大きなものを新しく作り上げること。", "primary_collocate": null, "pronunciation": "けんせつ", "ipa": "kensetsɯ", "syllable_count": 4, "sentences": [{"text": "駅の前に新しいビルの建設が始まった。", "target_word": "建設", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]に新[あたら]しいビルの建設[けんせつ]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "町の人は、橋の建設に賛成している。", "target_word": "建設", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]は、橋[はし]の建設[けんせつ]に賛成[さんせい]している。", "sentence_source": "generated"}, {"text": "工事が遅れて、ダムの建設は来年に延びた。", "target_word": "建設", "complexity_tier": "T3", "furigana": "工事[こうじ]が遅[おく]れて、ダムの建設[けんせつ]は来年[らいねん]に延[の]びた。", "sentence_source": "generated"}, {"text": "国は道路を建設するために、土地を買った。", "target_word": "建設", "complexity_tier": "T3", "furigana": "国[くに]は道路[どうろ]を建設[けんせつ]するために、土地[とち]を買[か]った。", "sentence_source": "generated"}, {"text": "この学校の建設には、三年かかった。", "target_word": "建設", "complexity_tier": "T3", "furigana": "この学校[がっこう]の建設[けんせつ]には、三年[さんねん]かかった。", "sentence_source": "generated"}, {"text": "大雨のせいで、トンネルの建設が一時止まった。", "target_word": "建設", "complexity_tier": "T3", "furigana": "大雨[おおあめ]のせいで、トンネルの建設[けんせつ]が一時[いちじ]止[と]まった。", "sentence_source": "generated"}, {"text": "住民は公園の建設について話し合った。", "target_word": "建設", "complexity_tier": "T3", "furigana": "住民[じゅうみん]は公園[こうえん]の建設[けんせつ]について話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "新しい空港を建設する計画が発表された。", "target_word": "建設", "complexity_tier": "T3", "furigana": "新[あたら]しい空港[くうこう]を建設[けんせつ]する計画[けいかく]が発表[はっぴょう]された。", "sentence_source": "generated"}, {"text": "彼は建設の現場で働いて、家族を支えている。", "target_word": "建設", "complexity_tier": "T3", "furigana": "彼[かれ]は建設[けんせつ]の現場[げんば]で働[はたら]いて、家族[かぞく]を支[ささ]えている。", "sentence_source": "generated"}, {"text": "建設が終われば、この町はもっと便利になる。", "target_word": "建設", "complexity_tier": "T3", "furigana": "建設[けんせつ]が終[お]われば、この町[まち]はもっと便利[べんり]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "建設", "label": "基本形"}, {"form": "建設する", "label": "する動詞"}, {"form": "建設した", "label": "過去形"}], "register": "中立", "sense_fingerprint": "ビル・橋・道路などの大きなものを新しく作り上げること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89bcd18f-d47f-4b0f-88fb-abadee0257a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38478, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建設", "is_correct": true, "explanation": "ビルを新しく作り始めることを表すので、「ビルの＿＿が始まった」に合う。"}, {"text": "感想", "is_correct": false, "explanation": "感想は考えや印象を指すので、ビルの作業が始まるという文には入らない。"}, {"text": "試合", "is_correct": false, "explanation": "試合は競技の場面を指すので、ビルについて「試合が始まった」とは言えない。"}, {"text": "病気", "is_correct": false, "explanation": "病気は体の不調を指すので、ビルの作業が始まるという文とは結びつかない。"}], "explanations": {"建設": "ビルを新しく作り始めることを表すので、「ビルの＿＿が始まった」に合う。", "感想": "感想は考えや印象を指すので、ビルの作業が始まるという文には入らない。", "試合": "試合は競技の場面を指すので、ビルについて「試合が始まった」とは言えない。", "病気": "病気は体の不調を指すので、ビルの作業が始まるという文とは結びつかない。"}, "sentence_index": 0, "correct_answer": "建設"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この映画は三年かけて建設された。", "explanation": "ここは〈制作〉の意味。映画は建設するものではなく制作するものなので、〈建設〉は合わない。"}, {"text": "新しいエアコンを建設した。", "explanation": "ここは〈設置〉の意味。エアコンは建設せず設置するものなので、〈建設〉は使わない。"}, {"text": "報告書を建設した。", "explanation": "ここは〈作成〉の意味。報告書は作成するもので、建設とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38478, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建設", "is_correct": true, "explanation": "公園を作ることについて話し合ったという文に合う。"}, {"text": "寝言", "is_correct": false, "explanation": "寝言は寝ている間に出す言葉で、公園について話し合う文には合わない。"}, {"text": "三角形", "is_correct": false, "explanation": "三角形は図形の名前で、公園の話し合いの内容にはならない。"}, {"text": "口紅", "is_correct": false, "explanation": "口紅は化粧品で、公園について話し合う対象としては合わない。"}], "explanations": {"建設": "公園を作ることについて話し合ったという文に合う。", "寝言": "寝言は寝ている間に出す言葉で、公園について話し合う文には合わない。", "三角形": "三角形は図形の名前で、公園の話し合いの内容にはならない。", "口紅": "口紅は化粧品で、公園について話し合う対象としては合わない。"}, "sentence_index": 6, "correct_answer": "建設"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壊れたパソコンを建設した。", "explanation": "ここは〈修理〉の意味。壊れた機械は直すもので、建設とは言わない。"}, {"text": "工場で車を建設している。", "explanation": "ここは〈製造〉の意味。車は製造するもので、建設の対象にはならない。"}, {"text": "彼は新しい曲を建設した。", "explanation": "ここは〈作曲〉の意味。曲は作曲するもので、建設とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38478, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工事は来年の春に建設を始まる予定だ。", "corrected_sentence": "工事は来年の春に建設が始まる予定だ。", "error_description": "「始まる」は自動詞なので主語に助詞「が」を付ける。「建設を」は誤りで、正しくは「建設が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38478, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい橋が建設させた。", "corrected_sentence": "新しい橋が建設された。", "error_description": "「建設させた」は誤りで、正しくは受身の「建設された」。橋は建設を行う主体ではなく、建設される側なので受身を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38480, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「流れている」の主語である水脈に付く「が」が正しい。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐので、動詞「流れている」には続かず文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、水脈を主語にできない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、水脈の流れを表す文には合わない。"}], "correct_answer": "が", "explanations": {"が": "「流れている」の主語である水脈に付く「が」が正しい。", "の": "「の」は名詞どうしをつなぐので、動詞「流れている」には続かず文が成り立たない。", "で": "「で」は場所や手段を示すので、水脈を主語にできない。", "と": "「と」は並列や相手を示すので、水脈の流れを表す文には合わない。"}, "error_tags": {"の": "名詞どうし", "で": "場所・手段", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38480, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38480, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面の下を流れる水の道。", "primary_collocate": null, "pronunciation": "すいみゃく", "ipa": "sɯimʲaku", "syllable_count": 4, "sentences": [{"text": "井戸を掘ったところ、深い所で水脈にあたった。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "井戸[いど]を掘[ほ]ったところ、深[ふか]い所[ところ]で水脈[すいみゃく]にあたった。", "sentence_source": "generated"}, {"text": "山の地下には、大きな水脈が流れている。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "山[やま]の地下[ちか]には、大[おお]きな水脈[すいみゃく]が流[なが]れている。", "sentence_source": "generated"}, {"text": "水脈が変わって、村の井戸が涸れてしまった。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "水脈[すいみゃく]が変[か]わって、村[むら]の井戸[いど]が涸[か]れてしまった。", "sentence_source": "generated"}, {"text": "調査の人は、水脈を探すために地面を調べた。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "調査[ちょうさ]の人[ひと]は、水脈[すいみゃく]を探[さが]すために地面[じめん]を調[しら]べた。", "sentence_source": "generated"}, {"text": "この町の水は、山から続く水脈から来ている。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "この町[まち]の水[みず]は、山[やま]から続[つづ]く水脈[すいみゃく]から来[き]ている。", "sentence_source": "generated"}, {"text": "地震のあと、水脈が動いて新しい泉ができた。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、水脈[すいみゃく]が動[うご]いて新[あたら]しい泉[いずみ]ができた。", "sentence_source": "generated"}, {"text": "水脈の上に家を建てると、湿気が多くなるという。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "水脈[すいみゃく]の上[うえ]に家[いえ]を建[た]てると、湿気[しっけ]が多[おお]くなるという。", "sentence_source": "generated"}, {"text": "昔の人は、水脈のありかを木の様子で知った。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、水脈[すいみゃく]のありかを木[き]の様子[ようす]で知[し]った。", "sentence_source": "generated"}, {"text": "雨が少なくても、水脈があれば井戸の水は減らない。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "雨[あめ]が少[すく]なくても、水脈[すいみゃく]があれば井戸[いど]の水[みず]は減[へ]らない。", "sentence_source": "generated"}, {"text": "工事で水脈を切ってしまい、水が出なくなった。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "工事[こうじ]で水脈[すいみゃく]を切[き]ってしまい、水[みず]が出[で]なくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水脈", "label": "基本形"}], "register": "中立", "sense_fingerprint": "井戸や泉の水のもとになる、地面の下の水の通り道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89bcd18f-d47f-4b0f-88fb-abadee0257a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38480, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水脈", "is_correct": true, "explanation": "深い所で当たる地下の水の通り道を表すので、「水脈にあたった」に合う。"}, {"text": "悲鳴", "is_correct": false, "explanation": "悲鳴は叫び声を指すので、井戸を掘ってあたるものとしては合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は書いた文章を指すので、井戸を掘ってあたるものにはならない。"}, {"text": "砂時計", "is_correct": false, "explanation": "砂時計は時間を計る道具で、井戸を掘って当たるものとしては合わない。"}], "explanations": {"水脈": "深い所で当たる地下の水の通り道を表すので、「水脈にあたった」に合う。", "悲鳴": "悲鳴は叫び声を指すので、井戸を掘ってあたるものとしては合わない。", "手紙": "手紙は書いた文章を指すので、井戸を掘ってあたるものにはならない。", "砂時計": "砂時計は時間を計る道具で、井戸を掘って当たるものとしては合わない。"}, "sentence_index": 0, "correct_answer": "水脈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "力を入れると、腕の水脈が浮き出てくる。", "explanation": "ここは〈血管〉の意味。腕に浮き出るのは血管で、地面の下を流れる水の道である水脈とは言わない。"}, {"text": "北の空から水脈が近づいている。", "explanation": "ここは〈雨雲〉の意味。水脈は地下の水の流れで、空から近づいてくるものではない。"}, {"text": "屋根の水脈が凍って破裂した。", "explanation": "ここは〈配管〉の意味。屋根にあって凍る管は配管で、地下の水脈とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38480, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水脈", "is_correct": true, "explanation": "地下の水の通り道を表すので、その上に家を建てると湿気が多くなるという文に合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は食品で、その上に家を建てるという文には合わない。"}, {"text": "絵画", "is_correct": false, "explanation": "絵画は美術作品で、その上に家を建てるという文には合わない。"}, {"text": "切手", "is_correct": false, "explanation": "切手は郵便に使う小さな紙片で、その上に家を建てるという文には合わない。"}], "explanations": {"水脈": "地下の水の通り道を表すので、その上に家を建てると湿気が多くなるという文に合う。", "砂糖": "砂糖は食品で、その上に家を建てるという文には合わない。", "絵画": "絵画は美術作品で、その上に家を建てるという文には合わない。", "切手": "切手は郵便に使う小さな紙片で、その上に家を建てるという文には合わない。"}, "sentence_index": 6, "correct_answer": "水脈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この崖は水脈が三色に重なっている。", "explanation": "ここは〈地層〉の意味。岩の層が色別に重なる様子で、水の通り道の水脈には当てはまらない。"}, {"text": "水脈を溶かすと、水がしょっぱくなる。", "explanation": "ここは〈塩〉の意味。塩は水に溶かすもので、水脈を溶かすとは言わない。"}, {"text": "水脈を砕いて金を取り出す。", "explanation": "ここは〈鉱石〉の意味。鉱石は砕いて金属を取り出すもので、水脈は水の通り道なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38480, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この村は水脈を水を引いている。", "corrected_sentence": "この村は水脈から水を引いている。", "error_description": "「引いている」は起点を表す「から」を使う。「水脈を」は誤りで、正しくは「水脈から」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38480, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "井戸が水脈であたって、水が噴き出した。", "corrected_sentence": "井戸が水脈にあたって、水が噴き出した。", "error_description": "「あたる」は当たる先に助詞「に」を取る。「水脈で」は誤りで、正しくは「水脈に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38481, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「水脈の位置」は水脈が「位置」を修飾するので、所有の「の」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「水脈が位置」では修飾の関係が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、「水脈を位置」では名詞同士がつながらない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や対象を示すので、「水脈に位置」では意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「水脈の位置」は水脈が「位置」を修飾するので、所有の「の」が正しい。", "が": "「が」は主語を示すので、「水脈が位置」では修飾の関係が成り立たない。", "を": "「を」は目的語を示すので、「水脈を位置」では名詞同士がつながらない。", "に": "「に」は場所や対象を示すので、「水脈に位置」では意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "着点・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38481, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「見つかり」の主語である水脈に付く「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、自動詞「見つかる」の主語にはできない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、水脈が見つかった文には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、水脈が見つかったという文の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「見つかり」の主語である水脈に付く「が」が正しい。", "を": "「を」は目的語を示すので、自動詞「見つかる」の主語にはできない。", "と": "「と」は並列や相手を示すので、水脈が見つかった文には合わない。", "へ": "「へ」は方向を示すので、水脈が見つかったという文の主語にはならない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38481, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地下に存在する、水が通っている層や流れのこと。地下水の通り道。", "primary_collocate": null, "pronunciation": "すいみゃく", "ipa": "sɯimʲaku", "syllable_count": 4, "sentences": [{"text": "地下の水脈は、岩の間を通って海へ向かっている。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "地下[ちか]の水脈[すいみゃく]は、岩[いわ]の間[あいだ]を通[とお]って海[うみ]へ向[む]かっている。", "sentence_source": "generated"}, {"text": "専門家が機械で調べ、地下の水脈の位置を地図に表した。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "専門家[せんもんか]が機械[きかい]で調[しら]べ、地下[ちか]の水脈[すいみゃく]の位置[いち]を地図[ちず]に表[あらわ]した。", "sentence_source": "generated"}, {"text": "砂漠の下にも、古い水脈が残っている。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "砂漠[さばく]の下[した]にも、古[ふる]い水脈[すいみゃく]が残[のこ]っている。", "sentence_source": "generated"}, {"text": "この水脈は雨水が長い時間をかけて集まったものだ。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "この水脈[すいみゃく]は雨水[あまみず]が長[なが]い時間[じかん]をかけて集[あつ]まったものだ。", "sentence_source": "generated"}, {"text": "水脈が細くなり、畑に使う水が足りなくなった。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "水脈[すいみゃく]が細[ほそ]くなり、畑[はたけ]に使[つか]う水[みず]が足[た]りなくなった。", "sentence_source": "generated"}, {"text": "工場が地下の水脈から水を汲み上げすぎて、周りの井戸が涸れてしまった。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "工場[こうじょう]が地下[ちか]の水脈[すいみゃく]から水[みず]を汲[く]み上[あ]げすぎて、周[まわ]りの井戸[いど]が涸[か]れてしまった。", "sentence_source": "generated"}, {"text": "水脈を汚さないよう、ごみを地面に捨ててはいけない。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "水脈[すいみゃく]を汚[よご]さないよう、ごみを地面[じめん]に捨[す]ててはいけない。", "sentence_source": "generated"}, {"text": "大きな水脈が見つかり、町は水不足から救われた。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "大[おお]きな水脈[すいみゃく]が見[み]つかり、町[まち]は水不足[みずぶそく]から救[すく]われた。", "sentence_source": "generated"}, {"text": "水脈の流れは遅く、水が入れ替わるのに何百年もかかる。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "水脈[すいみゃく]の流[なが]れは遅[おそ]く、水[みず]が入[い]れ替[か]わるのに何百年[なんびゃくねん]もかかる。", "sentence_source": "generated"}, {"text": "温泉は地下の水脈が熱で温められて湧いたものだ。", "target_word": "水脈", "complexity_tier": "T3", "furigana": "温泉[おんせん]は地下[ちか]の水脈[すいみゃく]が熱[ねつ]で温[あたた]められて湧[わ]いたものだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水脈", "label": "基本形"}], "register": "中立", "sense_fingerprint": "地質学的にとらえた、地下水が通る層や流れ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89bcd18f-d47f-4b0f-88fb-abadee0257a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38481, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水脈", "is_correct": true, "explanation": "岩の間を通って海へ向かう地下の水の流れを表すので、文に合う。"}, {"text": "消防車", "is_correct": false, "explanation": "消防車は地上を走る車で、地下を通って海へ向かう文には合わない。"}, {"text": "太陽", "is_correct": false, "explanation": "太陽は空にある天体で、地下を流れて海へ向かう文には合わない。"}, {"text": "卵", "is_correct": false, "explanation": "卵は食べ物や生き物の一部で、岩の間を通って海へ向かう文には合わない。"}], "explanations": {"水脈": "岩の間を通って海へ向かう地下の水の流れを表すので、文に合う。", "消防車": "消防車は地上を走る車で、地下を通って海へ向かう文には合わない。", "太陽": "太陽は空にある天体で、地下を流れて海へ向かう文には合わない。", "卵": "卵は食べ物や生き物の一部で、岩の間を通って海へ向かう文には合わない。"}, "sentence_index": 0, "correct_answer": "水脈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "患者の水脈が弱くなった。", "explanation": "ここは〈脈拍〉の意味。体の拍動である脈拍が弱くなる話で、地下の水の流れを指す水脈とは言わない。"}, {"text": "水脈が南から近づいている。", "explanation": "ここは〈台風〉の意味。台風は南から近づくが、水脈は地下の水の流れなので近づくことはない。"}, {"text": "水脈が詰まって、流しから水があふれた。", "explanation": "ここは〈排水管〉の意味。詰まって水をあふれさせるのは排水管で、水脈とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38481, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水脈", "is_correct": true, "explanation": "地下の水の通り道を表すので、汚さないよう注意するという文に合う。"}, {"text": "歌", "is_correct": false, "explanation": "歌は音楽作品で、汚さないよう注意するものとしては合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空の現象で、汚さないよう注意する対象にはならない。"}, {"text": "感情", "is_correct": false, "explanation": "感情は心の状態で、水脈を汚すという文の対象としては合わない。"}], "explanations": {"水脈": "地下の水の通り道を表すので、汚さないよう注意するという文に合う。", "歌": "歌は音楽作品で、汚さないよう注意するものとしては合わない。", "夕焼け": "夕焼けは空の現象で、汚さないよう注意する対象にはならない。", "感情": "感情は心の状態で、水脈を汚すという文の対象としては合わない。"}, "sentence_index": 6, "correct_answer": "水脈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水脈が風で運ばれて、道に積もった。", "explanation": "ここは〈砂〉の意味。砂は風で運ばれて積もるが、地下の水の通り道は風で運ばれない。"}, {"text": "水脈が強風で切れて停電した。", "explanation": "ここは〈電線〉の意味。強風で切れて停電を起こすのは電線で、水脈とは言わない。"}, {"text": "水脈を開けて食べた。", "explanation": "ここは〈缶詰〉の意味。缶詰は開けて食べるもので、水脈は開けて食べるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38481, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨水が地下の水脈で染み込んだ。", "corrected_sentence": "雨水が地下の水脈に染み込んだ。", "error_description": "「染み込む」は行き先を表す助詞「に」を取る。「水脈で」は誤りで、正しくは「水脈に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38481, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水脈にたどって、泉を見つけた。", "corrected_sentence": "水脈をたどって、泉を見つけた。", "error_description": "「たどる」は目的語に助詞「を」を取る。「水脈に」は誤りで、正しくは「水脈を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dbb598e-8c94-41d5-838d-a7761e1ea543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
