INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38482, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを、よくわかって、ちゃんとつかむこと。", "primary_collocate": null, "pronunciation": "はあく", "ipa": "haakɯ", "syllable_count": 3, "sentences": [{"text": "先生の説明が速くて、内容を把握するのに時間がかかった。", "target_word": "把握", "complexity_tier": "T3", "furigana": "先生[せんせい]の説明[せつめい]が速[はや]くて、内容[ないよう]を把握[はあく]するのに時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "試合の流れを把握している選手が、うまく指示を出した。", "target_word": "把握", "complexity_tier": "T3", "furigana": "試合[しあい]の流[なが]れを把握[はあく]している選手[せんしゅ]が、うまく指示[しじ]を出[だ]した。", "sentence_source": "generated"}, {"text": "契約書の条件を把握しないままサインするのは危ない。", "target_word": "把握", "complexity_tier": "T3", "furigana": "契約書[けいやくしょ]の条件[じょうけん]を把握[はあく]しないままサインするのは危[あぶ]ない。", "sentence_source": "generated"}, {"text": "彼女は会議の目的を把握して、必要な資料だけを用意した。", "target_word": "把握", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は会議[かいぎ]の目的[もくてき]を把握[はあく]して、必要[ひつよう]な資料[しりょう]だけを用意[ようい]した。", "sentence_source": "generated"}, {"text": "長い小説なので、登場人物を把握するのに苦労した。", "target_word": "把握", "complexity_tier": "T3", "furigana": "長[なが]い小説[しょうせつ]なので、登場人物[とうじょうじんぶつ]を把握[はあく]するのに苦労[くろう]した。", "sentence_source": "generated"}, {"text": "町の様子を把握するため、まず歩いて一周してみた。", "target_word": "把握", "complexity_tier": "T3", "furigana": "町[まち]の様子[ようす]を把握[はあく]するため、まず歩[ある]いて一周[いっしゅう]してみた。", "sentence_source": "generated"}, {"text": "部下の仕事量を把握していないと、無理な指示を出してしまう。", "target_word": "把握", "complexity_tier": "T3", "furigana": "部下[ぶか]の仕事量[しごとりょう]を把握[はあく]していないと、無理[むり]な指示[しじ]を出[だ]してしまう。", "sentence_source": "generated"}, {"text": "説明書を読んで、機械の使い方をひと通り把握した。", "target_word": "把握", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]を読[よ]んで、機械[きかい]の使[つか]い方[かた]をひと通[とお]り把握[はあく]した。", "sentence_source": "generated"}, {"text": "自分の弱点を把握することが、上達への近道だ。", "target_word": "把握", "complexity_tier": "T3", "furigana": "自分[じぶん]の弱点[じゃくてん]を把握[はあく]することが、上達[じょうたつ]への近道[ちかみち]だ。", "sentence_source": "generated"}, {"text": "現在の状況を把握できていないので、判断はもう少し待ってほしい。", "target_word": "把握", "complexity_tier": "T3", "furigana": "現在[げんざい]の状況[じょうきょう]を把握[はあく]できていないので、判断[はんだん]はもう少[すこ]し待[ま]ってほしい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "把握する", "label": "辞書形"}, {"form": "把握した", "label": "過去形"}, {"form": "把握しない", "label": "否定形"}, {"form": "把握できる", "label": "可能形"}, {"form": "把握される", "label": "受身形"}], "register": "標準", "sense_fingerprint": "内容や状況をよく理解して、しっかりつかむこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: ひと通り (Zipf 2.31)']::text[], 'c171a401-7adc-4cc9-9573-2a4e0f6702de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38482, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "把握", "is_correct": true, "explanation": "「内容を把握するのに時間がかかった」で、内容をよく理解するという意味になり、文脈に合う。"}, {"text": "返却", "is_correct": false, "explanation": "「内容を返却するのに時間」は意味が通らず、説明を理解する文脈と合わない。"}, {"text": "解雇", "is_correct": false, "explanation": "「内容を解雇するのに時間」は成り立たず、説明の理解という流れに合わない。"}, {"text": "停止", "is_correct": false, "explanation": "「内容を停止するのに時間」は不自然で、説明を理解するのに時間がかかったという文脈と合わない。"}], "explanations": {"把握": "「内容を把握するのに時間がかかった」で、内容をよく理解するという意味になり、文脈に合う。", "返却": "「内容を返却するのに時間」は意味が通らず、説明を理解する文脈と合わない。", "解雇": "「内容を解雇するのに時間」は成り立たず、説明の理解という流れに合わない。", "停止": "「内容を停止するのに時間」は不自然で、説明を理解するのに時間がかかったという文脈と合わない。"}, "sentence_index": 0, "correct_answer": "把握"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "拍手を把握して、会場を盛り上げた。", "explanation": "ここは〈送る〉の意味。拍手は送るもので、把握は内容や状況を理解する意味なので合わない。"}, {"text": "ドアの向こうの光を把握して、息をひそめた。", "explanation": "ここは〈感じる〉の意味。光は感じ取るもので、把握は内容や状況を理解する意味なので合わない。"}, {"text": "相槌を把握して、話を続けた。", "explanation": "ここは〈打つ〉の意味。相槌は打つものであり、把握は内容や状況を理解する意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38482, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "把握", "is_correct": true, "explanation": "「部下の仕事量を把握していないと」で、仕事量を理解していない状態を表し、文脈に合う。"}, {"text": "謝罪", "is_correct": false, "explanation": "「仕事量を謝罪していないと」は意味が通らず、無理な指示を防ぐ文脈と合わない。"}, {"text": "延期", "is_correct": false, "explanation": "「仕事量を延期していないと」は不自然で、仕事量を確認するという流れに合わない。"}, {"text": "撤回", "is_correct": false, "explanation": "「仕事量を撤回していないと」は成り立たず、指示の出し方という文脈と合わない。"}], "explanations": {"把握": "「部下の仕事量を把握していないと」で、仕事量を理解していない状態を表し、文脈に合う。", "謝罪": "「仕事量を謝罪していないと」は意味が通らず、無理な指示を防ぐ文脈と合わない。", "延期": "「仕事量を延期していないと」は不自然で、仕事量を確認するという流れに合わない。", "撤回": "「仕事量を撤回していないと」は成り立たず、指示の出し方という文脈と合わない。"}, "sentence_index": 6, "correct_answer": "把握"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "挨拶を把握して、その場を離れた。", "explanation": "ここは〈交わす〉の意味。挨拶は交わすもので、把握は内容や状況を理解する意味なので合わない。"}, {"text": "彼は神に永遠の愛を把握すると誓った。", "explanation": "ここは〈誓う〉の意味。愛は誓うと結びつく決まった言い方で、把握は内容を理解する意味なので合わない。"}, {"text": "大きなため息を把握して、肩を落とした。", "explanation": "ここは〈吐く〉の意味。ため息は吐くもので、把握は内容や状況を理解する意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38482, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先輩は仕事の流れに把握していて、手際がよい。", "corrected_sentence": "先輩は仕事の流れを把握していて、手際がよい。", "error_description": "誤りは「流れに把握」。正しくは「流れを把握」。把握は「を」で対象を取るので、「に」では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38482, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新人は契約の内容を把握してを、サインするべきだ。", "corrected_sentence": "新人は契約の内容を把握してから、サインするべきだ。", "error_description": "誤りは「把握してを」。正しくは「把握してから」。「〜してから」で続けるので、「を」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38483, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「原因を把握する」で、把握の対象を示す正しい格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「原因に把握する」では把握の対象を示せず、文が不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、把握の対象にはならないため合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示すため、「原因と把握する」では対象を表せず文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「原因を把握する」で、把握の対象を示す正しい格助詞。", "に": "「原因に把握する」では把握の対象を示せず、文が不自然になる。", "へ": "方向を示す助詞で、把握の対象にはならないため合わない。", "と": "並列を示すため、「原因と把握する」では対象を表せず文が成り立たない。"}, "error_tags": {"に": "位置・相手", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38483, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「人の気持ちを把握する」で、把握の対象を示す正しい格助詞。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すため、「気持ちから把握する」では対象を表せず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すため、「気持ちより把握する」では意味が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「気持ちの把握する」は名詞修飾にならず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「人の気持ちを把握する」で、把握の対象を示す正しい格助詞。", "から": "起点を示すため、「気持ちから把握する」では対象を表せず不自然。", "より": "比較を示すため、「気持ちより把握する」では意味が成り立たない。", "の": "「気持ちの把握する」は名詞修飾にならず、文が成り立たない。"}, "error_tags": {"から": "起点", "より": "比較", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38483, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の状態や内容を正しく理解し、自分のものとすること。", "primary_collocate": null, "pronunciation": "はあく", "ipa": "haakɯ", "syllable_count": 3, "sentences": [{"text": "これは、作物の生育状況を細かく把握し、必要な水や肥料を的確に与える仕組みです。", "target_word": "把握", "complexity_tier": "T3", "furigana": "これは、作物[さくもつ]の生育状況[せいいくじょうきょう]を細[こま]かく把握[はあく]し、必要[ひつよう]な水[みず]や肥料[ひりょう]を的確[てきかく]に与[あた]える仕組[しく]みです。", "sentence_source": "mined"}, {"text": "事故の原因を把握するために、警察は現場の写真を集めた。", "target_word": "把握", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]を把握[はあく]するために、警察[けいさつ]は現場[げんば]の写真[しゃしん]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "店長は毎日の売り上げを正確に把握している。", "target_word": "把握", "complexity_tier": "T3", "furigana": "店長[てんちょう]は毎日[まいにち]の売[う]り上[あ]げを正確[せいかく]に把握[はあく]している。", "sentence_source": "generated"}, {"text": "話の内容をうまく把握できず、もう一度説明してもらった。", "target_word": "把握", "complexity_tier": "T3", "furigana": "話[はなし]の内容[ないよう]をうまく把握[はあく]できず、もう一度[いちど]説明[せつめい]してもらった。", "sentence_source": "generated"}, {"text": "新しい部署に移ったばかりで、仕事の流れをまだ把握していない。", "target_word": "把握", "complexity_tier": "T3", "furigana": "新[あたら]しい部署[ぶしょ]に移[うつ]ったばかりで、仕事[しごと]の流[なが]れをまだ把握[はあく]していない。", "sentence_source": "generated"}, {"text": "地震が起きたとき、まず家族の無事を把握することが大切だ。", "target_word": "把握", "complexity_tier": "T3", "furigana": "地震[じしん]が起[お]きたとき、まず家族[かぞく]の無事[ぶじ]を把握[はあく]することが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "全体の状況を把握してから、役割を決めよう。", "target_word": "把握", "complexity_tier": "T3", "furigana": "全体[ぜんたい]の状況[じょうきょう]を把握[はあく]してから、役割[やくわり]を決[き]めよう。", "sentence_source": "generated"}, {"text": "彼は人の気持ちを把握するのが早く、客からの信頼も厚い。", "target_word": "把握", "complexity_tier": "T3", "furigana": "彼[かれ]は人[ひと]の気持[きも]ちを把握[はあく]するのが早[はや]く、客[きゃく]からの信頼[しんらい]も厚[あつ]い。", "sentence_source": "generated"}, {"text": "地図を見て、駅までの道を把握した。", "target_word": "把握", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]て、駅[えき]までの道[みち]を把握[はあく]した。", "sentence_source": "generated"}, {"text": "問題点を把握しないまま計画を進めると、後で困ることになる。", "target_word": "把握", "complexity_tier": "T3", "furigana": "問題点[もんだいてん]を把握[はあく]しないまま計画[けいかく]を進[すす]めると、後[あと]で困[こま]ることになる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "把握する", "label": "辞書形"}, {"form": "把握した", "label": "過去形"}, {"form": "把握しない", "label": "否定形"}, {"form": "把握できる", "label": "可能形"}, {"form": "把握される", "label": "受身形"}], "register": "標準", "sense_fingerprint": "状況や内容を正確に理解して、自分のものとしてつかむこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c171a401-7adc-4cc9-9573-2a4e0f6702de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38483, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "把握", "is_correct": true, "explanation": "「細かく把握し」で、作物の生育状況を正確に理解するという意味になり、文脈に合う。"}, {"text": "拒否", "is_correct": false, "explanation": "「細かく拒否し」では作物の状況を拒むことになり、水や肥料を的確に与えるという流れと合わない。"}, {"text": "延期", "is_correct": false, "explanation": "「細かく延期し」では状況を先送りする意味になり、生育状況を見て水や肥料を与える文脈に合わない。"}, {"text": "謝罪", "is_correct": false, "explanation": "「細かく謝罪し」は謝る意味で、生育状況の管理という文脈とまったく合わない。"}], "explanations": {"把握": "「細かく把握し」で、作物の生育状況を正確に理解するという意味になり、文脈に合う。", "拒否": "「細かく拒否し」では作物の状況を拒むことになり、水や肥料を的確に与えるという流れと合わない。", "延期": "「細かく延期し」では状況を先送りする意味になり、生育状況を見て水や肥料を与える文脈に合わない。", "謝罪": "「細かく謝罪し」は謝る意味で、生育状況の管理という文脈とまったく合わない。"}, "sentence_index": 0, "correct_answer": "把握"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "深呼吸を把握して、心を落ち着けた。", "explanation": "ここは〈吸う〉の意味。深呼吸は行うもので、把握は内容や状況を理解する意味なので合わない。"}, {"text": "祝杯を把握して、みんなで乾杯した。", "explanation": "ここは〈挙げる〉の意味。祝杯は挙げるもので、把握は内容や状況を理解する意味なので合わない。"}, {"text": "期待を把握して、胸をふくらませた。", "explanation": "ここは〈抱く〉の意味。期待は抱くもので、把握は内容や状況を理解する意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38483, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "把握", "is_correct": true, "explanation": "「全体の状況を把握してから」で、状況を理解してから役割を決めるという流れになる。"}, {"text": "返却", "is_correct": false, "explanation": "「状況を返却してから」は意味が通らず、状況を理解するという前提と合わない。"}, {"text": "撤回", "is_correct": false, "explanation": "「状況を撤回してから」は不自然で、状況を把握する文脈に合わない。"}, {"text": "解雇", "is_correct": false, "explanation": "「状況を解雇してから」は成り立たず、役割を決める前提と合わない。"}], "explanations": {"把握": "「全体の状況を把握してから」で、状況を理解してから役割を決めるという流れになる。", "返却": "「状況を返却してから」は意味が通らず、状況を理解するという前提と合わない。", "撤回": "「状況を撤回してから」は不自然で、状況を把握する文脈に合わない。", "解雇": "「状況を解雇してから」は成り立たず、役割を決める前提と合わない。"}, "sentence_index": 6, "correct_answer": "把握"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ガスの匂いを把握して、すぐに窓を開けた。", "explanation": "ここは〈感知〉の意味。匂いのような感覚は感知で捉えるもので、把握は状況や内容を理解する意味なので合わない。"}, {"text": "彼は王に忠誠を把握すると誓った。", "explanation": "ここは〈誓う〉の意味。忠誠は「誓う」と結びつく決まった言い方で、把握は内容を理解する意味なので合わない。"}, {"text": "こぼれそうな涙を把握して、ぐっとこらえた。", "explanation": "ここは〈こらえる〉の意味。涙は我慢する対象で、把握は内容を理解する意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38483, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店長は在庫の数を正確に把握で、発注を決めた。", "corrected_sentence": "店長は在庫の数を正確に把握して、発注を決めた。", "error_description": "誤りは「把握で」。正しくは「把握して」。「把握」は「する」を伴う名詞なので、後ろは「して」で続け、「で」では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38483, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "部下の仕事の進み具合を把握に、必要な指示を出す。", "corrected_sentence": "部下の仕事の進み具合を把握して、必要な指示を出す。", "error_description": "誤りは「把握に」。正しくは「把握して」。「把握」の後は「して」で続くので、「に」は文法的に誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b0992f6-7dda-4daa-b60c-e774e683d3ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
