INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38484, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "地面の傾きのことです。", "primary_collocate": null, "pronunciation": "こうばい", "ipa": "koːbai", "syllable_count": 4, "sentences": [{"text": "この坂道は勾配が急で、自転車では上れません。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "この坂道[さかみち]は勾配[こうばい]が急[きゅう]で、自転車[じてんしゃ]では上[のぼ]れません。", "sentence_source": "generated"}, {"text": "駅までの道は勾配がゆるやかなので、歩きやすいです。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "駅[えき]までの道[みち]は勾配[こうばい]がゆるやかなので、歩[ある]きやすいです。", "sentence_source": "generated"}, {"text": "勾配のきつい山道を、重い荷物を持って登った。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "勾配[こうばい]のきつい山道[やまみち]を、重[おも]い荷物[にもつ]を持[も]って登[のぼ]った。", "sentence_source": "generated"}, {"text": "畑の土地には少し勾配があって、雨水は下へ流れる。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "畑[はたけ]の土地[とち]には少[すこ]し勾配[こうばい]があって、雨水[あまみず]は下[した]へ流[なが]れる。", "sentence_source": "generated"}, {"text": "勾配が急な坂では、車はゆっくり下りるべきです。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "勾配[こうばい]が急[きゅう]な坂[さか]では、車[くるま]はゆっくり下[お]りるべきです。", "sentence_source": "generated"}, {"text": "この道は勾配がほとんどなく、ほぼ平らだ。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "この道[みち]は勾配[こうばい]がほとんどなく、ほぼ平[たい]らだ。", "sentence_source": "generated"}, {"text": "雨が降ると、勾配に沿って水が低いほうへ流れていく。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ると、勾配[こうばい]に沿[そ]って水[みず]が低[ひく]いほうへ流[なが]れていく。", "sentence_source": "generated"}, {"text": "線路は、勾配を小さくするために、ぐるりと回って作られた。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "線路[せんろ]は、勾配[こうばい]を小[ちい]さくするために、ぐるりと回[まわ]って作[つく]られた。", "sentence_source": "generated"}, {"text": "勾配の急な坂道では、バスのエンジンの音が大きくなる。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "勾配[こうばい]の急[きゅう]な坂道[さかみち]では、バスのエンジンの音[おと]が大[おお]きくなる。", "sentence_source": "generated"}, {"text": "庭に勾配をつけておくと、水がたまらなくなります。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "庭[にわ]に勾配[こうばい]をつけておくと、水[みず]がたまらなくなります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "勾配", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "坂道や土地の傾き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9d837e-9b28-4e2f-9d20-c846059db583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38484, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "勾配", "is_correct": true, "explanation": "坂の傾きを表す語で、「急で上れない」という説明に合う。"}, {"text": "地図", "is_correct": false, "explanation": "紙の地図を指すので、坂の傾きの説明には使わない。"}, {"text": "地震", "is_correct": false, "explanation": "揺れを指す語で、坂の急さを述べる文には合わない。"}, {"text": "答案", "is_correct": false, "explanation": "答えを書いた紙のことで、坂の傾きとは関係がない。"}], "explanations": {"勾配": "坂の傾きを表す語で、「急で上れない」という説明に合う。", "地図": "紙の地図を指すので、坂の傾きの説明には使わない。", "地震": "揺れを指す語で、坂の急さを述べる文には合わない。", "答案": "答えを書いた紙のことで、坂の傾きとは関係がない。"}, "sentence_index": 0, "correct_answer": "勾配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "車の勾配が上がった。", "explanation": "ここは〈速度〉の意味。勾配は地面の傾きなので、車の速さには使わない。"}, {"text": "この山は勾配が高い。", "explanation": "ここは〈高さ〉の意味。勾配は傾きの度合いで、山の標高を表すには使わない。"}, {"text": "木の葉の勾配が変わった。", "explanation": "ここは〈色〉の意味。勾配は地面の傾きなので、葉の色の変化には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38484, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勾配", "is_correct": true, "explanation": "傾いた地面に沿って水が流れるという意味に合う。"}, {"text": "答弁", "is_correct": false, "explanation": "国会などでの回答を指すので、水の流れの説明には合わない。"}, {"text": "懸賞", "is_correct": false, "explanation": "賞品をかけた催しのことで、水が流れる文脈では意味が通らない。"}, {"text": "参考書", "is_correct": false, "explanation": "勉強に使う本のことで、水が沿って流れるという文には合わない。"}], "explanations": {"勾配": "傾いた地面に沿って水が流れるという意味に合う。", "答弁": "国会などでの回答を指すので、水の流れの説明には合わない。", "懸賞": "賞品をかけた催しのことで、水が流れる文脈では意味が通らない。", "参考書": "勉強に使う本のことで、水が沿って流れるという文には合わない。"}, "sentence_index": 6, "correct_answer": "勾配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電池の勾配が短くなった。", "explanation": "ここは〈寿命〉の意味。勾配は地面の傾きなので、電池の持ちには使わない。"}, {"text": "スープの勾配が薄い。", "explanation": "ここは〈味〉の意味。勾配は傾きを表すので、味の濃さには使わない。"}, {"text": "荷物の勾配が重い。", "explanation": "ここは〈重さ〉の意味。勾配は傾きの度合いなので、荷物の重さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38484, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この自転車道は勾配をゆるやかで、子どもも安心して走れる。", "corrected_sentence": "この自転車道は勾配がゆるやかで、子どもも安心して走れる。", "error_description": "「ゆるやか」の主語は「が」で示す。「勾配を」は誤りで、正しくは「勾配が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38484, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この坂は勾配が重くて、自転車は押して登る。", "corrected_sentence": "この坂は勾配がきつくて、自転車は押して登る。", "error_description": "坂の傾きの強さは「きつい」「急」で表す。「勾配が重い」は不自然で、正しくは「勾配がきつい」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38485, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「道路の勾配が十分の一」で、勾配が主語になる。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示す。「勾配で十分の一と書いてある」は書く手段にならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「勾配へ十分の一と書いてある」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示す。「勾配より十分の一」では比べる対象が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「道路の勾配が十分の一」で、勾配が主語になる。", "で": "「で」は手段を示す。「勾配で十分の一と書いてある」は書く手段にならず不自然。", "へ": "「へ」は方向を示す。「勾配へ十分の一と書いてある」は不自然。", "より": "「より」は比較を示す。「勾配より十分の一」では比べる対象が成り立たない。"}, "error_tags": {"で": "手段", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38485, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「川の勾配が大きいほど」で、勾配が主語になる。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。「勾配で大きいほど」とは続かない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示す。「勾配と大きいほど」では並ぶ語が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。「勾配から大きいほど」では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「川の勾配が大きいほど」で、勾配が主語になる。", "で": "「で」は手段や場所を示す。「勾配で大きいほど」とは続かない。", "と": "「と」は並列を示す。「勾配と大きいほど」では並ぶ語が成り立たない。", "から": "「から」は起点を示す。「勾配から大きいほど」では意味が通らない。"}, "error_tags": {"で": "場所・手段", "と": "並列", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38485, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "水平面に対する面の傾きの度合い。", "primary_collocate": null, "pronunciation": "こうばい", "ipa": "koːbai", "syllable_count": 4, "sentences": [{"text": "雪が滑り落ちるように、屋根の勾配を急にしてあります。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "雪[ゆき]が滑[すべ]り落[お]ちるように、屋根[やね]の勾配[こうばい]を急[きゅう]にしてあります。", "sentence_source": "generated"}, {"text": "設計図には、道路の勾配が十分の一と書いてある。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "設計図[せっけいず]には、道路[どうろ]の勾配[こうばい]が十分[じゅうぶん]の一[いち]と書[か]いてある。", "sentence_source": "generated"}, {"text": "この階段は勾配が大きすぎて、お年寄りには危険だ。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "この階段[かいだん]は勾配[こうばい]が大[おお]きすぎて、お年寄[としよ]りには危険[きけん]だ。", "sentence_source": "generated"}, {"text": "車いすが通れるように、スロープの勾配は小さくしなければならない。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "車[くるま]いすが通[とお]れるように、スロープの勾配[こうばい]は小[ちい]さくしなければならない。", "sentence_source": "generated"}, {"text": "排水のために、床には少しだけ勾配がつけてある。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "排水[はいすい]のために、床[ゆか]には少[すこ]しだけ勾配[こうばい]がつけてある。", "sentence_source": "generated"}, {"text": "斜面の勾配を測る機械で、土地の傾きを調べた。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "斜面[しゃめん]の勾配[こうばい]を測[はか]る機械[きかい]で、土地[とち]の傾[かたむ]きを調[しら]べた。", "sentence_source": "generated"}, {"text": "屋根の勾配が違うと、家の見た目はずいぶん変わる。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "屋根[やね]の勾配[こうばい]が違[ちが]うと、家[いえ]の見[み]た目[め]はずいぶん変[か]わる。", "sentence_source": "generated"}, {"text": "川の勾配が大きいほど、水の流れは速くなります。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "川[かわ]の勾配[こうばい]が大[おお]きいほど、水[みず]の流[なが]れは速[はや]くなります。", "sentence_source": "generated"}, {"text": "工事の前に、水平な面に対する勾配を計算する。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "工事[こうじ]の前[まえ]に、水平[すいへい]な面[めん]に対[たい]する勾配[こうばい]を計算[けいさん]する。", "sentence_source": "generated"}, {"text": "勾配が三度以内なら、ボールはほとんど転がりません。", "target_word": "勾配", "complexity_tier": "T3", "furigana": "勾配[こうばい]が三度[さんど]以内[いない]なら、ボールはほとんど転[ころ]がりません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "勾配", "label": "基本形"}], "register": "formal", "sense_fingerprint": "水平な面に対して面がどれだけ傾いているかの度合い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e9d837e-9b28-4e2f-9d20-c846059db583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38485, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "勾配", "is_correct": true, "explanation": "屋根の傾きの度合いを表し、「急にする」という述語に合う。"}, {"text": "地震", "is_correct": false, "explanation": "揺れを指す語で、屋根の傾きを変える対象にはならない。"}, {"text": "地図", "is_correct": false, "explanation": "紙の地図を指すので、屋根の傾きは変えられない。"}, {"text": "答案", "is_correct": false, "explanation": "答えを書いた紙のことで、屋根の構造には関係がない。"}], "explanations": {"勾配": "屋根の傾きの度合いを表し、「急にする」という述語に合う。", "地震": "揺れを指す語で、屋根の傾きを変える対象にはならない。", "地図": "紙の地図を指すので、屋根の傾きは変えられない。", "答案": "答えを書いた紙のことで、屋根の構造には関係がない。"}, "sentence_index": 0, "correct_answer": "勾配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風の勾配が増した。", "explanation": "ここは〈強さ〉の意味。勾配は面の傾きなので、風の強弱には使わない。"}, {"text": "参加者の勾配が多かった。", "explanation": "ここは〈数〉の意味。勾配は傾きの度合いなので、人数には使わない。"}, {"text": "荷物の勾配を量る。", "explanation": "ここは〈重さ〉の意味。勾配は傾きなので、重さを量る対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38485, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勾配", "is_correct": true, "explanation": "屋根の傾きの違いを表し、見た目の変化を説明する文に合う。"}, {"text": "地下水", "is_correct": false, "explanation": "地下にある水のことで、屋根の傾きとは関係がない。"}, {"text": "地層", "is_correct": false, "explanation": "地面の層を指すので、屋根の形の違いには当てはまらない。"}, {"text": "答弁", "is_correct": false, "explanation": "国会などでの回答を指すので、家の見た目の説明には関係がない。"}], "explanations": {"勾配": "屋根の傾きの違いを表し、見た目の変化を説明する文に合う。", "地下水": "地下にある水のことで、屋根の傾きとは関係がない。", "地層": "地面の層を指すので、屋根の形の違いには当てはまらない。", "答弁": "国会などでの回答を指すので、家の見た目の説明には関係がない。"}, "sentence_index": 6, "correct_answer": "勾配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工事の勾配が長かった。", "explanation": "ここは〈年数〉の意味。勾配は傾きの度合いなので、期間の長さには使わない。"}, {"text": "大会で勾配が一位になった。", "explanation": "ここは〈順位〉の意味。勾配は傾きの度合いなので、大会の着順には使わない。"}, {"text": "熱があって、勾配が高い。", "explanation": "ここは〈体温〉の意味。勾配は地面の傾きなので、体の温度には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38485, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このスロープは勾配を急なため、車いすの利用者には危険である。", "corrected_sentence": "このスロープは勾配が急なため、車いすの利用者には危険である。", "error_description": "「急だ」の主語は「が」で示す。「勾配を」は誤りで、正しくは「勾配が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38485, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この斜面は勾配が重く、雨が降ると土砂が流れやすい。", "corrected_sentence": "この斜面は勾配が大きく、雨が降ると土砂が流れやすい。", "error_description": "傾きの度合いは「大きい」「急」で表す。「勾配が重く」は不自然で、正しくは「勾配が大きく」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70ffe75c-2646-4cf6-8b80-b50acc0a4388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38486, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「図を描く」の「を」。描く対象を示す目的語。"}, {"text": "が", "is_correct": false, "explanation": "「図が描いて」では図が主語になり、描く人が不在で文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「図へ描いて」は方向を表す「へ」が合わず、描く対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「図と描いて」は並列の「と」で、図と何かを並べて描く意味になり、文脈に合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「図を描く」の「を」。描く対象を示す目的語。", "が": "「図が描いて」では図が主語になり、描く人が不在で文が成り立たない。", "へ": "「図へ描いて」は方向を表す「へ」が合わず、描く対象を示せない。", "と": "「図と描いて」は並列の「と」で、図と何かを並べて描く意味になり、文脈に合わない。"}, "error_tags": {"が": "主語", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
