INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38486, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものをかくときに、かたちをしめすためのえ。", "primary_collocate": null, "pronunciation": "ず", "ipa": "zɯ", "syllable_count": 1, "sentences": [{"text": "理科の教科書には、植物の体の図がのっている。", "target_word": "図", "complexity_tier": "T3", "furigana": "理科[りか]の教科書[きょうかしょ]には、植物[しょくぶつ]の体[からだ]の図[ず]がのっている。", "sentence_source": "generated"}, {"text": "兄は家の図をかいて、部屋の場所を見せてくれた。", "target_word": "図", "complexity_tier": "T3", "furigana": "兄[あに]は家[いえ]の図[ず]をかいて、部屋[へや]の場所[ばしょ]を見[み]せてくれた。", "sentence_source": "generated"}, {"text": "この図のように、紙を半分におってください。", "target_word": "図", "complexity_tier": "T3", "furigana": "この図[ず]のように、紙[かみ]を半分[はんぶん]におってください。", "sentence_source": "generated"}, {"text": "図を見ながら、おもちゃのロボットを作った。", "target_word": "図", "complexity_tier": "T3", "furigana": "図[ず]を見[み]ながら、おもちゃのロボットを作[つく]った。", "sentence_source": "generated"}, {"text": "先生が黒板にまるい図をかいて、月の形を教えた。", "target_word": "図", "complexity_tier": "T3", "furigana": "先生[せんせい]が黒板[こくばん]にまるい図[ず]をかいて、月[つき]の形[かたち]を教[おし]えた。", "sentence_source": "generated"}, {"text": "図には、川と山の位置が分かりやすく示してある。", "target_word": "図", "complexity_tier": "T3", "furigana": "図[ず]には、川[かわ]と山[やま]の位置[いち]が分[わ]かりやすく示[しめ]してある。", "sentence_source": "generated"}, {"text": "その図は線が少なくて、とても見やすい。", "target_word": "図", "complexity_tier": "T3", "furigana": "その図[ず]は線[せん]が少[すく]なくて、とても見[み]やすい。", "sentence_source": "generated"}, {"text": "説明の図を見れば、使い方がすぐに分かる。", "target_word": "図", "complexity_tier": "T3", "furigana": "説明[せつめい]の図[ず]を見[み]れば、使[つか]い方[かた]がすぐに分[わ]かる。", "sentence_source": "generated"}, {"text": "ノートに図を写して、色をぬった。", "target_word": "図", "complexity_tier": "T3", "furigana": "ノートに図[ず]を写[うつ]して、色[いろ]をぬった。", "sentence_source": "generated"}, {"text": "この図は、わたしの町の道を表したものです。", "target_word": "図", "complexity_tier": "T3", "furigana": "この図[ず]は、わたしの町[まち]の道[みち]を表[あらわ]したものです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "図", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ものの形を示すためにかく絵（教科書や説明書の図）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c11387b-8867-4c59-8ba8-001d65627932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38486, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "図", "is_correct": true, "explanation": "正解。植物の体の形を示すために描かれ、教科書にのる図を指す。"}, {"text": "指紋", "is_correct": false, "explanation": "指紋は指の模様の意味。植物の体を示す教科書の内容とは結びつかない。"}, {"text": "体温", "is_correct": false, "explanation": "体温は体の熱の意味。教科書にのっている対象として文が成り立たない。"}, {"text": "雷", "is_correct": false, "explanation": "雷は自然現象の意味。教科書にのる対象として意味が通らない。"}], "explanations": {"図": "正解。植物の体の形を示すために描かれ、教科書にのる図を指す。", "指紋": "指紋は指の模様の意味。植物の体を示す教科書の内容とは結びつかない。", "体温": "体温は体の熱の意味。教科書にのっている対象として文が成り立たない。", "雷": "雷は自然現象の意味。教科書にのる対象として意味が通らない。"}, "sentence_index": 0, "correct_answer": "図"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町の図は、年々減っている。", "explanation": "図は形を示す絵で、町の人数の増減は表せない。"}, {"text": "図には、友人への感謝が丁寧に書かれていた。", "explanation": "図は形を示す絵で、感謝を丁寧に書き連ねるものではない。"}, {"text": "図には、今日の出来事がそのまま書かれていた。", "explanation": "図は形を示す絵で、出来事を文章で記録するものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38486, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "図", "is_correct": true, "explanation": "正解。線の少なさや見やすさを評価できる図を指し、文意に合う。"}, {"text": "布団", "is_correct": false, "explanation": "布団は寝具の意味。線が少ないとか見やすいと評する対象ではない。"}, {"text": "湯", "is_correct": false, "explanation": "湯は湯船のお湯の意味。線の多少を言う対象にはならない。"}, {"text": "灯油", "is_correct": false, "explanation": "灯油は燃料の意味。見やすさを評価する対象として成り立たない。"}], "explanations": {"図": "正解。線の少なさや見やすさを評価できる図を指し、文意に合う。", "布団": "布団は寝具の意味。線が少ないとか見やすいと評する対象ではない。", "湯": "湯は湯船のお湯の意味。線の多少を言う対象にはならない。", "灯油": "灯油は燃料の意味。見やすさを評価する対象として成り立たない。"}, "sentence_index": 6, "correct_answer": "図"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "湯の図は、ちょうどよかった。", "explanation": "湯の熱さの程度は温度で表し、図では表せない。"}, {"text": "この図は、町の夏祭りの思い出を涙ながらに語っている。", "explanation": "図は形を描き表すもので、思い出を言葉で語ることはできない。"}, {"text": "この図は、秋の夜長を静かに歌っている。", "explanation": "図は形や仕組みを描き表すもので、言葉で歌うことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38486, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この図を通りに、パーツを並べてください。", "corrected_sentence": "この図の通りに、パーツを並べてください。", "error_description": "誤: 「図」に「を」が付き、「通り」と続かない。正: 「図の通りに」の「の」。図に示したとおりを表す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38486, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この図を線が少なくて、初心者にも見やすい。", "corrected_sentence": "この図は線が少なくて、初心者にも見やすい。", "error_description": "誤: 「図」に「を」が付き、「線が少なくて」の主語にならない。正: 「図は線が少なくて」の「は」。図を主題として述べる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
