INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38487, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物事の形や仕組みを、線や点を使って平面上に描き表したもの。", "primary_collocate": null, "pronunciation": "ず", "ipa": "zɯ", "syllable_count": 1, "sentences": [{"text": "その会社の組織の図は、社長から順に線で結ばれている。", "target_word": "図", "complexity_tier": "T3", "furigana": "その会社[かいしゃ]の組織[そしき]の図[ず]は、社長[しゃちょう]から順[じゅん]に線[せん]で結[むす]ばれている。", "sentence_source": "generated"}, {"text": "先生は黒板に、電気が流れる仕組みを図で説明した。", "target_word": "図", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]に、電気[でんき]が流[なが]れる仕組[しく]みを図[ず]で説明[せつめい]した。", "sentence_source": "generated"}, {"text": "下の図を見て、問題に答えてください。", "target_word": "図", "complexity_tier": "T3", "furigana": "下[した]の図[ず]を見[み]て、問題[もんだい]に答[こた]えてください。", "sentence_source": "generated"}, {"text": "この図は、駅の中の道順を簡単に示している。", "target_word": "図", "complexity_tier": "T3", "furigana": "この図[ず]は、駅[えき]の中[なか]の道順[みちじゅん]を簡単[かんたん]に示[しめ]している。", "sentence_source": "generated"}, {"text": "説明書の図のとおりに、棚を組み立てた。", "target_word": "図", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]の図[ず]のとおりに、棚[たな]を組[く]み立[た]てた。", "sentence_source": "generated"}, {"text": "彼は紙に図をかいて、新しい機械の仕組みを教えてくれた。", "target_word": "図", "complexity_tier": "T3", "furigana": "彼[かれ]は紙[かみ]に図[ず]をかいて、新[あたら]しい機械[きかい]の仕組[しく]みを教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "文章だけでは分かりにくいので、図を入れることにした。", "target_word": "図", "complexity_tier": "T3", "furigana": "文章[ぶんしょう]だけでは分[わ]かりにくいので、図[ず]を入[い]れることにした。", "sentence_source": "generated"}, {"text": "次の図は、水が雲になって雨になる流れを表している。", "target_word": "図", "complexity_tier": "T3", "furigana": "次[つぎ]の図[ず]は、水[みず]が雲[くも]になって雨[あめ]になる流[なが]れを表[あらわ]している。", "sentence_source": "generated"}, {"text": "図と文章が合っていなくて、読者が混乱した。", "target_word": "図", "complexity_tier": "T3", "furigana": "図[ず]と文章[ぶんしょう]が合[あ]っていなくて、読者[どくしゃ]が混乱[こんらん]した。", "sentence_source": "generated"}, {"text": "この本は図が多いので、子どもでも理解しやすい。", "target_word": "図", "complexity_tier": "T3", "furigana": "この本[ほん]は図[ず]が多[おお]いので、子[こ]どもでも理解[りかい]しやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "図", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "形や仕組みを線や点で平面に描き表したもの（図解・図表の図）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c11387b-8867-4c59-8ba8-001d65627932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38487, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "図", "is_correct": true, "explanation": "正解。組織の関係を線で結んで示した図を指し、文意に合う。"}, {"text": "札", "is_correct": false, "explanation": "札は名札や木の札の意味。「組織の札」は線で結ばれる対象として文が成り立たない。"}, {"text": "絵", "is_correct": false, "explanation": "絵は美術作品を指す語。「組織の絵」は線で結ばれる組織図として成り立たない。"}, {"text": "箱", "is_correct": false, "explanation": "箱は入れ物の意味。「組織の箱」は文が成り立たない。"}], "explanations": {"図": "正解。組織の関係を線で結んで示した図を指し、文意に合う。", "札": "札は名札や木の札の意味。「組織の札」は線で結ばれる対象として文が成り立たない。", "絵": "絵は美術作品を指す語。「組織の絵」は線で結ばれる組織図として成り立たない。", "箱": "箱は入れ物の意味。「組織の箱」は文が成り立たない。"}, "sentence_index": 0, "correct_answer": "図"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この図は、駅前の景色を鮮やかな色で映している。", "explanation": "ここは〈写真〉の意味。図は線や点で形や仕組みを描き表すもので、色や景色を写し取るものではない。"}, {"text": "この図は、友人への近況を丁寧に伝えている。", "explanation": "ここは〈手紙〉の意味。図は形や仕組みを示すもので、近況を言葉で伝える役割は持たない。"}, {"text": "この図は、夕焼けの色を繊細に描いている。", "explanation": "ここは〈絵〉の意味。図は線や点で形を描き表すもので、色彩の表現は含まない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38487, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "図", "is_correct": true, "explanation": "正解。「図を入れる」で、説明のための図を文章に加えることを指し、文意に合う。"}, {"text": "湯気", "is_correct": false, "explanation": "湯気は蒸気の意味。文章に入れるものではなく、文が成り立たない。"}, {"text": "寝袋", "is_correct": false, "explanation": "寝袋は寝具の意味。文章に入れるものではない。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸は洗浄剤の意味。文章に入れるものではない。"}], "explanations": {"図": "正解。「図を入れる」で、説明のための図を文章に加えることを指し、文意に合う。", "湯気": "湯気は蒸気の意味。文章に入れるものではなく、文が成り立たない。", "寝袋": "寝袋は寝具の意味。文章に入れるものではない。", "石鹸": "石鹸は洗浄剤の意味。文章に入れるものではない。"}, "sentence_index": 6, "correct_answer": "図"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来週の参加者の図が、予想より多かった。", "explanation": "ここは〈数〉の意味。人の数は〈数〉で表し、線や点で形を描く図は人数を表せない。"}, {"text": "子どもたちの明るい図が、ホールいっぱいに響いた。", "explanation": "ここは〈声〉の意味。ホールに響くのは〈声〉で、線や点で形を描く図は音を発しない。"}, {"text": "今朝の図は、昨日より五度低かった。", "explanation": "ここは〈気温〉の意味。気温の高低は〈気温〉で表し、線や点で形を描く図は温度を表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38487, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "係員は、路線の図に乗り換えを説明した。", "corrected_sentence": "係員は、路線の図で乗り換えを説明した。", "error_description": "誤: 「図」に「に」が付いている。正: 「図で説明する」の「で」。道具・手段を表し、図を使って説明する意味になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38487, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この記事は図を多いので、初心者にも読みやすい。", "corrected_sentence": "この記事は図が多いので、初心者にも読みやすい。", "error_description": "誤: 「図」に「を」が付き、「多い」の主語になっていない。正: 「図が多い」の「が」。「多い」は「が」で主語を取る。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5da807ca-3184-4e62-8c9e-e6ebe3470212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38488, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "『口伝で伝わりました』で、口で話して伝える手段を示す。"}, {"text": "を", "is_correct": false, "explanation": "『口伝を伝わりました』では目的語を示せず、『伝わる』は目的語を取らないので不自然。"}, {"text": "に", "is_correct": false, "explanation": "『口伝に伝わりました』は帰着点を示すが、『口伝』を伝わる先とすると不自然。"}, {"text": "の", "is_correct": false, "explanation": "『口伝の伝わりました』では名詞修飾になるが、述語が続かず文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "『口伝で伝わりました』で、口で話して伝える手段を示す。", "を": "『口伝を伝わりました』では目的語を示せず、『伝わる』は目的語を取らないので不自然。", "に": "『口伝に伝わりました』は帰着点を示すが、『口伝』を伝わる先とすると不自然。", "の": "『口伝の伝わりました』では名詞修飾になるが、述語が続かず文が成り立たない。"}, "error_tags": {"を": "目的語（他動詞の対象）", "に": "帰着点・相手", "の": "所有・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38488, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "『口伝で守られています』で、守る手段として口伝を示す。"}, {"text": "と", "is_correct": false, "explanation": "『口伝と守られています』では並列・共同の相手を示すが、守る手段としては成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "『口伝へ守られています』は方向を示すが、『口伝』を守られる先とすると意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "『口伝より守られています』は比較を示すが、守る手段として続かず不自然。"}], "correct_answer": "で", "explanations": {"で": "『口伝で守られています』で、守る手段として口伝を示す。", "と": "『口伝と守られています』では並列・共同の相手を示すが、守る手段としては成り立たない。", "へ": "『口伝へ守られています』は方向を示すが、『口伝』を守られる先とすると意味が通らない。", "より": "『口伝より守られています』は比較を示すが、守る手段として続かず不自然。"}, "error_tags": {"と": "並列・共同", "へ": "方向・相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38488, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "口で伝えること。", "primary_collocate": null, "pronunciation": "くでん", "ipa": "kɯdeɴ", "syllable_count": 3, "sentences": [{"text": "この料理の作り方は、母から口伝で教わりました。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "この料理[りょうり]の作[つく]り方[かた]は、母[はは]から口伝[くでん]で教[おそ]わりました。", "sentence_source": "generated"}, {"text": "昔話は、おばあさんから孫へ口伝で伝わりました。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "昔話[むかしばなし]は、おばあさんから孫[まご]へ口伝[くでん]で伝[つた]わりました。", "sentence_source": "generated"}, {"text": "秘密の方法は、口伝でしか教えてもらえません。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "秘密[ひみつ]の方法[ほうほう]は、口伝[くでん]でしか教[おし]えてもらえません。", "sentence_source": "generated"}, {"text": "口伝だと、話す人によって内容が少しずつ変わります。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "口伝[くでん]だと、話[はな]す人[ひと]によって内容[ないよう]が少[すこ]しずつ変[か]わります。", "sentence_source": "generated"}, {"text": "祖父はこの歌を、口伝で覚えたそうです。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "祖父[そふ]はこの歌[うた]を、口伝[くでん]で覚[おぼ]えたそうです。", "sentence_source": "generated"}, {"text": "口伝では、細かい数字をまちがえやすいです。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "口伝[くでん]では、細[こま]かい数字[すうじ]をまちがえやすいです。", "sentence_source": "generated"}, {"text": "村のお祭りのやり方は、口伝で守られています。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "村[むら]のお祭[まつ]りのやり方[かた]は、口伝[くでん]で守[まも]られています。", "sentence_source": "generated"}, {"text": "待ち合わせの場所は、口伝でみんなに伝えました。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "待[ま]ち合[あ]わせの場所[ばしょ]は、口伝[くでん]でみんなに伝[つた]えました。", "sentence_source": "generated"}, {"text": "文字がなかった時代、物語は口伝で広まりました。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "文字[もじ]がなかった時代[じだい]、物語[ものがたり]は口伝[くでん]で広[ひろ]まりました。", "sentence_source": "generated"}, {"text": "父から子へ、口伝で受けつがれてきた技です。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "父[ちち]から子[こ]へ、口伝[くでん]で受[う]けつがれてきた技[わざ]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "口伝", "label": "基本形"}], "register": "中立（丁寧体）", "sense_fingerprint": "口で話して人に伝えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fe9a294-c720-4877-860c-14bdcabf3668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38488, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口伝", "is_correct": true, "explanation": "母から口で話して教わったことを表し、文に合う。"}, {"text": "雑音", "is_correct": false, "explanation": "「雑音」は騒がしい音を指す。教わる手段としては成り立たない。"}, {"text": "足跡", "is_correct": false, "explanation": "「足跡」は地面に残る跡を指す。教わる手段とは合わない。"}, {"text": "湯気", "is_correct": false, "explanation": "「湯気」は立ちのぼる蒸気を指す。教わる手段にはならない。"}], "explanations": {"口伝": "母から口で話して教わったことを表し、文に合う。", "雑音": "「雑音」は騒がしい音を指す。教わる手段としては成り立たない。", "足跡": "「足跡」は地面に残る跡を指す。教わる手段とは合わない。", "湯気": "「湯気」は立ちのぼる蒸気を指す。教わる手段にはならない。"}, "sentence_index": 0, "correct_answer": "口伝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その絵は、口伝で描かれた。", "explanation": "ここは〈筆〉（絵を描く道具）の意味。口伝は口で話して伝えることなので、絵を描く手段にはならない。"}, {"text": "料理は、口伝で温めた。", "explanation": "ここは〈加熱〉（火や電子レンジで熱する）の意味。口伝は口で話して伝えることなので、料理を温める手段にはならない。"}, {"text": "口伝で手紙を送った。", "explanation": "ここは〈伝書鳩〉（手紙を運ぶ鳩）の意味。口伝は口で話して伝えることで、手紙を送る手段ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38488, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口伝", "is_correct": true, "explanation": "代々口で伝えられてきたことを表し、守られている様子に合う。"}, {"text": "蒸気", "is_correct": false, "explanation": "「蒸気」は水が気体になったものを指す。守る手段にはならない。"}, {"text": "落書き", "is_correct": false, "explanation": "「落書き」は書いた線を指す。守る手段とは合わない。"}, {"text": "煙", "is_correct": false, "explanation": "「煙」は燃えて立ちのぼるものを指す。守る方法にはならない。"}], "explanations": {"口伝": "代々口で伝えられてきたことを表し、守られている様子に合う。", "蒸気": "「蒸気」は水が気体になったものを指す。守る手段にはならない。", "落書き": "「落書き」は書いた線を指す。守る手段とは合わない。", "煙": "「煙」は燃えて立ちのぼるものを指す。守る方法にはならない。"}, "sentence_index": 6, "correct_answer": "口伝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作戦の指示は、口伝で書かれていた。", "explanation": "ここは〈文書〉（文字で書いて残すもの）の意味。口伝は口で話して伝えることなので、文字で書かれた指示には使わない。"}, {"text": "番組は、口伝で放送された。", "explanation": "ここは〈ラジオ〉（電波で音声を流す媒体）の意味。口伝は人が口で伝えることで、放送の媒体にはならない。"}, {"text": "船は口伝で合図した。", "explanation": "ここは〈手旗信号〉（旗で合図する方法）の意味。口伝は口で話すことなので、旗や身振りの合図には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38488, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は、このお菓子の作り方を口伝に教えてくれた。", "corrected_sentence": "祖母は、このお菓子の作り方を口伝で教えてくれた。", "error_description": "手段を表す「で」が正しい。「口伝に」は誤りで、正しくは「口伝で教えてくれた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38488, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この家の味噌の作り方は、口伝の受け継がれている。", "corrected_sentence": "この家の味噌の作り方は、口伝で受け継がれている。", "error_description": "「口伝」は手段を表すので「で」を使う。「の」は名詞を修飾するときに使うもので、動詞「受け継がれている」には直接つながらない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38489, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『口伝によって』の『に』で、手段・根拠を表す『によって』を構成する。"}, {"text": "を", "is_correct": false, "explanation": "『をによって』では格助詞が重なって成り立たない。目的語の『を』は『によって』の前には入らない。"}, {"text": "と", "is_correct": false, "explanation": "『口伝とによって』では並列・共同の相手を示すが、『によって』の形と合わず成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "『口伝のによって』では名詞修飾になるが、『によって』の前に入ると文が崩れる。"}], "correct_answer": "に", "explanations": {"に": "『口伝によって』の『に』で、手段・根拠を表す『によって』を構成する。", "を": "『をによって』では格助詞が重なって成り立たない。目的語の『を』は『によって』の前には入らない。", "と": "『口伝とによって』では並列・共同の相手を示すが、『によって』の形と合わず成り立たない。", "の": "『口伝のによって』では名詞修飾になるが、『によって』の前に入ると文が崩れる。"}, "error_tags": {"を": "目的語（他動詞の対象）", "と": "並列・引用", "の": "所有・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38489, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "『口伝で守られている』で、守る手段として口伝を示す。"}, {"text": "より", "is_correct": false, "explanation": "『口伝より守られている』は比較を示すが、守る手段として続かず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "『口伝へ守られている』は方向を示すが、『口伝』を守られる先とすると意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "『口伝から守られている』は起点を示すが、守る手段としては続かず不自然。"}], "correct_answer": "で", "explanations": {"で": "『口伝で守られている』で、守る手段として口伝を示す。", "より": "『口伝より守られている』は比較を示すが、守る手段として続かず不自然。", "へ": "『口伝へ守られている』は方向を示すが、『口伝』を守られる先とすると意味が通らない。", "から": "『口伝から守られている』は起点を示すが、守る手段としては続かず不自然。"}, "error_tags": {"より": "比較", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38489, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "書かずに、話して伝えること。", "primary_collocate": null, "pronunciation": "くでん", "ipa": "kɯdeɴ", "syllable_count": 3, "sentences": [{"text": "大事な決まりだが、文書にせず口伝で伝えられている。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "大事[だいじ]な決[き]まりだが、文書[ぶんしょ]にせず口伝[くでん]で伝[つた]えられている。", "sentence_source": "generated"}, {"text": "能の秘伝は、書き残さず口伝によって受け継がれた。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "能[のう]の秘伝[ひでん]は、書[か]き残[のこ]さず口伝[くでん]によって受[う]け継[つ]がれた。", "sentence_source": "generated"}, {"text": "職人の技術は、本ではなく口伝で学ぶものだ。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "職人[しょくにん]の技術[ぎじゅつ]は、本[ほん]ではなく口伝[くでん]で学[まな]ぶものだ。", "sentence_source": "generated"}, {"text": "口伝は、文字に残らないので、間違いが生じやすい。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "口伝[くでん]は、文字[もじ]に残[のこ]らないので、間違[まちが]いが生[しょう]じやすい。", "sentence_source": "generated"}, {"text": "彼は師匠から茶の湯の心得を口伝で授かった。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "彼[かれ]は師匠[ししょう]から茶[ちゃ]の湯[ゆ]の心得[こころえ]を口伝[くでん]で授[さず]かった。", "sentence_source": "generated"}, {"text": "文字を持たない民族の歴史は、口伝で語り継がれてきた。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "文字[もじ]を持[も]たない民族[みんぞく]の歴史[れきし]は、口伝[くでん]で語[かた]り継[つ]がれてきた。", "sentence_source": "generated"}, {"text": "重要な手順は、書類にせず口伝のみで共有されていた。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "重要[じゅうよう]な手順[てじゅん]は、書類[しょるい]にせず口伝[くでん]のみで共有[きょうゆう]されていた。", "sentence_source": "generated"}, {"text": "この店の味は、レシピを書かずに口伝で守られている。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "この店[みせ]の味[あじ]は、レシピを書[か]かずに口伝[くでん]で守[まも]られている。", "sentence_source": "generated"}, {"text": "この薬の作り方は、家族の間だけの口伝である。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "この薬[くすり]の作[つく]り方[かた]は、家族[かぞく]の間[あいだ]だけの口伝[くでん]である。", "sentence_source": "generated"}, {"text": "書いた記録がないので、真偽は口伝に頼るしかない。", "target_word": "口伝", "complexity_tier": "T3", "furigana": "書[か]いた記録[きろく]がないので、真偽[しんぎ]は口伝[くでん]に頼[たよ]るしかない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "口伝", "label": "基本形"}, {"form": "口伝で", "label": "手段（で）"}, {"form": "口伝の", "label": "連体形（の）"}], "register": "中立〜やや硬い（常体）", "sense_fingerprint": "文字に書かず、言葉で話して伝えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fe9a294-c720-4877-860c-14bdcabf3668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38489, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口伝", "is_correct": true, "explanation": "口で話して伝えるという意味で、文書にせず伝える文脈に合う。"}, {"text": "雑草", "is_correct": false, "explanation": "「雑草」は草の一種を指す。伝える手段としては成り立たない。"}, {"text": "湯呑み", "is_correct": false, "explanation": "「湯呑み」は茶を飲む器を指す。伝える手段にはならない。"}, {"text": "蝶々", "is_correct": false, "explanation": "「蝶々」は昆虫を指す。伝える手段としては意味が通らない。"}], "explanations": {"口伝": "口で話して伝えるという意味で、文書にせず伝える文脈に合う。", "雑草": "「雑草」は草の一種を指す。伝える手段としては成り立たない。", "湯呑み": "「湯呑み」は茶を飲む器を指す。伝える手段にはならない。", "蝶々": "「蝶々」は昆虫を指す。伝える手段としては意味が通らない。"}, "sentence_index": 0, "correct_answer": "口伝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大事な連絡は、口伝に書いて送った。", "explanation": "ここは〈文書〉（書いて残す記録）の意味。口伝は書かずに話して伝えるものなので、書いて送る連絡には使えない。"}, {"text": "校内に口伝を掲示した。", "explanation": "ここは〈標語〉（文字で掲げる言葉）の意味。口伝は口で話す伝え方なので、掲示するものではない。"}, {"text": "説明は口伝を見ながら聞いた。", "explanation": "ここは〈映像〉（目で見るもの）の意味。口伝は口で話して伝えるもので、目で見ることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38489, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口伝", "is_correct": true, "explanation": "書類にせず口で伝えて共有したという意味で、文に合う。"}, {"text": "夕焼け", "is_correct": false, "explanation": "「夕焼け」は空の色の現象を指す。共有の手段にはならない。"}, {"text": "座布団", "is_correct": false, "explanation": "「座布団」は座るための敷物を指す。共有の手段としては意味が通らない。"}, {"text": "風鈴", "is_correct": false, "explanation": "「風鈴」は涼しげに鳴る飾りを指す。共有の手段にはならない。"}], "explanations": {"口伝": "書類にせず口で伝えて共有したという意味で、文に合う。", "夕焼け": "「夕焼け」は空の色の現象を指す。共有の手段にはならない。", "座布団": "「座布団」は座るための敷物を指す。共有の手段としては意味が通らない。", "風鈴": "「風鈴」は涼しげに鳴る飾りを指す。共有の手段にはならない。"}, "sentence_index": 6, "correct_answer": "口伝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅の様子は、口伝で撮影した。", "explanation": "ここは〈カメラ〉（映像を記録する道具）の意味。口伝は口で話すことで、撮影の道具にはならない。"}, {"text": "番組は、口伝で放送された。", "explanation": "ここは〈ラジオ〉（電波で音声を流す媒体）の意味。口伝は人が口で伝えることで、放送の媒体にはならない。"}, {"text": "予定は口伝に書いてある。", "explanation": "ここは〈ホワイトボード〉（文字や図を書く板）の意味。口伝は口で話して伝えるもので、書いて残すものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38489, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母から口伝な節回しを教わった。", "corrected_sentence": "祖母から口伝の節回しを教わった。", "error_description": "「口伝」は名詞なので、直後の名詞を修飾するには「の」を使う。正しくは「口伝の節回し」で、「口伝な」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38489, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この薬草の使い方は、口伝を伝えられてきた。", "corrected_sentence": "この薬草の使い方は、口伝で伝えられてきた。", "error_description": "「口伝」は手段を表すので「で」が正しい。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38490, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38490, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「地表の七割」の連体修飾。地表の一部を指している。"}, {"text": "と", "is_correct": false, "explanation": "「地表と七割」は並列になり、七割を修飾できない。"}, {"text": "より", "is_correct": false, "explanation": "「地表より七割」は比較の形になり、意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「地表を七割は」は、おおわれる（受け身）の文に目的語の「を」は付かず不自然。"}], "correct_answer": "の", "explanations": {"の": "「地表の七割」の連体修飾。地表の一部を指している。", "と": "「地表と七割」は並列になり、七割を修飾できない。", "より": "「地表より七割」は比較の形になり、意味が通らない。", "を": "「地表を七割は」は、おおわれる（受け身）の文に目的語の「を」は付かず不自然。"}, "error_tags": {"と": "並列", "より": "比較", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38490, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面の上の部分のことです。", "primary_collocate": null, "pronunciation": "ちひょう", "ipa": "tɕihjoː", "syllable_count": 3, "sentences": [{"text": "火山が噴火して、地表に熱い灰が降り積もりました。", "target_word": "地表", "complexity_tier": "T3", "furigana": "火山[かざん]が噴火[ふんか]して、地表[ちひょう]に熱[あつ]い灰[はい]が降[ふ]り積[つ]もりました。", "sentence_source": "generated"}, {"text": "雨が少ない地方では、地表が乾いてひび割れています。", "target_word": "地表", "complexity_tier": "T3", "furigana": "雨[あめ]が少[すく]ない地方[ちほう]では、地表[ちひょう]が乾[かわ]いてひび割[わ]れています。", "sentence_source": "generated"}, {"text": "飛行機が高度を下げると、地表の建物がはっきり見えてきた。", "target_word": "地表", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]が高度[こうど]を下[さ]げると、地表[ちひょう]の建物[たてもの]がはっきり見[み]えてきた。", "sentence_source": "generated"}, {"text": "地震の揺れは、地表に近いほど強く感じられる。", "target_word": "地表", "complexity_tier": "T3", "furigana": "地震[じしん]の揺[ゆ]れは、地表[ちひょう]に近[ちか]いほど強[つよ]く感[かん]じられる。", "sentence_source": "generated"}, {"text": "夜になると地表の熱が逃げるので、朝はとても冷え込む。", "target_word": "地表", "complexity_tier": "T3", "furigana": "夜[よる]になると地表[ちひょう]の熱[ねつ]が逃[に]げるので、朝[あさ]はとても冷[ひ]え込[こ]む。", "sentence_source": "generated"}, {"text": "地表にある水は、太陽に温められて水蒸気になります。", "target_word": "地表", "complexity_tier": "T3", "furigana": "地表[ちひょう]にある水[みず]は、太陽[たいよう]に温[あたた]められて水蒸気[すいじょうき]になります。", "sentence_source": "generated"}, {"text": "この虫は昼間は地中にいて、夜だけ地表に出てくる。", "target_word": "地表", "complexity_tier": "T3", "furigana": "この虫[むし]は昼間[ひるま]は地中[ちちゅう]にいて、夜[よる]だけ地表[ちひょう]に出[で]てくる。", "sentence_source": "generated"}, {"text": "宇宙から見ると、地表の七割は海でおおわれている。", "target_word": "地表", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]から見[み]ると、地表[ちひょう]の七割[ななわり]は海[うみ]でおおわれている。", "sentence_source": "generated"}, {"text": "工事の人たちは、まず地表の草や石を取りのぞいた。", "target_word": "地表", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]たちは、まず地表[ちひょう]の草[くさ]や石[いし]を取[と]りのぞいた。", "sentence_source": "generated"}, {"text": "木の根が地表に出ているので、歩くときにつまずきやすい。", "target_word": "地表", "complexity_tier": "T3", "furigana": "木[き]の根[ね]が地表[ちひょう]に出[で]ているので、歩[ある]くときにつまずきやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地表", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "地面のいちばん上の部分。土の上、空気とふれるところ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T4: contains vocabulary far above tier T4: 降り積もり (Zipf 1.33)']::text[], '0df70395-f463-48c9-9f7b-eb53760b6965') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38490, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地表", "is_correct": true, "explanation": "火山の灰が積もる場所を表す「地表」が入る。地面の表面のこと。"}, {"text": "鉛筆", "is_correct": false, "explanation": "「鉛筆に熱い灰が降り積もる」は場所として成り立たない。鉛筆は地面ではない。"}, {"text": "自転車", "is_correct": false, "explanation": "「自転車に熱い灰が降り積もる」は場所として不自然で、地面の意味にならない。"}, {"text": "財布", "is_correct": false, "explanation": "「財布に熱い灰が降り積もる」は場所として不自然で、地面の意味にならない。"}], "explanations": {"地表": "火山の灰が積もる場所を表す「地表」が入る。地面の表面のこと。", "鉛筆": "「鉛筆に熱い灰が降り積もる」は場所として成り立たない。鉛筆は地面ではない。", "自転車": "「自転車に熱い灰が降り積もる」は場所として不自然で、地面の意味にならない。", "財布": "「財布に熱い灰が降り積もる」は場所として不自然で、地面の意味にならない。"}, "sentence_index": 0, "correct_answer": "地表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ケーキの地表にいちごを並べて、クリームを塗った。", "explanation": "ここは〈表面〉の意味。食べ物の上のおもてを指すのは表面。地表は地面の表面を指すので、ケーキには使わない。"}, {"text": "船は地表を静かに進み、夕方に港へ着いた。", "explanation": "ここは〈海面〉の意味。船が進むのは海の表面。地表は陸の地面の表面を指すので、海には使わない。"}, {"text": "この酒蔵は地表の深い倉庫で、ワインを何年も寝かせている。", "explanation": "ここは〈地下〉の意味。地面の下の深いところにある倉庫は地下。地表は地面の表面なので、深い場所には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38490, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地表", "is_correct": true, "explanation": "虫が夜に出てくる場所として、地面の表面を表す「地表」が入る。"}, {"text": "切符", "is_correct": false, "explanation": "「夜だけ切符に出てくる」は意味が通らない。切符は地面ではない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「夜だけ冷蔵庫に出てくる」は虫の生態として成り立たない。"}, {"text": "缶詰", "is_correct": false, "explanation": "「夜だけ缶詰に出てくる」は虫の生態として成り立たない。"}], "explanations": {"地表": "虫が夜に出てくる場所として、地面の表面を表す「地表」が入る。", "切符": "「夜だけ切符に出てくる」は意味が通らない。切符は地面ではない。", "冷蔵庫": "「夜だけ冷蔵庫に出てくる」は虫の生態として成り立たない。", "缶詰": "「夜だけ缶詰に出てくる」は虫の生態として成り立たない。"}, "sentence_index": 6, "correct_answer": "地表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地表の蛍光灯が切れたので、部屋がとても暗い。", "explanation": "ここは〈天井〉の意味。部屋の上の面につく照明は天井。地表は地面の表面を指すので、室内には使わない。"}, {"text": "地表の瓦を直すため、職人が朝から来ている。", "explanation": "ここは〈屋根〉の意味。瓦は屋根に葺く材料。地表は地面の表面を指すので、瓦の位置には合わない。"}, {"text": "暑さで地表に汗がにじみ、ハンカチが手放せない。", "explanation": "ここは〈額〉の意味。汗がにじむのは顔の上部である額。地表は地面の表面なので、体の部位には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38490, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "風で地表を砂が積もり、道が埋まった。", "corrected_sentence": "風で地表に砂が積もり、道が埋まった。", "error_description": "「積もる」は場所を「に」で表す。「地表を」は誤りで、場所の「地表に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38490, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "飛行機から地表を見上げると、町が小さく見えた。", "corrected_sentence": "飛行機から地表を見下ろすと、町が小さく見えた。", "error_description": "上空の飛行機から地面を眺めるときは「見下ろす」を使う。「見上げる」は下から上を仰ぐ動作で、ここでは合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38491, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「地表から遠い」の起点。遠さの基準を表す。"}, {"text": "を", "is_correct": false, "explanation": "「地表を遠い」は形容詞が目的語を取れないので不自然。"}, {"text": "と", "is_correct": false, "explanation": "「地表と遠い」は並列の形で、遠さの基準を表せない。"}, {"text": "で", "is_correct": false, "explanation": "「地表で遠い」は場所を表すが、遠さの基準にはならない。"}], "correct_answer": "から", "explanations": {"から": "「地表から遠い」の起点。遠さの基準を表す。", "を": "「地表を遠い」は形容詞が目的語を取れないので不自然。", "と": "「地表と遠い」は並列の形で、遠さの基準を表せない。", "で": "「地表で遠い」は場所を表すが、遠さの基準にはならない。"}, "error_tags": {"を": "目的語", "と": "並列", "で": "場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38491, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「地表の下」の連体修飾。地表を基準に下の位置を示している。"}, {"text": "が", "is_correct": false, "explanation": "「地表が下には」は主語の形になり、下の位置を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「地表へ下には」は方向を表すが、「下には」と続かない。"}, {"text": "に", "is_correct": false, "explanation": "「地表に下には」は位置を表すが、下を修飾する形にならない。"}], "correct_answer": "の", "explanations": {"の": "「地表の下」の連体修飾。地表を基準に下の位置を示している。", "が": "「地表が下には」は主語の形になり、下の位置を示せない。", "へ": "「地表へ下には」は方向を表すが、「下には」と続かない。", "に": "「地表に下には」は位置を表すが、下を修飾する形にならない。"}, "error_tags": {"が": "主語", "へ": "方向", "に": "位置・帰着"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38491, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面の表面。地球の表面にある、土や岩などでできている部分。", "primary_collocate": null, "pronunciation": "ちひょう", "ipa": "tɕihjoː", "syllable_count": 3, "sentences": [{"text": "地表の岩は、風と雨で少しずつけずられていく。", "target_word": "地表", "complexity_tier": "T3", "furigana": "地表[ちひょう]の岩[いわ]は、風[かぜ]と雨[あめ]で少[すこ]しずつけずられていく。", "sentence_source": "generated"}, {"text": "深い穴をほると、地表から遠いほど温度が高くなる。", "target_word": "地表", "complexity_tier": "T3", "furigana": "深[ふか]い穴[あな]をほると、地表[ちひょう]から遠[とお]いほど温度[おんど]が高[たか]くなる。", "sentence_source": "generated"}, {"text": "砂漠では昼間の地表の温度が六十度をこえることもある。", "target_word": "地表", "complexity_tier": "T3", "furigana": "砂漠[さばく]では昼間[ひるま]の地表[ちひょう]の温度[おんど]が六十度[ろくじゅうど]をこえることもある。", "sentence_source": "generated"}, {"text": "地表近くの土には、植物が育つための栄養がたくさんある。", "target_word": "地表", "complexity_tier": "T3", "furigana": "地表[ちひょう]近[ちか]くの土[つち]には、植物[しょくぶつ]が育[そだ]つための栄養[えいよう]がたくさんある。", "sentence_source": "generated"}, {"text": "大きな隕石が落ちた場所では、地表に丸いくぼみができた。", "target_word": "地表", "complexity_tier": "T3", "furigana": "大[おお]きな隕石[いんせき]が落[お]ちた場所[ばしょ]では、地表[ちひょう]に丸[まる]いくぼみができた。", "sentence_source": "generated"}, {"text": "雪がとけると、黒い地表があらわれた。", "target_word": "地表", "complexity_tier": "T3", "furigana": "雪[ゆき]がとけると、黒[くろ]い地表[ちひょう]があらわれた。", "sentence_source": "generated"}, {"text": "衛星の写真で、地表の変化を長い間調べている。", "target_word": "地表", "complexity_tier": "T3", "furigana": "衛星[えいせい]の写真[しゃしん]で、地表[ちひょう]の変化[へんか]を長[なが]い間[あいだ]調[しら]べている。", "sentence_source": "generated"}, {"text": "地表の下には水が流れていて、井戸をほれば水が出る。", "target_word": "地表", "complexity_tier": "T3", "furigana": "地表[ちひょう]の下[した]には水[みず]が流[なが]れていて、井戸[いど]をほれば水[みず]が出[で]る。", "sentence_source": "generated"}, {"text": "地表をおおう氷が厚いので、この島では畑を作れない。", "target_word": "地表", "complexity_tier": "T3", "furigana": "地表[ちひょう]をおおう氷[こおり]が厚[あつ]いので、この島[しま]では畑[はたけ]を作[つく]れない。", "sentence_source": "generated"}, {"text": "地震のあと、地表に大きな割れ目ができていた。", "target_word": "地表", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、地表[ちひょう]に大[おお]きな割[わ]れ目[め]ができていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地表", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "地球の表面にある、土や岩でできた部分。地下や空に対する表面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0df70395-f463-48c9-9f7b-eb53760b6965') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38491, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地表", "is_correct": true, "explanation": "岩が風と雨で削られる、地球の表面にある土や岩の部分を表す「地表」が入る。"}, {"text": "切符", "is_correct": false, "explanation": "「切符の岩」は成り立たない。切符は地面や岩の一部ではない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "「鉛筆の岩」は成り立たない。鉛筆は岩ではない。"}, {"text": "財布", "is_correct": false, "explanation": "「財布の岩」は成り立たない。財布は岩ではない。"}], "explanations": {"地表": "岩が風と雨で削られる、地球の表面にある土や岩の部分を表す「地表」が入る。", "切符": "「切符の岩」は成り立たない。切符は地面や岩の一部ではない。", "鉛筆": "「鉛筆の岩」は成り立たない。鉛筆は岩ではない。", "財布": "「財布の岩」は成り立たない。財布は岩ではない。"}, "sentence_index": 0, "correct_answer": "地表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海の地表の深いところには、光がほとんど届かない。", "explanation": "ここは〈海底〉の意味。海の底の部分は海底。地表は地面の表面を指すので、海の底には使わない。"}, {"text": "皮膚の地表が荒れて、白くはがれてきた。", "explanation": "ここは〈皮膚〉の意味。体の表面を覆うものは皮膚。地表は地球の表面を指すので、人の体には使わない。"}, {"text": "木の幹の地表が、雨で黒くなった。", "explanation": "ここは〈表面〉の意味。物の外側の面は表面。地表は地球の表面を指すので、木の幹には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38491, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地表", "is_correct": true, "explanation": "衛星の写真で変化を調べる対象となる、地球の表面を表す「地表」が入る。"}, {"text": "風船", "is_correct": false, "explanation": "「衛星の写真で風船の変化を調べる」は地表の観察として成り立たない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「衛星の写真で冷蔵庫の変化を調べる」は地球の観察として成り立たない。"}, {"text": "石鹸", "is_correct": false, "explanation": "「衛星の写真で石鹸の変化を調べる」は地球の観察として成り立たない。"}], "explanations": {"地表": "衛星の写真で変化を調べる対象となる、地球の表面を表す「地表」が入る。", "風船": "「衛星の写真で風船の変化を調べる」は地表の観察として成り立たない。", "冷蔵庫": "「衛星の写真で冷蔵庫の変化を調べる」は地球の観察として成り立たない。", "石鹸": "「衛星の写真で石鹸の変化を調べる」は地球の観察として成り立たない。"}, "sentence_index": 6, "correct_answer": "地表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この学校は地表三階建てで、体育館は別にある。", "explanation": "ここは〈地上〉の意味。建物の階数は地上で数える。地表は地面の表面を指すので、階数には使わない。"}, {"text": "古い新聞の地表が黄ばんで、文字が読みにくい。", "explanation": "ここは〈紙面〉の意味。新聞や紙のおもてを指すのは紙面。地表は地球の表面を指すので、紙には使わない。"}, {"text": "夜の地表に星が広がっていた。", "explanation": "ここは〈夜空〉の意味。星が広がって見える空は夜空。地表は地面の表面を指すので、空には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38491, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地表を風で削られ、新しい地形ができた。", "corrected_sentence": "地表が風で削られ、新しい地形ができた。", "error_description": "「削られる」は受け身で、削られる側は「が」で示す。「地表を」は誤りで、「地表が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38491, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工事の作業員は、まず地表を書いて平らにした。", "corrected_sentence": "工事の作業員は、まず地表を削って平らにした。", "error_description": "地面を平らにするには土を「削る」。「書く」は紙や文字に使う動詞で、地表を目的語に取っても合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38492, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『浸透が速い』の〈が〉。浸透の速さという状態の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "『浸透を速い』は続かず、速いという形容詞には〈を〉で結べない。"}, {"text": "に", "is_correct": false, "explanation": "『浸透に速い』は成り立たず、場所を示す形にもならない。"}, {"text": "で", "is_correct": false, "explanation": "『浸透で速い』は手段を表すが、形容詞の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "『浸透が速い』の〈が〉。浸透の速さという状態の主語を示す。", "を": "『浸透を速い』は続かず、速いという形容詞には〈を〉で結べない。", "に": "『浸透に速い』は成り立たず、場所を示す形にもならない。", "で": "『浸透で速い』は手段を表すが、形容詞の主語にはならない。"}, "error_tags": {"を": "目的語", "に": "場所", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
