INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38492, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "水が少しずつ中に入っていくこと。", "primary_collocate": null, "pronunciation": "しんとう", "ipa": "ɕintoː", "syllable_count": 4, "sentences": [{"text": "雨水が地面に浸透して、地下水になる。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "雨水[あまみず]が地面[じめん]に浸透[しんとう]して、地下水[ちかすい]になる。", "sentence_source": "generated"}, {"text": "砂の地面は、水の浸透が速いので、雨がやむとすぐに乾く。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "砂[すな]の地面[じめん]は、水[みず]の浸透[しんとう]が速[はや]いので、雨[あめ]がやむとすぐに乾[かわ]く。", "sentence_source": "generated"}, {"text": "屋根の傷みから水が浸透し、天井にしみができた。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "屋根[やね]の傷[いた]みから水[みず]が浸透[しんとう]し、天井[てんじょう]にしみができた。", "sentence_source": "generated"}, {"text": "森の土は水の浸透がよく、洪水を防ぐ役目をする。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "森[もり]の土[つち]は水[みず]の浸透[しんとう]がよく、洪水[こうずい]を防[ふせ]ぐ役目[やくめ]をする。", "sentence_source": "generated"}, {"text": "地面を舗装すると、雨水が浸透しにくくなる。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "地面[じめん]を舗装[ほそう]すると、雨水[あまみず]が浸透[しんとう]しにくくなる。", "sentence_source": "generated"}, {"text": "大雨が降っても、乾いた土にはなかなか水が浸透しなかった。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "大雨[おおあめ]が降[ふ]っても、乾[かわ]いた土[つち]にはなかなか水[みず]が浸透[しんとう]しなかった。", "sentence_source": "generated"}, {"text": "川の水が堤防に浸透しないよう、粘土で固めた。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]が堤防[ていぼう]に浸透[しんとう]しないよう、粘土[ねんど]で固[かた]めた。", "sentence_source": "generated"}, {"text": "植木鉢の土に水を少しずつ浸透させた。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "植木鉢[うえきばち]の土[つち]に水[みず]を少[すこ]しずつ浸透[しんとう]させた。", "sentence_source": "generated"}, {"text": "雪解け水がゆっくり浸透して、春の畑を潤す。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "雪解[ゆきど]け水[みず]がゆっくり浸透[しんとう]して、春[はる]の畑[はたけ]を潤[うるお]す。", "sentence_source": "generated"}, {"text": "壁への水の浸透を止めないと、家の中にカビが生える。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "壁[かべ]への水[みず]の浸透[しんとう]を止[と]めないと、家[いえ]の中[なか]にカビが生[は]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "浸透", "label": "基本形"}, {"form": "浸透する", "label": "終止形"}, {"form": "浸透した", "label": "た形"}, {"form": "浸透して", "label": "て形"}, {"form": "浸透しにくい", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "水が少しずつ地面や物の中へ染み入る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e1d13d0-4a75-4ad6-af0d-7ff5a6956501') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38492, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浸透", "is_correct": true, "explanation": "雨水が地面の中へ少しずつ入り込んで地下水になる流れに合う。"}, {"text": "蒸発", "is_correct": false, "explanation": "蒸発は水が気体になって散ることで、地面に入って地下水になる流れとは逆になる。"}, {"text": "凝結", "is_correct": false, "explanation": "凝結は気体が液体に変わることで、地面から地下水になる流れとは結びつかない。"}, {"text": "点火", "is_correct": false, "explanation": "点火は火をつけることで、雨水が地下水になる文脈には合わない。"}], "explanations": {"浸透": "雨水が地面の中へ少しずつ入り込んで地下水になる流れに合う。", "蒸発": "蒸発は水が気体になって散ることで、地面に入って地下水になる流れとは逆になる。", "凝結": "凝結は気体が液体に変わることで、地面から地下水になる流れとは結びつかない。", "点火": "点火は火をつけることで、雨水が地下水になる文脈には合わない。"}, "sentence_index": 0, "correct_answer": "浸透"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ガスが配管の継ぎ目から浸透して、部屋に臭いがこもった。", "explanation": "ここは〈漏れる〉の意味。ガスが外へ洩れ出る話で、水が少しずつ中へ入る〈浸透〉とは逆の動きなので合わない。"}, {"text": "犬が夜中に庭へ浸透して、花を荒らした。", "explanation": "ここは〈侵入〉の意味。動物が勝手に入り込む話で、水がしみ込む〈浸透〉とは合わない。"}, {"text": "大雨で床下が浸透して、湿気がたまった。", "explanation": "ここは〈浸水〉の意味。水があふれて建物の下に入る話で、少しずつ染み込む〈浸透〉とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38492, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浸透", "is_correct": true, "explanation": "川の水が堤防の中へ入り込むのを防ぐ、という意味に合う。"}, {"text": "点滅", "is_correct": false, "explanation": "点滅は光が明滅することで、水が堤防に入るのを防ぐ話とは合わない。"}, {"text": "発光", "is_correct": false, "explanation": "発光は光を放つことで、水の侵入を防ぐ文脈には使えない。"}, {"text": "沸騰", "is_correct": false, "explanation": "沸騰は液体が泡立つことで、堤防に水が入るのを防ぐ話とは結びつかない。"}], "explanations": {"浸透": "川の水が堤防の中へ入り込むのを防ぐ、という意味に合う。", "点滅": "点滅は光が明滅することで、水が堤防に入るのを防ぐ話とは合わない。", "発光": "発光は光を放つことで、水の侵入を防ぐ文脈には使えない。", "沸騰": "沸騰は液体が泡立つことで、堤防に水が入るのを防ぐ話とは結びつかない。"}, "sentence_index": 6, "correct_answer": "浸透"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "街灯が浸透して、道が明るくなった。", "explanation": "ここは〈点灯〉の意味。明かりがともる話で、水が染み込む〈浸透〉とは違う。"}, {"text": "風船が浸透して、大きくなった。", "explanation": "ここは〈膨張〉の意味。空気で大きく膨らむ話で、少しずつ入る〈浸透〉とは合わない。"}, {"text": "ボールが浸透して、窓ガラスに当たった。", "explanation": "ここは〈跳ねる〉の意味。物が勢いよく当たる話で、物の内部へ入る〈浸透〉とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38492, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋根の隙間から雨水が少しずつ浸透させ、天井がぬれる。", "corrected_sentence": "屋根の隙間から雨水が少しずつ浸透し、天井がぬれる。", "error_description": "雨水は自分で入り込むので、自動詞の〈浸透する〉を使う。〈浸透させる〉は他の何かを染み込ませる他動詞で、主語が雨水だと誤り。正しくは〈浸透し〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38492, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この土は水がよく浸透され、大雨でも水たまりができない。", "corrected_sentence": "この土は水がよく浸透し、大雨でも水たまりができない。", "error_description": "〈浸透する〉は自動詞で、受身の〈浸透される〉は使わない。正しくは〈浸透し〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
