INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38493, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "液体が、物の表面から内部へとゆっくりと入り込むこと。", "primary_collocate": null, "pronunciation": "しんとう", "ipa": "ɕintoː", "syllable_count": 4, "sentences": [{"text": "脂質の膜は、ジャムに水が浸透するのを防ぐバリアーとして機能する。", "target_word": "浸透", "complexity_tier": "T4", "furigana": "脂質[ししつ]の膜[まく]は、ジャムに水[みず]が浸透[しんとう]するのを防[ふせ]ぐバリアーとして機能[きのう]する。", "sentence_source": "generated"}, {"text": "防水スプレーを使うと、雨水の浸透を防ぐことができる。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "防水[ぼうすい]スプレーを使[つか]うと、雨水[あまみず]の浸透[しんとう]を防[ふせ]ぐことができる。", "sentence_source": "generated"}, {"text": "固い地面は水の浸透が悪く、道に水たまりができる。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "固[かた]い地面[じめん]は水[みず]の浸透[しんとう]が悪[わる]く、道[みち]に水[みず]たまりができる。", "sentence_source": "generated"}, {"text": "布に染料が浸透するまで、一時間ほど待つ。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "布[ぬの]に染料[せんりょう]が浸透[しんとう]するまで、一時間[いちじかん]ほど待[ま]つ。", "sentence_source": "generated"}, {"text": "木材に油が浸透すると、雨にも強くなる。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "木材[もくざい]に油[あぶら]が浸透[しんとう]すると、雨[あめ]にも強[つよ]くなる。", "sentence_source": "generated"}, {"text": "化粧水が肌に浸透するように、手でやさしく押さえる。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "化粧水[けしょうすい]が肌[はだ]に浸透[しんとう]するように、手[て]でやさしく押[お]さえる。", "sentence_source": "generated"}, {"text": "この紙は、インクの浸透が早いので、にじみやすい。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "この紙[かみ]は、インクの浸透[しんとう]が早[はや]いので、にじみやすい。", "sentence_source": "generated"}, {"text": "コンクリートにひびがあると、雨水が浸透して中の鉄が錆びる。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "コンクリートにひびがあると、雨水[あまみず]が浸透[しんとう]して中[なか]の鉄[てつ]が錆[さ]びる。", "sentence_source": "generated"}, {"text": "塗料の浸透を良くするため、先に壁の汚れを落とした。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "塗料[とりょう]の浸透[しんとう]を良[よ]くするため、先[さき]に壁[かべ]の汚[よご]れを落[お]とした。", "sentence_source": "generated"}, {"text": "スポンジは水の浸透が速く、すぐに全体が濡れる。", "target_word": "浸透", "complexity_tier": "T3", "furigana": "スポンジは水[みず]の浸透[しんとう]が速[はや]く、すぐに全体[ぜんたい]が濡[ぬ]れる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "浸透", "label": "基本形"}, {"form": "浸透する", "label": "終止形"}, {"form": "浸透した", "label": "た形"}, {"form": "浸透して", "label": "て形"}, {"form": "浸透しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "液体が物の表面から内部へゆっくり染み込む", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e1d13d0-4a75-4ad6-af0d-7ff5a6956501') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38493, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浸透", "is_correct": true, "explanation": "膜が水分を内部へ通さないという文脈で、水分が入り込む現象を指す「浸透」が入る。"}, {"text": "振動", "is_correct": false, "explanation": "振動は揺れることで、水分の侵入を防ぐ膜の働きとは結びつかない。"}, {"text": "摩擦", "is_correct": false, "explanation": "摩擦は擦れ合うことで、水分がジャムに入るのを防ぐ話とは合わない。"}, {"text": "発酵", "is_correct": false, "explanation": "発酵は微生物が物質を変える働きで、水分の入り込みを防ぐ文脈には合わない。"}], "explanations": {"浸透": "膜が水分を内部へ通さないという文脈で、水分が入り込む現象を指す「浸透」が入る。", "振動": "振動は揺れることで、水分の侵入を防ぐ膜の働きとは結びつかない。", "摩擦": "摩擦は擦れ合うことで、水分がジャムに入るのを防ぐ話とは合わない。", "発酵": "発酵は微生物が物質を変える働きで、水分の入り込みを防ぐ文脈には合わない。"}, "sentence_index": 0, "correct_answer": "浸透"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜中の音楽が窓から浸透して、ご近所に迷惑をかけた。", "explanation": "ここは〈漏れる〉の意味。音が外へ洩れて聞こえる話で、液体が物の内部へゆっくり入る〈浸透〉とは違う。"}, {"text": "泥棒が夜中に窓から浸透して、部屋に入った。", "explanation": "ここは〈侵入〉の意味。人が勝手に入る話で、液体がゆっくり染み込む〈浸透〉とは合わない。"}, {"text": "大雨で地下室が浸透して、床が水びたしになった。", "explanation": "ここは〈浸水〉の意味。水があふれて建物の中に入る話で、表面からじわじわ染み込む〈浸透〉とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38493, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浸透", "is_correct": true, "explanation": "インクが紙に染み込む速さを表す「インクの浸透」に合い、にじみやすさの理由になる。"}, {"text": "点滅", "is_correct": false, "explanation": "点滅は光が明滅することで、インクのにじみやすさの説明にならない。"}, {"text": "照射", "is_correct": false, "explanation": "照射は光や放射線を当てることで、紙へのインクの広がりとは関係がない。"}, {"text": "沸騰", "is_correct": false, "explanation": "沸騰は液体が泡立つことで、インクが紙ににじむ話とは合わない。"}], "explanations": {"浸透": "インクが紙に染み込む速さを表す「インクの浸透」に合い、にじみやすさの理由になる。", "点滅": "点滅は光が明滅することで、インクのにじみやすさの説明にならない。", "照射": "照射は光や放射線を当てることで、紙へのインクの広がりとは関係がない。", "沸騰": "沸騰は液体が泡立つことで、インクが紙ににじむ話とは合わない。"}, "sentence_index": 6, "correct_answer": "浸透"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お湯が浸透したので、火を弱めた。", "explanation": "ここは〈沸騰〉の意味。お湯が泡立つ現象で、液体が物の内部へ入る〈浸透〉とは違う。"}, {"text": "湖の表面が浸透して、子どもがスケートをした。", "explanation": "ここは〈凍結〉の意味。水が固まる話で、物の内部へ入る〈浸透〉とは合わない。"}, {"text": "船が浸透したので、乗客が避難した。", "explanation": "ここは〈沈没〉の意味。船が水に沈む話で、少しずつ染み込む〈浸透〉とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38493, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "油が木材の内部を浸透すると、木が割れにくくなる。", "corrected_sentence": "油が木材の内部に浸透すると、木が割れにくくなる。", "error_description": "〈浸透する〉は、液体が入り込む先を〈に〉で示す。〈を〉を付けると、浸透が他動詞のように誤って使われている。正しくは〈に〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38493, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この布は汗を浸透が速いので、夏に向いている。", "corrected_sentence": "この布は汗の浸透が速いので、夏に向いている。", "error_description": "〈汗の浸透〉の〈の〉は名詞の浸透につく修飾の助詞。〈を〉は動詞の目的語を示すので、名詞の浸透の前では誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38494, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「沿う」の基準・対象を示す「に」で、「海岸に沿って」と続く。"}, {"text": "を", "is_correct": false, "explanation": "「海岸を沿って」は不自然。「沿う」は「〜に沿う」と続く。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段の「で」で、基準を示す場面には入らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」で、「海岸へ沿って」は文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「沿う」の基準・対象を示す「に」で、「海岸に沿って」と続く。", "を": "「海岸を沿って」は不自然。「沿う」は「〜に沿う」と続く。", "で": "場所や手段の「で」で、基準を示す場面には入らない。", "へ": "方向の「へ」で、「海岸へ沿って」は文が成り立たない。"}, "error_tags": {"を": "対象の誤り", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38494, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「沿う」の基準を示す「に」で、「線に沿って」と続く。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列の「と」で、「線と沿って」は続かない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」で、基準を示す「に」の代わりにはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」で、「線より沿って」は文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「沿う」の基準を示す「に」で、「線に沿って」と続く。", "と": "相手や並列の「と」で、「線と沿って」は続かない。", "から": "起点の「から」で、基準を示す「に」の代わりにはならない。", "より": "比較の「より」で、「線より沿って」は文が成り立たない。"}, "error_tags": {"と": "並列・相手", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38494, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものの形や道にぴったりとくっついて動くこと。", "primary_collocate": null, "pronunciation": "そう", "ipa": "soː", "syllable_count": 2, "sentences": [{"text": "川に沿って歩くと、小さな橋が見えてきた。", "target_word": "沿って", "complexity_tier": "T3", "furigana": "川(かわ)に沿(そ)って歩(ある)くと、小(ちい)さな橋(はし)が見(み)えてきた。", "sentence_source": "generated"}, {"text": "電車は海岸に沿って、ゆっくり走っている。", "target_word": "沿って", "complexity_tier": "T3", "furigana": "電車(でんしゃ)は海岸(かいがん)に沿(そ)って、ゆっくり走(はし)っている。", "sentence_source": "generated"}, {"text": "壁に沿って机を並べると、部屋が広く使える。", "target_word": "沿って", "complexity_tier": "T3", "furigana": "壁(かべ)に沿(そ)って机(つくえ)を並(なら)べると、部屋(へや)が広(ひろ)く使(つか)える。", "sentence_source": "generated"}, {"text": "道路に沿って桜の木が植えられている。", "target_word": "沿って", "complexity_tier": "T3", "furigana": "道路(どうろ)に沿(そ)って桜(さくら)の木(き)が植(う)えられている。", "sentence_source": "generated"}, {"text": "犬は塀に沿って歩き、角で止まった。", "target_word": "沿って", "complexity_tier": "T3", "furigana": "犬(いぬ)は塀(へい)に沿(そ)って歩(ある)き、角(かど)で止(と)まった。", "sentence_source": "generated"}, {"text": "線路に沿って自転車で走ったら、駅に着いた。", "target_word": "沿って", "complexity_tier": "T3", "furigana": "線路(せんろ)に沿(そ)って自転車(じてんしゃ)で走(はし)ったら、駅(えき)に着(つ)いた。", "sentence_source": "generated"}, {"text": "山の斜面に沿って、細い道が続いている。", "target_word": "沿って", "complexity_tier": "T3", "furigana": "山(やま)の斜面(しゃめん)に沿(そ)って、細(ほそ)い道(みち)が続(つづ)いている。", "sentence_source": "generated"}, {"text": "地図の線に沿ってはさみで紙を切った。", "target_word": "沿って", "complexity_tier": "T3", "furigana": "地図(ちず)の線(せん)に沿(そ)ってはさみで紙(かみ)を切(き)った。", "sentence_source": "generated"}, {"text": "湖に沿った道を、朝早く散歩した。", "target_word": "沿った", "complexity_tier": "T3", "furigana": "湖(みずうみ)に沿(そ)った道(みち)を、朝早(あさはや)く散歩(さんぽ)した。", "sentence_source": "generated"}, {"text": "彼は手すりに沿って階段を下りた。", "target_word": "沿って", "complexity_tier": "T3", "furigana": "彼(かれ)は手(て)すりに沿(そ)って階段(かいだん)を下(お)りた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "沿う", "label": "基本形"}, {"form": "沿い", "label": "連用形"}, {"form": "沿って", "label": "て形"}, {"form": "沿った", "label": "た形"}, {"form": "沿わない", "label": "ない形"}], "register": "neutral", "sense_fingerprint": "川・道・壁など細長いものに離れずについて進む動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93788fa0-f2a6-402a-8dac-82f8c6817f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38494, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沿って", "is_correct": true, "explanation": "「川に沿って」は川の形にぴったり添って進む意味で、「歩く」と合う。"}, {"text": "離れて", "is_correct": false, "explanation": "「川から離れて」なら意味は通るが、「川に」と続けると不自然で、川に添う動きを表せない。"}, {"text": "眺めて", "is_correct": false, "explanation": "眺める対象は「川を」で表すため、「川に眺めて歩く」は成り立たない。"}, {"text": "止まって", "is_correct": false, "explanation": "止まる動きは歩く動作と矛盾し、「川に止まって歩くと」は意味が通らない。"}], "explanations": {"沿って": "「川に沿って」は川の形にぴったり添って進む意味で、「歩く」と合う。", "離れて": "「川から離れて」なら意味は通るが、「川に」と続けると不自然で、川に添う動きを表せない。", "眺めて": "眺める対象は「川を」で表すため、「川に眺めて歩く」は成り立たない。", "止まって": "止まる動きは歩く動作と矛盾し、「川に止まって歩くと」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "沿って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大雨に沿って、川の水位も上がった。", "explanation": "ここは〈伴う〉（同時に起こる）の意味。沿うは道や物にぴったり従う意味なので、同時に起こる変化には使えない。"}, {"text": "母は病床の父に沿って、一晩中手を握っていた。", "explanation": "ここは〈添う〉（そばに付き添う）の意味。人のそばにいる場面は〈沿う〉では表せず、道や物に沿う定義と合わない。"}, {"text": "ガムが靴に沿って、なかなか取れない。", "explanation": "ここは〈張りつく〉の場面。ガムが靴に張りついて取れない状態は動きを伴わないので、〈沿う〉の「ぴったり動いて従う」という語義に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38494, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沿って", "is_correct": true, "explanation": "斜面の形にぴったり添う意味で、道の位置を表す文に合う。"}, {"text": "転がって", "is_correct": false, "explanation": "転がる動きは道が続く描写と合わず、「斜面に転がって」は意味が通らない。"}, {"text": "外れて", "is_correct": false, "explanation": "「斜面から外れて」なら離れる意味になり、道が斜面に沿って続く描写と矛盾する。"}, {"text": "倒れて", "is_correct": false, "explanation": "倒れる動作は道の並びを表さず、「斜面に倒れて、細い道が続く」は不自然。"}], "explanations": {"沿って": "斜面の形にぴったり添う意味で、道の位置を表す文に合う。", "転がって": "転がる動きは道が続く描写と合わず、「斜面に転がって」は意味が通らない。", "外れて": "「斜面から外れて」なら離れる意味になり、道が斜面に沿って続く描写と矛盾する。", "倒れて": "倒れる動作は道の並びを表さず、「斜面に倒れて、細い道が続く」は不自然。"}, "sentence_index": 6, "correct_answer": "沿って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼はバスに沿って、駅まで行った。", "explanation": "ここは〈乗る〉の場面。乗り物に入る動きは〈沿う〉では表せず、くっついて従う語義とも合わない。"}, {"text": "彼は祖母の手に沿って、階段を下りた。", "explanation": "ここは〈握る〉の場面（手をつかむ）。手を握る動作を〈沿う〉で言うと、ぴったり付いて従う定義と合わない。"}, {"text": "彼は故郷に沿って、東京で働いた。", "explanation": "ここは〈離れる〉の場面（故郷から離れる）。離れることを〈沿う〉で言うと、定義（離れずに従う）と正反対になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38494, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "川を沿って歩くと、古い石橋が見えてきた。", "corrected_sentence": "川に沿って歩くと、古い石橋が見えてきた。", "error_description": "「沿う」は「〜に沿う」と続け、対象は「に」で示す。「を」は誤りで、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "沿って", "is_correct": true, "explanation": "「て形」で、後ろに「、」や動詞を続けて文をつなぐ形。ここに合う。"}, {"text": "沿う", "is_correct": false, "explanation": "基本形で、「海岸に沿う、」と文を切ると不自然。"}, {"text": "沿った", "is_correct": false, "explanation": "た形で、文を中止できず「海岸に沿った、」と続かない。"}, {"text": "沿わない", "is_correct": false, "explanation": "否定形で、「沿わない、ゆっくり走っている」は意味も文の流れも合わない。"}], "correct_form": "沿って", "base_form": "沿う", "form_label": "て形", "sentence_index": 1, "explanations": {"沿って": "「て形」で、後ろに「、」や動詞を続けて文をつなぐ形。ここに合う。", "沿う": "基本形で、「海岸に沿う、」と文を切ると不自然。", "沿った": "た形で、文を中止できず「海岸に沿った、」と続かない。", "沿わない": "否定形で、「沿わない、ゆっくり走っている」は意味も文の流れも合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38494, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "線路に沿わって、桜並木が続いている。", "corrected_sentence": "線路に沿って、桜並木が続いている。", "error_description": "「沿う」のて形は「沿って」。「沿わって」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "沿って", "is_correct": true, "explanation": "「て形」で、後ろの動詞「はさみで…切った」へ続く形。ここに合う。"}, {"text": "沿った", "is_correct": false, "explanation": "た形で、文を中止できず「線に沿った、」と続かない。"}, {"text": "沿えない", "is_correct": false, "explanation": "否定の形で、「線に沿えないで切った」は意味が変わり、文の流れに合わない。"}, {"text": "沿え", "is_correct": false, "explanation": "命令形で、「線に沿え、」と続けると文が成り立たない。"}], "correct_form": "沿って", "base_form": "沿う", "form_label": "て形", "sentence_index": 7, "explanations": {"沿って": "「て形」で、後ろの動詞「はさみで…切った」へ続く形。ここに合う。", "沿った": "た形で、文を中止できず「線に沿った、」と続かない。", "沿えない": "否定の形で、「線に沿えないで切った」は意味が変わり、文の流れに合わない。", "沿え": "命令形で、「線に沿え、」と続けると文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38495, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「沿う」の基準を示す「に」で、「希望に沿う」と続く。"}, {"text": "を", "is_correct": false, "explanation": "「希望を沿う」は不自然。「沿う」は「〜に沿う」と続く。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段の「で」で、基準を示す場面には入らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」で、「希望へ沿う」は基準の意味と合わない。"}], "correct_answer": "に", "explanations": {"に": "「沿う」の基準を示す「に」で、「希望に沿う」と続く。", "を": "「希望を沿う」は不自然。「沿う」は「〜に沿う」と続く。", "で": "場所や手段の「で」で、基準を示す場面には入らない。", "へ": "方向の「へ」で、「希望へ沿う」は基準の意味と合わない。"}, "error_tags": {"を": "対象の誤り", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38495, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「沿う」の基準を示す「に」で、「法律に沿った」と続く。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列の「と」で、「法律と沿った」は続かない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」で、基準を示す「に」の代わりにはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」で、「法律より沿った手続き」は文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「沿う」の基準を示す「に」で、「法律に沿った」と続く。", "と": "相手や並列の「と」で、「法律と沿った」は続かない。", "から": "起点の「から」で、基準を示す「に」の代わりにはならない。", "より": "比較の「より」で、「法律より沿った手続き」は文が成り立たない。"}, "error_tags": {"と": "並列・相手", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38495, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "規則・方針・希望などに合わせて、それに従うこと。", "primary_collocate": null, "pronunciation": "そう", "ipa": "soː", "syllable_count": 2, "sentences": [{"text": "会社の方針に沿って、新しい計画を作った。", "target_word": "沿って", "complexity_tier": "T3", "furigana": "会社(かいしゃ)の方針(ほうしん)に沿(そ)って、新(あたら)しい計画(けいかく)を作(つく)った。", "sentence_source": "generated"}, {"text": "客の希望に沿う部屋を探してもらった。", "target_word": "沿う", "complexity_tier": "T3", "furigana": "客(きゃく)の希望(きぼう)に沿(そ)う部屋(へや)を探(さが)してもらった。", "sentence_source": "generated"}, {"text": "マニュアルに沿って、機械の使い方を説明する。", "target_word": "沿って", "complexity_tier": "T3", "furigana": "マニュアルに沿(そ)って、機械(きかい)の使(つか)い方(かた)を説明(せつめい)する。", "sentence_source": "generated"}, {"text": "この映画は原作に沿って作られている。", "target_word": "沿って", "complexity_tier": "T3", "furigana": "この映画(えいが)は原作(げんさく)に沿(そ)って作(つく)られている。", "sentence_source": "generated"}, {"text": "私の考えに沿わない意見でも、まず聞いてみる。", "target_word": "沿わない", "complexity_tier": "T3", "furigana": "私(わたし)の考(かんが)えに沿(そ)わない意見(いけん)でも、まず聞(き)いてみる。", "sentence_source": "generated"}, {"text": "先生の指導に沿って練習したら、上手になった。", "target_word": "沿って", "complexity_tier": "T3", "furigana": "先生(せんせい)の指導(しどう)に沿(そ)って練習(れんしゅう)したら、上手(じょうず)になった。", "sentence_source": "generated"}, {"text": "規則に沿って、今後の予定を話し合った。", "target_word": "沿って", "complexity_tier": "T3", "furigana": "規則(きそく)に沿(そ)って、今後(こんご)の予定(よてい)を話(はな)し合(あ)った。", "sentence_source": "generated"}, {"text": "法律に沿った手続きをしないと、許可が出ない。", "target_word": "沿った", "complexity_tier": "T3", "furigana": "法律(ほうりつ)に沿(そ)った手続(てつづ)きをしないと、許可(きょか)が出(で)ない。", "sentence_source": "generated"}, {"text": "予算に沿って買い物をするので、むだ使いが減った。", "target_word": "沿って", "complexity_tier": "T3", "furigana": "予算(よさん)に沿(そ)って買(か)い物(もの)をするので、むだ使(づか)いが減(へ)った。", "sentence_source": "generated"}, {"text": "期待に沿えず、本当に申し訳ありません。", "target_word": "沿えず", "complexity_tier": "T3", "furigana": "期待(きたい)に沿(そ)えず、本当(ほんとう)に申(もう)し訳(わけ)ありません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "沿う", "label": "基本形"}, {"form": "沿い", "label": "連用形"}, {"form": "沿って", "label": "て形"}, {"form": "沿った", "label": "た形"}, {"form": "沿わない", "label": "ない形"}, {"form": "沿えない", "label": "可能形・ない形"}], "register": "neutral", "sense_fingerprint": "方針・規則・希望などに合わせて従う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93788fa0-f2a6-402a-8dac-82f8c6817f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38495, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沿って", "is_correct": true, "explanation": "「方針に沿って」は方針に従う意味で、「計画を作った」と合う。"}, {"text": "離れて", "is_correct": false, "explanation": "「方針から離れて」なら意味は通るが、「方針に」と続けると不自然。"}, {"text": "眺めて", "is_correct": false, "explanation": "眺める対象に「方針」は取れず、「方針に眺めて」は成り立たない。"}, {"text": "止まって", "is_correct": false, "explanation": "止まる動きは計画を作る文脈と合わず、「方針に止まって」は意味が通らない。"}], "explanations": {"沿って": "「方針に沿って」は方針に従う意味で、「計画を作った」と合う。", "離れて": "「方針から離れて」なら意味は通るが、「方針に」と続けると不自然。", "眺めて": "眺める対象に「方針」は取れず、「方針に眺めて」は成り立たない。", "止まって": "止まる動きは計画を作る文脈と合わず、「方針に止まって」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "沿って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このネクタイは、スーツによく沿う。", "explanation": "ここは〈合う〉（釣り合う）の意味。服の釣り合いを〈沿う〉で言うと、規則や希望に従う語義とずれて合わない。"}, {"text": "夫婦は一生、互いに沿ってケンカばかりしていた。", "explanation": "ここは〈争う〉（言い争う）の場面。争いを〈沿う〉で言うと、道や物にぴったり従う語義とずれて合わない。"}, {"text": "彼女は仕事のミスに沿って、部長に叱られた。", "explanation": "ここは〈原因〉の場面（〜のせいで）。原因は〈沿う〉では表せず、規則や希望に従う語義とずれる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38495, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沿って", "is_correct": true, "explanation": "「規則に沿って」は規則に従う意味で、「話し合った」と合う。"}, {"text": "転がって", "is_correct": false, "explanation": "転がる動きは規則の文脈と合わず、「規則に転がって」は成り立たない。"}, {"text": "眺めて", "is_correct": false, "explanation": "眺める対象に「規則」は取れず、「規則に眺めて」は成り立たない。"}, {"text": "倒れて", "is_correct": false, "explanation": "倒れる動きは話し合いの文脈と合わず、「規則に倒れて」は成り立たない。"}], "explanations": {"沿って": "「規則に沿って」は規則に従う意味で、「話し合った」と合う。", "転がって": "転がる動きは規則の文脈と合わず、「規則に転がって」は成り立たない。", "眺めて": "眺める対象に「規則」は取れず、「規則に眺めて」は成り立たない。", "倒れて": "倒れる動きは話し合いの文脈と合わず、「規則に倒れて」は成り立たない。"}, "sentence_index": 6, "correct_answer": "沿って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は親元に沿って、一人暮らしを始めた。", "explanation": "ここは〈離れる〉の場面（親元から独立する）。離れる行動を〈沿う〉で言うと、離れずに従う定義と正反対になる。"}, {"text": "彼は駅で電車に沿った。", "explanation": "ここは〈乗る〉の場面（乗り物に入る）。乗り物に入る動作は〈沿う〉では表せず、道筋に従う語義と合わない。"}, {"text": "彼は祖母の手に沿って、ゆっくり歩いた。", "explanation": "ここは〈握る〉の場面（手をつかむ）。手を握る動作を〈沿う〉で言うと、ぴったり付いて従う定義と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38495, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上司の指示を沿って、報告書をまとめた。", "corrected_sentence": "上司の指示に沿って、報告書をまとめた。", "error_description": "「沿う」は「〜に沿う」と続け、対象は「に」で示す。「を」は誤りで、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "沿う", "is_correct": true, "explanation": "基本形で、後ろの名詞「部屋」を修飾する形。ここに合う。"}, {"text": "沿い", "is_correct": false, "explanation": "連用形で、「希望に沿い部屋」と名詞を直接修飾できず不自然。"}, {"text": "沿えず", "is_correct": false, "explanation": "「沿うことができず」の連用形で、「部屋」を修飾できず文が成り立たない。"}, {"text": "沿え", "is_correct": false, "explanation": "命令形で、名詞「部屋」を修飾できず文が成り立たない。"}], "correct_form": "沿う", "base_form": "沿う", "form_label": "基本形", "sentence_index": 1, "explanations": {"沿う": "基本形で、後ろの名詞「部屋」を修飾する形。ここに合う。", "沿い": "連用形で、「希望に沿い部屋」と名詞を直接修飾できず不自然。", "沿えず": "「沿うことができず」の連用形で、「部屋」を修飾できず文が成り立たない。", "沿え": "命令形で、名詞「部屋」を修飾できず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38495, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "規則に沿わった行動を心がける。", "corrected_sentence": "規則に沿った行動を心がける。", "error_description": "「沿う」の連体形（た形）は「沿った」。「沿わった」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "沿った", "is_correct": true, "explanation": "た形（連体形）で、後ろの名詞「手続き」を修飾する形。「法律に沿った手続き」は法律に従う手続きの意味で文に合う。"}, {"text": "沿って", "is_correct": false, "explanation": "て形で、後ろの名詞「手続き」を直接修飾できず、「法律に沿って手続き」は文が成り立たない。"}, {"text": "沿おう", "is_correct": false, "explanation": "意志形で、名詞「手続き」を修飾できず、文の中で成り立たない。"}, {"text": "沿わず", "is_correct": false, "explanation": "連用形（中止）で、名詞「手続き」を修飾できず「法律に沿わず手続き」は文が成り立たない。"}], "correct_form": "沿った", "base_form": "沿う", "form_label": "た形（連体形）", "sentence_index": 7, "explanations": {"沿った": "た形（連体形）で、後ろの名詞「手続き」を修飾する形。「法律に沿った手続き」は法律に従う手続きの意味で文に合う。", "沿って": "て形で、後ろの名詞「手続き」を直接修飾できず、「法律に沿って手続き」は文が成り立たない。", "沿おう": "意志形で、名詞「手続き」を修飾できず、文の中で成り立たない。", "沿わず": "連用形（中止）で、名詞「手続き」を修飾できず「法律に沿わず手続き」は文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
