INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38496, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "同じ方向の変化が少しずつ、ゆっくり進むようす。", "primary_collocate": null, "pronunciation": "だんだん", "ipa": "daɴdaɴ", "syllable_count": 4, "sentences": [{"text": "雨が段々強くなってきたので、急いで家に帰りました。", "target_word": "段々", "complexity_tier": "T3", "furigana": "雨[あめ]が段々[だんだん]強[つよ]くなってきたので、急[いそ]いで家[いえ]に帰[かえ]りました。", "sentence_source": "generated"}, {"text": "春になって、日が段々長くなりました。", "target_word": "段々", "complexity_tier": "T3", "furigana": "春[はる]になって、日[ひ]が段々[だんだん]長[なが]くなりました。", "sentence_source": "generated"}, {"text": "毎日練習したら、段々上手に弾けるようになった。", "target_word": "段々", "complexity_tier": "T3", "furigana": "毎日[まいにち]練習[れんしゅう]したら、段々[だんだん]上手[じょうず]に弾[ひ]けるようになった。", "sentence_source": "generated"}, {"text": "薬を飲むと、頭の痛みが段々消えていった。", "target_word": "段々", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]むと、頭[あたま]の痛[いた]みが段々[だんだん]消[き]えていった。", "sentence_source": "generated"}, {"text": "山道を登るうちに、空気が段々冷たくなった。", "target_word": "段々", "complexity_tier": "T3", "furigana": "山道[やまみち]を登[のぼ]るうちに、空気[くうき]が段々[だんだん]冷[つめ]たくなった。", "sentence_source": "generated"}, {"text": "最初は緊張していたが、話すうちに段々慣れてきた。", "target_word": "段々", "complexity_tier": "T3", "furigana": "最初[さいしょ]は緊張[きんちょう]していたが、話[はな]すうちに段々[だんだん]慣[な]れてきた。", "sentence_source": "generated"}, {"text": "夕方になって、町の明かりが段々ふえていく。", "target_word": "段々", "complexity_tier": "T3", "furigana": "夕方[ゆうがた]になって、町[まち]の明[あ]かりが段々[だんだん]ふえていく。", "sentence_source": "generated"}, {"text": "車の音が段々遠くなり、やがて聞こえなくなった。", "target_word": "段々", "complexity_tier": "T3", "furigana": "車[くるま]の音[おと]が段々[だんだん]遠[とお]くなり、やがて聞[き]こえなくなった。", "sentence_source": "generated"}, {"text": "夜が明けて、空が段々明るくなってきた。", "target_word": "段々", "complexity_tier": "T3", "furigana": "夜[よる]が明[あ]けて、空[そら]が段々[だんだん]明[あか]るくなってきた。", "sentence_source": "generated"}, {"text": "子どもは段々背が高くなって、去年の服が着られない。", "target_word": "段々", "complexity_tier": "T3", "furigana": "子[こ]どもは段々[だんだん]背[せ]が高[たか]くなって、去年[きょねん]の服[ふく]が着[き]られない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "段々", "label": "基本形"}, {"form": "段々と", "label": "と付き形"}], "register": "neutral", "sense_fingerprint": "同じ方向の変化が、少しずつ休まず進んでいくようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0df70395-f463-48c9-9f7b-eb53760b6965') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38496, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "段々", "is_correct": true, "explanation": "「段々強くなる」は少しずつ変化するようすを表す。正解。"}, {"text": "きっぱり", "is_correct": false, "explanation": "決意や断定を表す副詞で、少しずつの変化には合わない。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "よく眠るようすを表す副詞で、雨が強くなる変化には合わない。"}, {"text": "のんびり", "is_correct": false, "explanation": "ゆったりしたようすを表す副詞で、雨が強くなる変化には合わない。"}], "explanations": {"段々": "「段々強くなる」は少しずつ変化するようすを表す。正解。", "きっぱり": "決意や断定を表す副詞で、少しずつの変化には合わない。", "ぐっすり": "よく眠るようすを表す副詞で、雨が強くなる変化には合わない。", "のんびり": "ゆったりしたようすを表す副詞で、雨が強くなる変化には合わない。"}, "sentence_index": 0, "correct_answer": "段々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓を段々一度だけ開けた。", "explanation": "ここは〈一度に〉（一回で）の意味。「段々」は少しずつ進むようすなので、一回で開ける動作には使わない。"}, {"text": "全員が段々同時に返事をした。", "explanation": "ここは〈同時に〉の意味。「段々」は少しずつ進むようすで、同時に起こる出来事とは合わない。"}, {"text": "ボールを段々投げた。", "explanation": "ここは〈一度だけ投げる〉の意味。「段々」は少しずつ進む変化なので、一回の投げる動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38496, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "段々", "is_correct": true, "explanation": "「明かりが段々ふえていく」は少しずつ増えるようすを表す。正解。"}, {"text": "ぴったり", "is_correct": false, "explanation": "ぴったり合うようすを表し、増えていく変化には合わない。"}, {"text": "ぐったり", "is_correct": false, "explanation": "疲れて力が抜けるようすを表し、明かりが増える文脈には合わない。"}, {"text": "さっぱり", "is_correct": false, "explanation": "さっぱりしたようす、または全く〜ないを表し、増えていく変化には合わない。"}], "explanations": {"段々": "「明かりが段々ふえていく」は少しずつ増えるようすを表す。正解。", "ぴったり": "ぴったり合うようすを表し、増えていく変化には合わない。", "ぐったり": "疲れて力が抜けるようすを表し、明かりが増える文脈には合わない。", "さっぱり": "さっぱりしたようす、または全く〜ないを表し、増えていく変化には合わない。"}, "sentence_index": 6, "correct_answer": "段々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼はドアを段々ノックした。", "explanation": "ここは〈一回ずつ叩く〉の意味。「段々」は少しずつ進む変化なので、一度のノックには使わない。"}, {"text": "子どもは段々くしゃみをした。", "explanation": "ここは〈瞬間的に起こる〉の意味。「段々」は徐々に進むようすなので、一瞬のくしゃみとは合わない。"}, {"text": "写真を段々一枚撮った。", "explanation": "ここは〈一度だけ撮る〉の意味。「段々」は少しずつ進む変化なので、一枚だけ撮る行為とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38496, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電話を段々一度かけた。", "corrected_sentence": "電話を一度かけた。", "error_description": "「段々」は少しずつ進むようすを表すので、一回だけかける動作とは合わない。「段々」を削ると正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38496, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "段々の雨が強くなった。", "corrected_sentence": "段々と雨が強くなった。", "error_description": "「段々」は副詞なので「の」で名詞に続けない。少しずつのようすを表す「段々と」と続けると正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cfb3d88-3860-44c0-bf3a-63833092d72d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38498, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「古い石垣の間」の「の」で、石垣を場所の前に置いて所在を示している。"}, {"text": "を", "is_correct": false, "explanation": "「石垣を間から」となり、目的語の使い方が文に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「石垣に間から」となり、対象を示すが文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「石垣で間から」となり、手段の意味になって不自然になる。"}], "correct_answer": "の", "explanations": {"の": "「古い石垣の間」の「の」で、石垣を場所の前に置いて所在を示している。", "を": "「石垣を間から」となり、目的語の使い方が文に合わない。", "に": "「石垣に間から」となり、対象を示すが文が成り立たない。", "で": "「石垣で間から」となり、手段の意味になって不自然になる。"}, "error_tags": {"を": "目的語", "に": "相手・対象", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38498, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「石垣の上」の「の」で、石垣の上という位置を示している。"}, {"text": "へ", "is_correct": false, "explanation": "「石垣へ上で」となり、方向を示すが場所の意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「石垣から上で」となり、起点を示すが場所を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「石垣と上で」となり、並列の意味になって文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「石垣の上」の「の」で、石垣の上という位置を示している。", "へ": "「石垣へ上で」となり、方向を示すが場所の意味が通らない。", "から": "「石垣から上で」となり、起点を示すが場所を表せない。", "と": "「石垣と上で」となり、並列の意味になって文が成り立たない。"}, "error_tags": {"へ": "方向", "から": "起点", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38498, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "石垣は、石を積んで作った、かべのようなものです。", "primary_collocate": null, "pronunciation": "いしがき", "ipa": "iɕiɡaki", "syllable_count": 4, "sentences": [{"text": "城の石垣は、四百年前に積まれたものだ。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "城[しろ]の石垣[いしがき]は、四百年[よんひゃくねん]前[まえ]に積[つ]まれたものだ。", "sentence_source": "generated"}, {"text": "古い石垣の間から、小さな花が咲いていた。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "古[ふる]い石垣[いしがき]の間[あいだ]から、小[ちい]さな花[はな]が咲[さ]いていた。", "sentence_source": "generated"}, {"text": "石垣に登ってはいけないと、看板に書いてある。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "石垣[いしがき]に登[のぼ]ってはいけないと、看板[かんばん]に書[か]いてある。", "sentence_source": "generated"}, {"text": "畑のまわりには、低い石垣が続いている。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "畑[はたけ]のまわりには、低[ひく]い石垣[いしがき]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "石垣の石は、一つ一つ形が違う。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "石垣[いしがき]の石[いし]は、一[ひと]つ一[ひと]つ形[かたち]が違[ちが]う。", "sentence_source": "generated"}, {"text": "祖父の家は、高い石垣の上に建っている。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "祖父[そふ]の家[いえ]は、高[たか]い石垣[いしがき]の上[うえ]に建[た]っている。", "sentence_source": "generated"}, {"text": "大雨で石垣がくずれて、道が通れなくなった。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "大雨[おおあめ]で石垣[いしがき]がくずれて、道[みち]が通[とお]れなくなった。", "sentence_source": "generated"}, {"text": "猫が石垣の上で昼寝をしていた。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "猫[ねこ]が石垣[いしがき]の上[うえ]で昼寝[ひるね]をしていた。", "sentence_source": "generated"}, {"text": "石垣をなでながら、昔の人の仕事に感心した。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "石垣[いしがき]をなでながら、昔[むかし]の人[ひと]の仕事[しごと]に感心[かんしん]した。", "sentence_source": "generated"}, {"text": "島では、風を防ぐために家のまわりに石垣を作る。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "島[しま]では、風[かぜ]を防[ふせ]ぐために家[いえ]のまわりに石垣[いしがき]を作[つく]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "石垣", "label": "基本形"}], "register": "標準", "sense_fingerprint": "石を積んで作った壁のようなもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abc5df8a-7a09-4c1e-8bc7-9f0613fb5212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38498, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天気", "is_correct": false, "explanation": "天気は気象の状態で、城を積むという文意に合わず「城の天気は積まれた」は成り立たない。"}, {"text": "石垣", "is_correct": true, "explanation": "石垣は石を積んで作るものなので、「城の石垣は、四百年前に積まれたものだ」として自然に入る。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は文書で、積まれたものという文意には合わない。"}, {"text": "運動会", "is_correct": false, "explanation": "運動会は学校行事で、城の一部として積まれるものにはならない。"}], "explanations": {"天気": "天気は気象の状態で、城を積むという文意に合わず「城の天気は積まれた」は成り立たない。", "石垣": "石垣は石を積んで作るものなので、「城の石垣は、四百年前に積まれたものだ」として自然に入る。", "手紙": "手紙は文書で、積まれたものという文意には合わない。", "運動会": "運動会は学校行事で、城の一部として積まれるものにはならない。"}, "sentence_index": 0, "correct_answer": "石垣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "川には、人が渡れるように石垣を架けてある。", "explanation": "ここは〈石橋〉の意味。石垣は石を積んで壁を作るもので、川に架けて渡る橋にはならないので合わない。"}, {"text": "この広場では、石垣を一面に敷き詰めて、毎朝、市場が開かれる。", "explanation": "ここは〈石畳〉の意味。石垣は石を積んで壁を作るもので、地面に敷き詰めて道にするものではないので合わない。"}, {"text": "庭の石垣は木でできていて、夏は日陰を作る。", "explanation": "〈生け垣〉との混同。石垣は石を積んだものなので、木でできているとは言えず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38498, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教科書", "is_correct": false, "explanation": "教科書は学習用の本で、大雨で崩れるものではないので文が成り立たない。"}, {"text": "石垣", "is_correct": true, "explanation": "石垣は崩れることがあるもので、「大雨で石垣がくずれて、道が通れなくなった」として自然に入る。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は敷物で、大雨で崩れて道をふさぐという文意には合わない。"}, {"text": "花火", "is_correct": false, "explanation": "花火は打ち上げるもので、大雨で崩れて道が通れなくなるという文には合わない。"}], "explanations": {"教科書": "教科書は学習用の本で、大雨で崩れるものではないので文が成り立たない。", "石垣": "石垣は崩れることがあるもので、「大雨で石垣がくずれて、道が通れなくなった」として自然に入る。", "座布団": "座布団は敷物で、大雨で崩れて道をふさぐという文意には合わない。", "花火": "花火は打ち上げるもので、大雨で崩れて道が通れなくなるという文には合わない。"}, "sentence_index": 6, "correct_answer": "石垣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "島では、風を防ぐために家のまわりに石垣を植える。", "explanation": "ここは〈垣根〉の意味。石垣は石を積んだ壁で、植えるものではないので合わない。"}, {"text": "牧場では、牛が逃げないように石垣を張っている。", "explanation": "ここは〈柵〉の意味。石垣は石を積んだ壁で、張って牛を囲う柵とは別物なので合わない。"}, {"text": "この店では、石垣で焼いたピザが人気だ。", "explanation": "ここは〈石窯〉の意味。石垣は石を積んで壁を作るもので、ピザを焼く窯とは別物なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38498, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "石垣が修理するため、職人が集まった。", "corrected_sentence": "石垣を修理するため、職人が集まった。", "error_description": "「修理する」は目的語を「を」で示す。「石垣が」は誤りで、正しくは「石垣を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38498, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "石垣は、職人によって丁寧に積むれた。", "corrected_sentence": "石垣は、職人によって丁寧に積まれた。", "error_description": "「積む」の受身は「積まれる」で、「積むれた」は誤り。五段動詞の受身は未然形「積ま」に「れる」を付けて作る。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38499, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "材料・手段を表し、石垣を使って土を固めるという意味に合う。"}, {"text": "に", "is_correct": false, "explanation": "「石垣に固める」では固める先を示す形になり、材料の意味が出ない。"}, {"text": "と", "is_correct": false, "explanation": "「石垣と固めてある」では並列となり、固める対象として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「石垣から固める」では起点を示し、材料の意味にならない。"}], "correct_answer": "で", "explanations": {"で": "材料・手段を表し、石垣を使って土を固めるという意味に合う。", "に": "「石垣に固める」では固める先を示す形になり、材料の意味が出ない。", "と": "「石垣と固めてある」では並列となり、固める対象として成り立たない。", "から": "「石垣から固める」では起点を示し、材料の意味にならない。"}, "error_tags": {"に": "方向・帰着", "から": "起点", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38499, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "存在する場所を示し、「石垣にはすき間が残っている」に合う。"}, {"text": "が", "is_correct": false, "explanation": "「石垣がは」と助詞が重なり、文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "所属を示すが、「残してある」の場所にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の意味になり、文脈に合わない。"}], "correct_answer": "に", "explanations": {"に": "存在する場所を示し、「石垣にはすき間が残っている」に合う。", "が": "「石垣がは」と助詞が重なり、文として成り立たない。", "の": "所属を示すが、「残してある」の場所にはならない。", "より": "比較の意味になり、文脈に合わない。"}, "error_tags": {"が": "主語", "の": "所有・修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38499, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "石垣は、石を積み重ねて作られた壁や塀のことです。土地を区切ったり、土がくずれるのを防ぐために使われます。", "primary_collocate": null, "pronunciation": "いしがき", "ipa": "iɕiɡaki", "syllable_count": 4, "sentences": [{"text": "土地の境に石垣を築いて、隣の家との間を区切った。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "土地[とち]の境[さかい]に石垣[いしがき]を築[きず]いて、隣[となり]の家[いえ]との間[あいだ]を区切[くぎ]った。", "sentence_source": "generated"}, {"text": "がけの土がくずれないように、石垣で固めてある。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "がけの土[つち]がくずれないように、石垣[いしがき]で固[かた]めてある。", "sentence_source": "generated"}, {"text": "石垣は、斜面の土を支える役目も持っている。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "石垣[いしがき]は、斜面[しゃめん]の土[つち]を支[ささ]える役目[やくめ]も持[も]っている。", "sentence_source": "generated"}, {"text": "職人が石を一つずつ積み重ねて、石垣を作っていく。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "職人[しょくにん]が石[いし]を一[ひと]つずつ積[つ]み重[かさ]ねて、石垣[いしがき]を作[つく]っていく。", "sentence_source": "generated"}, {"text": "この町の石垣は、畑と道を分けるために作られた。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "この町[まち]の石垣[いしがき]は、畑[はたけ]と道[みち]を分[わ]けるために作[つく]られた。", "sentence_source": "generated"}, {"text": "地震のあと、石垣の点検が行われた。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、石垣[いしがき]の点検[てんけん]が行[おこな]われた。", "sentence_source": "generated"}, {"text": "石垣の修理には、同じ種類の石を使うことが多い。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "石垣[いしがき]の修理[しゅうり]には、同[おな]じ種類[しゅるい]の石[いし]を使[つか]うことが多[おお]い。", "sentence_source": "generated"}, {"text": "雨水が抜けるように、石垣にはすき間が残してある。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "雨水[あまみず]が抜[ぬ]けるように、石垣[いしがき]にはすき間[ま]が残[のこ]してある。", "sentence_source": "generated"}, {"text": "石垣のおかげで、坂の上の家は土砂から守られている。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "石垣[いしがき]のおかげで、坂[さか]の上[うえ]の家[いえ]は土砂[どしゃ]から守[まも]られている。", "sentence_source": "generated"}, {"text": "昔の農家は、屋敷のまわりを石垣で囲んだ。", "target_word": "石垣", "complexity_tier": "T3", "furigana": "昔[むかし]の農家[のうか]は、屋敷[やしき]のまわりを石垣[いしがき]で囲[かこ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "石垣", "label": "基本形"}], "register": "標準", "sense_fingerprint": "土地を区切り土のくずれを防ぐ、石を積んだ壁や塀", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abc5df8a-7a09-4c1e-8bc7-9f0613fb5212') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38499, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石垣", "is_correct": true, "explanation": "石を積んで作った壁で、土地の境に築くものとして合う。"}, {"text": "障子", "is_correct": false, "explanation": "紙を張った建具で、土地の境に築くものではない。"}, {"text": "金庫", "is_correct": false, "explanation": "物を入れる箱で、土地を区切るために築くものではない。"}, {"text": "座布団", "is_correct": false, "explanation": "座るための敷物で、土地を区切ることはできない。"}], "explanations": {"石垣": "石を積んで作った壁で、土地の境に築くものとして合う。", "障子": "紙を張った建具で、土地の境に築くものではない。", "金庫": "物を入れる箱で、土地を区切るために築くものではない。", "座布団": "座るための敷物で、土地を区切ることはできない。"}, "sentence_index": 0, "correct_answer": "石垣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜道を照らすために、庭の石垣を高く掲げて灯りにした。", "explanation": "〈石灯籠〉との混同。石灯籠は火を灯して道を照らす道具で、石垣は積んだ壁なので灯りにはならない。"}, {"text": "古い家の木製の石垣が、雨で少し腐ってきた。", "explanation": "〈塀〉のように木で作る囲いとの混同。石垣は石を積んだもので、木製とは言わない。"}, {"text": "米を粉にするため、石垣を回して挽いた。", "explanation": "〈石臼〉との混同。石臼は回して穀物を挽く道具で、石垣は積んだ壁なので回して挽くことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38499, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石垣", "is_correct": true, "explanation": "石を積んだ壁で、修理の対象として合う。"}, {"text": "畳", "is_correct": false, "explanation": "敷物で、石を使って修理するものではない。"}, {"text": "氷", "is_correct": false, "explanation": "凍った水で、石を使った修理の対象ではない。"}, {"text": "鍋", "is_correct": false, "explanation": "調理器具で、同じ種類の石で修理するものではない。"}], "explanations": {"石垣": "石を積んだ壁で、修理の対象として合う。", "畳": "敷物で、石を使って修理するものではない。", "氷": "凍った水で、石を使った修理の対象ではない。", "鍋": "調理器具で、同じ種類の石で修理するものではない。"}, "sentence_index": 6, "correct_answer": "石垣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "洞窟の石垣に、古い絵が描かれていた。", "explanation": "〈石壁〉との混同。石垣は石を積み上げた壁で、洞窟の自然の岩肌には使わない。"}, {"text": "川に架かる石垣を、馬車で渡った。", "explanation": "〈石橋〉との混同。石垣は橋ではないので、渡る対象にはならない。"}, {"text": "パン屋は石垣でパンを焼いている。", "explanation": "〈石窯〉との混同。石垣は焼く設備ではないので、パンを焼く場所として使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38499, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "畑の境に石垣を築いで、隣の土地との間を区切った。", "corrected_sentence": "畑の境に石垣を築いて、隣の土地との間を区切った。", "error_description": "誤り：「築いで」。正しくは「築いて」（て形）。石垣を目的語にとる「築く」のて形の濁音を誤っている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38499, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の後、石垣を崩れてしまった。", "corrected_sentence": "雨の後、石垣が崩れてしまった。", "error_description": "誤り：「石垣を崩れてしまった」。正しくは「石垣が崩れてしまった」。「崩れる」は自動詞なので、主語の「石垣」には「が」を使い、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb1c5d25-a0db-4c6a-8d19-cb3150f69d4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38504, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。雨水がたまる動作の主体なので、主語を示す「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "たまるは自動詞なので、目的語を示す「を」は取らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう方向を表す。たまる動作には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「雨水の」は名詞を修飾する「の」で、「たまって」の主語にはならず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "正解。雨水がたまる動作の主体なので、主語を示す「が」が正しい。", "を": "たまるは自動詞なので、目的語を示す「を」は取らない。", "へ": "「へ」は向かう方向を表す。たまる動作には合わない。", "の": "「雨水の」は名詞を修飾する「の」で、「たまって」の主語にはならず、文が成り立たない。"}, "error_tags": {"を": "object_with_intransitive", "へ": "direction", "の": "modifier"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38504, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。雨水が地面に落ちる動作の主体なので、主語を示す「が」が正しい。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列の相手が必要で、ここでは文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「雨水に」は「地面に」と二重になり、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「雨水で」は手段・原因の意味になり、落ちる主体にならない。"}], "correct_answer": "が", "explanations": {"が": "正解。雨水が地面に落ちる動作の主体なので、主語を示す「が」が正しい。", "と": "「と」は並列の相手が必要で、ここでは文が成り立たない。", "に": "「雨水に」は「地面に」と二重になり、不自然。", "で": "「雨水で」は手段・原因の意味になり、落ちる主体にならない。"}, "error_tags": {"と": "coordination_no_partner", "に": "dative_redundant", "で": "means_cause"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38504, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空から降ってくる水のことです。", "primary_collocate": null, "pronunciation": "あまみず", "ipa": "amamizɯ", "syllable_count": 4, "sentences": [{"text": "屋根に落ちた雨水は、管を通って庭に流れます。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "屋根[やね]に落[お]ちた雨水[あまみず]は、管[くだ]を通[とお]って庭[にわ]に流[なが]れます。", "sentence_source": "generated"}, {"text": "道のくぼみに雨水がたまって、大きな水たまりができた。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "道[みち]のくぼみに雨水[あまみず]がたまって、大[おお]きな水[みず]たまりができた。", "sentence_source": "generated"}, {"text": "窓ガラスを流れる雨水を、子どもが指でなぞっていた。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "窓[まど]ガラスを流[なが]れる雨水[あまみず]を、子[こ]どもが指[ゆび]でなぞっていた。", "sentence_source": "generated"}, {"text": "傘をさしていても、横から入る雨水でズボンがぬれた。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "傘[かさ]をさしていても、横[よこ]から入[はい]る雨水[あまみず]でズボンがぬれた。", "sentence_source": "generated"}, {"text": "雨水が靴の中に入って、一日中足が冷たかった。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "雨水[あまみず]が靴[くつ]の中[なか]に入[はい]って、一日中[いちにちじゅう]足[あし]が冷[つめ]たかった。", "sentence_source": "generated"}, {"text": "大雨のあと、駅の階段を雨水が滝のように流れていた。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "大雨[おおあめ]のあと、駅[えき]の階段[かいだん]を雨水[あまみず]が滝[たき]のように流[なが]れていた。", "sentence_source": "generated"}, {"text": "雨水がかかった本は、紙がふくらんでしまった。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "雨水[あまみず]がかかった本[ほん]は、紙[かみ]がふくらんでしまった。", "sentence_source": "generated"}, {"text": "木の葉にたまった雨水が、ぽたぽたと地面に落ちた。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "木[き]の葉[は]にたまった雨水[あまみず]が、ぽたぽたと地面[じめん]に落[お]ちた。", "sentence_source": "generated"}, {"text": "屋根のすき間から雨水がもれて、天井にしみができた。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "屋根[やね]のすき間[ま]から雨水[あまみず]がもれて、天井[てんじょう]にしみができた。", "sentence_source": "generated"}, {"text": "雨がやんだあとも、軒先から雨水が落ち続けていた。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "雨[あめ]がやんだあとも、軒先[のきさき]から雨水[あまみず]が落[お]ち続[つづ]けていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雨水", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "空から降ってきて、屋根・道・窓などを流れたりたまったりする雨の水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9efccec-f888-4901-be68-89be8aad15f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38504, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雨水", "is_correct": true, "explanation": "正解。屋根から流れて庭へ向かう、降った水のこと。"}, {"text": "毛布", "is_correct": false, "explanation": "毛布は布でできた寝具で、屋根から管を通って庭へ流れるものではないので合わない。"}, {"text": "稲妻", "is_correct": false, "explanation": "稲妻は空の光の現象で、管を通って流れる水にはならない。"}, {"text": "砂ぼこり", "is_correct": false, "explanation": "砂ぼこりは細かい土の粒で、屋根から流れて庭に出るものではないので合わない。"}], "explanations": {"雨水": "正解。屋根から流れて庭へ向かう、降った水のこと。", "毛布": "毛布は布でできた寝具で、屋根から管を通って庭へ流れるものではないので合わない。", "稲妻": "稲妻は空の光の現象で、管を通って流れる水にはならない。", "砂ぼこり": "砂ぼこりは細かい土の粒で、屋根から流れて庭に出るものではないので合わない。"}, "sentence_index": 0, "correct_answer": "雨水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "梅雨の間は雨水がこもって、部屋がかびやすい。", "explanation": "ここは〈湿気〉の意味。部屋にこもるのは湿った空気（湿気）で、水そのものの雨水は合わない。"}, {"text": "今日は二十四節気の雨水で、暦の上では春が始まる。", "explanation": "ここは〈二十四節気〉の名の意味。季節の区切りを表し、降ってくる水の意味にはならないので合わない。"}, {"text": "屋根の上で雨水が静かに鳴っていた。", "explanation": "ここは〈雨音〉の意味。鳴るのは音で、降ってくる水そのものの雨水は鳴らないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38504, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨水", "is_correct": true, "explanation": "正解。雨として降って本にかかった水を指す。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空の色で、本にかかって紙をふくらませるものではない。"}, {"text": "雷雲", "is_correct": false, "explanation": "雷雲は空の雲で、本にかかる水の意味にはならない。"}, {"text": "木漏れ日", "is_correct": false, "explanation": "木漏れ日は木の間から差す光で、本にかかって紙をぬらすものではない。"}], "explanations": {"雨水": "正解。雨として降って本にかかった水を指す。", "夕焼け": "夕焼けは空の色で、本にかかって紙をふくらませるものではない。", "雷雲": "雷雲は空の雲で、本にかかる水の意味にはならない。", "木漏れ日": "木漏れ日は木の間から差す光で、本にかかって紙をぬらすものではない。"}, "sentence_index": 6, "correct_answer": "雨水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜中に雨水がおりて、草が白くなった。", "explanation": "ここは〈露〉の意味。夜の冷えで水滴がつく露の話なので、降ってくる雨水は合わない。"}, {"text": "低い空に雨水が広がって、山が見えなくなった。", "explanation": "ここは〈雨雲〉の意味。空に広がって山を隠すのは雲で、降ってくる水の雨水は合わない。"}, {"text": "窓の外から雨水が聞こえてきた。", "explanation": "ここは〈雨音〉の意味。聞こえるのは音で、水である雨水は聞こえるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38504, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋根に落ちた雨水が、樋を通って庭へ流す。", "corrected_sentence": "屋根に落ちた雨水が、樋を通って庭へ流れる。", "error_description": "誤: 流す（他動詞）、正: 流れる（自動詞）。雨水が主語で移動する意味なので、自動詞の「流れる」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38504, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨水を、樋から庭へ流れた。", "corrected_sentence": "雨水が、樋から庭へ流れた。", "error_description": "誤: 雨水を（を）、正: 雨水が（が）。流れるは自動詞で、移動する雨水が主語になるので「が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38505, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。集めるは他動詞で、目的語の雨水に「を」が付く。"}, {"text": "に", "is_correct": false, "explanation": "「に」は着地点や相手を示すので、集める対象を示す語としては合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、集める対象を示さないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、集める対象を示す語にはならない。"}], "correct_answer": "を", "explanations": {"を": "正解。集めるは他動詞で、目的語の雨水に「を」が付く。", "に": "「に」は着地点や相手を示すので、集める対象を示す語としては合わない。", "へ": "「へ」は方向を示すが、集める対象を示さないので合わない。", "で": "「で」は手段や場所を示すので、集める対象を示す語にはならない。"}, "error_tags": {"に": "location_or_target", "へ": "direction", "で": "means"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
