INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38505, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "空から降ってくる水。雨の水。", "primary_collocate": null, "pronunciation": "あまみず", "ipa": "amamizɯ", "syllable_count": 4, "sentences": [{"text": "庭の花には、水道水ではなく、ためておいた雨水をあげています。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "庭[にわ]の花[はな]には、水道水[すいどうすい]ではなく、ためておいた雨水[あまみず]をあげています。", "sentence_source": "generated"}, {"text": "雨水をバケツに集めて、車を洗った。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "雨水[あまみず]をバケツに集[あつ]めて、車[くるま]を洗[あら]った。", "sentence_source": "generated"}, {"text": "この家では、雨水を大きなタンクにためて、トイレの水に使っています。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "この家[いえ]では、雨水[あまみず]を大[おお]きなタンクにためて、トイレの水[みず]に使[つか]っています。", "sentence_source": "generated"}, {"text": "雨水は飲み水には向かないので、そのまま飲んではいけません。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "雨水[あまみず]は飲[の]み水[みず]には向[む]かないので、そのまま飲[の]んではいけません。", "sentence_source": "generated"}, {"text": "雨が少ない町では、雨水をためる池が大切です。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "雨[あめ]が少[すく]ない町[まち]では、雨水[あまみず]をためる池[いけ]が大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "ベランダのプランターには雨水がたまりやすく、蚊が増える原因になる。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "ベランダのプランターには雨水[あまみず]がたまりやすく、蚊[か]が増[ふ]える原因[げんいん]になる。", "sentence_source": "generated"}, {"text": "祖母は、お風呂の掃除に雨水を使うことがあります。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、お風呂[ふろ]の掃除[そうじ]に雨水[あまみず]を使[つか]うことがあります。", "sentence_source": "generated"}, {"text": "校庭の地下に雨水をためる設備があり、洪水を防いでいる。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "校庭[こうてい]の地下[ちか]に雨水[あまみず]をためる設備[せつび]があり、洪水[こうずい]を防[ふせ]いでいる。", "sentence_source": "generated"}, {"text": "大きな容器を庭に置いて、雨水を集めた。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "大[おお]きな容器[ようき]を庭[にわ]に置[お]いて、雨水[あまみず]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "きれいに見えても、屋根から集めた雨水には、ごみが混じっている。", "target_word": "雨水", "complexity_tier": "T3", "furigana": "きれいに見[み]えても、屋根[やね]から集[あつ]めた雨水[あまみず]には、ごみが混[ま]じっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雨水", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "雨として降った水を、ためたり集めたりして利用・管理する対象として見たもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9efccec-f888-4901-be68-89be8aad15f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38505, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雨水", "is_correct": true, "explanation": "正解。ためておいた、雨として降った水のこと。"}, {"text": "砂利", "is_correct": false, "explanation": "砂利は石の粒で、花にあげる水の代わりにはならない。"}, {"text": "花びら", "is_correct": false, "explanation": "花びらは植物の一部で、水の代わりに花にあげるものではない。"}, {"text": "木くず", "is_correct": false, "explanation": "木くずは木を削った粉で、花にあげるものではないので合わない。"}], "explanations": {"雨水": "正解。ためておいた、雨として降った水のこと。", "砂利": "砂利は石の粒で、花にあげる水の代わりにはならない。", "花びら": "花びらは植物の一部で、水の代わりに花にあげるものではない。", "木くず": "木くずは木を削った粉で、花にあげるものではないので合わない。"}, "sentence_index": 0, "correct_answer": "雨水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "井戸を深く掘ったら、雨水を掘り当てた。", "explanation": "ここは〈地下水〉の意味。掘り当てるのは地中の地下水で、集めて使う雨水には合わない。"}, {"text": "地面の割れ目から、雨水がどんどん湧いてきた。", "explanation": "ここは〈湧き水〉の意味。湧くのは地中からの水で、集めて利用する雨水には合わない。"}, {"text": "雨水をさして、駅まで歩いた。", "explanation": "ここは〈雨傘〉の意味。「さす」は傘に対して使う動詞で、雨水は傘のように持つものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38505, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨水", "is_correct": true, "explanation": "正解。お風呂の掃除に使う、ためておいた雨水。"}, {"text": "陽炎", "is_correct": false, "explanation": "陽炎は熱で揺らいで見える空気の現象で、掃除に使うものではない。"}, {"text": "夕立", "is_correct": false, "explanation": "夕立は急に降る雨の現象で、掃除に使う水そのものではない。"}, {"text": "吹雪", "is_correct": false, "explanation": "吹雪は雪の嵐で、お風呂の掃除に使うものではない。"}], "explanations": {"雨水": "正解。お風呂の掃除に使う、ためておいた雨水。", "陽炎": "陽炎は熱で揺らいで見える空気の現象で、掃除に使うものではない。", "夕立": "夕立は急に降る雨の現象で、掃除に使う水そのものではない。", "吹雪": "吹雪は雪の嵐で、お風呂の掃除に使うものではない。"}, "sentence_index": 6, "correct_answer": "雨水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝から雨水が空を覆っていて、外は暗い。", "explanation": "ここは〈雨雲〉の意味。空を覆うのは雲なので、水そのものの雨水は合わない。"}, {"text": "屋根の上から雨水が響いてきた。", "explanation": "ここは〈雨音〉の意味。響くのは音で、水である雨水は響くものではない。"}, {"text": "雨の日は、雨水がむしむしして、部屋の空気が重い。", "explanation": "ここは〈湿気〉の意味。むしむしするのは空気（湿気）で、水そのものの雨水は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38505, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨水にためて、庭の水やりに使った。", "corrected_sentence": "雨水をためて、庭の水やりに使った。", "error_description": "誤: 雨水に（に）、正: 雨水を（を）。ためるは他動詞で、目的語に「を」を取る。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38505, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨水をためるて、トイレに使う。", "corrected_sentence": "雨水をためて、トイレに使う。", "error_description": "誤: ためるて、正: ためて。「ためる」のて形は「ためて」で、語尾の形が違う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38506, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。直すは他動詞で、目的語の箇所に「を」が付く。"}, {"text": "に", "is_correct": false, "explanation": "「に」は結果や場所を示すが、直す対象を示す語としては合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、直す対象を示さない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同や引用を示すので、直す対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "正解。直すは他動詞で、目的語の箇所に「を」が付く。", "に": "「に」は結果や場所を示すが、直す対象を示す語としては合わない。", "へ": "「へ」は方向を示すので、直す対象を示さない。", "と": "「と」は共同や引用を示すので、直す対象にはならない。"}, "error_tags": {"に": "result_or_location", "へ": "direction", "と": "companion"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
