INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38506, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物の、ある一つの場所。", "primary_collocate": null, "pronunciation": "かしょ", "ipa": "kaɕo", "syllable_count": 2, "sentences": [{"text": "壁のあの箇所に、小さなひびが入っている。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "壁[かべ]のあの箇所[かしょ]に、小[ちい]さなひびが入[はい]っている。", "sentence_source": "generated"}, {"text": "橋の古くなった箇所を、先月直しました。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "橋[はし]の古[ふる]くなった箇所[かしょ]を、先月[せんげつ]直[なお]しました。", "sentence_source": "generated"}, {"text": "痛い箇所を冷やすと、少し楽になった。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "痛[いた]い箇所[かしょ]を冷[ひ]やすと、少[すこ]し楽[らく]になった。", "sentence_source": "generated"}, {"text": "ドアの取っ手があたる箇所が、少しへこんでいる。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "ドアの取[と]っ手[て]があたる箇所[かしょ]が、少[すこ]しへこんでいる。", "sentence_source": "generated"}, {"text": "この箇所だけ色が違うので、あとで塗り直した。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "この箇所[かしょ]だけ色[いろ]が違[ちが]うので、あとで塗[ぬ]り直[なお]した。", "sentence_source": "generated"}, {"text": "車のへこんだ箇所を、写真に撮って保険会社に送った。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "車[くるま]のへこんだ箇所[かしょ]を、写真[しゃしん]に撮[と]って保険会社[ほけんがいしゃ]に送[おく]った。", "sentence_source": "generated"}, {"text": "机のどの箇所を拭いても、白い粉が取れなかった。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "机[つくえ]のどの箇所[かしょ]を拭[ふ]いても、白[しろ]い粉[こな]が取[と]れなかった。", "sentence_source": "generated"}, {"text": "道路のぬれている箇所は、すべりやすいので注意してください。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "道路[どうろ]のぬれている箇所[かしょ]は、すべりやすいので注意[ちゅうい]してください。", "sentence_source": "generated"}, {"text": "古い家の傷んだ箇所から、少しずつ雨がもれてきた。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "古[ふる]い家[いえ]の傷[いた]んだ箇所[かしょ]から、少[すこ]しずつ雨[あめ]がもれてきた。", "sentence_source": "generated"}, {"text": "服のやぶれた箇所に、かわいい布をはった。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "服[ふく]のやぶれた箇所[かしょ]に、かわいい布[ぬの]をはった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "箇所", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "壁・橋・体・服など、物の中のある一つの場所（傷みや汚れ、痛みのある所など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9efccec-f888-4901-be68-89be8aad15f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38506, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "箇所", "is_correct": true, "explanation": "正解。物の中のある一つの場所を指す。"}, {"text": "季節", "is_correct": false, "explanation": "季節は時期の区分で、壁の一か所を指すものではない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空の状態を表し、壁の一か所を指す言葉ではない。"}, {"text": "花びら", "is_correct": false, "explanation": "花びらは植物の一部で、壁のひびの位置には当たらない。"}], "explanations": {"箇所": "正解。物の中のある一つの場所を指す。", "季節": "季節は時期の区分で、壁の一か所を指すものではない。", "天気": "天気は空の状態を表し、壁の一か所を指す言葉ではない。", "花びら": "花びらは植物の一部で、壁のひびの位置には当たらない。"}, "sentence_index": 0, "correct_answer": "箇所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "待ち合わせの箇所は、駅の改札にしよう。", "explanation": "ここは〈集合場所〉の意味。人が集まる場所には、物の一部を指す箇所は使わない。"}, {"text": "会議は午後三時の箇所に始まる。", "explanation": "ここは〈時点〉の意味。時間の一点には箇所を使わず、物の中の位置を指す語なので合わない。"}, {"text": "今日の担当の箇所は、山田さんです。", "explanation": "ここは〈担当者〉の意味。人を指す語なので、物の部分を指す箇所は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38506, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "箇所", "is_correct": true, "explanation": "正解。机の中のある一か所を指す。"}, {"text": "空模様", "is_correct": false, "explanation": "空模様は空の様子で、机の一か所を指す語ではない。"}, {"text": "雨音", "is_correct": false, "explanation": "雨音は降る雨の音で、机の場所を指さない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空の色で、机を拭く対象にはならない。"}], "explanations": {"箇所": "正解。机の中のある一か所を指す。", "空模様": "空模様は空の様子で、机の一か所を指す語ではない。", "雨音": "雨音は降る雨の音で、机の場所を指さない。", "夕焼け": "夕焼けは空の色で、机を拭く対象にはならない。"}, "sentence_index": 6, "correct_answer": "箇所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "咳の箇所がなかなか治らない。", "explanation": "ここは〈症状〉の意味。咳のように病気の状態を言う場面で、箇所は合わない。"}, {"text": "このかばんの箇所は五千円です。", "explanation": "ここは〈値段〉の意味。金額を言う場面で、物の場所を指す箇所は使わない。"}, {"text": "この店の箇所は「さくら食堂」です。", "explanation": "ここは〈名前〉の意味。店の呼び名を言う場面で、箇所は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38506, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "棚のへこんだ箇所に、布でふいた。", "corrected_sentence": "棚のへこんだ箇所を、布でふいた。", "error_description": "誤: 箇所に（に）、正: 箇所を（を）。ふくは他動詞で、目的語に「を」を取る。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38506, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "汚れた箇所を、水でふきて乾かした。", "corrected_sentence": "汚れた箇所を、水でふいて乾かした。", "error_description": "誤: ふきて、正: ふいて。「ふく」の て形は「ふいて」で、活用形が違う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38507, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。線を引く位置を示すので、「箇所に」の「に」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「線を引く」にすでに「を」があるので、箇所に「を」を重ねると不自然。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、線を引く位置を表さない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同を示すので、位置を示す語としては合わない。"}], "correct_answer": "に", "explanations": {"に": "正解。線を引く位置を示すので、「箇所に」の「に」が正しい。", "を": "「線を引く」にすでに「を」があるので、箇所に「を」を重ねると不自然。", "が": "「が」は主語を示すので、線を引く位置を表さない。", "と": "「と」は共同を示すので、位置を示す語としては合わない。"}, "error_tags": {"を": "double_object", "が": "subject", "と": "companion"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38507, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。直すは他動詞で、目的語の箇所に「を」が付く。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、直す対象を示す語としては合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、直す対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同を示すので、直す対象を示す語としては合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。直すは他動詞で、目的語の箇所に「を」が付く。", "が": "「が」は主語を示すので、直す対象を示す語としては合わない。", "へ": "「へ」は方向を示すので、直す対象にはならない。", "と": "「と」は共同を示すので、直す対象を示す語としては合わない。"}, "error_tags": {"が": "subject", "へ": "direction", "と": "companion"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38507, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "文章・書類・曲などの全体のうち、指し示せる特定の位置や部分。", "primary_collocate": null, "pronunciation": "かしょ", "ipa": "kaɕo", "syllable_count": 2, "sentences": [{"text": "説明書のこの箇所が、よくわかりません。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]のこの箇所[かしょ]が、よくわかりません。", "sentence_source": "generated"}, {"text": "先生は、作文の間違えた箇所に赤いペンで線を引いた。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "先生[せんせい]は、作文[さくぶん]の間違[まちが]えた箇所[かしょ]に赤[あか]いペンで線[せん]を引[ひ]いた。", "sentence_source": "generated"}, {"text": "契約書の大切な箇所は、もう一度声に出して読んだ。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "契約書[けいやくしょ]の大切[たいせつ]な箇所[かしょ]は、もう一度[いちど]声[こえ]に出[だ]して読[よ]んだ。", "sentence_source": "generated"}, {"text": "本の気に入った箇所に、付せんをはっておいた。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "本[ほん]の気[き]に入[い]った箇所[かしょ]に、付[ふ]せんをはっておいた。", "sentence_source": "generated"}, {"text": "質問のある箇所に印をつけて、会議に持って行く。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "質問[しつもん]のある箇所[かしょ]に印[しるし]をつけて、会議[かいぎ]に持[も]って行[い]く。", "sentence_source": "generated"}, {"text": "この曲は、後半の箇所がいちばん盛り上がる。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "この曲[きょく]は、後半[こうはん]の箇所[かしょ]がいちばん盛[も]り上[あ]がる。", "sentence_source": "generated"}, {"text": "申込書に、名前を書く箇所が二つあります。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "申込書[もうしこみしょ]に、名前[なまえ]を書[か]く箇所[かしょ]が二[ふた]つあります。", "sentence_source": "generated"}, {"text": "計画の弱い箇所を、みんなで話し合って直した。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "計画[けいかく]の弱[よわ]い箇所[かしょ]を、みんなで話[はな]し合[あ]って直[なお]した。", "sentence_source": "generated"}, {"text": "文章が長いので、読みにくい箇所を短くした。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "文章[ぶんしょう]が長[なが]いので、読[よ]みにくい箇所[かしょ]を短[みじか]くした。", "sentence_source": "generated"}, {"text": "試験で、間違えた箇所をノートにまとめて復習した。", "target_word": "箇所", "complexity_tier": "T3", "furigana": "試験[しけん]で、間違[まちが]えた箇所[かしょ]をノートにまとめて復習[ふくしゅう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "箇所", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "文章・書類・計画・曲など全体の中の、指し示せる特定の位置や部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: 付せん (Zipf 1.06)']::text[], 'c9efccec-f888-4901-be68-89be8aad15f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38507, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "箇所", "is_correct": true, "explanation": "正解。説明の中の、特定の部分を指す。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は座る物で、説明書の中の部分を指さないので合わない。"}, {"text": "桜", "is_correct": false, "explanation": "桜は植物で、説明書の一部を指す語ではない。"}, {"text": "煙", "is_correct": false, "explanation": "煙は空中に広がるもので、説明書の中の位置を指さない。"}], "explanations": {"箇所": "正解。説明の中の、特定の部分を指す。", "座布団": "座布団は座る物で、説明書の中の部分を指さないので合わない。", "桜": "桜は植物で、説明書の一部を指す語ではない。", "煙": "煙は空中に広がるもので、説明書の中の位置を指さない。"}, "sentence_index": 0, "correct_answer": "箇所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この映画の箇所は『千と千尋の神隠し』だ。", "explanation": "ここは〈題名〉の意味。作品の名前を言う場面で、文章の一部を指す箇所は合わない。"}, {"text": "この小説の箇所は、山田さんです。", "explanation": "ここは〈作者〉の意味。作った人を指す語で、箇所は人を指さないので合わない。"}, {"text": "レポートの箇所は、来週の金曜です。", "explanation": "ここは〈締め切り〉の意味。期限を表す場面で、文章の一部を指す箇所は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38507, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "箇所", "is_correct": true, "explanation": "正解。申込書の中で名前を書く位置を指す。"}, {"text": "季節", "is_correct": false, "explanation": "季節は時期の区分で、名前を書く位置を表さない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空の色で、申込書の欄の位置ではない。"}, {"text": "雷雲", "is_correct": false, "explanation": "雷雲は空の雲で、名前を書く位置を表さないので合わない。"}], "explanations": {"箇所": "正解。申込書の中で名前を書く位置を指す。", "季節": "季節は時期の区分で、名前を書く位置を表さない。", "夕焼け": "夕焼けは空の色で、申込書の欄の位置ではない。", "雷雲": "雷雲は空の雲で、名前を書く位置を表さないので合わない。"}, "sentence_index": 6, "correct_answer": "箇所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の箇所は晴れです。", "explanation": "ここは〈天気〉の意味。空の状態を言う場面で、物の一部を指す箇所は合わない。"}, {"text": "参加者の箇所は三人だ。", "explanation": "ここは〈人数〉の意味。人の数を言う場面で、場所を表す箇所は合わない。"}, {"text": "この箱の箇所は千円です。", "explanation": "ここは〈値段〉の意味。金額を言う場面で、物の場所を指す箇所は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38507, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "説明書のわかりにくい箇所を、印をつけた。", "corrected_sentence": "説明書のわかりにくい箇所に、印をつけた。", "error_description": "誤: 箇所を（を）、正: 箇所に（に）。印をつける場所を示すので「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38507, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "読みにくい箇所を、みんなで直る。", "corrected_sentence": "読みにくい箇所を、みんなで直した。", "error_description": "誤: 直る（自動詞）、正: 直した（他動詞「直す」の過去形）。「箇所を」を目的語に取るので、他動詞の「直す」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '800b8427-2305-4379-a834-3be6279f554a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38508, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "狭い", "is_correct": true, "explanation": "「せまい」は「広い」の対義語で、空間にゆとりがないことを表す。"}, {"text": "高い", "is_correct": false, "explanation": "高さの反対は低い。広さの対義語ではない。"}, {"text": "重い", "is_correct": false, "explanation": "重さの反対は軽い。広さとは関係がない。"}, {"text": "遅い", "is_correct": false, "explanation": "速さの反対は速い。広い・せまいの軸とは関係がない。"}], "correct_answer": "狭い", "explanations": {"狭い": "「せまい」は「広い」の対義語で、空間にゆとりがないことを表す。", "高い": "高さの反対は低い。広さの対義語ではない。", "重い": "重さの反対は軽い。広さとは関係がない。", "遅い": "速さの反対は速い。広い・せまいの軸とは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38508, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "狭い", "is_correct": true, "explanation": "「広い」の対義語。「広く」を「狭く」に変えると反対の意味になる。"}, {"text": "低い", "is_correct": false, "explanation": "高さの反対。広さの対義語ではない。"}, {"text": "厚い", "is_correct": false, "explanation": "厚みの反対は薄い。広さとは関係がない。"}, {"text": "細い", "is_correct": false, "explanation": "太さの反対は太い。広さの反対語ではない。"}], "correct_answer": "狭い", "explanations": {"狭い": "「広い」の対義語。「広く」を「狭く」に変えると反対の意味になる。", "低い": "高さの反対。広さの対義語ではない。", "厚い": "厚みの反対は薄い。広さとは関係がない。", "細い": "太さの反対は太い。広さの反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38508, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "せまくない。", "primary_collocate": null, "pronunciation": "ひろい", "ipa": "çiɾoi", "syllable_count": 3, "sentences": [{"text": "この部屋は広いので、四人で寝ても大丈夫です。", "target_word": "広い", "complexity_tier": "T3", "furigana": "この部屋(へや)は広(ひろ)いので、四人(よにん)で寝(ね)ても大丈夫(だいじょうぶ)です。", "sentence_source": "generated"}, {"text": "前の家は狭かったが、今の家は広い。", "target_word": "広い", "complexity_tier": "T3", "furigana": "前(まえ)の家(いえ)は狭(せま)かったが、今(いま)の家(いえ)は広(ひろ)い。", "sentence_source": "generated"}, {"text": "道が広いから、大きいトラックも通れます。", "target_word": "広い", "complexity_tier": "T3", "furigana": "道(みち)が広(ひろ)いから、大(おお)きいトラックも通(とお)れます。", "sentence_source": "generated"}, {"text": "広いソファを買ったので、三人で座れる。", "target_word": "広い", "complexity_tier": "T3", "furigana": "広(ひろ)いソファを買(か)ったので、三人(さんにん)で座(すわ)れる。", "sentence_source": "generated"}, {"text": "この机は広くて、本もパソコンも置けます。", "target_word": "広く", "complexity_tier": "T3", "furigana": "この机(つくえ)は広(ひろ)くて、本(ほん)もパソコンも置(お)けます。", "sentence_source": "generated"}, {"text": "広い廊下では、子どもたちが走って遊んでいた。", "target_word": "広い", "complexity_tier": "T3", "furigana": "広(ひろ)い廊下(ろうか)では、子(こ)どもたちが走(はし)って遊(あそ)んでいた。", "sentence_source": "generated"}, {"text": "入り口が広いので、車いすでも入りやすいです。", "target_word": "広い", "complexity_tier": "T3", "furigana": "入(い)り口(ぐち)が広(ひろ)いので、車(くるま)いすでも入(はい)りやすいです。", "sentence_source": "generated"}, {"text": "狭い台所より、広い台所のほうが料理しやすい。", "target_word": "広い", "complexity_tier": "T3", "furigana": "狭(せま)い台所(だいどころ)より、広(ひろ)い台所(だいどころ)のほうが料理(りょうり)しやすい。", "sentence_source": "generated"}, {"text": "広い席に座りたかったので、早く店に行った。", "target_word": "広い", "complexity_tier": "T3", "furigana": "広(ひろ)い席(せき)に座(すわ)りたかったので、早(はや)く店(みせ)に行(い)った。", "sentence_source": "generated"}, {"text": "この橋は車が二台すれ違えるように、広く作られている。", "target_word": "広く", "complexity_tier": "T3", "furigana": "この橋(はし)は車(くるま)が二台(にだい)すれ違(ちが)えるように、広(ひろ)く作(つく)られている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "広い", "label": "終止形・連体形"}, {"form": "広く", "label": "連用形"}, {"form": "広かった", "label": "過去形"}, {"form": "広くない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "幅や空間にゆとりがあり、せまくないこと（せまいの反対）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: 違える (Zipf 2.31)']::text[], '8087f10f-9764-4266-bbce-4f535d18a169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38508, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "広い", "is_correct": true, "explanation": "「この部屋は〜ので、四人で寝ても大丈夫」の理由になる、空間にゆとりがあるという意味の形容詞の原形。"}, {"text": "狭い", "is_correct": false, "explanation": "せまいという意味。部屋がせまければ四人で寝ても大丈夫とは言えず、理由として成り立たない。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す形容詞。部屋の様子を説明する文では意味が通らない。"}, {"text": "遅い", "is_correct": false, "explanation": "速さや時間を表す形容詞。部屋を形容する場面には合わない。"}], "explanations": {"広い": "「この部屋は〜ので、四人で寝ても大丈夫」の理由になる、空間にゆとりがあるという意味の形容詞の原形。", "狭い": "せまいという意味。部屋がせまければ四人で寝ても大丈夫とは言えず、理由として成り立たない。", "重い": "重さを表す形容詞。部屋の様子を説明する文では意味が通らない。", "遅い": "速さや時間を表す形容詞。部屋を形容する場面には合わない。"}, "sentence_index": 0, "correct_answer": "広い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱の中身は、重さが広いので持ち運びにくい。", "explanation": "ここは〈重い〉の意味。重さには「重い」を使い、「広い」は重さには使わないので合わない。"}, {"text": "広い声で話すと、遠くまで届く。", "explanation": "ここは〈大きい〉の意味。声の大きさには「大きい」を使い、「広い」は使わないので合わない。"}, {"text": "広い道のりを歩いて、ようやく駅に着いた。", "explanation": "ここは〈長い〉の意味。距離の長さには「長い」を使い、「広い」は道の幅に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38508, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "広い", "is_correct": true, "explanation": "「入り口が〜ので、車いすでも入りやすい」の理由になる、空間にゆとりがあるという意味の形容詞の原形。"}, {"text": "薄い", "is_correct": false, "explanation": "厚みが少ないという意味。入り口の空間の大きさを表せず、理由として成り立たない。"}, {"text": "苦い", "is_correct": false, "explanation": "味を表す形容詞で、入り口の様子を説明する文には合わない。"}, {"text": "眠い", "is_correct": false, "explanation": "眠気を表す形容詞で、入り口を形容する場面では意味が通らない。"}], "explanations": {"広い": "「入り口が〜ので、車いすでも入りやすい」の理由になる、空間にゆとりがあるという意味の形容詞の原形。", "薄い": "厚みが少ないという意味。入り口の空間の大きさを表せず、理由として成り立たない。", "苦い": "味を表す形容詞で、入り口の様子を説明する文には合わない。", "眠い": "眠気を表す形容詞で、入り口を形容する場面では意味が通らない。"}, "sentence_index": 6, "correct_answer": "広い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅から家までは広いので、歩いて五分で着く。", "explanation": "ここは〈近い〉の意味。距離の近さには「近い」を使い、「広い」は距離に使わないので合わない。"}, {"text": "このホテルは値段が広いので、予約が取りにくい。", "explanation": "ここは〈高い〉の意味。値段の高低には「高い」を使い、「広い」は値段に使わないので合わない。"}, {"text": "このスープは量が広くて、お椀に入りきらない。", "explanation": "ここは〈多い〉の意味。量の多さには「多い」を使い、「広い」は量には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38508, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この部屋は広くので、家族四人で寝ても大丈夫です。", "corrected_sentence": "この部屋は広いので、家族四人で寝ても大丈夫です。", "error_description": "「広い」を連用形の「広く」にしたのが誤り。理由を表す「〜ので」の前には終止・連体形の「広い」を置く。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "広い", "is_correct": true, "explanation": "文末で言い切る終止形。「今の家は広い」と現在の状態を述べている。"}, {"text": "広く", "is_correct": false, "explanation": "連用形。文末に置くと言い切れず、文として終わらない。"}, {"text": "広ければ", "is_correct": false, "explanation": "仮定形。「〜ば」で文末に置くと言い切れず、「今の家は広ければ」では文が成り立たない。"}, {"text": "広くて", "is_correct": false, "explanation": "て形。文末に置くと言い切れず、「今の家は広くて」で文が終わらない。"}], "correct_form": "広い", "base_form": "広い", "form_label": "終止形", "sentence_index": 1, "explanations": {"広い": "文末で言い切る終止形。「今の家は広い」と現在の状態を述べている。", "広く": "連用形。文末に置くと言い切れず、文として終わらない。", "広ければ": "仮定形。「〜ば」で文末に置くと言い切れず、「今の家は広ければ」では文が成り立たない。", "広くて": "て形。文末に置くと言い切れず、「今の家は広くて」で文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38508, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "玄関の入り口が広いに、車いすでも入りやすいです。", "corrected_sentence": "玄関の入り口が広いので、車いすでも入りやすいです。", "error_description": "理由を表す「ので」が必要なのに「に」を続けたのが誤り。「広い」には「ので」で理由をつなぐ。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "広い", "is_correct": true, "explanation": "名詞「台所」を直接修飾する連体形。「広い台所」の形。"}, {"text": "広そう", "is_correct": false, "explanation": "様態の形。名詞「台所」を直接修飾できず、「広そう台所」は成り立たない。"}, {"text": "広さ", "is_correct": false, "explanation": "名詞。「広さ台所」のように名詞を直接修飾できず、文が成り立たない。"}, {"text": "広かろう", "is_correct": false, "explanation": "推量の形。名詞を直接修飾できず、比べる文の中に入れると意味が通らない。"}], "correct_form": "広い", "base_form": "広い", "form_label": "連体形", "sentence_index": 7, "explanations": {"広い": "名詞「台所」を直接修飾する連体形。「広い台所」の形。", "広そう": "様態の形。名詞「台所」を直接修飾できず、「広そう台所」は成り立たない。", "広さ": "名詞。「広さ台所」のように名詞を直接修飾できず、文が成り立たない。", "広かろう": "推量の形。名詞を直接修飾できず、比べる文の中に入れると意味が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38509, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "狭い", "is_correct": true, "explanation": "「せまい」は「広い」の対義語で、面積や範囲が小さいことを表す。"}, {"text": "薄い", "is_correct": false, "explanation": "厚みの反対。面積や範囲の対義語ではない。"}, {"text": "硬い", "is_correct": false, "explanation": "かたさの反対は柔らかい。面積とは関係がない。"}, {"text": "遅い", "is_correct": false, "explanation": "速さの反対は速い。面積や範囲の軸とは関係がない。"}], "correct_answer": "狭い", "explanations": {"狭い": "「せまい」は「広い」の対義語で、面積や範囲が小さいことを表す。", "薄い": "厚みの反対。面積や範囲の対義語ではない。", "硬い": "かたさの反対は柔らかい。面積とは関係がない。", "遅い": "速さの反対は速い。面積や範囲の軸とは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38509, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "狭い", "is_correct": true, "explanation": "「広い」の対義語で、面積や範囲が小さいことを表す。"}, {"text": "低い", "is_correct": false, "explanation": "高さの反対。面積や範囲の対義語ではない。"}, {"text": "厚い", "is_correct": false, "explanation": "厚みの反対は薄い。面積とは関係がない。"}, {"text": "軽い", "is_correct": false, "explanation": "重さの反対。面積や範囲とは関係がない。"}], "correct_answer": "狭い", "explanations": {"狭い": "「広い」の対義語で、面積や範囲が小さいことを表す。", "低い": "高さの反対。面積や範囲の対義語ではない。", "厚い": "厚みの反対は薄い。面積とは関係がない。", "軽い": "重さの反対。面積や範囲とは関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38509, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "面積や範囲が大きいこと。", "primary_collocate": null, "pronunciation": "ひろい", "ipa": "çiɾoi", "syllable_count": 3, "sentences": [{"text": "広い公園で、家族みんなでお弁当を食べた。", "target_word": "広い", "complexity_tier": "T3", "furigana": "広(ひろ)い公園(こうえん)で、家族(かぞく)みんなでお弁当(べんとう)を食(た)べた。", "sentence_source": "generated"}, {"text": "北海道は広いので、車で回るのに何日もかかる。", "target_word": "広い", "complexity_tier": "T3", "furigana": "北海道(ほっかいどう)は広(ひろ)いので、車(くるま)で回(まわ)るのに何日(なんにち)もかかる。", "sentence_source": "generated"}, {"text": "広い海を見ていると、悩みが小さく思えてくる。", "target_word": "広い", "complexity_tier": "T3", "furigana": "広(ひろ)い海(うみ)を見(み)ていると、悩(なや)みが小(ちい)さく思(おも)えてくる。", "sentence_source": "generated"}, {"text": "この町は面積が広いわりに、人口が少ない。", "target_word": "広い", "complexity_tier": "T3", "furigana": "この町(まち)は面積(めんせき)が広(ひろ)いわりに、人口(じんこう)が少(すく)ない。", "sentence_source": "generated"}, {"text": "広い畑でじゃがいもを作っている。", "target_word": "広い", "complexity_tier": "T3", "furigana": "広(ひろ)い畑(はたけ)でじゃがいもを作(つく)っている。", "sentence_source": "generated"}, {"text": "山の上から広い範囲の町並みが見えた。", "target_word": "広い", "complexity_tier": "T3", "furigana": "山(やま)の上(うえ)から広(ひろ)い範囲(はんい)の町並(まちな)みが見(み)えた。", "sentence_source": "generated"}, {"text": "広い草原を馬で走るのが夢だ。", "target_word": "広い", "complexity_tier": "T3", "furigana": "広(ひろ)い草原(そうげん)を馬(うま)で走(はし)るのが夢(ゆめ)だ。", "sentence_source": "generated"}, {"text": "この大学は敷地が広く、移動に自転車が必要だ。", "target_word": "広く", "complexity_tier": "T3", "furigana": "この大学(だいがく)は敷地(しきち)が広(ひろ)く、移動(いどう)に自転車(じてんしゃ)が必要(ひつよう)だ。", "sentence_source": "generated"}, {"text": "台風の影響は広い地域に及んだ。", "target_word": "広い", "complexity_tier": "T3", "furigana": "台風(たいふう)の影響(えいきょう)は広(ひろ)い地域(ちいき)に及(およ)んだ。", "sentence_source": "generated"}, {"text": "広い庭がある家に住むのが、祖父の昔からの希望だった。", "target_word": "広い", "complexity_tier": "T3", "furigana": "広(ひろ)い庭(にわ)がある家(いえ)に住(す)むのが、祖父(そふ)の昔(むかし)からの希望(きぼう)だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "広い", "label": "終止形・連体形"}, {"form": "広く", "label": "連用形"}, {"form": "広かった", "label": "過去形"}, {"form": "広くない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "土地・敷地・地域などの面積や範囲が大きいこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8087f10f-9764-4266-bbce-4f535d18a169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38509, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "広い", "is_correct": true, "explanation": "「〜公園で」の前に入り、面積が大きい公園を表す形容詞の原形。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す形容詞。公園の面積を表す語としては意味が通らない。"}, {"text": "遅い", "is_correct": false, "explanation": "速さや時間を表す形容詞で、公園を形容する文には合わない。"}, {"text": "熱い", "is_correct": false, "explanation": "温度を表す形容詞で、公園の大きさを説明する文では意味が通らない。"}], "explanations": {"広い": "「〜公園で」の前に入り、面積が大きい公園を表す形容詞の原形。", "重い": "重さを表す形容詞。公園の面積を表す語としては意味が通らない。", "遅い": "速さや時間を表す形容詞で、公園を形容する文には合わない。", "熱い": "温度を表す形容詞で、公園の大きさを説明する文では意味が通らない。"}, "sentence_index": 0, "correct_answer": "広い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この板は厚さが広いので、棚に使うと重くなる。", "explanation": "ここは〈厚い〉の意味。厚さには「厚い」を使い、「広い」は厚さには使わないので合わない。"}, {"text": "この紅茶は広いので、ミルクを入れて飲む。", "explanation": "ここは〈濃い〉の意味。飲み物の濃さには「濃い」を使い、「広い」は使わないので合わない。"}, {"text": "このお菓子は砂糖が広いので、とても甘い。", "explanation": "ここは〈多い〉の意味。分量の多さには「多い」を使い、「広い」は砂糖の量には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38509, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "広い", "is_correct": true, "explanation": "「〜草原を馬で走る」の前に入り、面積が大きい草原を表す形容詞の原形。"}, {"text": "軽い", "is_correct": false, "explanation": "重さの反対を表す形容詞。草原の広さを説明する文には合わない。"}, {"text": "甘い", "is_correct": false, "explanation": "味を表す形容詞で、草原を形容する文では意味が通らない。"}, {"text": "苦い", "is_correct": false, "explanation": "味を表す形容詞で、草原の様子を表す文には合わない。"}], "explanations": {"広い": "「〜草原を馬で走る」の前に入り、面積が大きい草原を表す形容詞の原形。", "軽い": "重さの反対を表す形容詞。草原の広さを説明する文には合わない。", "甘い": "味を表す形容詞で、草原を形容する文では意味が通らない。", "苦い": "味を表す形容詞で、草原の様子を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "広い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校から家までは広いので、歩いて五分で着く。", "explanation": "ここは〈近い〉の意味。距離の近さには「近い」を使い、「広い」は距離に使わないので合わない。"}, {"text": "この店は値段が広いので、学生はなかなか入れない。", "explanation": "ここは〈高い〉の意味。値段の高低には「高い」を使い、「広い」は値段には使わないので合わない。"}, {"text": "この紐は太さが広いので、結ぶと指が痛くなる。", "explanation": "ここは〈太い〉の意味。太さには「太い」を使い、「広い」は太さには使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38509, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この国は面積が広いく、移動に時間がかかる。", "corrected_sentence": "この国は面積が広く、移動に時間がかかる。", "error_description": "連用形は「広く」で、「広いく」は活用の誤り。後ろに続けるには「広く」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "広い", "is_correct": true, "explanation": "「〜ので」の前に置く終止形。「北海道は広いので」と理由を述べている。"}, {"text": "広く", "is_correct": false, "explanation": "連用形。「〜ので」の前では活用の形として合わない。"}, {"text": "広かろう", "is_correct": false, "explanation": "推量の形。「〜ので」の前には続かず、「広かろうので」は成り立たない。"}, {"text": "広くない", "is_correct": false, "explanation": "否定形。せまいという意味になり、理由の文が逆になる。"}], "correct_form": "広い", "base_form": "広い", "form_label": "終止形", "sentence_index": 1, "explanations": {"広い": "「〜ので」の前に置く終止形。「北海道は広いので」と理由を述べている。", "広く": "連用形。「〜ので」の前では活用の形として合わない。", "広かろう": "推量の形。「〜ので」の前には続かず、「広かろうので」は成り立たない。", "広くない": "否定形。せまいという意味になり、理由の文が逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38509, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "広いの草原で、馬を自由に走らせたい。", "corrected_sentence": "広い草原で、馬を自由に走らせたい。", "error_description": "「広い」の後に「の」を付けて名詞「草原」を修飾したのが誤り。名詞を修飾するのは連体形の「広い」だけで、「広いの草原」は不自然。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "広く", "is_correct": true, "explanation": "連用形。「敷地が広く、移動に〜が必要だ」と後ろの文へ続けている。"}, {"text": "広さ", "is_correct": false, "explanation": "名詞。「敷地が広さ、」では述語にならず、文が続かない。"}, {"text": "広そう", "is_correct": false, "explanation": "様態の形。「敷地が広そう、」では言い切れず、後ろの文とつながらない。"}, {"text": "広すぎ", "is_correct": false, "explanation": "「広すぎる」の語幹。「敷地が広すぎ、」では文の述語にならず、後ろの文へ続かない。"}], "correct_form": "広く", "base_form": "広い", "form_label": "連用形", "sentence_index": 7, "explanations": {"広く": "連用形。「敷地が広く、移動に〜が必要だ」と後ろの文へ続けている。", "広さ": "名詞。「敷地が広さ、」では述語にならず、文が続かない。", "広そう": "様態の形。「敷地が広そう、」では言い切れず、後ろの文とつながらない。", "広すぎ": "「広すぎる」の語幹。「敷地が広すぎ、」では文の述語にならず、後ろの文へ続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38510, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「分布」に続けて主題を示す係助詞。「キノコの分布は場所によって違う」と話題を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す格助詞。「違う」は目的語を取らないので、ここでは合わない。"}, {"text": "に", "is_correct": false, "explanation": "相手や結果を示す格助詞。「分布に、場所によって違う」と続けると文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す格助詞。分布を示す語には続かず、文の構造が合わない。"}], "correct_answer": "は", "explanations": {"は": "「分布」に続けて主題を示す係助詞。「キノコの分布は場所によって違う」と話題を示す。", "を": "目的語を示す格助詞。「違う」は目的語を取らないので、ここでは合わない。", "に": "相手や結果を示す格助詞。「分布に、場所によって違う」と続けると文が成り立たない。", "で": "場所や手段を示す格助詞。分布を示す語には続かず、文の構造が合わない。"}, "error_tags": {"を": "目的語（違うと合わない）", "に": "相手・結果（主題にならない）", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38510, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「中心に分布」の「に」。中心を基点にして広がって存在する様子を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す格助詞。「中心が分布」では文の関係が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用を示す格助詞。「中心と分布」では意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す格助詞。「分布する」は目的語を取らないため、「中心を分布していて」は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「中心に分布」の「に」。中心を基点にして広がって存在する様子を示す。", "が": "主語を示す格助詞。「中心が分布」では文の関係が成り立たない。", "と": "並列や引用を示す格助詞。「中心と分布」では意味が通らない。", "を": "目的語を示す格助詞。「分布する」は目的語を取らないため、「中心を分布していて」は成り立たない。"}, "error_tags": {"が": "主語（述語の関係が合わない）", "と": "並列・引用", "を": "目的語（分布は目的語を取らない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38510, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物が広い場所に広がってあること。", "primary_collocate": null, "pronunciation": "ぶんぷ", "ipa": "bɯmpɯ", "syllable_count": 3, "sentences": [{"text": "この花は日本の南の島に多く分布している。", "target_word": "分布", "complexity_tier": "T3", "furigana": "この花(はな)は日本(にほん)の南(みなみ)の島(しま)に多(おお)く分布(ぶんぷ)している。", "sentence_source": "generated"}, {"text": "森の中でも、キノコの分布は場所によって違う。", "target_word": "分布", "complexity_tier": "T3", "furigana": "森(もり)の中(なか)でも、キノコの分布(ぶんぷ)は場所(ばしょ)によって違(ちが)う。", "sentence_source": "generated"}, {"text": "先生は地図に動物の分布を書いてくれた。", "target_word": "分布", "complexity_tier": "T3", "furigana": "先生(せんせい)は地図(ちず)に動物(どうぶつ)の分布(ぶんぷ)を書(か)いてくれた。", "sentence_source": "generated"}, {"text": "寒い地域では、この木の分布が少なくなる。", "target_word": "分布", "complexity_tier": "T3", "furigana": "寒(さむ)い地域(ちいき)では、この木(き)の分布(ぶんぷ)が少(すく)なくなる。", "sentence_source": "generated"}, {"text": "ペンギンの分布は、主に南半球に限られている。", "target_word": "分布", "complexity_tier": "T3", "furigana": "ペンギンの分布(ぶんぷ)は、主(おも)に南半球(みなみはんきゅう)に限(かぎ)られている。", "sentence_source": "generated"}, {"text": "川の近くに、貝の分布が集中していた。", "target_word": "分布", "complexity_tier": "T3", "furigana": "川(かわ)の近(ちか)くに、貝(かい)の分布(ぶんぷ)が集中(しゅうちゅう)していた。", "sentence_source": "generated"}, {"text": "雨が多い地域では、この草の分布が広がりやすい。", "target_word": "分布", "complexity_tier": "T3", "furigana": "雨(あめ)が多(おお)い地域(ちいき)では、この草(くさ)の分布(ぶんぷ)が広(ひろ)がりやすい。", "sentence_source": "generated"}, {"text": "この虫は暖かい地域を中心に分布していて、北の寒い所にはいない。", "target_word": "分布", "complexity_tier": "T3", "furigana": "この虫(むし)は暖(あたた)かい地域(ちいき)を中心(ちゅうしん)に分布(ぶんぷ)していて、北(きた)の寒(さむ)い所(ところ)にはいない。", "sentence_source": "generated"}, {"text": "日本全国に分布するスズメは、町でよく見かける。", "target_word": "分布", "complexity_tier": "T3", "furigana": "日本全国(にほんぜんこく)に分布(ぶんぷ)するスズメは、町(まち)でよく見(み)かける。", "sentence_source": "generated"}, {"text": "調査で、珍しい魚の分布が少しずつ明らかになった。", "target_word": "分布", "complexity_tier": "T3", "furigana": "調査(ちょうさ)で、珍(めずら)しい魚(さかな)の分布(ぶんぷ)が少(すこ)しずつ明(あき)らかになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分布", "label": "基本形"}, {"form": "分布する", "label": "動詞形"}, {"form": "分布している", "label": "状態形"}], "register": "neutral", "sense_fingerprint": "動植物など自然の物が各地に広がって存在していること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8087f10f-9764-4266-bbce-4f535d18a169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38510, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分布", "is_correct": true, "explanation": "「多く〜している」で、生き物が各地に広がって存在することを表すサ変名詞。"}, {"text": "分解", "is_correct": false, "explanation": "物を成分や部品に分けることを表す。生き物が広がる文には合わない。"}, {"text": "分割", "is_correct": false, "explanation": "全体を複数に切り分けることを表す。「多く分割している」は意味が通らない。"}, {"text": "分担", "is_correct": false, "explanation": "仕事や役割を分けて受け持つことを表す。生き物の広がりを説明する文には合わない。"}], "explanations": {"分布": "「多く〜している」で、生き物が各地に広がって存在することを表すサ変名詞。", "分解": "物を成分や部品に分けることを表す。生き物が広がる文には合わない。", "分割": "全体を複数に切り分けることを表す。「多く分割している」は意味が通らない。", "分担": "仕事や役割を分けて受け持つことを表す。生き物の広がりを説明する文には合わない。"}, "sentence_index": 0, "correct_answer": "分布"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の資料を分布したら、すぐになくなった。", "explanation": "ここは〈配って渡す〉の意味の「配布」。資料を配る動作に「分布」は使わないので合わない。"}, {"text": "遺産を分布したことで、兄弟がもめた。", "explanation": "ここは〈取り分として分ける〉の意味の「分配」。財産を分けることに「分布」は使わないので合わない。"}, {"text": "ケーキを四つに分布して、みんなで食べた。", "explanation": "ここは〈切って分ける〉の意味の「分割」。物を切り分けることには「分布」は使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38510, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分布", "is_correct": true, "explanation": "「この草の〜が広がりやすい」で、草が各地に散らばって存在することを表す名詞。"}, {"text": "分析", "is_correct": false, "explanation": "物事を要素ごとに調べることを表す。草が広がる文には合わない。"}, {"text": "採掘", "is_correct": false, "explanation": "地下の鉱物を掘り出すことを表す。草の広がりを説明する文では意味が通らない。"}, {"text": "配分", "is_correct": false, "explanation": "割り当てて分けることを表す。草が広がる文には合わない。"}], "explanations": {"分布": "「この草の〜が広がりやすい」で、草が各地に散らばって存在することを表す名詞。", "分析": "物事を要素ごとに調べることを表す。草が広がる文には合わない。", "採掘": "地下の鉱物を掘り出すことを表す。草の広がりを説明する文では意味が通らない。", "配分": "割り当てて分けることを表す。草が広がる文には合わない。"}, "sentence_index": 6, "correct_answer": "分布"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "動物を分布して、鳥と魚に分けた。", "explanation": "ここは〈種類ごとに分ける〉の意味の「分類」。種類を分けることに「分布」は使わないので合わない。"}, {"text": "道が三つに分布している。", "explanation": "ここは〈枝分かれする〉の意味の「分岐」。道の枝分かれには「分布」は使わないので合わない。"}, {"text": "山で植物を分布して、標本にした。", "explanation": "ここは〈採って集める〉の意味の「採取」。植物を採ることに「分布」は使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38510, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この虫は日本の南の島に多く分布がしている。", "corrected_sentence": "この虫は日本の南の島に多く分布している。", "error_description": "「分布」はサ変動詞として「分布する」の形で使う。「分布が」と間に助詞を挟んだのが誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38510, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この虫は暖かい地域に分布されている。", "corrected_sentence": "この虫は暖かい地域に分布している。", "error_description": "「分布」は「分布する」の形で自動詞的に使う。受け身の「分布される」は不自然で、「分布している」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38511, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見る」の目的語を示す格助詞。「分布を見ると」と続けると文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す格助詞。「見る」は目的語を取るので、「分布が見ると」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "相手や結果を示す格助詞。「分布に見ると」は文の構造が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格助詞。「分布へ見る」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「見る」の目的語を示す格助詞。「分布を見ると」と続けると文が成り立つ。", "が": "主語を示す格助詞。「見る」は目的語を取るので、「分布が見ると」は合わない。", "に": "相手や結果を示す格助詞。「分布に見ると」は文の構造が合わない。", "へ": "方向を示す格助詞。「分布へ見る」は意味が通らない。"}, "error_tags": {"が": "主語（見るの目的語にならない）", "に": "相手・結果", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38511, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「偏っている」の主語を示す格助詞。「病院の分布が偏っている」と成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す格助詞。「偏る」は目的語を取らないので、「分布を偏っていて」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す格助詞。「分布で偏っていて」は文の構造が合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用を示す格助詞。「分布と偏っていて」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「偏っている」の主語を示す格助詞。「病院の分布が偏っている」と成り立つ。", "を": "目的語を示す格助詞。「偏る」は目的語を取らないので、「分布を偏っていて」は合わない。", "で": "場所や手段を示す格助詞。「分布で偏っていて」は文の構造が合わない。", "と": "並列や引用を示す格助詞。「分布と偏っていて」は意味が通らない。"}, "error_tags": {"を": "目的語（偏るは目的語を取らない）", "で": "手段・場所", "と": "並列・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38511, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある範囲にわたって、物が散らばって存在していること。", "primary_collocate": null, "pronunciation": "ぶんぷ", "ipa": "bɯmpɯ", "syllable_count": 3, "sentences": [{"text": "町の人口の分布を調べて、新しい駅の場所を決めた。", "target_word": "分布", "complexity_tier": "T3", "furigana": "町(まち)の人口(じんこう)の分布(ぶんぷ)を調(しら)べて、新(あたら)しい駅(えき)の場所(ばしょ)を決(き)めた。", "sentence_source": "generated"}, {"text": "テストの点数の分布を見ると、七十点の人が一番多い。", "target_word": "分布", "complexity_tier": "T3", "furigana": "テストの点数(てんすう)の分布(ぶんぷ)を見(み)ると、七十点(ななじゅってん)の人(ひと)が一番(いちばん)多(おお)い。", "sentence_source": "generated"}, {"text": "星は空全体に分布しているように見える。", "target_word": "分布", "complexity_tier": "T3", "furigana": "星(ほし)は空全体(そらぜんたい)に分布(ぶんぷ)しているように見(み)える。", "sentence_source": "generated"}, {"text": "年齢の分布がわかる表を、会議で配った。", "target_word": "分布", "complexity_tier": "T3", "furigana": "年齢(ねんれい)の分布(ぶんぷ)がわかる表(ひょう)を、会議(かいぎ)で配(くば)った。", "sentence_source": "generated"}, {"text": "店の分布を地図にすると、駅の周りに集まっていた。", "target_word": "分布", "complexity_tier": "T3", "furigana": "店(みせ)の分布(ぶんぷ)を地図(ちず)にすると、駅(えき)の周(まわ)りに集(あつ)まっていた。", "sentence_source": "generated"}, {"text": "このグラフは、身長の分布を表している。", "target_word": "分布", "complexity_tier": "T3", "furigana": "このグラフは、身長(しんちょう)の分布(ぶんぷ)を表(あらわ)している。", "sentence_source": "generated"}, {"text": "工場が全国に分布しているので、配達が早い。", "target_word": "分布", "complexity_tier": "T3", "furigana": "工場(こうじょう)が全国(ぜんこく)に分布(ぶんぷ)しているので、配達(はいたつ)が早(はや)い。", "sentence_source": "generated"}, {"text": "病院の分布が偏っていて、山の村は不便だ。", "target_word": "分布", "complexity_tier": "T3", "furigana": "病院(びょういん)の分布(ぶんぷ)が偏(かたよ)っていて、山(やま)の村(むら)は不便(ふべん)だ。", "sentence_source": "generated"}, {"text": "雪の分布を示す図で、北の山が白く塗られていた。", "target_word": "分布", "complexity_tier": "T3", "furigana": "雪(ゆき)の分布(ぶんぷ)を示(しめ)す図(ず)で、北(きた)の山(やま)が白(しろ)く塗(ぬ)られていた。", "sentence_source": "generated"}, {"text": "客の分布がわかれば、広告を出す場所を選べる。", "target_word": "分布", "complexity_tier": "T3", "furigana": "客(きゃく)の分布(ぶんぷ)がわかれば、広告(こうこく)を出(だ)す場所(ばしょ)を選(えら)べる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分布", "label": "基本形"}, {"form": "分布する", "label": "動詞形"}, {"form": "分布している", "label": "状態形"}], "register": "neutral", "sense_fingerprint": "人・店・数値などが範囲内に散らばっている状態（統計や調査で扱う）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8087f10f-9764-4266-bbce-4f535d18a169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38511, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分布", "is_correct": true, "explanation": "「町の人口の〜を調べて」で、人口が範囲内にどう散らばっているかを表す名詞。"}, {"text": "生産", "is_correct": false, "explanation": "物を作り出すことを表す。人口を調べる文には合わない。"}, {"text": "採掘", "is_correct": false, "explanation": "地下の資源を掘り出すことを表す。人口を調べる文では意味が通らない。"}, {"text": "調達", "is_correct": false, "explanation": "必要な物を用意することを表す。人口の調査には合わない。"}], "explanations": {"分布": "「町の人口の〜を調べて」で、人口が範囲内にどう散らばっているかを表す名詞。", "生産": "物を作り出すことを表す。人口を調べる文には合わない。", "採掘": "地下の資源を掘り出すことを表す。人口を調べる文では意味が通らない。", "調達": "必要な物を用意することを表す。人口の調査には合わない。"}, "sentence_index": 0, "correct_answer": "分布"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎月のお金を分布して、旅行に備えた。", "explanation": "ここは〈少しずつためる〉の意味の「貯金」。お金をためることには「貯金」を使い、「分布」は物の散らばりを表すので合わない。"}, {"text": "山で虫を分布して、標本にした。", "explanation": "ここは〈採って集める〉の意味の「採取」。虫を採ることには「分布」は使わないので合わない。"}, {"text": "紙を四つに分布して、袋に入れた。", "explanation": "ここは〈切って分ける〉の意味の「分割」。紙を切り分けることには「分布」は使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38511, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分布", "is_correct": true, "explanation": "「工場が全国に〜しているので」で、工場が各地に散らばって存在することを表すサ変名詞。"}, {"text": "分解", "is_correct": false, "explanation": "物を部品や成分に分けることを表す。工場の広がりを説明する文には合わない。"}, {"text": "分割", "is_correct": false, "explanation": "全体を複数に切り分けることを表す。「全国に分割している」は意味が通らない。"}, {"text": "配分", "is_correct": false, "explanation": "割り当てて分けることを表す。工場の立地を説明する文には合わない。"}], "explanations": {"分布": "「工場が全国に〜しているので」で、工場が各地に散らばって存在することを表すサ変名詞。", "分解": "物を部品や成分に分けることを表す。工場の広がりを説明する文には合わない。", "分割": "全体を複数に切り分けることを表す。「全国に分割している」は意味が通らない。", "配分": "割り当てて分けることを表す。工場の立地を説明する文には合わない。"}, "sentence_index": 6, "correct_answer": "分布"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "本を分布して、ジャンルごとに並べた。", "explanation": "ここは〈種類ごとに分ける〉の意味の「分類」。本をジャンル別に分けることには「分布」は使わないので合わない。"}, {"text": "川が二つに分布して流れる。", "explanation": "ここは〈枝分かれする〉の意味の「分岐」。川の枝分かれには「分布」は使わないので合わない。"}, {"text": "プリントを分布して、全員に渡した。", "explanation": "ここは〈配って渡す〉の意味の「配布」。プリントを配ることには「分布」は使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38511, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店の分布が調べて、新しい倉庫の場所を決めた。", "corrected_sentence": "店の分布を調べて、新しい倉庫の場所を決めた。", "error_description": "「調べる」は目的語に「を」を取る。「分布が」と主語の「が」を付けたのが誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38511, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "支店の分布が確認した。", "corrected_sentence": "支店の分布を確認した。", "error_description": "「確認する」は目的語に「を」を取る。「分布が」と主語の「が」を付けたのが誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38512, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「降雨が強まる」の「が」。降雨が強まる主体を示す。"}, {"text": "を", "is_correct": false, "explanation": "「降雨を強まる」は他動詞でないので、「を」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「降雨に強まる」は文が成り立たず、「に」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「降雨と強まる」は並列にならず、意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「降雨が強まる」の「が」。降雨が強まる主体を示す。", "を": "「降雨を強まる」は他動詞でないので、「を」は成り立たない。", "に": "「降雨に強まる」は文が成り立たず、「に」は不自然。", "と": "「降雨と強まる」は並列にならず、意味が通らない。"}, "error_tags": {"を": "目的語の誤用", "に": "対象の誤用", "と": "並列の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38512, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「降雨があった」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「降雨をあった」は文にならず、「を」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「降雨とあった」は意味が通らず、「と」は合わない。"}, {"text": "から", "is_correct": false, "explanation": "「降雨からあった」は成り立たず、起点を表す「から」は合わない。"}], "correct_answer": "が", "explanations": {"が": "「降雨があった」の主語を示す「が」。", "を": "「降雨をあった」は文にならず、「を」は不自然。", "と": "「降雨とあった」は意味が通らず、「と」は合わない。", "から": "「降雨からあった」は成り立たず、起点を表す「から」は合わない。"}, "error_tags": {"を": "目的語の誤用", "と": "並列の誤用", "から": "起点の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38512, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "空から水が落ちてくることです。", "primary_collocate": null, "pronunciation": "こうう", "ipa": "koːɯ", "syllable_count": 3, "sentences": [{"text": "降雨のため、今日の運動会は中止になりました。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "降雨(こうう)のため、今日(きょう)の運動会(うんどうかい)は中止(ちゅうし)になりました。", "sentence_source": "generated"}, {"text": "夜から降雨が強まるので、傘を持って行こう。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "夜(よる)から降雨(こうう)が強(つよ)まるので、傘(かさ)を持(も)って行(い)こう。", "sentence_source": "generated"}, {"text": "午後は降雨の確率が高いと、天気予報で言っていた。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "午後(ごご)は降雨(こうう)の確率(かくりつ)が高(たか)いと、天気予報(てんきよほう)で言(い)っていた。", "sentence_source": "generated"}, {"text": "降雨が続いて、川の水が増えている。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "降雨(こうう)が続(つづ)いて、川(かわ)の水(みず)が増(ふ)えている。", "sentence_source": "generated"}, {"text": "昨日の降雨で、道が水たまりだらけになった。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "昨日(きのう)の降雨(こうう)で、道(みち)が水(みず)たまりだらけになった。", "sentence_source": "generated"}, {"text": "降雨のせいで、電車が少し遅れた。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "降雨(こうう)のせいで、電車(でんしゃ)が少(すこ)し遅(おく)れた。", "sentence_source": "generated"}, {"text": "明け方に短い降雨があったが、すぐにやんだ。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "明(あ)け方(がた)に短(みじか)い降雨(こうう)があったが、すぐにやんだ。", "sentence_source": "generated"}, {"text": "川の上流で強い降雨があったため、下流の水位が上がった。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "川(かわ)の上流(じょうりゅう)で強(つよ)い降雨(こうう)があったため、下流(かりゅう)の水位(すいい)が上(あ)がった。", "sentence_source": "generated"}, {"text": "降雨が止んだら、洗濯物を外に干そう。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "降雨(こうう)が止(や)んだら、洗濯物(せんたくもの)を外(そと)に干(ほ)そう。", "sentence_source": "generated"}, {"text": "台風の接近で、広い地域に激しい降雨が予想される。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "台風(たいふう)の接近(せっきん)で、広(ひろ)い地域(ちいき)に激(はげ)しい降雨(こうう)が予想(よそう)される。", "sentence_source": "generated"}], "morphological_forms": [{"form": "降雨", "label": "基本形"}, {"form": "降雨量", "label": "複合語"}], "register": "formal", "sense_fingerprint": "天気の現象として雨が降ること（天気予報・行事の中止などで使う）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8087f10f-9764-4266-bbce-4f535d18a169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38512, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降雨", "is_correct": true, "explanation": "「降雨のため中止」の空欄に入り、雨が降ることを表す。文脈の理由として合う。"}, {"text": "晴天", "is_correct": false, "explanation": "晴れた天気は運動会を中止する理由にならず、「晴天のため中止」は意味が通らない。"}, {"text": "練習", "is_correct": false, "explanation": "練習は行事中止の理由にならず、「練習のため中止」は文として成り立たない。"}, {"text": "参加", "is_correct": false, "explanation": "参加は中止の理由にならず、「参加のため中止」は意味が通らない。"}], "explanations": {"降雨": "「降雨のため中止」の空欄に入り、雨が降ることを表す。文脈の理由として合う。", "晴天": "晴れた天気は運動会を中止する理由にならず、「晴天のため中止」は意味が通らない。", "練習": "練習は行事中止の理由にならず、「練習のため中止」は文として成り立たない。", "参加": "参加は中止の理由にならず、「参加のため中止」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "降雨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜中の降雨で、庭がうっすら白く積もっていた。", "explanation": "ここは〈降雪〉の意味。降雨は雨を指すので、白く積もる雪の描写には合わない。"}, {"text": "明け方、谷間に降雨が立ち込めていた。", "explanation": "ここは〈霧〉の意味。降雨は雨が降ることなので、谷に立ち込める霧には合わない。"}, {"text": "午後は降雨で、ぽかぽかと暖かい日差しが続いた。", "explanation": "ここは〈日照〉の意味。降雨は雨が降ることなので、日差しが続く状態には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38512, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降雨", "is_correct": true, "explanation": "短く降って「すぐにやんだ」と続く流れに合う。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝坊は「やむ」ものではなく、「すぐにやんだ」と続かない。"}, {"text": "食事", "is_correct": false, "explanation": "食事は途中で「やんだ」とは言わず、文の流れに合わない。"}, {"text": "会議", "is_correct": false, "explanation": "会議は「すぐにやんだ」と言える出来事ではなく、文脈に合わない。"}], "explanations": {"降雨": "短く降って「すぐにやんだ」と続く流れに合う。", "寝坊": "寝坊は「やむ」ものではなく、「すぐにやんだ」と続かない。", "食事": "食事は途中で「やんだ」とは言わず、文の流れに合わない。", "会議": "会議は「すぐにやんだ」と言える出来事ではなく、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "降雨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "噴火の降雨で、町は一日中灰色に覆われた。", "explanation": "ここは〈降灰〉の意味。降雨は雨を指すので、火山灰が降る現象には合わない。"}, {"text": "遠くで降雨が鳴り、空が一瞬光った。", "explanation": "ここは〈雷〉の意味。雨は鳴らないので、音を伴う雷の描写には合わない。"}, {"text": "朝、畑一面に降雨が降りて、野菜が白くなった。", "explanation": "ここは〈霜〉の意味。降雨は雨を指すので、畑に降りて白くする霜には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38512, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "強い降雨を、川の水位が上がった。", "corrected_sentence": "強い降雨で、川の水位が上がった。", "error_description": "原因を表す「で」が正しいのに「を」になっている。降雨は目的語になれず、「降雨を＋上がった」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38512, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "降雨が続きて、道がぬかるんだ。", "corrected_sentence": "降雨が続いて、道がぬかるんだ。", "error_description": "動詞「続く」のて形は「続いて」。「続きて」は活用の誤りで、正しくは「続いて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38513, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「春の降雨がとても大切だ」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「降雨を大切だ」は成り立たず、「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「降雨にとても大切だ」は不自然で、「に」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「降雨ととても大切だ」は意味が通らず、「と」は合わない。"}], "correct_answer": "が", "explanations": {"が": "「春の降雨がとても大切だ」の主語を示す「が」。", "を": "「降雨を大切だ」は成り立たず、「を」は合わない。", "に": "「降雨にとても大切だ」は不自然で、「に」は合わない。", "と": "「降雨ととても大切だ」は意味が通らず、「と」は合わない。"}, "error_tags": {"を": "目的語の誤用", "に": "対象の誤用", "と": "並列の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38513, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「降雨がなく」の主語を示す「が」。"}, {"text": "へ", "is_correct": false, "explanation": "「降雨へなく」は方向を示す「へ」で、「なく」の主語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「降雨からなく」は起点を示す「から」で、「なく」の主語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「降雨のなく」は連体修飾の「の」で、文の主語を示すことはできない。"}], "correct_answer": "が", "explanations": {"が": "「降雨がなく」の主語を示す「が」。", "へ": "「降雨へなく」は方向を示す「へ」で、「なく」の主語にはならない。", "から": "「降雨からなく」は起点を示す「から」で、「なく」の主語にはならない。", "の": "「降雨のなく」は連体修飾の「の」で、文の主語を示すことはできない。"}, "error_tags": {"へ": "方向の誤用", "から": "起点の誤用", "の": "連体の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38513, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "空から降る雨のこと。特に、農業や生活に必要な水としての雨を指す。", "primary_collocate": null, "pronunciation": "こうう", "ipa": "koːɯ", "syllable_count": 3, "sentences": [{"text": "今年は降雨が少なく、農家は水不足に困っている。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "今年(ことし)は降雨(こうう)が少(すく)なく、農家(のうか)は水不足(みずぶそく)に困(こま)っている。", "sentence_source": "generated"}, {"text": "田んぼには、春の降雨がとても大切だ。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "田(た)んぼには、春(はる)の降雨(こうう)がとても大切(たいせつ)だ。", "sentence_source": "generated"}, {"text": "降雨のおかげで、畑の野菜が元気に育った。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "降雨(こうう)のおかげで、畑(はたけ)の野菜(やさい)が元気(げんき)に育(そだ)った。", "sentence_source": "generated"}, {"text": "降雨が足りないと、ダムの水も減ってしまう。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "降雨(こうう)が足(た)りないと、ダムの水(みず)も減(へ)ってしまう。", "sentence_source": "generated"}, {"text": "農家の人は、降雨の量を毎日ノートに書いている。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "農家(のうか)の人(ひと)は、降雨(こうう)の量(りょう)を毎日(まいにち)ノートに書(か)いている。", "sentence_source": "generated"}, {"text": "適度な降雨があれば、米がよく実る。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "適度(てきど)な降雨(こうう)があれば、米(こめ)がよく実(みの)る。", "sentence_source": "generated"}, {"text": "降雨が多い年は、果物の味が薄くなることがある。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "降雨(こうう)が多(おお)い年(とし)は、果物(くだもの)の味(あじ)が薄(うす)くなることがある。", "sentence_source": "generated"}, {"text": "長い間降雨がなく、川も井戸も水が減った。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "長(なが)い間(あいだ)降雨(こうう)がなく、川(かわ)も井戸(いど)も水(みず)が減(へ)った。", "sentence_source": "generated"}, {"text": "降雨を待つ農家のために、雨乞いの祭りが開かれた。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "降雨(こうう)を待(ま)つ農家(のうか)のために、雨乞(あまご)いの祭(まつ)りが開(ひら)かれた。", "sentence_source": "generated"}, {"text": "夏の降雨は、町の水道の水源を支えている。", "target_word": "降雨", "complexity_tier": "T3", "furigana": "夏(なつ)の降雨(こうう)は、町(まち)の水道(すいどう)の水源(すいげん)を支(ささ)えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "降雨", "label": "基本形"}, {"form": "降雨量", "label": "複合語"}], "register": "formal", "sense_fingerprint": "農作物や水源を潤す恵みとしての雨（降雨量の多少が話題になる）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8087f10f-9764-4266-bbce-4f535d18a169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38513, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降雨", "is_correct": true, "explanation": "雨の少なさが水不足を生む文脈に合う。"}, {"text": "残業", "is_correct": false, "explanation": "残業は水不足と関係せず、「残業が少なく」は文脈に合わない。"}, {"text": "値段", "is_correct": false, "explanation": "値段は水不足の原因にならず、「値段が少なく」は意味が通らない。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝坊は農業の水不足と関係せず、文として意味が通らない。"}], "explanations": {"降雨": "雨の少なさが水不足を生む文脈に合う。", "残業": "残業は水不足と関係せず、「残業が少なく」は文脈に合わない。", "値段": "値段は水不足の原因にならず、「値段が少なく」は意味が通らない。", "寝坊": "寝坊は農業の水不足と関係せず、文として意味が通らない。"}, "sentence_index": 0, "correct_answer": "降雨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜のうちの降雨で、屋根が真っ白に積もった。", "explanation": "ここは〈降雪〉の意味。降雨は雨を指すので、屋根に積もる雪の描写には合わない。"}, {"text": "夏の強い降雨で、作物の葉が焼けてしまった。", "explanation": "ここは〈日照〉の意味。降雨は雨なので、強い日差しで葉が焼ける状況には合わない。"}, {"text": "冬の朝、畑に降雨が降りて、野菜が白くなった。", "explanation": "ここは〈霜〉の意味。降雨は雨を指すので、畑に降りる霜の描写には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38513, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降雨", "is_correct": true, "explanation": "雨が多い年の影響として、果物の味に関わる文脈に合う。"}, {"text": "会議", "is_correct": false, "explanation": "会議が多くても果物の味は薄くならず、文脈に合わない。"}, {"text": "注文", "is_correct": false, "explanation": "注文の多さは果物の味と関係せず、「注文が多い年」は意味が通らない。"}, {"text": "通学", "is_correct": false, "explanation": "通学の多さは果物の味と無関係で、文として成り立たない。"}], "explanations": {"降雨": "雨が多い年の影響として、果物の味に関わる文脈に合う。", "会議": "会議が多くても果物の味は薄くならず、文脈に合わない。", "注文": "注文の多さは果物の味と関係せず、「注文が多い年」は意味が通らない。", "通学": "通学の多さは果物の味と無関係で、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "降雨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "噴火の降雨で、町の水道が灰で詰まった。", "explanation": "ここは〈降灰〉の意味。降雨は雨を指すので、火山灰が降る現象には合わない。"}, {"text": "遠くで降雨が鳴り、窓がびりびり震えた。", "explanation": "ここは〈雷〉の意味。雨は鳴らないので、音と振動を伴う雷の描写には合わない。"}, {"text": "大きな降雨で家が揺れ、棚の皿が割れた。", "explanation": "ここは〈地震〉の意味。降雨は雨を指すので、家を揺らす地震の描写には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38513, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春の降雨を、田植えの準備が遅れた。", "corrected_sentence": "春の降雨で、田植えの準備が遅れた。", "error_description": "原因を表す「で」が正しいのに「を」になっている。降雨は目的語にならず、「降雨を＋遅れた」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38513, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "降雨が少ないったので、ため池が干上がった。", "corrected_sentence": "降雨が少なかったので、ため池が干上がった。", "error_description": "形容詞「少ない」の過去形は「少なかった」。「少ないった」は活用の誤りで、正しくは「少なかった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38514, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「貯留によって」の「に」。「によって」で原因や手段を表す形になる。"}, {"text": "を", "is_correct": false, "explanation": "「貯留を によって」は成立せず、目的語を示す「を」は前後の形に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「貯留で によって」は重なって不自然で、手段の「で」は合わない。"}, {"text": "が", "is_correct": false, "explanation": "「貯留が によって」は成立せず、主語の「が」は合わない。"}], "correct_answer": "に", "explanations": {"に": "「貯留によって」の「に」。「によって」で原因や手段を表す形になる。", "を": "「貯留を によって」は成立せず、目的語を示す「を」は前後の形に合わない。", "で": "「貯留で によって」は重なって不自然で、手段の「で」は合わない。", "が": "「貯留が によって」は成立せず、主語の「が」は合わない。"}, "error_tags": {"を": "object", "で": "means", "が": "subject"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
