INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38514, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "水をためておくこと。", "primary_collocate": null, "pronunciation": "ちょりゅう", "ipa": "tɕoɾʲɯː", "syllable_count": 3, "sentences": [{"text": "雨水の貯留タンクを家の裏に設置した。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "雨水[あまみず]の貯留[ちょりゅう]タンクを家[いえ]の裏[うら]に設置[せっち]した。", "sentence_source": "generated"}, {"text": "ダムは水の貯留によって、夏の水不足を防いでいる。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "ダムは水[みず]の貯留[ちょりゅう]によって、夏[なつ]の水不足[みずぶそく]を防[ふせ]いでいる。", "sentence_source": "generated"}, {"text": "大雨のときは、川の水を一時的に貯留する池がある。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "大雨[おおあめ]のときは、川[かわ]の水[みず]を一時的[いちじてき]に貯留[ちょりゅう]する池[いけ]がある。", "sentence_source": "generated"}, {"text": "田んぼは水の貯留にも役立っている。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "田[た]んぼは水[みず]の貯留[ちょりゅう]にも役立[やくだ]っている。", "sentence_source": "generated"}, {"text": "貯留した水は、畑にまく分だけ毎朝使います。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "貯留[ちょりゅう]した水[みず]は、畑[はたけ]にまく分[ぶん]だけ毎朝[まいあさ]使[つか]います。", "sentence_source": "generated"}, {"text": "この地域では、雨水の貯留が義務づけられている。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "この地域[ちいき]では、雨水[あまみず]の貯留[ちょりゅう]が義務[ぎむ]づけられている。", "sentence_source": "generated"}, {"text": "貯留できる量が少ないので、水の使い方に注意してください。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "貯留[ちょりゅう]できる量[りょう]が少[すく]ないので、水[みず]の使[つか]い方[かた]に注意[ちゅうい]してください。", "sentence_source": "generated"}, {"text": "地下に水を貯留するため、大きな穴を掘った。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "地下[ちか]に水[みず]を貯留[ちょりゅう]するため、大[おお]きな穴[あな]を掘[ほ]った。", "sentence_source": "generated"}, {"text": "水の貯留が足りなくなって、町は給水を制限した。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "水[みず]の貯留[ちょりゅう]が足[た]りなくなって、町[まち]は給水[きゅうすい]を制限[せいげん]した。", "sentence_source": "generated"}, {"text": "学校の屋上に雨水を貯留して、花に水をやっている。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "学校[がっこう]の屋上[おくじょう]に雨水[あまみず]を貯留[ちょりゅう]して、花[はな]に水[みず]をやっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "貯留", "label": "基本形"}, {"form": "貯留する", "label": "動詞形"}, {"form": "貯留した", "label": "過去形"}, {"form": "貯留される", "label": "受身形"}], "register": "formal", "sense_fingerprint": "水を一か所にためておくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c060a24-146e-49fd-8615-760bc8dc184c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38514, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "貯留", "is_correct": true, "explanation": "雨水を一か所にためておく意味で、タンクの説明に合う。"}, {"text": "貯金", "is_correct": false, "explanation": "お金をためる意味で、雨水のタンクという文脈には合わない。"}, {"text": "点検", "is_correct": false, "explanation": "調べて確認する意味で、タンクを表す言葉としては合わない。"}, {"text": "換気", "is_correct": false, "explanation": "空気を入れ替える意味で、雨水を入れるタンクには合わない。"}], "explanations": {"貯留": "雨水を一か所にためておく意味で、タンクの説明に合う。", "貯金": "お金をためる意味で、雨水のタンクという文脈には合わない。", "点検": "調べて確認する意味で、タンクを表す言葉としては合わない。", "換気": "空気を入れ替える意味で、雨水を入れるタンクには合わない。"}, "sentence_index": 0, "correct_answer": "貯留"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎月の給料の一部を、貯留している。", "explanation": "ここは〈貯金〉の意味。貯留は水や気体などをためておくことで、お金には使わない。"}, {"text": "大切な書類は、金庫に貯留しておく。", "explanation": "ここは〈保管〉の意味。貯留は液体や気体が対象なので、書類には合わない。"}, {"text": "ダムの水門を開けて、水を下流へ貯留する。", "explanation": "ここは〈放流〉の意味。貯留は水をためておくことで、ダムから流し出すことではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38514, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "貯留", "is_correct": true, "explanation": "「貯留できる量」の形で、ためておける分量の話に合う。"}, {"text": "点滅", "is_correct": false, "explanation": "明かりがつくことや消えることを表し、量の話には合わない。"}, {"text": "反省", "is_correct": false, "explanation": "自分を振り返る意味で、水の量の話には合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "歩き回る意味で、水をためる量の話には合わない。"}], "explanations": {"貯留": "「貯留できる量」の形で、ためておける分量の話に合う。", "点滅": "明かりがつくことや消えることを表し、量の話には合わない。", "反省": "自分を振り返る意味で、水の量の話には合わない。", "散歩": "歩き回る意味で、水をためる量の話には合わない。"}, "sentence_index": 6, "correct_answer": "貯留"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "長い残業で、疲れが体に貯留した。", "explanation": "ここは〈蓄積〉の意味。貯留は容器や場所に液体などをためることで、疲労のような抽象的なものには使わない。"}, {"text": "大型トラックに荷物を貯留して運ぶ。", "explanation": "ここは〈運搬〉の意味。貯留は運ぶことではなく、ためておくことを表す。"}, {"text": "このパンは、冷暗所で貯留すると長持ちする。", "explanation": "ここは〈保存〉の意味。貯留は液体や気体をためることで、パンのような固形物には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38514, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "貯留に量を毎日確認して、水不足に備える。", "corrected_sentence": "貯留の量を毎日確認して、水不足に備える。", "error_description": "「貯留の量」の「の」が正しい。「貯留に」は後ろの「量」を修飾できず、格助詞「に」が不適切。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38514, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨水を貯留で、夏の渇水に備えた。", "corrected_sentence": "雨水を貯留して、夏の渇水に備えた。", "error_description": "「貯留して」の「して」が正しい。「貯留で」は動詞として続くべきところに格助詞「で」が来ており、文として成立しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
