INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38515, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "液体や気体などを容器や場所にためておくこと。", "primary_collocate": null, "pronunciation": "ちょりゅう", "ipa": "tɕoɾʲɯː", "syllable_count": 3, "sentences": [{"text": "工場では、石油をタンクに貯留している。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、石油[せきゆ]をタンクに貯留[ちょりゅう]している。", "sentence_source": "generated"}, {"text": "二酸化炭素を地下に貯留する技術が研究されている。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "二酸化炭素[にさんかたんそ]を地下[ちか]に貯留[ちょりゅう]する技術[ぎじゅつ]が研究[けんきゅう]されている。", "sentence_source": "generated"}, {"text": "ガスを貯留する施設は、町から離れた場所にある。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "ガスを貯留[ちょりゅう]する施設[しせつ]は、町[まち]から離[はな]れた場所[ばしょ]にある。", "sentence_source": "generated"}, {"text": "薬品の貯留には、専用の容器が必要です。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "薬品[やくひん]の貯留[ちょりゅう]には、専用[せんよう]の容器[ようき]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "貯留したガスが漏れないよう、毎日点検している。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "貯留[ちょりゅう]したガスが漏[も]れないよう、毎日[まいにち]点検[てんけん]している。", "sentence_source": "generated"}, {"text": "酒蔵では、できた酒を大きなタンクに貯留している。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "酒蔵[さかぐら]では、できた酒[さけ]を大[おお]きなタンクに貯留[ちょりゅう]している。", "sentence_source": "generated"}, {"text": "使用済みの廃液は、専用の容器に貯留してから処理する。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "使用済[しようず]みの廃液[はいえき]は、専用[せんよう]の容器[ようき]に貯留[ちょりゅう]してから処理[しょり]する。", "sentence_source": "generated"}, {"text": "燃料をどれだけ貯留しているかは、このメーターで確認できます。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "燃料[ねんりょう]をどれだけ貯留[ちょりゅう]しているかは、このメーターで確認[かくにん]できます。", "sentence_source": "generated"}, {"text": "槽に貯留された液体は、ゆっくり混ぜられている。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "槽[そう]に貯留[ちょりゅう]された液体[えきたい]は、ゆっくり混[ま]ぜられている。", "sentence_source": "generated"}, {"text": "水素を安全に貯留する方法が、新しい課題になっている。", "target_word": "貯留", "complexity_tier": "T3", "furigana": "水素[すいそ]を安全[あんぜん]に貯留[ちょりゅう]する方法[ほうほう]が、新[あたら]しい課題[かだい]になっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "貯留", "label": "基本形"}, {"form": "貯留する", "label": "動詞形"}, {"form": "貯留した", "label": "過去形"}, {"form": "貯留される", "label": "受身形"}], "register": "formal", "sense_fingerprint": "液体や気体を容器や場所にためておくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c060a24-146e-49fd-8615-760bc8dc184c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38515, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "貯留", "is_correct": true, "explanation": "液体をタンクにためておく意味で、石油をタンクに入れる文に合う。"}, {"text": "貯金", "is_correct": false, "explanation": "お金を積み立てる意味で、石油には使えない。"}, {"text": "換気", "is_correct": false, "explanation": "空気を入れ替える意味で、石油をタンクに入れる文には合わない。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける意味で、石油をタンクに入れる文には合わない。"}], "explanations": {"貯留": "液体をタンクにためておく意味で、石油をタンクに入れる文に合う。", "貯金": "お金を積み立てる意味で、石油には使えない。", "換気": "空気を入れ替える意味で、石油をタンクに入れる文には合わない。", "点火": "火をつける意味で、石油をタンクに入れる文には合わない。"}, "sentence_index": 0, "correct_answer": "貯留"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は一年分の給料を、通帳に貯留した。", "explanation": "ここは〈貯金〉の意味。貯留は液体や気体をためることで、お金には使わない。"}, {"text": "安全弁を開けて、蒸気を外へ貯留する。", "explanation": "ここは〈放出〉の意味。貯留は外へ出すことではなく、中にためておくこと。"}, {"text": "来館者の人数を、貯留して記録する。", "explanation": "ここは〈集計〉の意味。貯留は数を数えることではなく、物をためておくことを表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38515, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "貯留", "is_correct": true, "explanation": "容器にためておく意味で、使用済みの廃液を容器に入れる文に合う。"}, {"text": "放電", "is_correct": false, "explanation": "電気を逃がす意味で、廃液を容器に入れる文には合わない。"}, {"text": "点灯", "is_correct": false, "explanation": "明かりをつける意味で、廃液を容器に入れる文には合わない。"}, {"text": "鑑賞", "is_correct": false, "explanation": "作品を味わう意味で、容器という文脈には合わない。"}], "explanations": {"貯留": "容器にためておく意味で、使用済みの廃液を容器に入れる文に合う。", "放電": "電気を逃がす意味で、廃液を容器に入れる文には合わない。", "点灯": "明かりをつける意味で、廃液を容器に入れる文には合わない。", "鑑賞": "作品を味わう意味で、容器という文脈には合わない。"}, "sentence_index": 6, "correct_answer": "貯留"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来週の天気を、貯留して発表する。", "explanation": "ここは〈予報〉の意味。貯留は物をためておくことで、天気の情報には使わない。"}, {"text": "新しい案を、会議で貯留して採用した。", "explanation": "ここは〈保留〉の意味。貯留は液体や気体などをためることで、案や議題には使わない。"}, {"text": "このパンは、冷暗所で貯留すると長持ちする。", "explanation": "ここは〈保存〉の意味。貯留は液体や気体をためることで、パンのような固形物には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38515, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ガスの貯留を、来月から始まる。", "corrected_sentence": "ガスの貯留が、来月から始まる。", "error_description": "主語には「が」が必要。「始まる」は自動詞なので、「貯留を始まる」と目的語の「を」を続けることはできない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38515, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "貯留な容器は、いつも清潔に保つ。", "corrected_sentence": "貯留用の容器は、いつも清潔に保つ。", "error_description": "「貯留用の」が正しい。貯留は名詞なので、「な」で続けると形容動詞のように誤って扱うことになる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38516, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「多い」の主語を示す「が」で、水分が多い、という意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「水分を多い」は形容詞に「を」を付けた誤りで、成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「水分で多い」は手段の意味になり、主語を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「水分と多い」は共同の意味になり、主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「多い」の主語を示す「が」で、水分が多い、という意味になる。", "を": "「水分を多い」は形容詞に「を」を付けた誤りで、成り立たない。", "で": "「水分で多い」は手段の意味になり、主語を示せない。", "と": "「水分と多い」は共同の意味になり、主語を示せない。"}, "error_tags": {"を": "object", "で": "means", "と": "companion"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38516, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「出る」の主語を示す「が」で、水分が出る、という意味になる。"}, {"text": "に", "is_correct": false, "explanation": "「水分に出てきた」は成り立たず、主語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「水分へ出てきた」は方向の意味になり、主語を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「水分より出てきた」は比較の意味になり、主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「出る」の主語を示す「が」で、水分が出る、という意味になる。", "に": "「水分に出てきた」は成り立たず、主語を示せない。", "へ": "「水分へ出てきた」は方向の意味になり、主語を示せない。", "より": "「水分より出てきた」は比較の意味になり、主語を示せない。"}, "error_tags": {"に": "dative", "へ": "direction", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38516, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "体の中や食べ物の中にある、水のことです。", "primary_collocate": null, "pronunciation": "すいぶん", "ipa": "sɯibɯɴ", "syllable_count": 4, "sentences": [{"text": "熱が出たときは、水分をたくさんとって休む。", "target_word": "水分", "complexity_tier": "T3", "furigana": "熱[ねつ]が出[で]たときは、水分[すいぶん]をたくさんとって休[やす]む。", "sentence_source": "generated"}, {"text": "スイカは水分が多くて、夏にぴったりのくだものだ。", "target_word": "水分", "complexity_tier": "T3", "furigana": "スイカは水分[すいぶん]が多[おお]くて、夏[なつ]にぴったりのくだものだ。", "sentence_source": "generated"}, {"text": "赤ちゃんの体は、大人より水分の割合が高い。", "target_word": "水分", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんの体[からだ]は、大人[おとな]より水分[すいぶん]の割合[わりあい]が高[たか]い。", "sentence_source": "generated"}, {"text": "なすは塩もみして水分を出すと、味がしみ込みやすい。", "target_word": "水分", "complexity_tier": "T3", "furigana": "なすは塩もみ[しおもみ]して水分[すいぶん]を出[だ]すと、味[あじ]が染[し]み込[こ]みやすい。", "sentence_source": "generated"}, {"text": "お菓子は水分が少ないので、長くもつ。", "target_word": "水分", "complexity_tier": "T3", "furigana": "お菓子[かし]は水分[すいぶん]が少[すく]ないので、長[なが]くもつ。", "sentence_source": "generated"}, {"text": "走ったあとは、水分をとって少し休もう。", "target_word": "水分", "complexity_tier": "T3", "furigana": "走[はし]ったあとは、水分[すいぶん]をとって少[すこ]し休[やす]もう。", "sentence_source": "generated"}, {"text": "植物に水をやらないと、葉の水分がなくなって枯れる。", "target_word": "水分", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]に水[みず]をやらないと、葉[は]の水分[すいぶん]がなくなって枯[か]れる。", "sentence_source": "generated"}, {"text": "トマトを切ると、中から水分が出てきた。", "target_word": "水分", "complexity_tier": "T3", "furigana": "トマトを切[き]ると、中[なか]から水分[すいぶん]が出[で]てきた。", "sentence_source": "generated"}, {"text": "かぜをひいた弟に、水分を多めにとらせた。", "target_word": "水分", "complexity_tier": "T3", "furigana": "かぜをひいた弟[おとうと]に、水分[すいぶん]を多[おお]めにとらせた。", "sentence_source": "generated"}, {"text": "ごはんは水分が足りないと、かたく炊き上がる。", "target_word": "水分", "complexity_tier": "T3", "furigana": "ごはんは水分[すいぶん]が足[た]りないと、かたく炊[た]き上[あ]がる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水分", "label": "基本形"}], "register": "標準語（常体）", "sense_fingerprint": "体や食べ物の中にある水。飲んだり取ったりする水もいう。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T3: contains vocabulary far above tier T3: 塩もみ (Zipf 1.65), しみ込み (Zipf 1.34)']::text[], 'b78d2d53-321c-4106-8d9f-0277da1b53d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38516, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水分", "is_correct": true, "explanation": "熱のときに水分を多く取って休む、という一般的な行動に合う。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽をたくさんとるとは言わず、熱の対処にならない。"}, {"text": "寝言", "is_correct": false, "explanation": "寝言をとる行為は文として成り立たず、熱の対処にならない。"}, {"text": "熱意", "is_correct": false, "explanation": "熱意をとるとは言わず、休む行動に合わない。"}], "explanations": {"水分": "熱のときに水分を多く取って休む、という一般的な行動に合う。", "音楽": "音楽をたくさんとるとは言わず、熱の対処にならない。", "寝言": "寝言をとる行為は文として成り立たず、熱の対処にならない。", "熱意": "熱意をとるとは言わず、休む行動に合わない。"}, "sentence_index": 0, "correct_answer": "水分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の部屋は水分がじりじり暑く、寝苦しい。", "explanation": "ここは〈気温〉の意味。じりじり暑いのは気温で、水分とは言わない。"}, {"text": "梅干しは水分が強く、保存がきく。", "explanation": "ここは〈塩分〉の意味。保存がきくのは塩分で、水分では説明できない。"}, {"text": "このお香は水分が長く続く。", "explanation": "ここは〈香り〉の意味。長く続くのはお香の香りで、水分とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38516, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水分", "is_correct": true, "explanation": "水が足りず葉が枯れる、という文脈で水分の減少を表す。"}, {"text": "音", "is_correct": false, "explanation": "葉の音がなくなって枯れる、とは言わない。"}, {"text": "形", "is_correct": false, "explanation": "葉の形がなくなって枯れる、は枯れる理由にならない。"}, {"text": "名前", "is_correct": false, "explanation": "葉の名前がなくなる、は文として不自然。"}], "explanations": {"水分": "水が足りず葉が枯れる、という文脈で水分の減少を表す。", "音": "葉の音がなくなって枯れる、とは言わない。", "形": "葉の形がなくなって枯れる、は枯れる理由にならない。", "名前": "葉の名前がなくなる、は文として不自然。"}, "sentence_index": 6, "correct_answer": "水分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このケーキは水分が香ばしく、子どもに人気だ。", "explanation": "ここは〈香ばしさ〉の意味。香ばしさは焼き色や焦げの香りで、水分とは言わない。"}, {"text": "ナッツは水分が油っぽく、高カロリーだ。", "explanation": "ここは〈脂肪〉の意味。高カロリーの元は脂肪で、水分が油っぽいとは言わない。"}, {"text": "ごぼうは水分がごりごりして、歯ごたえがある。", "explanation": "ここは〈繊維〉の意味。ごりごりした歯ごたえは繊維で、水分とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38516, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の午後は、水分にたくさんとる習慣をつけたい。", "corrected_sentence": "夏の午後は、水分をたくさんとる習慣をつけたい。", "error_description": "「とる」は目的語に「を」を取るので、「水分にとる」は誤り。正しくは「水分をとる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38516, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "畑の土の水分をなくなって、野菜が育たない。", "corrected_sentence": "畑の土の水分がなくなって、野菜が育たない。", "error_description": "「なくなる」は主語に「が」を取るので、「水分をなくなって」は誤り。正しくは「水分がなくなって」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38517, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「取る」の目的語を示す「を」で、水分を取る、という意味になる。"}, {"text": "に", "is_correct": false, "explanation": "「水分に取る」は成り立たず、「取る」の目的語を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「水分で取る」は手段の意味になり、目的語を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「取る」は主語に「が」を取らず、「水分が取る」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「取る」の目的語を示す「を」で、水分を取る、という意味になる。", "に": "「水分に取る」は成り立たず、「取る」の目的語を示せない。", "で": "「水分で取る」は手段の意味になり、目的語を示せない。", "が": "「取る」は主語に「が」を取らず、「水分が取る」は不自然。"}, "error_tags": {"に": "dative", "で": "means", "が": "subject"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
