INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38517, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物の中に含まれている水。特に、生物の体内や食品などに存在する水のことを指す。", "primary_collocate": null, "pronunciation": "すいぶん", "ipa": "sɯibɯɴ", "syllable_count": 4, "sentences": [{"text": "この際、脂質の膜がジャムの水分浸透を防ぐバリアーとして機能するという科学的裏付けも無視できない。", "target_word": "水分", "complexity_tier": "T3", "furigana": "この際[さい]、脂質[ししつ]の膜[まく]がジャムの水分[すいぶん]浸透[しんとう]を防[ふせ]ぐバリアーとして機能[きのう]するという科学的[かがくてき]裏付[うらづ]けも無視[むし]できない。", "sentence_source": "mined"}, {"text": "運動のあとは、こまめに水分を取ったほうがいい。", "target_word": "水分", "complexity_tier": "T3", "furigana": "運動[うんどう]のあとは、こまめに水分[すいぶん]を取[と]ったほうがいい。", "sentence_source": "generated"}, {"text": "この野菜は水分が多いので、炒めると水が出る。", "target_word": "水分", "complexity_tier": "T3", "furigana": "この野菜[やさい]は水分[すいぶん]が多[おお]いので、炒[いた]めると水[みず]が出[で]る。", "sentence_source": "generated"}, {"text": "洗濯物から水分が抜けて、午後にはすっかり乾いた。", "target_word": "水分", "complexity_tier": "T3", "furigana": "洗濯物[せんたくもの]から水分[すいぶん]が抜[ぬ]けて、午後[ごご]にはすっかり乾[かわ]いた。", "sentence_source": "generated"}, {"text": "パンは水分が飛ぶと、かたくなってしまう。", "target_word": "水分", "complexity_tier": "T3", "furigana": "パンは水分[すいぶん]が飛[と]ぶと、かたくなってしまう。", "sentence_source": "generated"}, {"text": "スポンジの水分をしっかり絞ってから、台所をふいた。", "target_word": "水分", "complexity_tier": "T3", "furigana": "スポンジの水分[すいぶん]をしっかり絞[しぼ]ってから、台所[だいどころ]をふいた。", "sentence_source": "generated"}, {"text": "夏は汗で水分が失われるため、熱中症に注意が必要だ。", "target_word": "水分", "complexity_tier": "T3", "furigana": "夏[なつ]は汗[あせ]で水分[すいぶん]が失[うしな]われるため、熱中症[ねっちゅうしょう]に注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "この土は水分を保つ力が強く、花が育ちやすい。", "target_word": "水分", "complexity_tier": "T3", "furigana": "この土[つち]は水分[すいぶん]を保[たも]つ力[ちから]が強[つよ]く、花[はな]が育[そだ]ちやすい。", "sentence_source": "generated"}, {"text": "米を炊くときは、水分の量で食感が変わる。", "target_word": "水分", "complexity_tier": "T3", "furigana": "米[こめ]を炊[た]くときは、水分[すいぶん]の量[りょう]で食感[しょっかん]が変[か]わる。", "sentence_source": "generated"}, {"text": "干し柿は水分が減り、甘味が強くなる。", "target_word": "水分", "complexity_tier": "T3", "furigana": "干[ほ]し柿[がき]は水分[すいぶん]が減[へ]り、甘味[あまみ]が強[つよ]くなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水分", "label": "基本形"}], "register": "標準語（常体）", "sense_fingerprint": "物や生物の体、食品などの中に含まれている水。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b78d2d53-321c-4106-8d9f-0277da1b53d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38517, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水分", "is_correct": true, "explanation": "ジャムの水分が浸透するのを脂質の膜が防ぐ、という文脈に合う。"}, {"text": "音波", "is_correct": false, "explanation": "音波はジャムの浸透の対象にならず、文が成り立たない。"}, {"text": "硬度", "is_correct": false, "explanation": "ジャムの硬度が浸透するとは言えず、膜の働きの説明に合わない。"}, {"text": "色彩", "is_correct": false, "explanation": "色彩は浸透の対象にならず、文が成り立たない。"}], "explanations": {"水分": "ジャムの水分が浸透するのを脂質の膜が防ぐ、という文脈に合う。", "音波": "音波はジャムの浸透の対象にならず、文が成り立たない。", "硬度": "ジャムの硬度が浸透するとは言えず、膜の働きの説明に合わない。", "色彩": "色彩は浸透の対象にならず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "水分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "梅雨は水分が高く、部屋が蒸し暑い。", "explanation": "ここは〈湿度〉の意味。空気の湿りの度合いは湿度で、水分が高いとは言わない。"}, {"text": "悲しい映画で、水分が頬をつたい、止まらなかった。", "explanation": "ここは〈涙〉の意味。頬をつたうのは涙で、水分とは言わない。"}, {"text": "傷口から水分がどくどく流れ、包帯が真っ赤になった。", "explanation": "ここは〈血〉の意味。どくどく流れて真っ赤にするのは血で、水分とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38517, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水分", "is_correct": true, "explanation": "汗で体の水が失われ、熱中症に注意が必要だという文脈に合う。"}, {"text": "色", "is_correct": false, "explanation": "汗で色が失われるとは言わず、熱中症の話に合わない。"}, {"text": "硬さ", "is_correct": false, "explanation": "汗で硬さが失われる、は熱中症と結びつかない。"}, {"text": "音量", "is_correct": false, "explanation": "汗で音量が失われる、は意味が通らない。"}], "explanations": {"水分": "汗で体の水が失われ、熱中症に注意が必要だという文脈に合う。", "色": "汗で色が失われるとは言わず、熱中症の話に合わない。", "硬さ": "汗で硬さが失われる、は熱中症と結びつかない。", "音量": "汗で音量が失われる、は意味が通らない。"}, "sentence_index": 6, "correct_answer": "水分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "干し柿は水分が濃く、甘さが増す。", "explanation": "ここは〈糖分〉の意味。甘さが濃くなるのは糖分で、水分が濃くなるとは言わない。"}, {"text": "梅干しは水分が塩辛く、保存がきく。", "explanation": "ここは〈塩分〉の意味。塩辛いのは塩分で、水分とは言わない。"}, {"text": "ベーコンは水分がこってりして、香ばしい。", "explanation": "ここは〈脂〉の意味。こってりするのは脂で、水分とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38517, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寝る前は、こまめに水分が取る習慣をつけたい。", "corrected_sentence": "寝る前は、こまめに水分を取る習慣をつけたい。", "error_description": "「取る」は目的語に「を」を取るので、「水分が取る」は誤り。正しくは「水分を取る」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38517, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "焼いたパンは水分を飛ぶと、かたくなる。", "corrected_sentence": "焼いたパンは水分が飛ぶと、かたくなる。", "error_description": "「飛ぶ」は主語に「が」を取るので、「水分を飛ぶ」は誤り。正しくは「水分が飛ぶ」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38518, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「一週間に三回」で、一週間あたりの回数を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表すため、「一週間を三回」では回数との関係が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すため、「一週間へ三回」は意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "主語を表すため、「一週間が三回、泳ぎます」は主語が合わず不自然。"}], "correct_answer": "に", "explanations": {"に": "「一週間に三回」で、一週間あたりの回数を示す。", "を": "目的語を表すため、「一週間を三回」では回数との関係が成り立たない。", "へ": "方向を表すため、「一週間へ三回」は意味が通らない。", "が": "主語を表すため、「一週間が三回、泳ぎます」は主語が合わず不自然。"}, "error_tags": {"を": "目的語", "へ": "方向", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38518, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38518, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一週間の長さのこと。", "primary_collocate": null, "pronunciation": "しゅうかん", "ipa": "ɕɯːkaɴ", "syllable_count": 4, "sentences": [{"text": "一週間は七日間です。", "target_word": "週間", "complexity_tier": "T2", "furigana": "一週間(いっしゅうかん)は七日間(なのかかん)です。", "sentence_source": "generated"}, {"text": "私は一週間に三回、プールで泳ぎます。", "target_word": "週間", "complexity_tier": "T2", "furigana": "私(わたし)は一週間(いっしゅうかん)に三回(さんかい)、プールで泳(およ)ぎます。", "sentence_source": "generated"}, {"text": "夏休みは四十二日あるので、ちょうど六週間です。", "target_word": "週間", "complexity_tier": "T3", "furigana": "夏休(なつやす)みは四十二日(しじゅうににち)あるので、ちょうど六週間(ろくしゅうかん)です。", "sentence_source": "generated"}, {"text": "出張は一週間続きましたが、とても充実していました。", "target_word": "週間", "complexity_tier": "T3", "furigana": "出張(しゅっちょう)は一週間(いっしゅうかん)続(つづ)きましたが、とても充実(じゅうじつ)していました。", "sentence_source": "generated"}, {"text": "先生は、宿題を一週間以内に出すように言いました。", "target_word": "週間", "complexity_tier": "T3", "furigana": "先生(せんせい)は、宿題(しゅくだい)を一週間(いっしゅうかん)以内(いない)に出(だ)すように言(い)いました。", "sentence_source": "generated"}, {"text": "一週間ぶりに、友達に会いました。", "target_word": "週間", "complexity_tier": "T2", "furigana": "一週間(いっしゅうかん)ぶりに、友達(ともだち)に会(あ)いました。", "sentence_source": "generated"}, {"text": "この薬は、一週間分をまとめて出してもらえます。", "target_word": "週間", "complexity_tier": "T3", "furigana": "この薬(くすり)は、一週間分(いっしゅうかんぶん)をまとめて出(だ)してもらえます。", "sentence_source": "generated"}, {"text": "雨が一週間も降り続いて、洗濯物が乾きません。", "target_word": "週間", "complexity_tier": "T3", "furigana": "雨(あめ)が一週間(いっしゅうかん)も降(ふ)り続(つづ)いて、洗濯物(せんたくもの)が乾(かわ)きません。", "sentence_source": "generated"}, {"text": "祭りは一週間続き、町はずっとにぎやかです。", "target_word": "週間", "complexity_tier": "T3", "furigana": "祭(まつ)りは一週間(いっしゅうかん)続(つづ)き、町(まち)はずっとにぎやかです。", "sentence_source": "generated"}, {"text": "赤ちゃんが生まれて二週間がたち、ようやく生活に慣れました。", "target_word": "週間", "complexity_tier": "T4", "furigana": "赤(あか)ちゃんが生(う)まれて二週間(にしゅうかん)がたち、ようやく生活(せいかつ)に慣(な)れました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "週間", "label": "基本形"}], "register": "中立（です・ます体）", "sense_fingerprint": "七日間という時間の長さ（数字の後ろにつけて数える）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: contains vocabulary far above tier T1: 降り続い (Zipf 2.24)']::text[], 'cc0a982a-50ff-4c39-bd65-8c88b1cfa552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38518, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "週間", "is_correct": true, "explanation": "七日間という期間の単位で、「一週間は七日間です」の定義と一致する。"}, {"text": "時間", "is_correct": false, "explanation": "「一時間は七日間です」は時間の単位が合わず、文が成り立たない。"}, {"text": "年間", "is_correct": false, "explanation": "「一年間は七日間です」は長さが合わないので、文の内容と矛盾する。"}, {"text": "日間", "is_correct": false, "explanation": "「一日間は七日間です」は日数が合わないので、文の内容と矛盾する。"}], "explanations": {"週間": "七日間という期間の単位で、「一週間は七日間です」の定義と一致する。", "時間": "「一時間は七日間です」は時間の単位が合わず、文が成り立たない。", "年間": "「一年間は七日間です」は長さが合わないので、文の内容と矛盾する。", "日間": "「一日間は七日間です」は日数が合わないので、文の内容と矛盾する。"}, "sentence_index": 0, "correct_answer": "週間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この会社の週間は、毎年四月に始まります。", "explanation": "ここは〈年度〉の意味。週間は一週間の長さを表す語で、毎年四月に始まる会計の期間とは合わない。"}, {"text": "週間は、家でゆっくり休みます。", "explanation": "ここは〈週末〉の意味。週間は一週間という長さを表す語で、特定の休日を指す「週末」の代わりにはならない。"}, {"text": "この旅行の週間は、十日です。", "explanation": "ここは〈日数〉の意味。週間は一週間という長さを表す語で、十日と日数を数える使い方とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38518, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "週間", "is_correct": true, "explanation": "「一週間分」は一週間の量を表す標準的な言い方で、文の内容と一致する。"}, {"text": "時間", "is_correct": false, "explanation": "「一時間分」は薬の量として成り立たず、文の内容に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「一季節分」は薬の期間として使わない。文の内容に合わない。"}, {"text": "分野", "is_correct": false, "explanation": "期間を表す語ではないので、薬の量を示す「一〜分」に合わない。"}], "explanations": {"週間": "「一週間分」は一週間の量を表す標準的な言い方で、文の内容と一致する。", "時間": "「一時間分」は薬の量として成り立たず、文の内容に合わない。", "季節": "「一季節分」は薬の期間として使わない。文の内容に合わない。", "分野": "期間を表す語ではないので、薬の量を示す「一〜分」に合わない。"}, "sentence_index": 6, "correct_answer": "週間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この虫の週間は、わずか数日です。", "explanation": "ここは〈寿命〉の意味。週間は長さの単位で、生き物が生きている期間の総称にはならない。"}, {"text": "週間を聞かれて、三十歳と答えました。", "explanation": "ここは〈年齢〉の意味。週間は期間の長さを表す語で、人の年を表す語ではない。"}, {"text": "集合の週間は、午前九時です。", "explanation": "ここは〈時刻〉の意味。週間は一週間の長さを表す語で、ある時点の時刻を表すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38518, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この計画は、一週間に完成します。", "corrected_sentence": "この計画は、一週間で完成します。", "error_description": "期間の長さで完成までの時間を表すには「で」を使う。「に」にすると「一週間に完成」となり不自然。正しくは「一週間で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38518, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "展示会は一週間続かました。", "corrected_sentence": "展示会は一週間続きました。", "error_description": "「続く」の連用形は「続き」。未然形「続か」に「ました」を付けるのは誤り。正しくは「続きました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38519, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「二週間の予定」の修飾を表し、予定の長さを示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表すため、「二週間を予定」では成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "時点や相手を示すため、「二週間に予定」と修飾関係を作れない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すため、「二週間で予定」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「二週間の予定」の修飾を表し、予定の長さを示す。", "を": "目的語を表すため、「二週間を予定」では成り立たない。", "に": "時点や相手を示すため、「二週間に予定」と修飾関係を作れない。", "で": "手段や場所を表すため、「二週間で予定」は意味が通らない。"}, "error_tags": {"を": "目的語", "に": "時点・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38519, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「五週間の入院」の修飾を表し、入院の期間を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を表すが、「五週間が入院」では期間と入院の関係が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すため、「五週間へ入院」とは言えない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すが、「五週間から入院」では期間を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「五週間の入院」の修飾を表し、入院の期間を示す。", "が": "主語を表すが、「五週間が入院」では期間と入院の関係が成り立たない。", "へ": "方向を表すため、「五週間へ入院」とは言えない。", "から": "起点を表すが、「五週間から入院」では期間を修飾できない。"}, "error_tags": {"が": "主語", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38519, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一週間の期間。", "primary_collocate": null, "pronunciation": "しゅうかん", "ipa": "ɕɯːkaɴ", "syllable_count": 4, "sentences": [{"text": "彼らは驚くべきスピードで成長し、わずか数週間で出荷可能な体重になります。", "target_word": "週間", "complexity_tier": "T3", "furigana": "彼(かれ)らは驚(おどろ)くべきスピードで成長(せいちょう)し、わずか数週間(すうしゅうかん)で出荷(しゅっか)可能(かのう)な体重(たいじゅう)になります。", "sentence_source": "mined"}, {"text": "旅行は二週間の予定でしたが、天気が悪くて少し短くなりました。", "target_word": "週間", "complexity_tier": "T3", "furigana": "旅行(りょこう)は二週間(にしゅうかん)の予定(よてい)でしたが、天気(てんき)が悪(わる)くて少(すこ)し短(みじか)くなりました。", "sentence_source": "generated"}, {"text": "風邪が治るまでに、三週間もかかりました。", "target_word": "週間", "complexity_tier": "T3", "furigana": "風邪(かぜ)が治(なお)るまでに、三週間(さんしゅうかん)もかかりました。", "sentence_source": "generated"}, {"text": "この本は、貸し出し期間が二週間です。", "target_word": "週間", "complexity_tier": "T3", "furigana": "この本(ほん)は、貸(か)し出(だ)し期間(きかん)が二週間(にしゅうかん)です。", "sentence_source": "generated"}, {"text": "四週間の講座が、来月から始まります。", "target_word": "週間", "complexity_tier": "T3", "furigana": "四週間(よんしゅうかん)の講座(こうざ)が、来月(らいげつ)から始(はじ)まります。", "sentence_source": "generated"}, {"text": "夏休みが始まって、もう三週間たちました。", "target_word": "週間", "complexity_tier": "T3", "furigana": "夏休(なつやす)みが始(はじ)まって、もう三週間(さんしゅうかん)たちました。", "sentence_source": "generated"}, {"text": "荷物は注文してから、一週間ほどで届きます。", "target_word": "週間", "complexity_tier": "T3", "furigana": "荷物(にもつ)は注文(ちゅうもん)してから、一週間(いっしゅうかん)ほどで届(とど)きます。", "sentence_source": "generated"}, {"text": "彼は五週間の入院のあと、ようやく家に帰れました。", "target_word": "週間", "complexity_tier": "T4", "furigana": "彼(かれ)は五週間(ごしゅうかん)の入院(にゅういん)のあと、ようやく家(いえ)に帰(かえ)れました。", "sentence_source": "generated"}, {"text": "試験まであと二週間しかないので、毎日勉強しています。", "target_word": "週間", "complexity_tier": "T3", "furigana": "試験(しけん)まであと二週間(にしゅうかん)しかないので、毎日(まいにち)勉強(べんきょう)しています。", "sentence_source": "generated"}, {"text": "数週間前に植えた花が、やっと咲きました。", "target_word": "週間", "complexity_tier": "T3", "furigana": "数週間(すうしゅうかん)前(まえ)に植(う)えた花(はな)が、やっと咲(さ)きました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "週間", "label": "基本形"}], "register": "中立（です・ます体）", "sense_fingerprint": "七日間を単位とする期間（数字の後ろにつけて数える）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc0a982a-50ff-4c39-bd65-8c88b1cfa552') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38519, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "週間", "is_correct": true, "explanation": "わずか数週間で出荷できるまで成長するという期間の意味に合う。"}, {"text": "時間", "is_correct": false, "explanation": "数時間では鶏が出荷できるまで成長しないので、文の内容として不自然。"}, {"text": "年間", "is_correct": false, "explanation": "数年間では「わずか」と言える出荷までの期間ではなく、文脈に合わない。"}, {"text": "分野", "is_correct": false, "explanation": "期間を表す語ではないため、「数〜で」の時間の長さとして成り立たない。"}], "explanations": {"週間": "わずか数週間で出荷できるまで成長するという期間の意味に合う。", "時間": "数時間では鶏が出荷できるまで成長しないので、文の内容として不自然。", "年間": "数年間では「わずか」と言える出荷までの期間ではなく、文脈に合わない。", "分野": "期間を表す語ではないため、「数〜で」の時間の長さとして成り立たない。"}, "sentence_index": 0, "correct_answer": "週間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "待ち合わせの週間は、午後三時です。", "explanation": "ここは〈時刻〉の意味。週間は一週間の長さを表す語で、ある時点の時刻を指すことはできないので合わない。"}, {"text": "週間は、家族と映画を見に行く予定です。", "explanation": "ここは〈週末〉の意味。週間は一週間という長さを表す語で、特定の休日を指す「週末」の代わりにはならない。"}, {"text": "彼は週間を田舎で過ごしました。", "explanation": "数字がないと「週間」は期間を表せず、〈一生〉の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38519, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "週間", "is_correct": true, "explanation": "一週間ほどで届くという期間の意味に合う。「一〜ほど」の形で自然に成り立つ。"}, {"text": "時刻", "is_correct": false, "explanation": "時刻は一点の時間で「一時刻ほど」とは言えず、届くまでの期間に合わない。"}, {"text": "時代", "is_correct": false, "explanation": "時代は長い区切りの期間で、注文から届くまでの時間には合わない。"}, {"text": "季節", "is_correct": false, "explanation": "一季節ほどで届くという時間の感覚は、注文から届くまでの文脈に合わない。"}], "explanations": {"週間": "一週間ほどで届くという期間の意味に合う。「一〜ほど」の形で自然に成り立つ。", "時刻": "時刻は一点の時間で「一時刻ほど」とは言えず、届くまでの期間に合わない。", "時代": "時代は長い区切りの期間で、注文から届くまでの時間には合わない。", "季節": "一季節ほどで届くという時間の感覚は、注文から届くまでの文脈に合わない。"}, "sentence_index": 6, "correct_answer": "週間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "手紙の週間は、右上に書きます。", "explanation": "ここは〈日付〉の意味。週間は期間の長さを表すので、手紙の右上に書く日の表記には合わない。"}, {"text": "ここから駅までの週間は、二キロです。", "explanation": "ここは〈距離〉の意味。週間は時間の長さを表す語で、道のりを示す距離の代わりにはならない。"}, {"text": "注文の週間は、一箱から十箱までです。", "explanation": "ここは〈数量〉の意味。週間は時間の長さを表す語で、品物の個数の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38519, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい講座は、二週間を終わります。", "corrected_sentence": "新しい講座は、二週間で終わります。", "error_description": "期間の長さで終わる時間を表すには「で」を使う。「を」にすると「終わる」の目的語になり、「二週間を終わります」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38519, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祭りは一週間続かました。", "corrected_sentence": "祭りは一週間続きました。", "error_description": "「続く」の連用形は「続き」。未然形「続か」に「ました」を付けるのは誤り。正しくは「続きました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cdb77ee-5326-404e-a91e-0d767cc9c290') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38520, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38520, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「湿度の保持が難しい」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「保持を難しい」は成り立たず、「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「保持に難しい」は不自然で、「に」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「保持と難しい」は意味が通らず、「と」は合わない。"}], "correct_answer": "が", "explanations": {"が": "「湿度の保持が難しい」の主語を示す「が」。", "を": "「保持を難しい」は成り立たず、「を」は合わない。", "に": "「保持に難しい」は不自然で、「に」は合わない。", "と": "「保持と難しい」は意味が通らず、「と」は合わない。"}, "error_tags": {"を": "目的語の誤用", "に": "対象の誤用", "と": "並列の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38520, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かをそのままの状態で続けること。", "primary_collocate": null, "pronunciation": "ほじ", "ipa": "hoʑi", "syllable_count": 2, "sentences": [{"text": "魔法瓶は中の温度を長時間保持するので、冬でもお茶が冷めません。", "target_word": "保持", "complexity_tier": "T3", "furigana": "魔法瓶[まほうびん]は中[なか]の温度[おんど]を長時間[ちょうじかん]保持[ほじ]するので、冬[ふゆ]でもお茶[ちゃ]が冷[さ]めません。", "sentence_source": "generated"}, {"text": "現状の保持だけを目指していては、会社は新しい客をつかめない。", "target_word": "保持", "complexity_tier": "T3", "furigana": "現状[げんじょう]の保持[ほじ]だけを目指[めざ]していては、会社[かいしゃ]は新[あたら]しい客[きゃく]をつかめない。", "sentence_source": "generated"}, {"text": "肌の水分を保持する力が弱いと、冬は乾燥しやすくなります。", "target_word": "保持", "complexity_tier": "T3", "furigana": "肌[はだ]の水分[すいぶん]を保持[ほじ]する力[ちから]が弱[よわ]いと、冬[ふゆ]は乾燥[かんそう]しやすくなります。", "sentence_source": "generated"}, {"text": "体温を保持するために、雪山では厚い服を重ねて着る。", "target_word": "保持", "complexity_tier": "T3", "furigana": "体温[たいおん]を保持[ほじ]するために、雪山[ゆきやま]では厚[あつ]い服[ふく]を重[かさ]ねて着[き]る。", "sentence_source": "generated"}, {"text": "彼は入院中も、体力の保持を目標に毎日歩いていた。", "target_word": "保持", "complexity_tier": "T3", "furigana": "彼[かれ]は入院中[にゅういんちゅう]も、体力[たいりょく]の保持[ほじ]を目標[もくひょう]に毎日[まいにち]歩[ある]いていた。", "sentence_source": "generated"}, {"text": "この容器は食べ物の鮮度を保持できるので、お弁当に便利です。", "target_word": "保持", "complexity_tier": "T3", "furigana": "この容器[ようき]は食[た]べ物[もの]の鮮度[せんど]を保持[ほじ]できるので、お弁当[べんとう]に便利[べんり]です。", "sentence_source": "generated"}, {"text": "選手たちは今のリードを保持したまま、最終回を迎えた。", "target_word": "保持", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちは今[いま]のリードを保持[ほじ]したまま、最終回[さいしゅうかい]を迎[むか]えた。", "sentence_source": "generated"}, {"text": "湿度の保持が難しい部屋では、カビが生えやすくなる。", "target_word": "保持", "complexity_tier": "T3", "furigana": "湿度[しつど]の保持[ほじ]が難[むずか]しい部屋[へや]では、カビが生[は]えやすくなる。", "sentence_source": "generated"}, {"text": "古い建物の形を保持しながら、中だけを新しく作り直した。", "target_word": "保持", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]の形[かたち]を保持[ほじ]しながら、中[なか]だけを新[あたら]しく作[つく]り直[なお]した。", "sentence_source": "generated"}, {"text": "姿勢を保持する筋肉が弱ると、長く座っているだけで疲れる。", "target_word": "保持", "complexity_tier": "T3", "furigana": "姿勢[しせい]を保持[ほじ]する筋肉[きんにく]が弱[よわ]ると、長[なが]く座[すわ]っているだけで疲[つか]れる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "保持する", "label": "dictionary form"}, {"form": "保持した", "label": "past"}, {"form": "保持して", "label": "te-form"}, {"form": "保持される", "label": "passive"}], "register": "neutral", "sense_fingerprint": "温度・水分・姿勢・現状などの状態を変えずに保ち続けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8087f10f-9764-4266-bbce-4f535d18a169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38520, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保持", "is_correct": true, "explanation": "温度を変えずに保つ意味で、「長時間保持するので冷めない」と合う。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は温度を保つ行為ではなく、「散歩するので冷めない」は意味が通らない。"}, {"text": "作成", "is_correct": false, "explanation": "作成は温度を保つことと無関係で、文脈に合わない。"}, {"text": "放送", "is_correct": false, "explanation": "放送は保温とは関係せず、「放送するので冷めない」は成り立たない。"}], "explanations": {"保持": "温度を変えずに保つ意味で、「長時間保持するので冷めない」と合う。", "散歩": "散歩は温度を保つ行為ではなく、「散歩するので冷めない」は意味が通らない。", "作成": "作成は温度を保つことと無関係で、文脈に合わない。", "放送": "放送は保温とは関係せず、「放送するので冷めない」は成り立たない。"}, "sentence_index": 0, "correct_answer": "保持"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工事で渋滞を保持して、道路はすっかり空いた。", "explanation": "ここは〈解消〉の意味。保持は状態を変えずに続けることで、渋滞を取り除く意味には合わない。"}, {"text": "判定は来週まで保持にした。", "explanation": "ここは〈保留〉の意味。保持は今の状態をそのまま続けることで、判断を先送りにする意味には合わない。"}, {"text": "電気を保持するので、こまめに消す。", "explanation": "ここは〈消費〉の意味。保持は変えずに保つことで、電気を使い減らす意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38520, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保持", "is_correct": true, "explanation": "リードを変えずに保ったまま最終回を迎える流れに合う。"}, {"text": "修理", "is_correct": false, "explanation": "リードは修理するものではなく、「リードを修理したまま」は意味が通らない。"}, {"text": "卒業", "is_correct": false, "explanation": "リードは卒業する対象ではなく、「リードを卒業した」は成り立たない。"}, {"text": "転校", "is_correct": false, "explanation": "リードは転校するものではなく、「リードを転校した」は文として不自然。"}], "explanations": {"保持": "リードを変えずに保ったまま最終回を迎える流れに合う。", "修理": "リードは修理するものではなく、「リードを修理したまま」は意味が通らない。", "卒業": "リードは卒業する対象ではなく、「リードを卒業した」は成り立たない。", "転校": "リードは転校するものではなく、「リードを転校した」は文として不自然。"}, "sentence_index": 6, "correct_answer": "保持"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客の数の保持に対応するため、レジを増やした。", "explanation": "ここは〈増加〉の意味。保持は変えずに続けることで、数が増える状況には合わない。"}, {"text": "熱の保持で部屋がだんだん冷えた。", "explanation": "ここは〈発散〉の意味。熱を保つと冷えないので、熱が逃げて冷える状況には合わない。"}, {"text": "大事な書類を保持して、慌てて探した。", "explanation": "ここは〈紛失〉の意味。手元に持ち続けるという意味は、なくして探す状況には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38520, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "室温を保持さため、窓を閉めておく。", "corrected_sentence": "室温を保持するため、窓を閉めておく。", "error_description": "「保持する」の活用の誤り。「保持さため」は「さ」が余分で、正しくは「保持するため」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
