INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38521, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「販売権を保持する」の目的語を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「販売権に保持している」は不自然で、「に」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "「販売権で保持している」は成り立たず、「で」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「販売権と保持している」は意味が通らず、「と」は合わない。"}], "correct_answer": "を", "explanations": {"を": "「販売権を保持する」の目的語を示す「を」。", "に": "「販売権に保持している」は不自然で、「に」は合わない。", "で": "「販売権で保持している」は成り立たず、「で」は合わない。", "と": "「販売権と保持している」は意味が通らず、「と」は合わない。"}, "error_tags": {"に": "対象の誤用", "で": "手段の誤用", "と": "並列の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
