INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38521, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "権利・記録・資格などを手放さず、そのまま持ち続けること。", "primary_collocate": null, "pronunciation": "ほじ", "ipa": "hoʑi", "syllable_count": 2, "sentences": [{"text": "彼は百メートル走の世界記録を保持している。", "target_word": "保持", "complexity_tier": "T3", "furigana": "彼[かれ]は百[ひゃく]メートル走[そう]の世界記録[せかいきろく]を保持[ほじ]している。", "sentence_source": "generated"}, {"text": "この会社は海外での販売権を保持しているため、他社は同じ商品を売れない。", "target_word": "保持", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は海外[かいがい]での販売権[はんばいけん]を保持[ほじ]しているため、他社[たしゃ]は同[おな]じ商品[しょうひん]を売[う]れない。", "sentence_source": "generated"}, {"text": "運転免許を保持する人だけが、この車を借りられます。", "target_word": "保持", "complexity_tier": "T3", "furigana": "運転免許[うんてんめんきょ]を保持[ほじ]する人[ひと]だけが、この車[くるま]を借[か]りられます。", "sentence_source": "generated"}, {"text": "資料は五年間保持するという決まりなので、古い書類も捨てられない。", "target_word": "保持", "complexity_tier": "T3", "furigana": "資料[しりょう]は五年間[ごねんかん]保持[ほじ]するという決[き]まりなので、古[ふる]い書類[しょるい]も捨[す]てられない。", "sentence_source": "generated"}, {"text": "祖父は昔の土地を今も保持しており、毎年税金を払っている。", "target_word": "保持", "complexity_tier": "T3", "furigana": "祖父[そふ]は昔[むかし]の土地[とち]を今[いま]も保持[ほじ]しており、毎年[まいとし]税金[ぜいきん]を払[はら]っている。", "sentence_source": "generated"}, {"text": "その店は特許を保持しているので、同じ作り方は他の店にできない。", "target_word": "保持", "complexity_tier": "T3", "furigana": "その店[みせ]は特許[とっきょ]を保持[ほじ]しているので、同[おな]じ作[つく]り方[かた]は他[ほか]の店[みせ]にできない。", "sentence_source": "generated"}, {"text": "去年の優勝者が、今年もタイトルを保持した。", "target_word": "保持", "complexity_tier": "T3", "furigana": "去年[きょねん]の優勝者[ゆうしょうしゃ]が、今年[ことし]もタイトルを保持[ほじ]した。", "sentence_source": "generated"}, {"text": "大事な鍵は、責任者だけが保持することになっている。", "target_word": "保持", "complexity_tier": "T3", "furigana": "大事[だいじ]な鍵[かぎ]は、責任者[せきにんしゃ]だけが保持[ほじ]することになっている。", "sentence_source": "generated"}, {"text": "株を長く保持すれば、配当を毎年受け取れます。", "target_word": "保持", "complexity_tier": "T3", "furigana": "株[かぶ]を長[なが]く保持[ほじ]すれば、配当[はいとう]を毎年[まいとし]受[う]け取[と]れます。", "sentence_source": "generated"}, {"text": "会員の資格を保持するには、年に一度の更新が必要です。", "target_word": "保持", "complexity_tier": "T3", "furigana": "会員[かいいん]の資格[しかく]を保持[ほじ]するには、年[とし]に一度[いちど]の更新[こうしん]が必要[ひつよう]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "保持する", "label": "dictionary form"}, {"form": "保持した", "label": "past"}, {"form": "保持している", "label": "progressive"}, {"form": "保持される", "label": "passive"}], "register": "formal", "sense_fingerprint": "記録・権利・資格・地位などを手放さずに持ち続けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8087f10f-9764-4266-bbce-4f535d18a169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38521, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保持", "is_correct": true, "explanation": "世界記録を手放さず持ち続けている意味で、「保持している」と合う。"}, {"text": "修理", "is_correct": false, "explanation": "記録は修理する対象ではなく、「世界記録を修理している」は意味が通らない。"}, {"text": "放送", "is_correct": false, "explanation": "記録は放送するものではなく、「世界記録を放送している」は文脈に合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "記録は散歩するものではなく、「世界記録を散歩している」は成り立たない。"}], "explanations": {"保持": "世界記録を手放さず持ち続けている意味で、「保持している」と合う。", "修理": "記録は修理する対象ではなく、「世界記録を修理している」は意味が通らない。", "放送": "記録は放送するものではなく、「世界記録を放送している」は文脈に合わない。", "散歩": "記録は散歩するものではなく、「世界記録を散歩している」は成り立たない。"}, "sentence_index": 0, "correct_answer": "保持"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この会社は海外での販売権を保持したので、他社は同じ商品を売れる。", "explanation": "ここは〈放棄〉の意味。保持は手放さず持ち続けることで、権利を手放す文脈には合わない。"}, {"text": "祖父は昔の土地を息子に譲渡して、今も保持している。", "explanation": "ここは〈譲渡〉の意味。譲り渡した物を保持するとは言わず、譲渡の文脈には合わない。"}, {"text": "更新は来月まで保持した。", "explanation": "ここは〈延期〉の意味。保持は今の状態を変えずに続けることで、日程を先に送る意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38521, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保持", "is_correct": true, "explanation": "タイトルを今年も持ち続けたという意味で、「保持した」と合う。"}, {"text": "卒業", "is_correct": false, "explanation": "タイトルは卒業する対象ではなく、「タイトルを卒業した」は成り立たない。"}, {"text": "転校", "is_correct": false, "explanation": "タイトルは転校するものではなく、「タイトルを転校した」は文として不自然。"}, {"text": "寝坊", "is_correct": false, "explanation": "寝坊はタイトルと無関係で、「タイトルを寝坊した」は意味が通らない。"}], "explanations": {"保持": "タイトルを今年も持ち続けたという意味で、「保持した」と合う。", "卒業": "タイトルは卒業する対象ではなく、「タイトルを卒業した」は成り立たない。", "転校": "タイトルは転校するものではなく、「タイトルを転校した」は文として不自然。", "寝坊": "寝坊はタイトルと無関係で、「タイトルを寝坊した」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "保持"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の資料を全員に保持した。", "explanation": "ここは〈配布〉の意味。保持は自分の手元に持ち続けることで、人々に配って渡す意味には合わない。"}, {"text": "彼は先月、初めてその資格を保持した。", "explanation": "ここは〈取得〉の意味。保持は既に持っているものを持ち続けることで、初めて得る場面には合わない。"}, {"text": "その特許は保持したまま、他社に売却した。", "explanation": "ここは〈売却〉の意味。保持は手元に持ち続けることで、手放して売る意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38521, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この団体は国の認定に保持しているので、補助金を受けられる。", "corrected_sentence": "この団体は国の認定を保持しているので、補助金を受けられる。", "error_description": "「保持する」は他動詞なので目的語を「を」で示す。「に」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38521, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "資格を保持さない人は、更新できない。", "corrected_sentence": "資格を保持しない人は、更新できない。", "error_description": "サ変動詞「保持する」の否定形は「保持しない」。「保持さない」は活用の誤りで、正しくは「保持しない」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
