INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38522, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "たくさんのものを、人にわけあたえること。", "primary_collocate": null, "pronunciation": "ぶんぱい", "ipa": "bɯmpai", "syllable_count": 4, "sentences": [{"text": "先生は遠足のお菓子を、クラスの全員に公平に分配した。", "target_word": "分配", "complexity_tier": "T3", "furigana": "先生[せんせい]は遠足[えんそく]のお菓子[かし]を、クラスの全員[ぜんいん]に公平[こうへい]に分配[ぶんぱい]した。", "sentence_source": "generated"}, {"text": "災害のあと、市は集めた食料を避難所の人々に分配した。", "target_word": "分配", "complexity_tier": "T3", "furigana": "災害[さいがい]のあと、市[し]は集[あつ]めた食料[しょくりょう]を避難所[ひなんじょ]の人々[ひとびと]に分配[ぶんぱい]した。", "sentence_source": "generated"}, {"text": "お土産の分配を任された姉は、一人ずつ名前を見ながら配った。", "target_word": "分配", "complexity_tier": "T3", "furigana": "お土産[みやげ]の分配[ぶんぱい]を任[まか]された姉[あね]は、一人[ひとり]ずつ名前[なまえ]を見[み]ながら配[くば]った。", "sentence_source": "generated"}, {"text": "母は焼いたケーキを兄弟の数に合わせて分配した。", "target_word": "分配", "complexity_tier": "T3", "furigana": "母[はは]は焼[や]いたケーキを兄弟[きょうだい]の数[かず]に合[あ]わせて分配[ぶんぱい]した。", "sentence_source": "generated"}, {"text": "毛布を分配するため、人々は体育館の前に長い列を作った。", "target_word": "分配", "complexity_tier": "T3", "furigana": "毛布[もうふ]を分配[ぶんぱい]するため、人々[ひとびと]は体育館[たいいくかん]の前[まえ]に長[なが]い列[れつ]を作[つく]った。", "sentence_source": "generated"}, {"text": "遺産の分配でもめて、兄弟が口をきかなくなった。", "target_word": "分配", "complexity_tier": "T3", "furigana": "遺産[いさん]の分配[ぶんぱい]でもめて、兄弟[きょうだい]が口[くち]をきかなくなった。", "sentence_source": "generated"}, {"text": "仕事の分配が不公平だと、チームの雰囲気は悪くなる。", "target_word": "分配", "complexity_tier": "T3", "furigana": "仕事[しごと]の分配[ぶんぱい]が不公平[ふこうへい]だと、チームの雰囲気[ふんいき]は悪[わる]くなる。", "sentence_source": "generated"}, {"text": "募金で集まった服は、必要な家族に分配されます。", "target_word": "分配", "complexity_tier": "T3", "furigana": "募金[ぼきん]で集[あつ]まった服[ふく]は、必要[ひつよう]な家族[かぞく]に分配[ぶんぱい]されます。", "sentence_source": "generated"}, {"text": "収穫したりんごを村の人たちに分配する日は、いつもにぎやかだ。", "target_word": "分配", "complexity_tier": "T3", "furigana": "収穫[しゅうかく]したりんごを村[むら]の人[ひと]たちに分配[ぶんぱい]する日[ひ]は、いつもにぎやかだ。", "sentence_source": "generated"}, {"text": "水の分配を決めないと、畑ごとに不足が出てしまう。", "target_word": "分配", "complexity_tier": "T3", "furigana": "水[みず]の分配[ぶんぱい]を決[き]めないと、畑[はたけ]ごとに不足[ふそく]が出[で]てしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分配する", "label": "dictionary form"}, {"form": "分配した", "label": "past"}, {"form": "分配して", "label": "te-form"}, {"form": "分配される", "label": "passive"}], "register": "neutral", "sense_fingerprint": "食べ物や品物など多くのものを、人々に分けて渡すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8087f10f-9764-4266-bbce-4f535d18a169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38522, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分配", "is_correct": true, "explanation": "取り分を人々に配ることを表し、「公平に」「クラスの全員に」と合う"}, {"text": "返却", "is_correct": false, "explanation": "借りたものを返すこと。お菓子を全員に配る文脈とは合わない"}, {"text": "配慮", "is_correct": false, "explanation": "相手に気を配ること。物を配る動作には使わない"}, {"text": "分解", "is_correct": false, "explanation": "ばらばらにすること。お菓子を配る場面では成り立たない"}], "explanations": {"分配": "取り分を人々に配ることを表し、「公平に」「クラスの全員に」と合う", "返却": "借りたものを返すこと。お菓子を全員に配る文脈とは合わない", "配慮": "相手に気を配ること。物を配る動作には使わない", "分解": "ばらばらにすること。お菓子を配る場面では成り立たない"}, "sentence_index": 0, "correct_answer": "分配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "時計を分配して部品を調べた。", "explanation": "ここは〈分解〉の意味。部品にばらすことは〈分解〉で、〈分配〉とは言わない"}, {"text": "道が途中で二つに分配していた。", "explanation": "ここは〈分岐〉の意味。道が枝分かれすることは〈分岐〉で、〈分配〉とは言わない"}, {"text": "大きな図面を三枚に分配して印刷した。", "explanation": "ここは〈分割〉の意味。一つのものを切り分けることは〈分割〉で、人に割り当てる〈分配〉とは言わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38522, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分配", "is_correct": true, "explanation": "仕事を人に割り振ることを表し、「不公平だと」という話と合う"}, {"text": "停止", "is_correct": false, "explanation": "動きを止めること。仕事の割り振りの話とは合わない"}, {"text": "収納", "is_correct": false, "explanation": "しまうこと。割り振りの文脈では使わない"}, {"text": "解散", "is_correct": false, "explanation": "集まりを解くこと。仕事を割り振る文脈とは合わない"}], "explanations": {"分配": "仕事を人に割り振ることを表し、「不公平だと」という話と合う", "停止": "動きを止めること。仕事の割り振りの話とは合わない", "収納": "しまうこと。割り振りの文脈では使わない", "解散": "集まりを解くこと。仕事を割り振る文脈とは合わない"}, "sentence_index": 6, "correct_answer": "分配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "材料を分配して、よく混ぜた。", "explanation": "ここは〈混合〉の意味。よく混ぜ合わせることは〈混合〉で、割り当てる〈分配〉とは言わない"}, {"text": "名簿を五十音順に分配した。", "explanation": "ここは〈配列〉の意味。順番どおりに並べることは〈配列〉で、人や物を割り当てる〈分配〉とは合わない"}, {"text": "相手の立場に分配して話した。", "explanation": "ここは〈配慮〉の意味。相手の気持ちを思いやることで、物を割り振る〈分配〉とは合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38522, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寄付された食料は、避難所の人々に分配するされた。", "corrected_sentence": "寄付された食料は、避難所の人々に分配された。", "error_description": "「分配」に「する」を重ねた誤り。受け身の正しい形は「分配された」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38522, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班長は仕事を公平に分配でした。", "corrected_sentence": "班長は仕事を公平に分配した。", "error_description": "動詞として「分配した」が正しい形。「分配でした」は名詞に「でした」を付けた誤り", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
