INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38523, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "複数の人や場所などに、物や金銭などを分けて割り当てること。", "primary_collocate": null, "pronunciation": "ぶんぱい", "ipa": "bɯmpai", "syllable_count": 4, "sentences": [{"text": "国は予算を各地方に分配し、学校や道路の整備を進めている。", "target_word": "分配", "complexity_tier": "T3", "furigana": "国[くに]は予算[よさん]を各地方[かくちほう]に分配[ぶんぱい]し、学校[がっこう]や道路[どうろ]の整備[せいび]を進[すす]めている。", "sentence_source": "generated"}, {"text": "会社は決算のあと、株主に利益を分配した。", "target_word": "分配", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は決算[けっさん]のあと、株主[かぶぬし]に利益[りえき]を分配[ぶんぱい]した。", "sentence_source": "generated"}, {"text": "今年の補助金は、人口の多い順に各市へ分配される。", "target_word": "分配", "complexity_tier": "T3", "furigana": "今年[ことし]の補助金[ほじょきん]は、人口[じんこう]の多[おお]い順[じゅん]に各市[かくし]へ分配[ぶんぱい]される。", "sentence_source": "generated"}, {"text": "部屋の分配は、くじ引きで決めることになった。", "target_word": "分配", "complexity_tier": "T3", "furigana": "部屋[へや]の分配[ぶんぱい]は、くじ引[び]きで決[き]めることになった。", "sentence_source": "generated"}, {"text": "本部は新しい人員を各店舗に分配し、人手の不足を解消しようとした。", "target_word": "分配", "complexity_tier": "T3", "furigana": "本部[ほんぶ]は新[あたら]しい人員[じんいん]を各店舗[かくてんぽ]に分配[ぶんぱい]し、人手[ひとで]の不足[ふそく]を解消[かいしょう]しようとした。", "sentence_source": "generated"}, {"text": "利益は、持っている株の数に応じて株主に分配される。", "target_word": "分配", "complexity_tier": "T3", "furigana": "利益[りえき]は、持[も]っている株[かぶ]の数[かず]に応[おう]じて株主[かぶぬし]に分配[ぶんぱい]される。", "sentence_source": "generated"}, {"text": "資金の分配を見直さなければ、小さな部署は活動を続けられない。", "target_word": "分配", "complexity_tier": "T3", "furigana": "資金[しきん]の分配[ぶんぱい]を見直[みなお]さなければ、小[ちい]さな部署[ぶしょ]は活動[かつどう]を続[つづ]けられない。", "sentence_source": "generated"}, {"text": "委員会は集めた寄付金を三つの団体に分配する案を出した。", "target_word": "分配", "complexity_tier": "T3", "furigana": "委員会[いいんかい]は集[あつ]めた寄付金[きふきん]を三[みっ]つの団体[だんたい]に分配[ぶんぱい]する案[あん]を出[だ]した。", "sentence_source": "generated"}, {"text": "教室の机を各班に分配するよう、先生に頼まれた。", "target_word": "分配", "complexity_tier": "T3", "furigana": "教室[きょうしつ]の机[つくえ]を各班[かくはん]に分配[ぶんぱい]するよう、先生[せんせい]に頼[たの]まれた。", "sentence_source": "generated"}, {"text": "電力会社は需要に合わせて、電気を地域ごとに分配している。", "target_word": "分配", "complexity_tier": "T3", "furigana": "電力会社[でんりょくがいしゃ]は需要[じゅよう]に合[あ]わせて、電気[でんき]を地域[ちいき]ごとに分配[ぶんぱい]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "分配する", "label": "dictionary form"}, {"form": "分配した", "label": "past"}, {"form": "分配して", "label": "te-form"}, {"form": "分配される", "label": "passive"}], "register": "formal", "sense_fingerprint": "予算・利益・人員などを、決まりに従って複数の相手や場所に割り当てること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T3: contains vocabulary far above tier T3: 各市 (Zipf 1.88)']::text[], '8087f10f-9764-4266-bbce-4f535d18a169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38523, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分配", "is_correct": true, "explanation": "予算を各地方に割り当てる意味で、「整備を進めている」という文脈に合う"}, {"text": "返却", "is_correct": false, "explanation": "返すこと。予算を地方へ割り当てる文脈ではない"}, {"text": "配慮", "is_correct": false, "explanation": "気遣いを表す。予算の割り当てには使わない"}, {"text": "分解", "is_correct": false, "explanation": "ばらすこと。予算は分解しない"}], "explanations": {"分配": "予算を各地方に割り当てる意味で、「整備を進めている」という文脈に合う", "返却": "返すこと。予算を地方へ割り当てる文脈ではない", "配慮": "気遣いを表す。予算の割り当てには使わない", "分解": "ばらすこと。予算は分解しない"}, "sentence_index": 0, "correct_answer": "分配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "川が途中で二つに分配されている。", "explanation": "ここは〈分岐〉の意味。流れが枝分かれすることは〈分岐〉で、割り当てる〈分配〉とは言わない"}, {"text": "書類を種類ごとに分配して棚に収めた。", "explanation": "ここは〈分類〉の意味。種類ごとに仲間分けすることは〈分類〉で、割り当てる〈分配〉とは合わない"}, {"text": "卵の白身と黄身を分配して、ボウルに入れた。", "explanation": "ここは〈分離〉の意味。混ざったものを引き離すことは〈分離〉で、〈分配〉とは合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38523, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分配", "is_correct": true, "explanation": "資金を各部署へ割り当てる意味で、見直す対象として合う"}, {"text": "採用", "is_correct": false, "explanation": "人や方法を取り入れること。資金の割り当てを見直す文脈とは合わない"}, {"text": "解雇", "is_correct": false, "explanation": "雇用を終わらせること。資金には使わない"}, {"text": "撤去", "is_correct": false, "explanation": "取り除くこと。資金を割り当てる話とは合わない"}], "explanations": {"分配": "資金を各部署へ割り当てる意味で、見直す対象として合う", "採用": "人や方法を取り入れること。資金の割り当てを見直す文脈とは合わない", "解雇": "雇用を終わらせること。資金には使わない", "撤去": "取り除くこと。資金を割り当てる話とは合わない"}, "sentence_index": 6, "correct_answer": "分配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スープを分配して、火にかけた。", "explanation": "ここは〈加熱〉の意味。火で温めることは〈加熱〉で、割り当てる〈分配〉とは言わない"}, {"text": "ケーキの生地を分配して、よく泡立てた。", "explanation": "ここは〈泡立て〉の意味。空気を含ませて泡にすることは〈泡立て〉で、〈分配〉とは言わない"}, {"text": "周囲の人に分配して、音を小さくした。", "explanation": "ここは〈配慮〉の意味。周りへの気遣いを表すので、物を割り振る〈分配〉とは合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38523, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来年度の予算は、各部署に分配さた。", "corrected_sentence": "来年度の予算は、各部署に分配された。", "error_description": "受け身の正しい形は「分配された」。「れ」が抜けた「分配さた」は誤り", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38523, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寄付金は、三つの施設を分配された。", "corrected_sentence": "寄付金は、三つの施設に分配された。", "error_description": "分配の相手は「に」で示す。「施設を」は誤り", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38526, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "衰退", "is_correct": true, "explanation": "対義語。成長（大きくなる・よくなる）に対し、衰えて弱くなること"}, {"text": "発明", "is_correct": false, "explanation": "新しい物を考え出すこと。成長の対義語ではない"}, {"text": "誕生", "is_correct": false, "explanation": "生まれること。成長とは対になる語ではない"}, {"text": "完成", "is_correct": false, "explanation": "仕上がること。成長の対義語ではない"}], "correct_answer": "衰退", "explanations": {"衰退": "対義語。成長（大きくなる・よくなる）に対し、衰えて弱くなること", "発明": "新しい物を考え出すこと。成長の対義語ではない", "誕生": "生まれること。成長とは対になる語ではない", "完成": "仕上がること。成長の対義語ではない"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38526, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "衰退", "is_correct": true, "explanation": "対義語。成長（大きくなる・よくなる）に対し、衰えて弱くなること"}, {"text": "発見", "is_correct": false, "explanation": "今まで知られていなかったものを見つけること。成長の対義語ではない"}, {"text": "普及", "is_correct": false, "explanation": "広く行き渡ること。成長とは対になる語ではない"}, {"text": "交換", "is_correct": false, "explanation": "互いに取り替えること。成長の対義語ではない"}], "correct_answer": "衰退", "explanations": {"衰退": "対義語。成長（大きくなる・よくなる）に対し、衰えて弱くなること", "発見": "今まで知られていなかったものを見つけること。成長の対義語ではない", "普及": "広く行き渡ること。成長とは対になる語ではない", "交換": "互いに取り替えること。成長の対義語ではない"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38526, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものが大きくなったり、もっとよくなったりすること。", "primary_collocate": null, "pronunciation": "せいちょう", "ipa": "seːtɕoː", "syllable_count": 4, "sentences": [{"text": "この子は一年で背が十センチ伸び、体の成長が早い。", "target_word": "成長", "complexity_tier": "T3", "furigana": "この子[こ]は一年[いちねん]で背[せ]が十[じゅう]センチ伸[の]び、体[からだ]の成長[せいちょう]が早[はや]い。", "sentence_source": "generated"}, {"text": "苗は毎日の水やりのおかげで、順調に成長している。", "target_word": "成長", "complexity_tier": "T3", "furigana": "苗[なえ]は毎日[まいにち]の水[みず]やりのおかげで、順調[じゅんちょう]に成長[せいちょう]している。", "sentence_source": "generated"}, {"text": "彼は失敗から学び、人として大きく成長した。", "target_word": "成長", "complexity_tier": "T3", "furigana": "彼[かれ]は失敗[しっぱい]から学[まな]び、人[ひと]として大[おお]きく成長[せいちょう]した。", "sentence_source": "generated"}, {"text": "経済の成長が止まり、会社の売り上げも伸びなくなった。", "target_word": "成長", "complexity_tier": "T3", "furigana": "経済[けいざい]の成長[せいちょう]が止[と]まり、会社[かいしゃ]の売[う]り上[あ]げも伸[の]びなくなった。", "sentence_source": "generated"}, {"text": "日当たりが悪いと、植物の成長は遅くなる。", "target_word": "成長", "complexity_tier": "T3", "furigana": "日当[ひあ]たりが悪[わる]いと、植物[しょくぶつ]の成長[せいちょう]は遅[おそ]くなる。", "sentence_source": "generated"}, {"text": "新人の成長を見るのが、先輩としての一番の楽しみです。", "target_word": "成長", "complexity_tier": "T3", "furigana": "新人[しんじん]の成長[せいちょう]を見[み]るのが、先輩[せんぱい]としての一番[いちばん]の楽[たの]しみです。", "sentence_source": "generated"}, {"text": "子どもの成長に合わせて、毎年新しい靴を買う。", "target_word": "成長", "complexity_tier": "T3", "furigana": "子[こ]どもの成長[せいちょう]に合[あ]わせて、毎年[まいとし]新[あたら]しい靴[くつ]を買[か]う。", "sentence_source": "generated"}, {"text": "小さな店だったが、十年で全国に支店を持つ会社へ成長した。", "target_word": "成長", "complexity_tier": "T3", "furigana": "小[ちい]さな店[みせ]だったが、十年[じゅうねん]で全国[ぜんこく]に支店[してん]を持[も]つ会社[かいしゃ]へ成長[せいちょう]した。", "sentence_source": "generated"}, {"text": "成長のスピードは人それぞれなので、他の子と比べなくてもいい。", "target_word": "成長", "complexity_tier": "T3", "furigana": "成長[せいちょう]のスピードは人[ひと]それぞれなので、他[ほか]の子[こ]と比[くら]べなくてもいい。", "sentence_source": "generated"}, {"text": "魚は水温が高いほど成長が早く、半年で出荷できる大きさになる。", "target_word": "成長", "complexity_tier": "T3", "furigana": "魚[さかな]は水温[すいおん]が高[たか]いほど成長[せいちょう]が早[はや]く、半年[はんとし]で出荷[しゅっか]できる大[おお]きさになる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "成長する", "label": "dictionary form"}, {"form": "成長した", "label": "past"}, {"form": "成長している", "label": "progressive"}, {"form": "成長して", "label": "te-form"}], "register": "neutral", "sense_fingerprint": "人・植物・会社・経済などが大きくなったり、より良い状態へ進んだりすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8087f10f-9764-4266-bbce-4f535d18a169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38526, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成長", "is_correct": true, "explanation": "体が大きくなることを表し、「体の〜が早い」と合う"}, {"text": "注意", "is_correct": false, "explanation": "気をつけること。「体の注意が早い」とは言えない"}, {"text": "返却", "is_correct": false, "explanation": "返すこと。体の状態を表す文脈とは合わない"}, {"text": "解散", "is_correct": false, "explanation": "集まりを解くこと。体の話には使わない"}], "explanations": {"成長": "体が大きくなることを表し、「体の〜が早い」と合う", "注意": "気をつけること。「体の注意が早い」とは言えない", "返却": "返すこと。体の状態を表す文脈とは合わない", "解散": "集まりを解くこと。体の話には使わない"}, "sentence_index": 0, "correct_answer": "成長"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "借金の成長が続き、返済がますます苦しくなった。", "explanation": "ここは〈増加〉の意味。借金のように量が増えていく場合は〈増加〉を使い、〈成長〉は大きくなる・よくなる変化に使う"}, {"text": "新しい橋の成長が来月に近づいた。", "explanation": "ここは〈完成〉の意味。工事が仕上がることは〈完成〉で、〈成長〉とは言わない"}, {"text": "気温の成長が続き、真夏日が増えた。", "explanation": "ここは〈上昇〉の意味。温度が高くなることは〈上昇〉で、〈成長〉は生き物や事業が育つ場合に使う"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38526, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成長", "is_correct": true, "explanation": "子どもが大きくなることを表し、靴を買い替える話に合う"}, {"text": "集中", "is_correct": false, "explanation": "one点に気持ちを向けること。「子どもの集中に合わせて」とは言わない"}, {"text": "解約", "is_correct": false, "explanation": "契約を終わらせること。靴の話とは合わない"}, {"text": "延期", "is_correct": false, "explanation": "予定を後にずらすこと。「子どもの延期に合わせて」とは言えない"}], "explanations": {"成長": "子どもが大きくなることを表し、靴を買い替える話に合う", "集中": "one点に気持ちを向けること。「子どもの集中に合わせて」とは言わない", "解約": "契約を終わらせること。靴の話とは合わない", "延期": "予定を後にずらすこと。「子どもの延期に合わせて」とは言えない"}, "sentence_index": 6, "correct_answer": "成長"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "道路の成長を進めている。", "explanation": "ここは〈整備〉の意味。道路や設備を整えることは〈整備〉で、大きくなる意味の〈成長〉とは合わない"}, {"text": "部屋の成長に、家族全員で取り組んだ。", "explanation": "ここは〈整理〉の意味。物をきちんと片づけることは〈整理〉で、〈成長〉とは言わない"}, {"text": "人員の成長を見直すことにした。", "explanation": "ここは〈配置〉の意味。人を配り直すことは〈配置〉で、人が育つ意味の〈成長〉とは別"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38526, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会社は三年間で大きく成長さした。", "corrected_sentence": "この会社は三年間で大きく成長した。", "error_description": "「成長する」の過去形は「成長した」。「成長さした」は使役の「させた」と混ざった誤り", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38526, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "娘の成長に記録するため、毎月写真を撮っている。", "corrected_sentence": "娘の成長を記録するため、毎月写真を撮っている。", "error_description": "「記録する」の目的語は「を」で示す。「成長に」は誤り", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38528, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "いい加減", "is_correct": true, "explanation": "対義語。きまりを緩めず守る厳密に対し、守る気がなくゆるいこと"}, {"text": "静か", "is_correct": false, "explanation": "物音が少ないさま。厳密と対になる語ではない"}, {"text": "丁寧", "is_correct": false, "explanation": "注意深く行き届いたさま。厳密と対になる語ではない"}, {"text": "親切", "is_correct": false, "explanation": "人に優しく尽くすさま。厳密と対になる語ではない"}], "correct_answer": "いい加減", "explanations": {"いい加減": "対義語。きまりを緩めず守る厳密に対し、守る気がなくゆるいこと", "静か": "物音が少ないさま。厳密と対になる語ではない", "丁寧": "注意深く行き届いたさま。厳密と対になる語ではない", "親切": "人に優しく尽くすさま。厳密と対になる語ではない"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
