INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38528, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "きまりをきちんと守って、少しもゆるめないこと。", "primary_collocate": null, "pronunciation": "げんみつ", "ipa": "ɡenmitsɯ", "syllable_count": 4, "sentences": [{"text": "この試験は時間を厳密に守らなければならず、一分遅れても受けられない。", "target_word": "厳密", "complexity_tier": "T3", "furigana": "この試験[しけん]は時間[じかん]を厳密[げんみつ]に守[まも]らなければならず、一分[いっぷん]遅[おく]れても受[う]けられない。", "sentence_source": "generated"}, {"text": "工場では衛生管理が厳密で、入る前に必ず手を洗う。", "target_word": "厳密", "complexity_tier": "T3", "furigana": "工場[こうじょう]では衛生管理[えいせいかんり]が厳密[げんみつ]で、入[はい]る前[まえ]に必[かなら]ず手[て]を洗[あら]う。", "sentence_source": "generated"}, {"text": "厳密なルールがあるので、選手は少しの反則も許されない。", "target_word": "厳密", "complexity_tier": "T3", "furigana": "厳密[げんみつ]なルールがあるので、選手[せんしゅ]は少[すこ]しの反則[はんそく]も許[ゆる]されない。", "sentence_source": "generated"}, {"text": "薬は決められた量を厳密に守って飲んでください。", "target_word": "厳密", "complexity_tier": "T3", "furigana": "薬[くすり]は決[き]められた量[りょう]を厳密[げんみつ]に守[まも]って飲[の]んでください。", "sentence_source": "generated"}, {"text": "先生は校則に厳密で、制服の乱れを見逃さない。", "target_word": "厳密", "complexity_tier": "T3", "furigana": "先生[せんせい]は校則[こうそく]に厳密[げんみつ]で、制服[せいふく]の乱[みだ]れを見逃[みのが]さない。", "sentence_source": "generated"}, {"text": "彼女は厳密な食事制限を続け、お菓子は一口も食べなかった。", "target_word": "厳密", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は厳密[げんみつ]な食事制限[しょくじせいげん]を続[つづ]け、お菓子[かし]は一口[ひとくち]も食[た]べなかった。", "sentence_source": "generated"}, {"text": "国境の検査が厳密になり、荷物はすべて開けて調べられた。", "target_word": "厳密", "complexity_tier": "T3", "furigana": "国境[こっきょう]の検査[けんさ]が厳密[げんみつ]になり、荷物[にもつ]はすべて開[あ]けて調[しら]べられた。", "sentence_source": "generated"}, {"text": "契約書の内容を厳密に実行しないと、会社は責任を問われる。", "target_word": "厳密", "complexity_tier": "T3", "furigana": "契約書[けいやくしょ]の内容[ないよう]を厳密[げんみつ]に実行[じっこう]しないと、会社[かいしゃ]は責任[せきにん]を問[と]われる。", "sentence_source": "generated"}, {"text": "厳密な審査の結果、合格者はたった三人だった。", "target_word": "厳密", "complexity_tier": "T3", "furigana": "厳密[げんみつ]な審査[しんさ]の結果[けっか]、合格者[ごうかくしゃ]はたった三人[さんにん]だった。", "sentence_source": "generated"}, {"text": "規則を厳密に適用しすぎて、病気の客まで店から出されてしまった。", "target_word": "厳密", "complexity_tier": "T3", "furigana": "規則[きそく]を厳密[げんみつ]に適用[てきよう]しすぎて、病気[びょうき]の客[きゃく]まで店[みせ]から出[だ]されてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "厳密だ", "label": "plain predicate"}, {"form": "厳密な", "label": "attributive"}, {"form": "厳密に", "label": "adverbial"}, {"form": "厳密で", "label": "te-form"}], "register": "formal", "sense_fingerprint": "規則や基準を少しもゆるめず、きちんと守るさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8087f10f-9764-4266-bbce-4f535d18a169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38528, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厳密", "is_correct": true, "explanation": "きまりを緩めず守る意味で、「時間を〜に守る」と合う"}, {"text": "活発", "is_correct": false, "explanation": "盛んなさま。時間を守る動作とは合わない"}, {"text": "鮮明", "is_correct": false, "explanation": "はっきりしているさま。守り方を表さない"}, {"text": "豊富", "is_correct": false, "explanation": "たくさんあるさま。守る動作とは合わない"}], "explanations": {"厳密": "きまりを緩めず守る意味で、「時間を〜に守る」と合う", "活発": "盛んなさま。時間を守る動作とは合わない", "鮮明": "はっきりしているさま。守り方を表さない", "豊富": "たくさんあるさま。守る動作とは合わない"}, "sentence_index": 0, "correct_answer": "厳密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この冬は厳密な寒さが続いた。", "explanation": "ここは〈厳寒〉の意味。寒さが激しいことは〈厳寒〉で、規則を緩めない〈厳密〉とは合わない"}, {"text": "夏の厳密な暑さに、みんながまいっていた。", "explanation": "ここは〈厳しい〉の意味。天候の激しさは〈厳しい〉で、〈厳密〉は規則の徹底に使う"}, {"text": "厳密な雰囲気の中、式典が始まった。", "explanation": "ここは〈厳粛〉の意味。式の重々しさを表すので、規則を守る意味の〈厳密〉とは合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38528, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厳密", "is_correct": true, "explanation": "検査を緩めず行う意味で、「国境の検査が〜になり」と合う"}, {"text": "静か", "is_correct": false, "explanation": "物音が少ないさま。検査の厳しさを表さない"}, {"text": "陽気", "is_correct": false, "explanation": "明るく快活なさま。検査の文脈とは合わない"}, {"text": "元気", "is_correct": false, "explanation": "活力があるさま。検査には使わない"}], "explanations": {"厳密": "検査を緩めず行う意味で、「国境の検査が〜になり」と合う", "静か": "物音が少ないさま。検査の厳しさを表さない", "陽気": "明るく快活なさま。検査の文脈とは合わない", "元気": "活力があるさま。検査には使わない"}, "sentence_index": 6, "correct_answer": "厳密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厳密な父に育てられ、夜の外出も許されなかった。", "explanation": "ここは〈厳格〉の意味。人の性格や教育方針は〈厳格〉と言い、〈厳密〉は事柄の正確さや規則の緩まなさに使う"}, {"text": "厳密たる事実を前に、言葉を失った。", "explanation": "ここは〈厳然〉の意味。動かしがたい事実を表すので、〈厳密〉とは言わない"}, {"text": "厳密な顔つきの店員が、客の荷物を調べた。", "explanation": "ここは〈いかめしい〉の意味。顔つきの険しさを表すことは〈いかめしい〉で、規則を緩めない〈厳密〉とは合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38528, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この制度は、規則を厳密な守ることを求めている。", "corrected_sentence": "この制度は、規則を厳密に守ることを求めている。", "error_description": "動詞「守る」を修飾するには連用形「厳密に」が必要。「厳密な」は名詞にしか付かない", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "厳密で", "is_correct": true, "explanation": "て形。「工場では衛生管理が〜、入る前に」と続けるための形"}, {"text": "厳密だ", "is_correct": false, "explanation": "終止形。文を言い切る形で、読点の前には続かない"}, {"text": "厳密な", "is_correct": false, "explanation": "連体形。名詞の前に置く形で、「衛生管理が〜」の述語にはならない"}, {"text": "厳密に", "is_correct": false, "explanation": "連用形。動詞を修飾する形で、「衛生管理が〜」の述語にはならない"}], "correct_form": "厳密で", "base_form": "厳密だ", "form_label": "て形", "sentence_index": 1, "explanations": {"厳密で": "て形。「工場では衛生管理が〜、入る前に」と続けるための形", "厳密だ": "終止形。文を言い切る形で、読点の前には続かない", "厳密な": "連体形。名詞の前に置く形で、「衛生管理が〜」の述語にはならない", "厳密に": "連用形。動詞を修飾する形で、「衛生管理が〜」の述語にはならない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38528, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "審査は、ルールを厳密で確認して行われた。", "corrected_sentence": "審査は、ルールを厳密に確認して行われた。", "error_description": "動詞「確認する」を修飾するには連用形「厳密に」が必要。「厳密で」は動詞に続かない", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "厳密に", "is_correct": true, "explanation": "連用形。動詞「実行しない」を修飾する形で、「厳密に実行しないと」と続く"}, {"text": "厳密です", "is_correct": false, "explanation": "丁寧な断定の形。動詞の前には置けず、「内容を〜実行しないと」とつながらない"}, {"text": "厳密だった", "is_correct": false, "explanation": "過去の形。文を終える形で、「実行しないと」の前には続かない"}, {"text": "厳密ではない", "is_correct": false, "explanation": "否定の形。動詞を修飾できず、「内容を〜実行しないと」とはつながらない"}], "correct_form": "厳密に", "base_form": "厳密だ", "form_label": "連用形", "sentence_index": 7, "explanations": {"厳密に": "連用形。動詞「実行しない」を修飾する形で、「厳密に実行しないと」と続く", "厳密です": "丁寧な断定の形。動詞の前には置けず、「内容を〜実行しないと」とつながらない", "厳密だった": "過去の形。文を終える形で、「実行しないと」の前には続かない", "厳密ではない": "否定の形。動詞を修飾できず、「内容を〜実行しないと」とはつながらない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa04e301-ccca-4722-9e47-f6f25cf121c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38530, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「友だちとの争い」で、「と」に続けて名詞「争い」を修飾する「の」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「友だちと」の後に「が」を置くと、「と」と並ばず成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、ここは名詞を修飾する位置なので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、「友だちと___争い」の形では成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「友だちとの争い」で、「と」に続けて名詞「争い」を修飾する「の」が入る。", "が": "「友だちと」の後に「が」を置くと、「と」と並ばず成り立たない。", "を": "「を」は目的語を示すが、ここは名詞を修飾する位置なので合わない。", "で": "「で」は場所や手段を示すが、「友だちと___争い」の形では成り立たない。"}, "error_tags": {"が": "主語を示す（「と」の後に続かない）", "を": "目的語を示す（修飾位置に合わない）", "で": "場所・手段を示す（成り立たない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38530, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38530, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人がお互いに、自分の方が正しいと言い合って、けんかをすること。", "primary_collocate": null, "pronunciation": "あらそい", "ipa": "aɾasoi", "syllable_count": 4, "sentences": [{"text": "兄と弟は、どちらが正しいかで争いになった。", "target_word": "争い", "complexity_tier": "T3", "furigana": "兄[あに]と弟[おとうと]は、どちらが正[ただ]しいかで争[あらそ]いになった。", "sentence_source": "generated"}, {"text": "友だちとの争いは、すぐに謝って終わらせたい。", "target_word": "争い", "complexity_tier": "T3", "furigana": "友[とも]だちとの争[あらそ]いは、すぐに謝[あやま]って終[お]わらせたい。", "sentence_source": "generated"}, {"text": "小さな争いが原因で、二人は口をきかなくなった。", "target_word": "争い", "complexity_tier": "T3", "furigana": "小[ちい]さな争[あらそ]いが原因[げんいん]で、二人[ふたり]は口[くち]をきかなくなった。", "sentence_source": "generated"}, {"text": "子どもたちの争いを、先生が止めに入った。", "target_word": "争い", "complexity_tier": "T3", "furigana": "子[こ]どもたちの争[あらそ]いを、先生[せんせい]が止[と]めに入[はい]った。", "sentence_source": "generated"}, {"text": "母は、家族の争いを見るのが悲しいと言った。", "target_word": "争い", "complexity_tier": "T3", "furigana": "母[はは]は、家族[かぞく]の争[あらそ]いを見[み]るのが悲[かな]しいと言[い]った。", "sentence_source": "generated"}, {"text": "順番をめぐる争いが、教室で起きた。", "target_word": "争い", "complexity_tier": "T3", "furigana": "順番[じゅんばん]をめぐる争[あらそ]いが、教室[きょうしつ]で起[お]きた。", "sentence_source": "generated"}, {"text": "隣の席で争いが始まり、店の中が静かになった。", "target_word": "争い", "complexity_tier": "T3", "furigana": "隣[となり]の席[せき]で争[あらそ]いが始[はじ]まり、店[みせ]の中[なか]が静[しず]かになった。", "sentence_source": "generated"}, {"text": "二人は謝ったので、争いはすぐに終わった。", "target_word": "争い", "complexity_tier": "T3", "furigana": "二人[ふたり]は謝[あやま]ったので、争[あらそ]いはすぐに終[お]わった。", "sentence_source": "generated"}, {"text": "彼は争いが嫌いで、いつも先に折れる。", "target_word": "争い", "complexity_tier": "T3", "furigana": "彼[かれ]は争[あらそ]いが嫌[きら]いで、いつも先[さき]に折[お]れる。", "sentence_source": "generated"}, {"text": "犬の鳴き声がうるさいと言って、近所の人と争いになった。", "target_word": "争い", "complexity_tier": "T3", "furigana": "犬[いぬ]の鳴[な]き声[ごえ]がうるさいと言[い]って、近所[きんじょ]の人[ひと]と争[あらそ]いになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "争い", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人どうしが自分の正しさを言い合って起こす身近なけんか", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fa4e591-0cd8-4cce-86d4-2d04b8b274fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38530, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "争い", "is_correct": true, "explanation": "「争いになった」で、言い合いのけんかが起きたことを表し、文の意味に合う。"}, {"text": "反省", "is_correct": false, "explanation": "反省は自分の行いを振り返ること。互いに正しさを言い合う出来事とは意味が合わない。"}, {"text": "安心", "is_correct": false, "explanation": "安心は心配がなくなった気持ち。「どちらが正しいか」で揉めた文脈には入らない。"}, {"text": "感謝", "is_correct": false, "explanation": "感謝は相手に礼を伝える気持ち。言い合いになったという内容とは結びつかない。"}], "explanations": {"争い": "「争いになった」で、言い合いのけんかが起きたことを表し、文の意味に合う。", "反省": "反省は自分の行いを振り返ること。互いに正しさを言い合う出来事とは意味が合わない。", "安心": "安心は心配がなくなった気持ち。「どちらが正しいか」で揉めた文脈には入らない。", "感謝": "感謝は相手に礼を伝える気持ち。言い合いになったという内容とは結びつかない。"}, "sentence_index": 0, "correct_answer": "争い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "親友との争いを深めて、お互いの夢を語り合った。", "explanation": "ここは〈友情を深める〉の意味。争いはけんかや言い合いのことで、仲を深める意味では使わない。「争いを深める」は語り合う内容とも合わない。"}, {"text": "学級会では、遠足の行き先について争いを重ねて、全員が納得する案を決めた。", "explanation": "ここは〈話し合い〉の意味。争いは感情をぶつけ合うけんかで、落ち着いて案を決める話し合いには使わない。"}, {"text": "結婚式で、二人は互いの争いを祝い合った。", "explanation": "ここは〈祝福〉の意味。争いは人どうしがぶつかり合うことで、祝い事には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38530, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "争い", "is_correct": true, "explanation": "「争いが始まり」で、言い合いが起きたことを表す。文の意味に合う。"}, {"text": "歓声", "is_correct": false, "explanation": "歓声は盛り上がって上がる大きな声。「店の中が静かになった」と矛盾する。"}, {"text": "拍手", "is_correct": false, "explanation": "拍手は手を打ち鳴らす音。静かになったという結末と合わない。"}, {"text": "大合唱", "is_correct": false, "explanation": "大合唱は大勢で声をそろえて歌うこと。静かになった状況と矛盾する。"}], "explanations": {"争い": "「争いが始まり」で、言い合いが起きたことを表す。文の意味に合う。", "歓声": "歓声は盛り上がって上がる大きな声。「店の中が静かになった」と矛盾する。", "拍手": "拍手は手を打ち鳴らす音。静かになったという結末と合わない。", "大合唱": "大合唱は大勢で声をそろえて歌うこと。静かになった状況と矛盾する。"}, "sentence_index": 6, "correct_answer": "争い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝のランニングで、部員は争いを重ねて体を鍛えた。", "explanation": "ここは〈練習〉の意味。争いは言い合いやけんかのことで、体を鍛える練習の意味では使わない。"}, {"text": "久しぶりに会った二人は、争いを重ねて昔話に花を咲かせた。", "explanation": "ここは〈再会の語らい〉の意味。争いは対立してぶつかり合うことで、なつかしく語り合う場面には合わない。"}, {"text": "チームは争いを大切にして、力を合わせて仕事を進めた。", "explanation": "ここは〈協調〉の意味。争いは対立して譲らないことで、力を合わせる協調とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38530, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校庭での争いが、先生がすぐ止めに入った。", "corrected_sentence": "校庭での争いを、先生がすぐ止めに入った。", "error_description": "「争い」に続く助詞が誤り。止める対象を表す「を」が必要なのに「が」を使っている。「が」だと主語が二つ重なり不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38530, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友だちとの争いを、すぐに謝って結んだ。", "corrected_sentence": "友だちとの争いを、すぐに謝って収めた。", "error_description": "「争い」と組み合わせる動詞が誤り。「結ぶ」は契約などに使い、争いには使わない。争いは「収める」「終わらせる」で閉じるものなので「収めた」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38531, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「大きな争いになった」で、なる対象を示す「に」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「争いが なった」では、「なる」の形が成り立たず不自然になる。"}, {"text": "を", "is_correct": false, "explanation": "「争いを なった」は目的語の形になり、「なる」と結びつかない。"}, {"text": "で", "is_correct": false, "explanation": "「争いで なった」は手段を示すが、「なる」とは成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「大きな争いになった」で、なる対象を示す「に」が入る。", "が": "「争いが なった」では、「なる」の形が成り立たず不自然になる。", "を": "「争いを なった」は目的語の形になり、「なる」と結びつかない。", "で": "「争いで なった」は手段を示すが、「なる」とは成り立たない。"}, "error_tags": {"が": "主語を示す（「なる」と合わない）", "を": "目的語を示す（「なる」と合わない）", "で": "手段を示す（成り立たない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38531, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「争いが生まれた」で、生まれる主体を示す「が」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「争いを生まれた」は目的語の形になり、「生まれる」と合わない。"}, {"text": "に", "is_correct": false, "explanation": "「争いに生まれた」は成り立たず、自然な文にならない。"}, {"text": "と", "is_correct": false, "explanation": "「争いと生まれた」は並列の形になり、「生まれる」と結びつかない。"}], "correct_answer": "が", "explanations": {"が": "「争いが生まれた」で、生まれる主体を示す「が」が入る。", "を": "「争いを生まれた」は目的語の形になり、「生まれる」と合わない。", "に": "「争いに生まれた」は成り立たず、自然な文にならない。", "と": "「争いと生まれた」は並列の形になり、「生まれる」と結びつかない。"}, "error_tags": {"を": "目的語を示す（「生まれる」と合わない）", "に": "場所・相手を示す（成り立たない）", "と": "並列・相手を示す（成り立たない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38531, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "意見や利害の対立から起こる、言い合いやけんか。", "primary_collocate": null, "pronunciation": "あらそい", "ipa": "aɾasoi", "syllable_count": 4, "sentences": [{"text": "土地の使い方をめぐって、住民の間に争いが起きた。", "target_word": "争い", "complexity_tier": "T3", "furigana": "土地[とち]の使[つか]い方[かた]をめぐって、住民[じゅうみん]の間[あいだ]に争[あらそ]いが起[お]きた。", "sentence_source": "generated"}, {"text": "意見の違いが、会議で大きな争いになった。", "target_word": "争い", "complexity_tier": "T3", "furigana": "意見[いけん]の違[ちが]いが、会議[かいぎ]で大[おお]きな争[あらそ]いになった。", "sentence_source": "generated"}, {"text": "遺産をめぐる争いは、何年も続いている。", "target_word": "争い", "complexity_tier": "T3", "furigana": "遺産[いさん]をめぐる争[あらそ]いは、何年[なんねん]も続[つづ]いている。", "sentence_source": "generated"}, {"text": "利益の分け方で、二つの会社が争いを始めた。", "target_word": "争い", "complexity_tier": "T3", "furigana": "利益[りえき]の分[わ]け方[かた]で、二[ふた]つの会社[かいしゃ]が争[あらそ]いを始[はじ]めた。", "sentence_source": "generated"}, {"text": "水の権利をめぐる争いを、町の代表が話し合いで解決した。", "target_word": "争い", "complexity_tier": "T3", "furigana": "水[みず]の権利[けんり]をめぐる争[あらそ]いを、町[まち]の代表[だいひょう]が話[はな]し合[あ]いで解決[かいけつ]した。", "sentence_source": "generated"}, {"text": "お金の問題があるので、兄弟の間に争いが絶えない。", "target_word": "争い", "complexity_tier": "T3", "furigana": "お金[かね]の問題[もんだい]があるので、兄弟[きょうだい]の間[あいだ]に争[あらそ]いが絶[た]えない。", "sentence_source": "generated"}, {"text": "争いを避けるため、委員長は全員の意見を聞いた。", "target_word": "争い", "complexity_tier": "T3", "furigana": "争[あらそ]いを避[さ]けるため、委員長[いいんちょう]は全員[ぜんいん]の意見[いけん]を聞[き]いた。", "sentence_source": "generated"}, {"text": "方針の違いから、部の中に争いが生まれた。", "target_word": "争い", "complexity_tier": "T3", "furigana": "方針[ほうしん]の違[ちが]いから、部[ぶ]の中[なか]に争[あらそ]いが生[う]まれた。", "sentence_source": "generated"}, {"text": "隣の国との争いが、ニュースで大きく伝えられた。", "target_word": "争い", "complexity_tier": "T3", "furigana": "隣[となり]の国[くに]との争[あらそ]いが、ニュースで大[おお]きく伝[つた]えられた。", "sentence_source": "generated"}, {"text": "二つの村は、昔から境界をめぐって争いを続けてきた。", "target_word": "争い", "complexity_tier": "T3", "furigana": "二[ふた]つの村[むら]は、昔[むかし]から境界[きょうかい]をめぐって争[あらそ]いを続[つづ]けてきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "争い", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "意見や利益の対立から集団や国の間で起こる言い合い・もめごと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fa4e591-0cd8-4cce-86d4-2d04b8b274fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38531, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "争い", "is_correct": true, "explanation": "「争いが起きた」で、利害の対立から言い合いが生じたことを表す。文の意味に合う。"}, {"text": "余韻", "is_correct": false, "explanation": "余韻は音や出来事のあとに残る響き。争いが起きたという文の意味に合わない。"}, {"text": "記憶", "is_correct": false, "explanation": "記憶は覚えていること。「住民の間に記憶が起きた」とは結びつかない。"}, {"text": "栄光", "is_correct": false, "explanation": "栄光は輝かしい名誉。対立が起きたという内容とは合わない。"}], "explanations": {"争い": "「争いが起きた」で、利害の対立から言い合いが生じたことを表す。文の意味に合う。", "余韻": "余韻は音や出来事のあとに残る響き。争いが起きたという文の意味に合わない。", "記憶": "記憶は覚えていること。「住民の間に記憶が起きた」とは結びつかない。", "栄光": "栄光は輝かしい名誉。対立が起きたという内容とは合わない。"}, "sentence_index": 0, "correct_answer": "争い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "住民たちは、支えてくれた人への感謝を争いで表した。", "explanation": "ここは〈感謝〉の意味。争いは意見や利害のぶつかり合いのことで、感謝の気持ちを表す語ではない。"}, {"text": "大会の準備で、委員たちは争いを分担して、手際よく進めた。", "explanation": "ここは〈分担〉の意味。争いは対立して言い合うことで、仕事を分け合う分担の意味では使わない。"}, {"text": "子どもたちは、公園の砂場で大きな争いを作って遊んだ。", "explanation": "ここは〈作る・制作〉の意味。争いは言い合いや対立のことで、物を作る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38531, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "争い", "is_correct": true, "explanation": "「争いを避けるため」で、もめごとを避ける意味になり文に合う。"}, {"text": "注文", "is_correct": false, "explanation": "注文は品物を頼むこと。「避けるため」と結びつかず、意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空の状態。避ける対象として不自然で、文脈に合わない。"}, {"text": "祝福", "is_correct": false, "explanation": "祝福は喜びを祈ること。避けるものとしては合わない。"}], "explanations": {"争い": "「争いを避けるため」で、もめごとを避ける意味になり文に合う。", "注文": "注文は品物を頼むこと。「避けるため」と結びつかず、意味が通らない。", "天気": "天気は空の状態。避ける対象として不自然で、文脈に合わない。", "祝福": "祝福は喜びを祈ること。避けるものとしては合わない。"}, "sentence_index": 6, "correct_answer": "争い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二社は新商品の研究に争いを注ぎ、技術を高め合った。", "explanation": "ここは〈研究〉の意味。争いは意見や利害がぶつかることで、研究に力を注ぐ意味では使わない。"}, {"text": "住民たちは、週末の散歩で争いを重ね、町の景色を楽しんだ。", "explanation": "ここは〈散歩〉の意味。争いは言い合いやけんかのことで、のんびり歩く散歩の意味では使わない。"}, {"text": "企業は争いを大切にして、取引先と長く付き合っている。", "explanation": "ここは〈協調〉の意味。争いは対立のことで、取引先と協調を保つ方針とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38531, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "予算の配分をめぐって、委員の間に争いが起きさせた。", "corrected_sentence": "予算の配分をめぐって、委員の間に争いが起きた。", "error_description": "「起きる」の活用が誤り。「起きる」は自動詞なので使役の「起きさせた」は使えず、過去形の「起きた」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38531, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "立場の違いから、組合の中に争いを生まれた。", "corrected_sentence": "立場の違いから、組合の中に争いが生まれた。", "error_description": "「生まれる」に続く助詞が誤り。主語を示す「が」が必要なのに「を」を使っている。「を」だと目的語の形になり不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38532, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「儀礼が数多くある」で、存在する主体を示す「が」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「儀礼を数多くある」は成り立たず、「ある」と合わない。"}, {"text": "で", "is_correct": false, "explanation": "「儀礼で数多くある」は場所や手段の形になり、存在を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「儀礼と数多くある」は並列の形になり、不自然な文になる。"}], "correct_answer": "が", "explanations": {"が": "「儀礼が数多くある」で、存在する主体を示す「が」が入る。", "を": "「儀礼を数多くある」は成り立たず、「ある」と合わない。", "で": "「儀礼で数多くある」は場所や手段の形になり、存在を表せない。", "と": "「儀礼と数多くある」は並列の形になり、不自然な文になる。"}, "error_tags": {"を": "目的語を示す（「ある」と合わない）", "で": "場所・手段を示す（成り立たない）", "と": "並列を示す（不自然）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38532, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38532, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "おきまりのやりかたや、きちんとしたふるまいのこと。", "primary_collocate": null, "pronunciation": "ぎれい", "ipa": "ɡiɾei", "syllable_count": 3, "sentences": [{"text": "結婚式は、古くからの儀礼に従って進められた。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]は、古[ふる]くからの儀礼[ぎれい]に従[したが]って進[すす]められた。", "sentence_source": "generated"}, {"text": "茶道には、細かい儀礼が数多くある。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "茶道[さどう]には、細[こま]かい儀礼[ぎれい]が数多[かずおお]くある。", "sentence_source": "generated"}, {"text": "外国の王を迎えるため、国は正式な儀礼を整えた。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "外国[がいこく]の王[おう]を迎[むか]えるため、国[くに]は正式[せいしき]な儀礼[ぎれい]を整[ととの]えた。", "sentence_source": "generated"}, {"text": "神社の儀礼は、見ているだけでも気持ちが引き締まる。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "神社[じんじゃ]の儀礼[ぎれい]は、見[み]ているだけでも気持[きも]ちが引[ひ]き締[し]まる。", "sentence_source": "generated"}, {"text": "彼は儀礼を重んじる人で、あいさつの順番にも気を配る。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "彼[かれ]は儀礼[ぎれい]を重[おも]んじる人[ひと]で、あいさつの順番[じゅんばん]にも気[き]を配[くば]る。", "sentence_source": "generated"}, {"text": "新入社員は、会社の儀礼を覚えるのに苦労した。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "新入社員[しんにゅうしゃいん]は、会社[かいしゃ]の儀礼[ぎれい]を覚[おぼ]えるのに苦労[くろう]した。", "sentence_source": "generated"}, {"text": "葬式の儀礼は、地域によって少しずつ違う。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "葬式[そうしき]の儀礼[ぎれい]は、地域[ちいき]によって少[すこ]しずつ違[ちが]う。", "sentence_source": "generated"}, {"text": "形だけの儀礼ではなく、心のこもった感謝を伝えたい。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "形[かたち]だけの儀礼[ぎれい]ではなく、心[こころ]のこもった感謝[かんしゃ]を伝[つた]えたい。", "sentence_source": "generated"}, {"text": "祖父は、お正月の儀礼を毎年きちんと守っている。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "祖父[そふ]は、お正月[しょうがつ]の儀礼[ぎれい]を毎年[まいとし]きちんと守[まも]っている。", "sentence_source": "generated"}, {"text": "儀礼を知らないと、目上の人の前で失礼になることがある。", "target_word": "儀礼", "complexity_tier": "T3", "furigana": "儀礼[ぎれい]を知[し]らないと、目上[めうえ]の人[ひと]の前[まえ]で失礼[しつれい]になることがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "儀礼", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "式や行事、礼儀で決まっている作法やふるまい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fa4e591-0cd8-4cce-86d4-2d04b8b274fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38532, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "儀礼", "is_correct": true, "explanation": "「古くからの儀礼に従って」で、決まった作法に従うという意味になり文に合う。"}, {"text": "無関心", "is_correct": false, "explanation": "無関心は関心がないこと。決まりに従うという文脈とは結びつかない。"}, {"text": "不安", "is_correct": false, "explanation": "不安は心配な気持ち。決まった作法に従うという文の意味に合わない。"}, {"text": "怠慢", "is_correct": false, "explanation": "怠慢は怠けること。従う対象としては意味が通らない。"}], "explanations": {"儀礼": "「古くからの儀礼に従って」で、決まった作法に従うという意味になり文に合う。", "無関心": "無関心は関心がないこと。決まりに従うという文脈とは結びつかない。", "不安": "不安は心配な気持ち。決まった作法に従うという文の意味に合わない。", "怠慢": "怠慢は怠けること。従う対象としては意味が通らない。"}, "sentence_index": 0, "correct_answer": "儀礼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は料理の儀礼がよく、あっという間に完成した。", "explanation": "ここは〈手際〉の意味。儀礼は決まった式や作法のことで、作業の速さや要領を表す場面には使わない。"}, {"text": "彼は話すとき、大きな儀礼で感情を表す。", "explanation": "ここは〈仕草〉の意味。儀礼は決まったふるまいを指し、自然な身振りには合わない。"}, {"text": "彼の絵は儀礼があって、ほかの人とは違う個性をもつ。", "explanation": "ここは〈個性〉の意味。儀礼は決まったやりかたや作法のことで、その人らしさを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38532, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "儀礼", "is_correct": true, "explanation": "「葬式の儀礼は、地域によって違う」で、地域ごとに異なる作法を表し文に合う。"}, {"text": "円周率", "is_correct": false, "explanation": "円周率は円の周りと直径の比。地域によって違うものではない。"}, {"text": "光速", "is_correct": false, "explanation": "光速は光が進む速さで、地域によって変わらない。"}, {"text": "元素記号", "is_correct": false, "explanation": "元素記号は元素を表す記号で、地域によって違わない。"}], "explanations": {"儀礼": "「葬式の儀礼は、地域によって違う」で、地域ごとに異なる作法を表し文に合う。", "円周率": "円周率は円の周りと直径の比。地域によって違うものではない。", "光速": "光速は光が進む速さで、地域によって変わらない。", "元素記号": "元素記号は元素を表す記号で、地域によって違わない。"}, "sentence_index": 6, "correct_answer": "儀礼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家計の儀礼を考えて、無駄な買い物を減らした。", "explanation": "ここは〈節約〉の意味。儀礼は決まった作法のことで、お金を大事に使う意味では使わない。"}, {"text": "旅行の儀礼を立てて、毎日の行き先を決めた。", "explanation": "ここは〈計画〉の意味。儀礼は作法や式のことで、予定を組む計画の意味では使わない。"}, {"text": "彼は儀礼を持って、毎晩遅くまで練習を続けた。", "explanation": "ここは〈熱意〉の意味。儀礼は作法のことで、物事に打ち込む気持ちとは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38532, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "客は茶道の儀礼が細かく覚えた。", "corrected_sentence": "客は茶道の儀礼を細かく覚えた。", "error_description": "「覚えた」は他動詞なので、覚える対象は「を」で示す。「が」は目的語の標示として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38532, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は、お盆の儀礼を大切に飾っている。", "corrected_sentence": "祖母は、お盆の儀礼を大切に守っている。", "error_description": "「儀礼」と組み合わせる動詞が誤り。儀礼は「守る」ものなので「飾る」は使えない。「守っている」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38534, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「言い伝えを、子どもたちに話した」の「を」。話す内容を示す目的語になる。"}, {"text": "に", "is_correct": false, "explanation": "「言い伝えに 子どもたちに話した」では二つの「に」が重なり、目的語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は話す内容には使えず、ここでは成立しない。"}, {"text": "の", "is_correct": false, "explanation": "所有や修飾の「の」では、話す内容を示す文にならない。"}], "correct_answer": "を", "explanations": {"を": "「言い伝えを、子どもたちに話した」の「を」。話す内容を示す目的語になる。", "に": "「言い伝えに 子どもたちに話した」では二つの「に」が重なり、目的語を示せない。", "へ": "方向を表す「へ」は話す内容には使えず、ここでは成立しない。", "の": "所有や修飾の「の」では、話す内容を示す文にならない。"}, "error_tags": {"に": "dative", "へ": "direction", "の": "possessive"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38534, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「言い伝えが残っている」の「が」。言い伝えが主語として残る形になる。"}, {"text": "を", "is_correct": false, "explanation": "「言い伝えを残っている」は成立せず、目的語の「を」は残るという自動詞の文に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「言い伝えと残っている」は並列や相手を示す形で、この文の主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「残っている」の主語には使えず、文が成立しない。"}], "correct_answer": "が", "explanations": {"が": "「言い伝えが残っている」の「が」。言い伝えが主語として残る形になる。", "を": "「言い伝えを残っている」は成立せず、目的語の「を」は残るという自動詞の文に合わない。", "と": "「言い伝えと残っている」は並列や相手を示す形で、この文の主語にはならない。", "へ": "方向の「へ」は「残っている」の主語には使えず、文が成立しない。"}, "error_tags": {"を": "object", "と": "accompaniment", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38534, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "昔から人から人へ話して伝えられたこと。", "primary_collocate": null, "pronunciation": "いいつたえ", "ipa": "iːtsɯtae", "syllable_count": 5, "sentences": [{"text": "この村には、山の神様についての言い伝えがある。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "この村[むら]には、山[やま]の神様[かみさま]についての言い伝え[いいつたえ]がある。", "sentence_source": "generated"}, {"text": "祖母から聞いた言い伝えを、子どもたちに話した。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "祖母[そぼ]から聞[き]いた言い伝え[いいつたえ]を、子[こ]どもたちに話[はな]した。", "sentence_source": "generated"}, {"text": "言い伝えによると、この池には大きな龍が住んでいたそうだ。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "言い伝え[いいつたえ]によると、この池[いけ]には大[おお]きな龍[りゅう]が住[す]んでいたそうだ。", "sentence_source": "generated"}, {"text": "古い言い伝えを信じて、人々は毎年お祭りをしている。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "古[ふる]い言い伝え[いいつたえ]を信[しん]じて、人々[ひとびと]は毎年[まいとし]お祭[まつ]りをしている。", "sentence_source": "generated"}, {"text": "「夜に口笛を吹くと蛇が来る」という言い伝えがある。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "「夜[よる]に口笛[くちぶえ]を吹[ふ]くと蛇[へび]が来[く]る」という言い伝え[いいつたえ]がある。", "sentence_source": "generated"}, {"text": "言い伝えは本当かどうか分からないが、おもしろい話だ。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "言い伝え[いいつたえ]は本当[ほんとう]かどうか分[わ]からないが、おもしろい話[はなし]だ。", "sentence_source": "generated"}, {"text": "町の言い伝えを集めて、一冊の本にまとめた。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "町[まち]の言い伝え[いいつたえ]を集[あつ]めて、一冊[いっさつ]の本[ほん]にまとめた。", "sentence_source": "generated"}, {"text": "この橋には悲しい言い伝えが残っている。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "この橋[はし]には悲[かな]しい言い伝え[いいつたえ]が残[のこ]っている。", "sentence_source": "generated"}, {"text": "言い伝えを守って、その木は誰も切らない。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "言い伝え[いいつたえ]を守[まも]って、その木[き]は誰[だれ]も切[き]らない。", "sentence_source": "generated"}, {"text": "お年寄りから地域の言い伝えを聞く授業があった。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "お年寄[としよ]りから地域[ちいき]の言い伝え[いいつたえ]を聞[き]く授業[じゅぎょう]があった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "言い伝え", "label": "基本形"}, {"form": "言い伝える", "label": "動詞形"}, {"form": "言い伝えられる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "昔から人々の間で話して伝えられてきた話", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c060a24-146e-49fd-8615-760bc8dc184c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38534, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "言い伝え", "is_correct": true, "explanation": "昔から語り継がれた話の意味で、山の神様についての話に合う。"}, {"text": "時刻表", "is_correct": false, "explanation": "予定を示す表で、神様についての話には合わない。"}, {"text": "天気図", "is_correct": false, "explanation": "天気を示す図で、神様についての話には合わない。"}, {"text": "会計簿", "is_correct": false, "explanation": "お金の記録で、神様についての話には合わない。"}], "explanations": {"言い伝え": "昔から語り継がれた話の意味で、山の神様についての話に合う。", "時刻表": "予定を示す表で、神様についての話には合わない。", "天気図": "天気を示す図で、神様についての話には合わない。", "会計簿": "お金の記録で、神様についての話には合わない。"}, "sentence_index": 0, "correct_answer": "言い伝え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の議事録は、言い伝えとして保存している。", "explanation": "ここは〈記録〉の意味。言い伝えは文字に書かず口で伝えられるもので、書いた記録には使わない。"}, {"text": "本部から、新しい規則の言い伝えが届いた。", "explanation": "ここは〈通達〉の意味。言い伝えは昔から語り継がれた話で、組織からの連絡には使わない。"}, {"text": "その試験の問題は、前日に言い伝えとして公表された。", "explanation": "ここは〈公表〉の意味。言い伝えは人々の間で語り継がれたもので、公式な発表には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38534, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "言い伝え", "is_correct": true, "explanation": "町に伝わる話の意味で、集めて本にまとめる対象に合う。"}, {"text": "乗車券", "is_correct": false, "explanation": "乗り物の切符で、本にまとめる対象ではない。"}, {"text": "呼吸", "is_correct": false, "explanation": "体の動きで、集めて本にまとめる対象ではない。"}, {"text": "寝袋", "is_correct": false, "explanation": "眠るための道具で、本にまとめる対象ではない。"}], "explanations": {"言い伝え": "町に伝わる話の意味で、集めて本にまとめる対象に合う。", "乗車券": "乗り物の切符で、本にまとめる対象ではない。", "呼吸": "体の動きで、集めて本にまとめる対象ではない。", "寝袋": "眠るための道具で、本にまとめる対象ではない。"}, "sentence_index": 6, "correct_answer": "言い伝え"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先月の売上を、言い伝えとして部長に報告した。", "explanation": "ここは〈報告〉の意味。言い伝えは昔から伝わる話で、業務の報告には使わない。"}, {"text": "両社は、言い伝えを結んで取引を始めた。", "explanation": "ここは〈契約〉の意味。言い伝えは約束事ではなく、語り継がれた話を指す。"}, {"text": "友達に、言い伝えの年賀状を送った。", "explanation": "ここは〈年賀状〉の意味。言い伝えは口で語り継がれた話で、挨拶状には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38534, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父から聞いた言い伝えを、本になった。", "corrected_sentence": "祖父から聞いた言い伝えが、本になった。", "error_description": "「言い伝えが本になった」の主語は「が」。「を」にすると「本になった」と続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38534, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村の言い伝えに、子どもたちに話す。", "corrected_sentence": "村の言い伝えを、子どもたちに話す。", "error_description": "「言い伝えを話す」の「を」が正しい。「言い伝えに」では話す内容として働かず、格助詞の選び方が誤っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38535, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「言い伝えが多い」の「が」。多いものを主語として示す形になる。"}, {"text": "を", "is_correct": false, "explanation": "「言い伝えを多い」は成立せず、目的語の「を」は形容詞の文に合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」では「言い伝えで多い」とならず、文として成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「多い」の主語にはならず、文が成立しない。"}], "correct_answer": "が", "explanations": {"が": "「言い伝えが多い」の「が」。多いものを主語として示す形になる。", "を": "「言い伝えを多い」は成立せず、目的語の「を」は形容詞の文に合わない。", "で": "手段の「で」では「言い伝えで多い」とならず、文として成立しない。", "へ": "方向の「へ」は「多い」の主語にはならず、文が成立しない。"}, "error_tags": {"を": "object", "で": "means", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38535, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「言い伝えで守られてきた」の「で」。手段や方法を示し、守られてきた理由を表す。"}, {"text": "を", "is_correct": false, "explanation": "「言い伝えを守られてきた」は受身の形に合わず、目的語の「を」は成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「言い伝えと守られてきた」は共同や相手を示す形で、この文には合わない。"}, {"text": "の", "is_correct": false, "explanation": "所有や修飾の「の」では「守られてきた」の手段を示せず、文が成立しない。"}], "correct_answer": "で", "explanations": {"で": "「言い伝えで守られてきた」の「で」。手段や方法を示し、守られてきた理由を表す。", "を": "「言い伝えを守られてきた」は受身の形に合わず、目的語の「を」は成立しない。", "と": "「言い伝えと守られてきた」は共同や相手を示す形で、この文には合わない。", "の": "所有や修飾の「の」では「守られてきた」の手段を示せず、文が成立しない。"}, "error_tags": {"を": "object", "と": "accompaniment", "の": "possessive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38535, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "古くから語り継がれてきた話や知識。特に、文字に書かれずに口で伝えられてきたもの。", "primary_collocate": null, "pronunciation": "いいつたえ", "ipa": "iːtsɯtae", "syllable_count": 5, "sentences": [{"text": "文字のない時代の知恵は、言い伝えとして残った。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "文字[もじ]のない時代[じだい]の知恵[ちえ]は、言い伝え[いいつたえ]として残[のこ]った。", "sentence_source": "generated"}, {"text": "漁師たちの間には、天気を読む言い伝えが多い。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "漁師[りょうし]たちの間[あいだ]には、天気[てんき]を読[よ]む言い伝え[いいつたえ]が多[おお]い。", "sentence_source": "generated"}, {"text": "言い伝えは書物ではなく、口から口へと受け継がれた。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "言い伝え[いいつたえ]は書物[しょもつ]ではなく、口[くち]から口[くち]へと受[う]け継[つ]がれた。", "sentence_source": "generated"}, {"text": "農家の言い伝えでは、ツバメが低く飛ぶと雨が降る。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "農家[のうか]の言い伝え[いいつたえ]では、ツバメが低[ひく]く飛[と]ぶと雨[あめ]が降[ふ]る。", "sentence_source": "generated"}, {"text": "この薬草の使い方は、家に伝わる言い伝えで学んだ。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "この薬草[やくそう]の使[つか]い方[かた]は、家[いえ]に伝[つた]わる言い伝え[いいつたえ]で学[まな]んだ。", "sentence_source": "generated"}, {"text": "祖父は、山での暮らしの言い伝えをたくさん知っている。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "祖父[そふ]は、山[やま]での暮[く]らしの言い伝え[いいつたえ]をたくさん知[し]っている。", "sentence_source": "generated"}, {"text": "記録がないので、言い伝えだけが手がかりだ。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "記録[きろく]がないので、言い伝え[いいつたえ]だけが手[て]がかりだ。", "sentence_source": "generated"}, {"text": "民族の歴史は、長い間言い伝えで守られてきた。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "民族[みんぞく]の歴史[れきし]は、長[なが]い間[あいだ]言い伝え[いいつたえ]で守[まも]られてきた。", "sentence_source": "generated"}, {"text": "船乗りの言い伝えに、星の位置で方角を知る方法がある。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "船乗[ふなの]りの言い伝え[いいつたえ]に、星[ほし]の位置[いち]で方角[ほうがく]を知[し]る方法[ほうほう]がある。", "sentence_source": "generated"}, {"text": "言い伝えが消える前に、録音して残しておきたい。", "target_word": "言い伝え", "complexity_tier": "T3", "furigana": "言い伝え[いいつたえ]が消[き]える前[まえ]に、録音[ろくおん]して残[のこ]しておきたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "言い伝え", "label": "基本形"}, {"form": "言い伝える", "label": "動詞形"}, {"form": "言い伝えられる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "文字に書かれず口で受け継がれてきた話や知識", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c060a24-146e-49fd-8615-760bc8dc184c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38535, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "言い伝え", "is_correct": true, "explanation": "文字なしで口から受け継がれた知恵の意味で、残り方に合う。"}, {"text": "寝具", "is_correct": false, "explanation": "眠るための道具で、知恵が残る形としては合わない。"}, {"text": "手袋", "is_correct": false, "explanation": "手を守る道具で、知恵が残る形としては合わない。"}, {"text": "調味料", "is_correct": false, "explanation": "料理の味付けで、知恵が残る形としては合わない。"}], "explanations": {"言い伝え": "文字なしで口から受け継がれた知恵の意味で、残り方に合う。", "寝具": "眠るための道具で、知恵が残る形としては合わない。", "手袋": "手を守る道具で、知恵が残る形としては合わない。", "調味料": "料理の味付けで、知恵が残る形としては合わない。"}, "sentence_index": 0, "correct_answer": "言い伝え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この本は、言い伝えとして全三巻で出版された。", "explanation": "ここは〈出版物〉の意味。言い伝えは口で語り継がれるもので、印刷された本には使わない。"}, {"text": "買う物の言い伝えをメモにして、スーパーへ持って行った。", "explanation": "ここは〈買い物メモ〉の意味。言い伝えは口で語り継がれた話や知恵で、書いたメモとは違う。"}, {"text": "ピアノの言い伝えは、毎日練習して身につける。", "explanation": "ここは〈技能〉の意味。言い伝えは知恵や話で、練習で身につける技術には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38535, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "言い伝え", "is_correct": true, "explanation": "記録がないときに頼る、口で伝わる話の意味に合う。"}, {"text": "紅茶", "is_correct": false, "explanation": "飲み物で、手がかりになる話や知識ではない。"}, {"text": "石鹸", "is_correct": false, "explanation": "洗うための道具で、手がかりになる話や知識ではない。"}, {"text": "卵焼き", "is_correct": false, "explanation": "料理の名前で、手がかりになる話や知識ではない。"}], "explanations": {"言い伝え": "記録がないときに頼る、口で伝わる話の意味に合う。", "紅茶": "飲み物で、手がかりになる話や知識ではない。", "石鹸": "洗うための道具で、手がかりになる話や知識ではない。", "卵焼き": "料理の名前で、手がかりになる話や知識ではない。"}, "sentence_index": 6, "correct_answer": "言い伝え"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "論文の言い伝えを読んで、結果を比べた。", "explanation": "ここは〈研究〉の意味。言い伝えは語り継がれた話で、学術論文には使わない。"}, {"text": "この薬の言い伝えは、一日三回と箱に書いてある。", "explanation": "ここは〈用法〉の意味。言い伝えは昔の話や知恵で、薬の使い方の表示には使わない。"}, {"text": "来週の予定を、言い伝えとして手帳に書いた。", "explanation": "ここは〈予定〉の意味。言い伝えは昔から語り継がれたもので、未来の予定には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38535, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い言い伝えな知恵は、今も役立つ。", "corrected_sentence": "古い言い伝えの知恵は、今も役立つ。", "error_description": "「言い伝えの知恵」の「の」が正しい。言い伝えは名詞なので、「な」を付けて修飾することはできない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38535, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この村には、言い伝えを伝わる歌がある。", "corrected_sentence": "この村には、言い伝えとして伝わる歌がある。", "error_description": "「言い伝えとして伝わる」が正しい。「言い伝えを」は「伝わる」の目的語にならず、資格・立場を示す「として」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9452b99-6555-44f7-82ad-15bfe87bbac0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38536, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「おこづかいが不足している」で、不足している主体を示す「が」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「おこづかいを不足している」は成り立たず、「不足する」と合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ助詞で、「不足している」の主語を示せない。文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「おこづかいで不足している」は手段の形になり、文の意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「おこづかいが不足している」で、不足している主体を示す「が」が入る。", "を": "「おこづかいを不足している」は成り立たず、「不足する」と合わない。", "の": "「の」は名詞どうしをつなぐ助詞で、「不足している」の主語を示せない。文が成り立たない。", "で": "「おこづかいで不足している」は手段の形になり、文の意味が通らない。"}, "error_tags": {"を": "目的語を示す（「不足する」と合わない）", "の": "名詞をつなぐだけで主語を示せない（成り立たない）", "で": "手段を示す（成り立たない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38536, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ペンが不足していて」で、不足している主体を示す「が」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「ペンを不足していて」は成り立たず、「不足する」と合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所を示すが、「ペンで不足していて」は成り立たず不自然になる。"}, {"text": "と", "is_correct": false, "explanation": "「ペンと不足していて」は並列の形になり、文の意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「ペンが不足していて」で、不足している主体を示す「が」が入る。", "を": "「ペンを不足していて」は成り立たず、「不足する」と合わない。", "で": "「で」は手段・場所を示すが、「ペンで不足していて」は成り立たず不自然になる。", "と": "「ペンと不足していて」は並列の形になり、文の意味が通らない。"}, "error_tags": {"を": "目的語を示す（「不足する」と合わない）", "で": "手段を示す（成り立たない）", "と": "並列を示す（成り立たない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38536, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ほしいものが足りないこと。", "primary_collocate": null, "pronunciation": "ふそく", "ipa": "ɸɯsokɯ", "syllable_count": 3, "sentences": [{"text": "旅行に行きたいが、お金の不足で今年はあきらめた。", "target_word": "不足", "complexity_tier": "T3", "furigana": "旅行[りょこう]に行[い]きたいが、お金[かね]の不足[ふそく]で今年[ことし]はあきらめた。", "sentence_source": "generated"}, {"text": "新しいゲームを買うには、おこづかいが不足している。", "target_word": "不足", "complexity_tier": "T3", "furigana": "新[あたら]しいゲームを買[か]うには、おこづかいが不足[ふそく]している。", "sentence_source": "generated"}, {"text": "時間が不足して、見たい映画を全部は見られなかった。", "target_word": "不足", "complexity_tier": "T3", "furigana": "時間[じかん]が不足[ふそく]して、見[み]たい映画[えいが]を全部[ぜんぶ]は見[み]られなかった。", "sentence_source": "generated"}, {"text": "部屋に本棚がほしいが、置く場所の不足が悩みだ。", "target_word": "不足", "complexity_tier": "T3", "furigana": "部屋[へや]に本棚[ほんだな]がほしいが、置[お]く場所[ばしょ]の不足[ふそく]が悩[なや]みだ。", "sentence_source": "generated"}, {"text": "材料の不足に気づき、急いで店へ買いに走った。", "target_word": "不足", "complexity_tier": "T3", "furigana": "材料[ざいりょう]の不足[ふそく]に気[き]づき、急[いそ]いで店[みせ]へ買[か]いに走[はし]った。", "sentence_source": "generated"}, {"text": "十人で遊ぶには、ボールが不足している。", "target_word": "不足", "complexity_tier": "T3", "furigana": "十人[じゅうにん]で遊[あそ]ぶには、ボールが不足[ふそく]している。", "sentence_source": "generated"}, {"text": "料理を作っていたら、塩が不足していたので足した。", "target_word": "不足", "complexity_tier": "T3", "furigana": "料理[りょうり]を作[つく]っていたら、塩[しお]が不足[ふそく]していたので足[た]した。", "sentence_source": "generated"}, {"text": "ほしい色のペンが不足していて、全部はそろわなかった。", "target_word": "不足", "complexity_tier": "T3", "furigana": "ほしい色[いろ]のペンが不足[ふそく]していて、全部[ぜんぶ]はそろわなかった。", "sentence_source": "generated"}, {"text": "机の数が不足して、何人かは床に座った。", "target_word": "不足", "complexity_tier": "T3", "furigana": "机[つくえ]の数[かず]が不足[ふそく]して、何人[なんにん]かは床[ゆか]に座[すわ]った。", "sentence_source": "generated"}, {"text": "友だちに借りた分で、なんとか不足を補った。", "target_word": "不足", "complexity_tier": "T3", "furigana": "友[とも]だちに借[か]りた分[ぶん]で、なんとか不足[ふそく]を補[おぎな]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "不足", "label": "基本形"}, {"form": "不足する", "label": "動詞形"}, {"form": "不足している", "label": "継続形"}], "register": "neutral", "sense_fingerprint": "ほしい物・お金・時間などが望む量に届かないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: そろわ (Zipf 2.29)']::text[], '0fa4e591-0cd8-4cce-86d4-2d04b8b274fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38536, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不足", "is_correct": true, "explanation": "「お金の不足で」で、お金が足りないことを表し、今年あきらめた理由として文に合う。"}, {"text": "体調", "is_correct": false, "explanation": "体調は体のぐあい。お金の状態を理由として述べる文脈には合わない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は春夏秋冬などの時期。お金の事情を理由として表せない。"}, {"text": "友情", "is_correct": false, "explanation": "友情は友だちどうしの気持ち。お金の事情を表す語ではない。"}], "explanations": {"不足": "「お金の不足で」で、お金が足りないことを表し、今年あきらめた理由として文に合う。", "体調": "体調は体のぐあい。お金の状態を理由として述べる文脈には合わない。", "季節": "季節は春夏秋冬などの時期。お金の事情を理由として表せない。", "友情": "友情は友だちどうしの気持ち。お金の事情を表す語ではない。"}, "sentence_index": 0, "correct_answer": "不足"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎週末、不足の山歩きを楽しんでいる。", "explanation": "ここは〈趣味〉の意味。不足は足りないことで、楽しみとして続ける活動を指す語ではない。"}, {"text": "カレーを作ったので、不足を冷凍した。", "explanation": "ここは〈余り〉の意味。不足は足りないことで、食べずに残った分を指すときには使わない。"}, {"text": "練習の後で、部員たちは不足を一緒に食べて、大きな声で笑った。", "explanation": "ここは〈食べ物〉の意味。不足は足りないことで、食べ物を指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38536, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不足", "is_correct": true, "explanation": "「塩が不足していたので足した」で、塩が足りなかったことを表し文に合う。"}, {"text": "愛着", "is_correct": false, "explanation": "愛着はものに親しみを感じること。塩の足りなさを表すには合わない。"}, {"text": "退屈", "is_correct": false, "explanation": "退屈は時間をもてあますこと。塩の状態を言い表せない。"}, {"text": "好奇心", "is_correct": false, "explanation": "好奇心は知りたいと思う気持ち。塩の量を表す語ではない。"}], "explanations": {"不足": "「塩が不足していたので足した」で、塩が足りなかったことを表し文に合う。", "愛着": "愛着はものに親しみを感じること。塩の足りなさを表すには合わない。", "退屈": "退屈は時間をもてあますこと。塩の状態を言い表せない。", "好奇心": "好奇心は知りたいと思う気持ち。塩の量を表す語ではない。"}, "sentence_index": 6, "correct_answer": "不足"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の試験が不足で、夜も眠れない。", "explanation": "ここは〈不安〉の意味。不足は量が足りないことで、心配な気持ちを表す場面には使わない。"}, {"text": "使わない道具は不足だから、思い切って捨てた。", "explanation": "ここは〈不要〉の意味。不足は足りないことで、いらないものを指すときには使わない。"}, {"text": "友だちとの別れで、胸に不足があふれた。", "explanation": "ここは〈悲しみ〉の意味。不足は量が欠けることで、心の痛みを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38536, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教室の机が不足させて、何人かは床に座った。", "corrected_sentence": "教室の机が不足して、何人かは床に座った。", "error_description": "「机が」を主語にするなら「不足して」が正しい。「不足させる」は「〜を不足させる」のように目的語を取るため、主語の「机が」とは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38536, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "おやつの量を不足して、みんなで分けた。", "corrected_sentence": "おやつの量が不足して、みんなで分けた。", "error_description": "「不足する」の助詞が誤り。不足は自動詞なので「が」が必要で、「を」は目的語を示すため合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38537, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「不足すると」の「と」。不足という条件から結果を導く形で、文の流れに合う。"}, {"text": "を", "is_correct": false, "explanation": "「不足を」は目的語になれず、「不足する」は主語が「が」で続く動きなので文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「不足するで」は文法的に続かない。理由や手段の「で」は名詞に付く。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は行き先を示すので、状態を表す「不足する」の後ろには合わない。"}], "correct_answer": "と", "explanations": {"と": "「不足すると」の「と」。不足という条件から結果を導く形で、文の流れに合う。", "を": "「不足を」は目的語になれず、「不足する」は主語が「が」で続く動きなので文が成り立たない。", "で": "「不足するで」は文法的に続かない。理由や手段の「で」は名詞に付く。", "へ": "「へ」は行き先を示すので、状態を表す「不足する」の後ろには合わない。"}, "error_tags": {"を": "目的語", "で": "接続", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "過剰", "is_correct": true, "explanation": "「過剰」は必要以上にあることで、「不足」の対義語。"}, {"text": "教室", "is_correct": false, "explanation": "「教室」は学ぶ場所を指す具体的な名詞で、「不足」の対義語ではない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕方の空の色を表す語で、「不足」と対になる語ではない。"}, {"text": "名前", "is_correct": false, "explanation": "人や物につける呼び名で、「不足」の対義語にはならない。"}], "correct_answer": "過剰", "explanations": {"過剰": "「過剰」は必要以上にあることで、「不足」の対義語。", "教室": "「教室」は学ぶ場所を指す具体的な名詞で、「不足」の対義語ではない。", "夕焼け": "夕方の空の色を表す語で、「不足」と対になる語ではない。", "名前": "人や物につける呼び名で、「不足」の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38537, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "過剰", "is_correct": true, "explanation": "「過剰」は必要以上の量のことで、「不足」の対義語。"}, {"text": "公園", "is_correct": false, "explanation": "人が遊ぶ場所を指す名詞で、「不足」の対義語ではない。"}, {"text": "手紙", "is_correct": false, "explanation": "気持ちや用件を伝える文書で、「不足」と対になる語ではない。"}, {"text": "季節", "is_correct": false, "explanation": "一年を区切った時期を表し、「不足」の対義語にはならない。"}], "correct_answer": "過剰", "explanations": {"過剰": "「過剰」は必要以上の量のことで、「不足」の対義語。", "公園": "人が遊ぶ場所を指す名詞で、「不足」の対義語ではない。", "手紙": "気持ちや用件を伝える文書で、「不足」と対になる語ではない。", "季節": "一年を区切った時期を表し、「不足」の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38537, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "必要なものが欠けている状態。", "primary_collocate": null, "pronunciation": "ふそく", "ipa": "ɸɯsokɯ", "syllable_count": 3, "sentences": [{"text": "山の村では、冬になると水の不足が問題になる。", "target_word": "不足", "complexity_tier": "T3", "furigana": "山[やま]の村[むら]では、冬[ふゆ]になると水[みず]の不足[ふそく]が問題[もんだい]になる。", "sentence_source": "generated"}, {"text": "栄養が不足すると、体の調子がくずれやすい。", "target_word": "不足", "complexity_tier": "T3", "furigana": "栄養[えいよう]が不足[ふそく]すると、体[からだ]の調子[ちょうし]がくずれやすい。", "sentence_source": "generated"}, {"text": "病院では医者の不足が深刻になっている。", "target_word": "不足", "complexity_tier": "T3", "furigana": "病院[びょういん]では医者[いしゃ]の不足[ふそく]が深刻[しんこく]になっている。", "sentence_source": "generated"}, {"text": "説明の不足で、客に誤解されてしまった。", "target_word": "不足", "complexity_tier": "T3", "furigana": "説明[せつめい]の不足[ふそく]で、客[きゃく]に誤解[ごかい]されてしまった。", "sentence_source": "generated"}, {"text": "情報が不足しているので、まだ結論は出せない。", "target_word": "不足", "complexity_tier": "T3", "furigana": "情報[じょうほう]が不足[ふそく]しているので、まだ結論[けつろん]は出[だ]せない。", "sentence_source": "generated"}, {"text": "計画に不足している点を、みんなで話し合った。", "target_word": "不足", "complexity_tier": "T3", "furigana": "計画[けいかく]に不足[ふそく]している点[てん]を、みんなで話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "資金の不足から、工事は途中で止まった。", "target_word": "不足", "complexity_tier": "T3", "furigana": "資金[しきん]の不足[ふそく]から、工事[こうじ]は途中[とちゅう]で止[と]まった。", "sentence_source": "generated"}, {"text": "練習の不足が、試合の結果にはっきり出た。", "target_word": "不足", "complexity_tier": "T3", "furigana": "練習[れんしゅう]の不足[ふそく]が、試合[しあい]の結果[けっか]にはっきり出[で]た。", "sentence_source": "generated"}, {"text": "食料が不足したときに備えて、水と米を買っておく。", "target_word": "不足", "complexity_tier": "T3", "furigana": "食料[しょくりょう]が不足[ふそく]したときに備[そな]えて、水[みず]と米[こめ]を買[か]っておく。", "sentence_source": "generated"}, {"text": "彼の話は証拠の不足が目立ち、信じにくかった。", "target_word": "不足", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は証拠[しょうこ]の不足[ふそく]が目立[めだ]ち、信[しん]じにくかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "不足", "label": "基本形"}, {"form": "不足する", "label": "動詞形"}, {"form": "不足している", "label": "継続形"}], "register": "neutral", "sense_fingerprint": "水・栄養・人員・情報など必要なものが欠けて問題になる状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fa4e591-0cd8-4cce-86d4-2d04b8b274fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38537, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不足", "is_correct": true, "explanation": "「不足」は必要なものが欠けている状態。水が足りないことが問題になるという文に合う。"}, {"text": "友情", "is_correct": false, "explanation": "友情は人どうしの心のつながりで、水の状態を表す語ではないので文が成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空の様子を表す語で、「水の天気」は意味をなさない。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は手紙や荷物の配達のことで、水の問題には当てはまらない。"}], "explanations": {"不足": "「不足」は必要なものが欠けている状態。水が足りないことが問題になるという文に合う。", "友情": "友情は人どうしの心のつながりで、水の状態を表す語ではないので文が成り立たない。", "天気": "天気は空の様子を表す語で、「水の天気」は意味をなさない。", "郵便": "郵便は手紙や荷物の配達のことで、水の問題には当てはまらない。"}, "sentence_index": 0, "correct_answer": "不足"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この鍋は具材が不足するほど入っていて、食べきれなかった。", "explanation": "ここは〈過剰〉の意味。不足は必要なものが欠けていることなので、たくさんありすぎる具材には合わない。"}, {"text": "駅が遠くて、通学が不足だ。", "explanation": "ここは〈不便〉の意味。不足は物や量が足りないことで、通いにくさには使わない。"}, {"text": "この古い雑誌は不足になったので、捨てた。", "explanation": "ここは〈不要〉の意味。不足は必要なものが欠けることで、もう使わない物には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38537, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不足", "is_correct": true, "explanation": "資金が足りないから工事が途中で止まった、という因果に合う。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽は演奏や曲のことで、資金の状態を表す語としては文が成り立たない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は生き物が生きられる期間を表し、資金には使えない。"}, {"text": "雑誌", "is_correct": false, "explanation": "雑誌は定期的に出る本で、工事が止まった理由としては意味が通らない。"}], "explanations": {"不足": "資金が足りないから工事が途中で止まった、という因果に合う。", "音楽": "音楽は演奏や曲のことで、資金の状態を表す語としては文が成り立たない。", "寿命": "寿命は生き物が生きられる期間を表し、資金には使えない。", "雑誌": "雑誌は定期的に出る本で、工事が止まった理由としては意味が通らない。"}, "sentence_index": 6, "correct_answer": "不足"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その匂いはとても不足で、窓を開けた。", "explanation": "ここは〈不快〉の意味。不足は必要なものが欠けている状態で、においや気分には使わない。"}, {"text": "その判決は不足だと、みんなが怒った。", "explanation": "ここは〈不当〉の意味。不足は量が足りないことで、判断が正しくないことには使わない。"}, {"text": "応募者は全員不足になった。", "explanation": "ここは〈不採用〉の意味。不足は必要なものが欠けることで、選ばれなかったことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38537, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この地域は雨が少なく、農業用水を不足が続いている。", "corrected_sentence": "この地域は雨が少なく、農業用水の不足が続いている。", "error_description": "「不足」の前の名詞は「の」で続ける。「を」は動作の対象を示すので、「農業用水を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38537, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "避難所では、物資が不足ている状態が続いた。", "corrected_sentence": "避難所では、物資が不足している状態が続いた。", "error_description": "継続を表すには「不足している」とする。「不足ている」は「している」の活用が欠けていて誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
