INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38538, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "川や湖、雨などの水が、地面の上や地下でどのように動くかを研究する学問です。", "primary_collocate": null, "pronunciation": "すいもん", "ipa": "sɯimoɴ", "syllable_count": 4, "sentences": [{"text": "大学で水文を学び、川の洪水について研究している。", "target_word": "水文", "complexity_tier": "T3", "furigana": "大学[だいがく]で水文[すいもん]を学[まな]び、川[かわ]の洪水[こうずい]について研究[けんきゅう]している。", "sentence_source": "generated"}, {"text": "水文の専門家が、川の水の流れを調べている。", "target_word": "水文", "complexity_tier": "T3", "furigana": "水文[すいもん]の専門家[せんもんか]が、川[かわ]の水[みず]の流[なが]れを調[しら]べている。", "sentence_source": "generated"}, {"text": "水文は、雨が地面にしみこんだあとの水の動きを研究する学問だ。", "target_word": "水文", "complexity_tier": "T3", "furigana": "水文[すいもん]は、雨[あめ]が地面[じめん]にしみこんだあとの水[みず]の動[うご]きを研究[けんきゅう]する学問[がくもん]だ。", "sentence_source": "generated"}, {"text": "水文の知識があれば、大雨のときの川の変化を予想しやすい。", "target_word": "水文", "complexity_tier": "T3", "furigana": "水文[すいもん]の知識[ちしき]があれば、大雨[おおあめ]のときの川[かわ]の変化[へんか]を予想[よそう]しやすい。", "sentence_source": "generated"}, {"text": "この町では、水文の研究が防災に役立てられている。", "target_word": "水文", "complexity_tier": "T3", "furigana": "この町[まち]では、水文[すいもん]の研究[けんきゅう]が防災[ぼうさい]に役立[やくだ]てられている。", "sentence_source": "generated"}, {"text": "姉は水文に興味を持ち、理学部に進んだ。", "target_word": "水文", "complexity_tier": "T3", "furigana": "姉[あね]は水文[すいもん]に興味[きょうみ]を持[も]ち、理学部[りがくぶ]に進[すす]んだ。", "sentence_source": "generated"}, {"text": "水文の先生は、湖の水が地下へしみこむ様子を説明した。", "target_word": "水文", "complexity_tier": "T3", "furigana": "水文[すいもん]の先生[せんせい]は、湖[みずうみ]の水[みず]が地下[ちか]へしみこむ様子[ようす]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "水不足の対策を考えるとき、水文の考え方が大切になる。", "target_word": "水文", "complexity_tier": "T3", "furigana": "水不足[みずぶそく]の対策[たいさく]を考[かんが]えるとき、水文[すいもん]の考[かんが]え方[かた]が大切[たいせつ]になる。", "sentence_source": "generated"}, {"text": "水文の授業で、川の水量を測る方法を習った。", "target_word": "水文", "complexity_tier": "T3", "furigana": "水文[すいもん]の授業[じゅぎょう]で、川[かわ]の水量[すいりょう]を測[はか]る方法[ほうほう]を習[なら]った。", "sentence_source": "generated"}, {"text": "水文を研究する人たちは、雨と川の関係を長い間記録している。", "target_word": "水文", "complexity_tier": "T3", "furigana": "水文[すいもん]を研究[けんきゅう]する人[ひと]たちは、雨[あめ]と川[かわ]の関係[かんけい]を長[なが]い間[あいだ]記録[きろく]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水文", "label": "基本形"}], "register": "formal", "sense_fingerprint": "川・湖・雨・地下水など自然界の水の動きを調べる学問分野", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: しみこん (Zipf 1.79)','sentence 6 above tier T2: contains vocabulary far above tier T2: しみこむ (Zipf 1.46)']::text[], '0fa4e591-0cd8-4cce-86d4-2d04b8b274fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38538, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水文", "is_correct": true, "explanation": "「水文」は水の動きを研究する学問で、大学で学ぶ対象として文が成り立つ。"}, {"text": "友情", "is_correct": false, "explanation": "友情は人間関係の気持ちで、大学で学ぶ学問ではないので合わない。"}, {"text": "遠慮", "is_correct": false, "explanation": "遠慮は人に気を遣う態度で、学ぶ対象の学問にはならない。"}, {"text": "緊張", "is_correct": false, "explanation": "緊張は心の状態で、大学で学ぶ学問として文が成り立たない。"}], "explanations": {"水文": "「水文」は水の動きを研究する学問で、大学で学ぶ対象として文が成り立つ。", "友情": "友情は人間関係の気持ちで、大学で学ぶ学問ではないので合わない。", "遠慮": "遠慮は人に気を遣う態度で、学ぶ対象の学問にはならない。", "緊張": "緊張は心の状態で、大学で学ぶ学問として文が成り立たない。"}, "sentence_index": 0, "correct_answer": "水文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蛇口をひねると、水文の水が濁って出てきた。", "explanation": "ここは〈水道〉の意味。水文は学問の分野で、蛇口から出る水には使わない。"}, {"text": "この山は村の水文になっている。", "explanation": "ここは〈水源〉の意味。水文は学問の分野で、水が生まれる場所には使わない。"}, {"text": "大雨で水文が起きた。", "explanation": "ここは〈水害〉の意味。水文は学問の分野で、大雨が引き起こす被害には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38538, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水文", "is_correct": true, "explanation": "「水文の先生」は学問分野の先生で、湖の水が地下へしみこむ様子を説明する文に合う。"}, {"text": "玄関", "is_correct": false, "explanation": "玄関は家の入口で、「玄関の先生」と言うと意味が通らない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は眠くなる感覚で、先生の専門や職業を表す語にはならない。"}, {"text": "腹痛", "is_correct": false, "explanation": "腹痛は体の痛みで、先生に付く語として意味をなさない。"}], "explanations": {"水文": "「水文の先生」は学問分野の先生で、湖の水が地下へしみこむ様子を説明する文に合う。", "玄関": "玄関は家の入口で、「玄関の先生」と言うと意味が通らない。", "眠気": "眠気は眠くなる感覚で、先生の専門や職業を表す語にはならない。", "腹痛": "腹痛は体の痛みで、先生に付く語として意味をなさない。"}, "sentence_index": 6, "correct_answer": "水文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "暑い日は、水文を補給するのを忘れないようにしよう。", "explanation": "ここは〈水分〉の意味。水文は学問の分野で、体に補給できるものではない。"}, {"text": "朝の空が水文に広がった。", "explanation": "ここは〈水色〉の意味。水文は学問の名前で、空の色には使えない。"}, {"text": "川の水文が深いので、船は出せなかった。", "explanation": "ここは〈水深〉の意味。水文は学問の分野で、水の深さを表す語ではないので、川の深さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38538, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は水文が興味を持ち、大学で研究を続けている。", "corrected_sentence": "兄は水文に興味を持ち、大学で研究を続けている。", "error_description": "「興味を持つ」の対象には「に」を使う。「水文が」は誤りで、「水文に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38538, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水文を研究た人は、川の水量を毎月測っている。", "corrected_sentence": "水文を研究した人は、川の水量を毎月測っている。", "error_description": "「研究する」の過去の形は「研究した」。「研究た」は動詞の活用が誤っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
