INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38539, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「水文の授業」の「の」。水文が授業の分野であることを示す。"}, {"text": "が", "is_correct": false, "explanation": "「先生は水文が授業で」は、水文を主語にすると文の流れが崩れる。"}, {"text": "を", "is_correct": false, "explanation": "「水文を授業で」は目的語の形になり、授業の分野を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「水文へ授業で」は方向を表すが、分野を示す意味にはならない。"}], "correct_answer": "の", "explanations": {"の": "「水文の授業」の「の」。水文が授業の分野であることを示す。", "が": "「先生は水文が授業で」は、水文を主語にすると文の流れが崩れる。", "を": "「水文を授業で」は目的語の形になり、授業の分野を示せない。", "へ": "「水文へ授業で」は方向を表すが、分野を示す意味にはならない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38539, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "地球上の水の分布や循環、水と環境との関係を科学的に研究する分野。", "primary_collocate": null, "pronunciation": "すいもん", "ipa": "sɯimoɴ", "syllable_count": 4, "sentences": [{"text": "彼は大学院で水文を専攻し、川の流れを研究している。", "target_word": "水文", "complexity_tier": "T3", "furigana": "彼[かれ]は大学院[だいがくいん]で水文[すいもん]を専攻[せんこう]し、川[かわ]の流[なが]れを研究[けんきゅう]している。", "sentence_source": "generated"}, {"text": "水文は、雨や川、地下水など地球上の水の動きを調べる学問だ。", "target_word": "水文", "complexity_tier": "T3", "furigana": "水文[すいもん]は、雨[あめ]や川[かわ]、地下水[ちかすい]など地球上[ちきゅうじょう]の水[みず]の動[うご]きを調[しら]べる学問[がくもん]だ。", "sentence_source": "generated"}, {"text": "水文の専門家が、ダムの建設が川に与える影響を説明した。", "target_word": "水文", "complexity_tier": "T3", "furigana": "水文[すいもん]の専門家[せんもんか]が、ダムの建設[けんせつ]が川[かわ]に与[あた]える影響[えいきょう]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "水文を学ぶと、雨が川や海へ流れていく道すじがよくわかる。", "target_word": "水文", "complexity_tier": "T3", "furigana": "水文[すいもん]を学[まな]ぶと、雨[あめ]が川[かわ]や海[うみ]へ流[なが]れていく道[みち]すじがよくわかる。", "sentence_source": "generated"}, {"text": "この地域は雨が少ないので、水文の調査が欠かせない。", "target_word": "水文", "complexity_tier": "T3", "furigana": "この地域[ちいき]は雨[あめ]が少[すく]ないので、水文[すいもん]の調査[ちょうさ]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "姉は水文に興味があって、毎週末、近くの川の水量を測っている。", "target_word": "水文", "complexity_tier": "T3", "furigana": "姉[あね]は水文[すいもん]に興味[きょうみ]があって、毎週末[まいしゅうまつ]、近[ちか]くの川[かわ]の水量[すいりょう]を測[はか]っている。", "sentence_source": "generated"}, {"text": "水文の知識があれば、洪水の危険を前もって予測しやすくなる。", "target_word": "水文", "complexity_tier": "T3", "furigana": "水文[すいもん]の知識[ちしき]があれば、洪水[こうずい]の危険[きけん]を前[まえ]もって予測[よそく]しやすくなる。", "sentence_source": "generated"}, {"text": "先生は水文の授業で、地下水がどう循環するかを図で見せてくれた。", "target_word": "水文", "complexity_tier": "T3", "furigana": "先生[せんせい]は水文[すいもん]の授業[じゅぎょう]で、地下水[ちかすい]がどう循環[じゅんかん]するかを図[ず]で見[み]せてくれた。", "sentence_source": "generated"}, {"text": "水の循環を数字で調べるには、水文の考え方が役に立つ。", "target_word": "水文", "complexity_tier": "T3", "furigana": "水[みず]の循環[じゅんかん]を数字[すうじ]で調[しら]べるには、水文[すいもん]の考[かんが]え方[かた]が役[やく]に立[た]つ。", "sentence_source": "generated"}, {"text": "気候が変わると水の分布も変わるため、水文の研究は今とても重要だ。", "target_word": "水文", "complexity_tier": "T3", "furigana": "気候[きこう]が変[か]わると水[みず]の分布[ぶんぷ]も変[か]わるため、水文[すいもん]の研究[けんきゅう]は今[いま]とても重要[じゅうよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水文", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "水文：地球上の水の分布・循環を科学的に研究する学問分野", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: 道すじ (Zipf 1.43)']::text[], '0fa4e591-0cd8-4cce-86d4-2d04b8b274fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38539, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水文", "is_correct": true, "explanation": "「水文を専攻し」は学問分野を選ぶ意味で、大学院で川の流れを研究する文に合う。"}, {"text": "遠慮", "is_correct": false, "explanation": "遠慮は人に気を遣う態度で、専攻の対象となる学問ではない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は眠くなる感覚で、専攻する分野にはならない。"}, {"text": "腹痛", "is_correct": false, "explanation": "腹痛は体の痛みで、大学院で専攻する対象として文が成り立たない。"}], "explanations": {"水文": "「水文を専攻し」は学問分野を選ぶ意味で、大学院で川の流れを研究する文に合う。", "遠慮": "遠慮は人に気を遣う態度で、専攻の対象となる学問ではない。", "眠気": "眠気は眠くなる感覚で、専攻する分野にはならない。", "腹痛": "腹痛は体の痛みで、大学院で専攻する対象として文が成り立たない。"}, "sentence_index": 0, "correct_answer": "水文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大雨で川の水文が上がり、避難を呼びかけた。", "explanation": "ここは〈水位〉の意味。水文は学問の分野で、水かさのように上がる量ではない。"}, {"text": "夏になると、海で水文を買う人が増える。", "explanation": "ここは〈水着〉の意味。水文は学問の分野で、買える物ではない。"}, {"text": "やかんから水文が出ている。", "explanation": "ここは〈水蒸気〉の意味。水文は学問の分野で、湯気のように出る物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38539, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水文", "is_correct": true, "explanation": "「水文の知識」は学問の知識で、洪水の危険を予測しやすくするという文に合う。"}, {"text": "玄関", "is_correct": false, "explanation": "玄関は建物の入口で、「玄関の知識」は意味をなさない。"}, {"text": "友情", "is_correct": false, "explanation": "友情は人間関係の気持ちで、洪水の予測に関する知識の対象にはならない。"}, {"text": "緊張", "is_correct": false, "explanation": "緊張は心の状態で、予測の知識として文が成り立たない。"}], "explanations": {"水文": "「水文の知識」は学問の知識で、洪水の危険を予測しやすくするという文に合う。", "玄関": "玄関は建物の入口で、「玄関の知識」は意味をなさない。", "友情": "友情は人間関係の気持ちで、洪水の予測に関する知識の対象にはならない。", "緊張": "緊張は心の状態で、予測の知識として文が成り立たない。"}, "sentence_index": 6, "correct_answer": "水文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水文が低いので、川で泳ぐのは危ない。", "explanation": "ここは〈水温〉の意味。水文は学問の分野で、水の温度を表す語ではない。"}, {"text": "天井から水文がして、困った。", "explanation": "ここは〈水漏れ〉の意味。水文は学問の分野で、天井から漏れ出る水には使わない。"}, {"text": "水文模様の服を着た。", "explanation": "ここは〈水玉〉の意味。水文は学問の分野で、模様の名前には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38539, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は大学で水文が専攻し、川の水量を測っている。", "corrected_sentence": "彼女は大学で水文を専攻し、川の水量を測っている。", "error_description": "「専攻する」の対象は「を」で示す。「水文が」にすると主語になり、専攻する対象がなくなるため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38539, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は大学で水文を研究室に入り、地下水の流れを調べている。", "corrected_sentence": "彼は大学で水文の研究室に入り、地下水の流れを調べている。", "error_description": "『水文』は後ろの『研究室』を修飾する名詞なので『の』で続ける。『を』は目的語の印なので、『水文を研究室に入り』は文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
