INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38540, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "かたまって、うごかないこと。", "primary_collocate": null, "pronunciation": "せいてき", "ipa": "seːteki", "syllable_count": 4, "sentences": [{"text": "静的な絵が好きです。", "target_word": "静的", "complexity_tier": "T2", "furigana": "静的[せいてき]な絵[え]が好[す]きです。", "sentence_source": "generated"}, {"text": "この踊りは静的な感じがします。", "target_word": "静的", "complexity_tier": "T2", "furigana": "この踊[おど]りは静的[せいてき]な感[かん]じがします。", "sentence_source": "generated"}, {"text": "この彫刻は静的だ。", "target_word": "静的", "complexity_tier": "T1", "furigana": "この彫刻[ちょうこく]は静的[せいてき]だ。", "sentence_source": "generated"}, {"text": "静的な写真を一枚撮った。", "target_word": "静的", "complexity_tier": "T3", "furigana": "静的[せいてき]な写真[しゃしん]を一枚[いちまい]撮[と]った。", "sentence_source": "generated"}, {"text": "静的で動かない人形だった。", "target_word": "静的", "complexity_tier": "T3", "furigana": "静的[せいてき]で動[うご]かない人形[にんぎょう]だった。", "sentence_source": "generated"}, {"text": "静的に立つ像を見ました。", "target_word": "静的", "complexity_tier": "T2", "furigana": "静的[せいてき]に立[た]つ像[ぞう]を見[み]ました。", "sentence_source": "generated"}, {"text": "この映画は静的な場面が多い。", "target_word": "静的", "complexity_tier": "T3", "furigana": "この映画[えいが]は静的[せいてき]な場面[ばめん]が多[おお]い。", "sentence_source": "generated"}, {"text": "動きのない静的な景色だ。", "target_word": "静的", "complexity_tier": "T3", "furigana": "動[うご]きのない静的[せいてき]な景色[けしき]だ。", "sentence_source": "generated"}, {"text": "静的に見える花が風で揺れた。", "target_word": "静的", "complexity_tier": "T3", "furigana": "静的[せいてき]に見[み]える花[はな]が風[かぜ]で揺[ゆ]れた。", "sentence_source": "generated"}, {"text": "静的であるほど、見る人は落ち着く。", "target_word": "静的", "complexity_tier": "T4", "furigana": "静的[せいてき]であるほど、見[み]る人[ひと]は落[お]ち着[つ]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "静的な", "label": "活用"}, {"form": "静的に", "label": "活用"}, {"form": "静的だ", "label": "活用"}, {"form": "静的で", "label": "活用"}], "register": "plain", "sense_fingerprint": "形状詞 | かたまって動かないさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a6e59f-ea65-43a2-8a55-7ec9fc7d85ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38540, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "静的", "is_correct": true, "explanation": "せいてき。見出し語そのもの。"}, {"text": "成績", "is_correct": false, "explanation": "せいせき。「て」が「せ」に変わる。"}, {"text": "警笛", "is_correct": false, "explanation": "けいてき。「せ」が「け」に変わる。"}, {"text": "製鉄", "is_correct": false, "explanation": "せいてつ。「き」が「つ」に変わる。"}, {"text": "正式", "is_correct": false, "explanation": "せいしき。「て」が「し」に変わる。"}], "explanations": {"静的": "せいてき。見出し語そのもの。", "成績": "せいせき。「て」が「せ」に変わる。", "警笛": "けいてき。「せ」が「け」に変わる。", "製鉄": "せいてつ。「き」が「つ」に変わる。", "正式": "せいしき。「て」が「し」に変わる。"}, "sentence_index": null, "correct_answer": "静的"}, "level_3": {"options": [{"text": "静的", "is_correct": true, "explanation": "動かない絵という意味が合う。"}, {"text": "不便", "is_correct": false, "explanation": "形は合うが、絵の性質として意味が合わない。"}, {"text": "丈夫", "is_correct": false, "explanation": "形は合うが、絵の好みとして意味が合わない。"}, {"text": "失礼", "is_correct": false, "explanation": "形は合うが、絵を表す意味が合わない。"}], "explanations": {"静的": "動かない絵という意味が合う。", "不便": "形は合うが、絵の性質として意味が合わない。", "丈夫": "形は合うが、絵の好みとして意味が合わない。", "失礼": "形は合うが、絵を表す意味が合わない。"}, "sentence_index": 0, "correct_answer": "静的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "静的な水が、勢いよく流れていた。", "explanation": "「静的」は動かないさまで、勢いよく流れる水と矛盾する。"}, {"text": "彼は静的に走って、ゴールした。", "explanation": "「静的」は動かないことなので、走る動作とは矛盾する。"}, {"text": "このゲームは静的で、画面が激しく動く。", "explanation": "「静的」は動かないことなので、激しく動く画面とは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38540, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "静的", "is_correct": true, "explanation": "せいてき。見出し語そのもの。"}, {"text": "制定", "is_correct": false, "explanation": "せいてい。「き」が「い」に変わる。"}, {"text": "晴天", "is_correct": false, "explanation": "せいてん。「き」が「ん」に変わる。"}, {"text": "恣意的", "is_correct": false, "explanation": "しいてき。「せ」が「し」に変わる。"}], "explanations": {"静的": "せいてき。見出し語そのもの。", "制定": "せいてい。「き」が「い」に変わる。", "晴天": "せいてん。「き」が「ん」に変わる。", "恣意的": "しいてき。「せ」が「し」に変わる。"}, "sentence_index": null, "correct_answer": "静的"}, "level_3": {"options": [{"text": "静的", "is_correct": true, "explanation": "動きの少ない場面という意味で合う。"}, {"text": "空腹", "is_correct": false, "explanation": "形は合うが、場面の性質を表せない。"}, {"text": "丈夫", "is_correct": false, "explanation": "形は合うが、場面が丈夫だという意味は成り立たない。"}, {"text": "健康", "is_correct": false, "explanation": "形は合うが、場面の性質として意味が合わない。"}], "explanations": {"静的": "動きの少ない場面という意味で合う。", "空腹": "形は合うが、場面の性質を表せない。", "丈夫": "形は合うが、場面が丈夫だという意味は成り立たない。", "健康": "形は合うが、場面の性質として意味が合わない。"}, "sentence_index": 6, "correct_answer": "静的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "静的な祭りで、みんなが踊って叫んだ。", "explanation": "「静的」は動かないことで、踊って叫ぶ祭りと矛盾する。"}, {"text": "静的な犬が庭を元気に走り回っている。", "explanation": "「静的」は動かないことで、走り回る犬と矛盾する。"}, {"text": "静的な川は、速く流れて波が立っている。", "explanation": "「静的」は動かないことで、速く流れる川と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
