INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38541, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "状態や性質が、時間がたっても変わらないさま。", "primary_collocate": null, "pronunciation": "せいてき", "ipa": "seːteki", "syllable_count": 4, "sentences": [{"text": "結果として、建築は静的な物体ではなく、見る者によって絶えず意味が更新される開かれた場として再定義されるのです。", "target_word": "静的", "complexity_tier": "T6", "furigana": "結果[けっか]として、建築[けんちく]は静的[せいてき]な物体[ぶったい]ではなく、見[み]る者[もの]によって絶[た]えず意味[いみ]が更新[こうしん]される開[ひら]かれた場[ば]として再定義[さいていぎ]されるのです。", "sentence_source": "mined"}, {"text": "静的な規則は何年も変わらない。", "target_word": "静的", "complexity_tier": "T3", "furigana": "静的[せいてき]な規則[きそく]は何年[なんねん]も変[か]わらない。", "sentence_source": "generated"}, {"text": "静的なデータは頻繁に変わらない。", "target_word": "静的", "complexity_tier": "T3", "furigana": "静的[せいてき]なデータは頻繁[ひんぱん]に変[か]わらない。", "sentence_source": "generated"}, {"text": "このページの内容は静的で、毎日同じだ。", "target_word": "静的", "complexity_tier": "T3", "furigana": "このページの内容[ないよう]は静的[せいてき]で、毎日[まいにち]同[おな]じだ。", "sentence_source": "generated"}, {"text": "静的だった市場が、急に変わり始めた。", "target_word": "静的", "complexity_tier": "T3", "furigana": "静的[せいてき]だった市場[しじょう]が、急[きゅう]に変[か]わり始[はじ]めた。", "sentence_source": "generated"}, {"text": "彼の考え方は静的で、昔から変わらない。", "target_word": "静的", "complexity_tier": "T3", "furigana": "彼[かれ]の考[かんが]え方[かた]は静的[せいてき]で、昔[むかし]から変[か]わらない。", "sentence_source": "generated"}, {"text": "静的な構造は時間が経っても変わらない。", "target_word": "静的", "complexity_tier": "T3", "furigana": "静的[せいてき]な構造[こうぞう]は時間[じかん]が経[た]っても変[か]わらない。", "sentence_source": "generated"}, {"text": "静的なウェブページを作った。", "target_word": "静的", "complexity_tier": "T3", "furigana": "静的[せいてき]なウェブページを作[つく]った。", "sentence_source": "generated"}, {"text": "状態が静的に保たれている。", "target_word": "静的", "complexity_tier": "T4", "furigana": "状態[じょうたい]が静的[せいてき]に保[たも]たれている。", "sentence_source": "generated"}, {"text": "静的な状態から動的な状態へ変わる。", "target_word": "静的", "complexity_tier": "T3", "furigana": "静的[せいてき]な状態[じょうたい]から動的[どうてき]な状態[じょうたい]へ変[か]わる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "静的な", "label": "活用"}, {"form": "静的に", "label": "活用"}, {"form": "静的だ", "label": "活用"}, {"form": "静的で", "label": "活用"}], "register": "plain", "sense_fingerprint": "形状詞 | 時間がたっても状態が変わらないさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a6e59f-ea65-43a2-8a55-7ec9fc7d85ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
