INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38541, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "静的", "is_correct": true, "explanation": "せいてき。見出し語そのもの。"}, {"text": "製鉄", "is_correct": false, "explanation": "せいてつ。「き」が「つ」に変わる。"}, {"text": "晴天", "is_correct": false, "explanation": "せいてん。「き」が「ん」に変わる。"}, {"text": "正式", "is_correct": false, "explanation": "せいしき。「て」が「し」に変わる。"}], "explanations": {"静的": "せいてき。見出し語そのもの。", "製鉄": "せいてつ。「き」が「つ」に変わる。", "晴天": "せいてん。「き」が「ん」に変わる。", "正式": "せいしき。「て」が「し」に変わる。"}, "sentence_index": null, "correct_answer": "静的"}, "level_3": {"options": [{"text": "静的", "is_correct": true, "explanation": "時間が経っても変わらない構造に合う。"}, {"text": "派手", "is_correct": false, "explanation": "形は合うが、「変わらない」という内容と意味が合わない。"}, {"text": "贅沢", "is_correct": false, "explanation": "形は合うが、構造が変わらないという意味に合わない。"}, {"text": "有名", "is_correct": false, "explanation": "形は合うが、構造の性質として意味が合わない。"}], "explanations": {"静的": "時間が経っても変わらない構造に合う。", "派手": "形は合うが、「変わらない」という内容と意味が合わない。", "贅沢": "形は合うが、構造が変わらないという意味に合わない。", "有名": "形は合うが、構造の性質として意味が合わない。"}, "sentence_index": 6, "correct_answer": "静的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "静的なルールが、毎日書き換えられている。", "explanation": "「静的」は変わらないさまなので、毎日書き換えられることと矛盾する。"}, {"text": "このサイトは静的で、内容が毎分更新される。", "explanation": "「静的」は内容が変わらないことで、毎分の更新と矛盾する。"}, {"text": "静的な状況は、一日ごとに大きく変わった。", "explanation": "「静的」は時間がたっても変わらないさまで、大きく変わることと矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38541, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "静的なデータは毎秒変わり続ける。", "corrected_sentence": "静的なデータは頻繁に変わらない。", "error_description": "「静的」は時間がたっても変わらないさまなので、「毎秒変わり続ける」は矛盾する。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "静的な", "is_correct": true, "explanation": "名詞「規則」を修飾する連体形。"}, {"text": "静的だ", "is_correct": false, "explanation": "終止形で、名詞の前には置けない。"}, {"text": "静的です", "is_correct": false, "explanation": "丁寧な終止形で、名詞の前には置けない。"}, {"text": "静的ならば", "is_correct": false, "explanation": "仮定形で、名詞を修飾できない。"}], "correct_form": "静的な", "base_form": "静的", "form_label": "連体形（〜な）", "sentence_index": 1, "explanations": {"静的な": "名詞「規則」を修飾する連体形。", "静的だ": "終止形で、名詞の前には置けない。", "静的です": "丁寧な終止形で、名詞の前には置けない。", "静的ならば": "仮定形で、名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38541, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "静的な構造は時間とともに激しく変わる。", "corrected_sentence": "静的な構造は時間が経ってもほとんど変わらない。", "error_description": "「静的」は変わらないことなので、「激しく変わる」は矛盾する。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "静的な", "is_correct": true, "explanation": "名詞「ウェブページ」を修飾する連体形。"}, {"text": "静的だ", "is_correct": false, "explanation": "終止形で、名詞の前には置けない。"}, {"text": "静的でした", "is_correct": false, "explanation": "丁寧な過去形で、名詞を修飾できない。"}, {"text": "静的なら", "is_correct": false, "explanation": "条件形で、名詞の前には置けない。"}], "correct_form": "静的な", "base_form": "静的", "form_label": "連体形（〜な）", "sentence_index": 7, "explanations": {"静的な": "名詞「ウェブページ」を修飾する連体形。", "静的だ": "終止形で、名詞の前には置けない。", "静的でした": "丁寧な過去形で、名詞を修飾できない。", "静的なら": "条件形で、名詞の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38542, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「遺物を守る」の「を」。守る対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「遺物が、村の人たちは大切に守っている」では、遺物が主語になり、守る対象が抜ける。"}, {"text": "に", "is_correct": false, "explanation": "「遺物に守る」は対象の示し方として不自然で、「守る」には「を」を使う。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、守る対象を表す形にならない。"}], "correct_answer": "を", "explanations": {"を": "「遺物を守る」の「を」。守る対象を示す。", "が": "「遺物が、村の人たちは大切に守っている」では、遺物が主語になり、守る対象が抜ける。", "に": "「遺物に守る」は対象の示し方として不自然で、「守る」には「を」を使う。", "へ": "「へ」は方向を示すので、守る対象を表す形にならない。"}, "error_tags": {"が": "主語", "に": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
