INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38542, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "昔の人が残した、今も残っているもの。", "primary_collocate": null, "pronunciation": "いぶつ", "ipa": "ibɯt͡sɯ", "syllable_count": 3, "sentences": [{"text": "祖父の家の倉庫から、江戸時代の遺物が見つかった。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "祖父[そふ]の家[いえ]の倉庫[そうこ]から、江戸時代[えどじだい]の遺物[いぶつ]が見[み]つかった。", "sentence_source": "generated"}, {"text": "昔の人が残した遺物を、村の人たちは大切に守っている。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]が残[のこ]した遺物[いぶつ]を、村[むら]の人[ひと]たちは大切[たいせつ]に守[まも]っている。", "sentence_source": "generated"}, {"text": "この島には、古い時代の遺物が今も数多く残っている。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "この島[しま]には、古[ふる]い時代[じだい]の遺物[いぶつ]が今[いま]も数多[かずおお]く残[のこ]っている。", "sentence_source": "generated"}, {"text": "畑を耕していたら、土の中から遺物が出てきて驚いた。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "畑[はたけ]を耕[たがや]していたら、土[つち]の中[なか]から遺物[いぶつ]が出[で]てきて驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "遺物を見ると、昔の人がどんな暮らしをしていたか想像できる。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "遺物[いぶつ]を見[み]ると、昔[むかし]の人[ひと]がどんな暮[く]らしをしていたか想像[そうぞう]できる。", "sentence_source": "generated"}, {"text": "寺には、千年前の僧が使ったという遺物が大切にしまわれている。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "寺[てら]には、千年前[せんねんまえ]の僧[そう]が使[つか]ったという遺物[いぶつ]が大切[たいせつ]にしまわれている。", "sentence_source": "generated"}, {"text": "遺物は壊れやすいので、素手でさわってはいけない。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "遺物[いぶつ]は壊[こわ]れやすいので、素手[すで]でさわってはいけない。", "sentence_source": "generated"}, {"text": "洞窟の奥で、昔の人が残した遺物が見つかり、調査が始まった。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "洞窟[どうくつ]の奥[おく]で、昔[むかし]の人[ひと]が残[のこ]した遺物[いぶつ]が見[み]つかり、調査[ちょうさ]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "この石の道具は、遠い昔の人が残した貴重な遺物だ。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "この石[いし]の道具[どうぐ]は、遠[とお]い昔[むかし]の人[ひと]が残[のこ]した貴重[きちょう]な遺物[いぶつ]だ。", "sentence_source": "generated"}, {"text": "古い遺物が出た場所では、工事を止めて調べることになっている。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "古[ふる]い遺物[いぶつ]が出[で]た場所[ばしょ]では、工事[こうじ]を止[と]めて調[しら]べることになっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遺物", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "遺物：昔の人が残し、今も手元や土地に残っているもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fa4e591-0cd8-4cce-86d4-2d04b8b274fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38542, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遺物", "is_correct": true, "explanation": "「遺物」は昔の人が残したもので、江戸時代の遺物が見つかったという文に合う。"}, {"text": "雷", "is_correct": false, "explanation": "雷は空で起きる現象で、江戸時代のものとして見つかる語ではない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは夕方の空の色で、倉庫から見つかるものではない。"}, {"text": "影", "is_correct": false, "explanation": "影は光でできる暗い部分で、江戸時代のものとして見つかるとは言えない。"}], "explanations": {"遺物": "「遺物」は昔の人が残したもので、江戸時代の遺物が見つかったという文に合う。", "雷": "雷は空で起きる現象で、江戸時代のものとして見つかる語ではない。", "夕焼け": "夕焼けは夕方の空の色で、倉庫から見つかるものではない。", "影": "影は光でできる暗い部分で、江戸時代のものとして見つかるとは言えない。"}, "sentence_index": 0, "correct_answer": "遺物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "恐竜の骨の遺物が、この地層から発見された。", "explanation": "ここは〈化石〉の意味。遺物は昔の人が残したものなので、恐竜の骨には使わない。"}, {"text": "墜落した飛行機の遺物が、海岸に流れ着いた。", "explanation": "ここは〈残骸〉の意味。遺物は人が残した品で、壊れた機体の破片には合わない。"}, {"text": "駅に届いた財布を、遺物センターに預けた。", "explanation": "ここは〈遺失物〉の意味。遺物は昔の人が残した品で、落とし物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38542, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遺物", "is_correct": true, "explanation": "「遺物は壊れやすい」という文の主語で、昔の人が残した品に合う。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽は耳で聴く芸術で、壊れやすいものとして文が成り立たない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は生き物の生きられる期間を表し、壊れやすい品の説明には合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は眠くなる感覚で、壊れやすいものとしては意味が通らない。"}], "explanations": {"遺物": "「遺物は壊れやすい」という文の主語で、昔の人が残した品に合う。", "音楽": "音楽は耳で聴く芸術で、壊れやすいものとして文が成り立たない。", "寿命": "寿命は生き物の生きられる期間を表し、壊れやすい品の説明には合わない。", "眠気": "眠気は眠くなる感覚で、壊れやすいものとしては意味が通らない。"}, "sentence_index": 6, "correct_answer": "遺物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この池には、小さな遺物がたくさんいる。", "explanation": "ここは〈生き物〉の意味。遺物は昔の人が残した品で、池で暮らす生き物には使わない。"}, {"text": "誕生日に友人から遺物をもらった。", "explanation": "ここは〈贈り物〉の意味。遺物は昔の人が残したもので、誕生日の贈り物には使わない。"}, {"text": "親から子へ、遺物で目の色が伝わる。", "explanation": "ここは〈遺伝〉の意味。遺物は昔の人が残した品で、親から子へ伝わるものには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38542, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寺の住職は、昔の人が残した遺物に、丁寧に保管している。", "corrected_sentence": "寺の住職は、昔の人が残した遺物を、丁寧に保管している。", "error_description": "「保管する」の対象には「を」を使う。「遺物に」は誤りで、「遺物を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38542, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "遺物が見つけた場所は、保存のため封鎖された。", "corrected_sentence": "遺物が見つかった場所は、保存のため封鎖された。", "error_description": "「遺物」が主語のときは自動詞の「見つかる」を使う。「見つけた」は他動詞で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38543, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「遺物は」と、遺物を主題として示す助詞。後ろの「すべて市の資料館に展示されている」と結ぶ。"}, {"text": "を", "is_correct": false, "explanation": "「展示されている」は受身なので、対象を「を」で示す文にはならない。遺物は主題の「は」で示す。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ。後ろに名詞が続かず、文が切れてしまう。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる時の助詞。ここは比較していないので、意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "「遺物は」と、遺物を主題として示す助詞。後ろの「すべて市の資料館に展示されている」と結ぶ。", "を": "「展示されている」は受身なので、対象を「を」で示す文にはならない。遺物は主題の「は」で示す。", "の": "「の」は名詞どうしをつなぐ。後ろに名詞が続かず、文が切れてしまう。", "より": "「より」は比べる時の助詞。ここは比較していないので、意味が通らない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38543, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38543, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "過去の時代に作られた、または残された品や文化のこと。今でも見ることができるもの。", "primary_collocate": null, "pronunciation": "いぶつ", "ipa": "ibɯt͡sɯ", "syllable_count": 3, "sentences": [{"text": "博物館では、縄文時代の遺物を間近で見ることができる。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]では、縄文時代[じょうもんじだい]の遺物[いぶつ]を間近[まぢか]で見[み]ることができる。", "sentence_source": "generated"}, {"text": "この遺跡から出た遺物は、すべて市の資料館に展示されている。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "この遺跡[いせき]から出[で]た遺物[いぶつ]は、すべて市[し]の資料館[しりょうかん]に展示[てんじ]されている。", "sentence_source": "generated"}, {"text": "発掘された遺物を調べて、当時の文化を明らかにする。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "発掘[はっくつ]された遺物[いぶつ]を調[しら]べて、当時[とうじ]の文化[ぶんか]を明[あき]らかにする。", "sentence_source": "generated"}, {"text": "貝塚で見つかった遺物から、昔の人の食べ物がわかった。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "貝塚[かいづか]で見[み]つかった遺物[いぶつ]から、昔[むかし]の人[ひと]の食[た]べ物[もの]がわかった。", "sentence_source": "generated"}, {"text": "展示室には、千五百年前に作られた土器などの遺物が並んでいる。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "展示室[てんじしつ]には、千五百年前[せんごひゃくねんまえ]に作[つく]られた土器[どき]などの遺物[いぶつ]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "世界遺産の町には、中世の文化を伝える遺物が多い。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "世界遺産[せかいいさん]の町[まち]には、中世[ちゅうせい]の文化[ぶんか]を伝[つた]える遺物[いぶつ]が多[おお]い。", "sentence_source": "generated"}, {"text": "遺物の年代は、土の層や使われた材料を調べて決める。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "遺物[いぶつ]の年代[ねんだい]は、土[つち]の層[そう]や使[つか]われた材料[ざいりょう]を調[しら]べて決[き]める。", "sentence_source": "generated"}, {"text": "修学旅行で、古代の遺物が集まる博物館を訪れた。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "修学旅行[しゅうがくりょこう]で、古代[こだい]の遺物[いぶつ]が集[あつ]まる博物館[はくぶつかん]を訪[おとず]れた。", "sentence_source": "generated"}, {"text": "この遺物は、当時の人々の信仰を知る大切な手がかりだ。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "この遺物[いぶつ]は、当時[とうじ]の人々[ひとびと]の信仰[しんこう]を知[し]る大切[たいせつ]な手[て]がかりだ。", "sentence_source": "generated"}, {"text": "考古学者は、出土した遺物を一つずつ洗って記録していく。", "target_word": "遺物", "complexity_tier": "T3", "furigana": "考古学者[こうこがくしゃ]は、出土[しゅつど]した遺物[いぶつ]を一[ひと]つずつ洗[あら]って記録[きろく]していく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "遺物", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "遺物：過去の時代の品や文化を伝え、博物館や遺跡で今も見られるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fa4e591-0cd8-4cce-86d4-2d04b8b274fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38543, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遺物", "is_correct": true, "explanation": "「縄文時代の遺物」は昔の時代に残された品を指し、博物館で間近に見られる文脈に合う。"}, {"text": "料金", "is_correct": false, "explanation": "「縄文時代の料金を間近で見る」は意味をなさない。間近で見られるのは品物で、料金ではない。"}, {"text": "天気", "is_correct": false, "explanation": "「縄文時代の天気を間近で見る」は合わない。天気は間近で見る対象ではない。"}, {"text": "予約", "is_correct": false, "explanation": "「縄文時代の予約を間近で見る」は不自然。予約は見る対象ではなく、取るものだ。"}], "explanations": {"遺物": "「縄文時代の遺物」は昔の時代に残された品を指し、博物館で間近に見られる文脈に合う。", "料金": "「縄文時代の料金を間近で見る」は意味をなさない。間近で見られるのは品物で、料金ではない。", "天気": "「縄文時代の天気を間近で見る」は合わない。天気は間近で見る対象ではない。", "予約": "「縄文時代の予約を間近で見る」は不自然。予約は見る対象ではなく、取るものだ。"}, "sentence_index": 0, "correct_answer": "遺物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父の遺物の遺言状を、弁護士が読み上げた。", "explanation": "ここは〈遺言〉の意味。死後に残す意思を書いた文書は遺言状と言い、〈遺物〉は昔の時代の品を指すので合わない。"}, {"text": "祖父は多額の遺物を残してくれた。", "explanation": "ここは〈遺産〉の意味。財産は遺産と言い、遺物は昔の時代の品を指すので合わない。"}, {"text": "この遺物の周りは、石垣と堀が残る広い場所だ。", "explanation": "ここは〈遺跡〉の意味。土地や建物の跡は遺跡で、遺物は持ち運べる品を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38543, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遺物", "is_correct": true, "explanation": "「遺物の年代」は、土の層などで時代を調べる対象の品を指し、文に合う。"}, {"text": "注文", "is_correct": false, "explanation": "「注文の年代」は意味をなさない。年代を調べるのは古い品で、注文ではない。"}, {"text": "予定", "is_correct": false, "explanation": "「予定の年代」は不自然。予定は未来の計画で、土の層から調べられるものではない。"}, {"text": "順番", "is_correct": false, "explanation": "「順番の年代」は合わない。年代は品物や遺跡の時代を示す語で、順番には使わない。"}], "explanations": {"遺物": "「遺物の年代」は、土の層などで時代を調べる対象の品を指し、文に合う。", "注文": "「注文の年代」は意味をなさない。年代を調べるのは古い品で、注文ではない。", "予定": "「予定の年代」は不自然。予定は未来の計画で、土の層から調べられるものではない。", "順番": "「順番の年代」は合わない。年代は品物や遺跡の時代を示す語で、順番には使わない。"}, "sentence_index": 6, "correct_answer": "遺物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "落とした財布が、駅の遺物センターに届いていた。", "explanation": "ここは〈遺失物〉の意味。落とし物は遺失物と言い、遺物は昔の時代の品を指すので合わない。"}, {"text": "父から遺物として、目の色や髪の質を受け継いだ。", "explanation": "ここは〈遺伝〉の意味。親の体質を子が受け継ぐことは遺伝と言い、〈遺物〉は昔の時代の品を指すので合わない。"}, {"text": "旅行で買った遺物を、今も家に飾っている。", "explanation": "ここは〈記念品〉の意味。旅先で買った品は記念品と言い、遺物は昔の時代の品を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38543, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "発掘で見つかった遺物に、大学の研究室で調べている。", "corrected_sentence": "発掘で見つかった遺物を、大学の研究室で調べている。", "error_description": "「調べる」の対象は「を」で示す。「遺物に」は誤りで、「遺物を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38543, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者は、古い遺物を作って時代を調べる。", "corrected_sentence": "研究者は、古い遺物を発掘して時代を調べる。", "error_description": "遺物は作るものではなく、過去に残ったものを発掘して調べる。「作って」は誤りで、「発掘して」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38544, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「重んじる」は対象を「を」で示す。「知を重んじる」は知を大切にするという意味で正しい。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示す。「知と重んじる」では重んじる対象が示せず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「重んじる」に「に」は使わず、対象は「を」で示す。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「知で重んじる」では対象が示せず不自然。"}], "correct_answer": "を", "explanations": {"を": "「重んじる」は対象を「を」で示す。「知を重んじる」は知を大切にするという意味で正しい。", "と": "「と」は相手や並列を示す。「知と重んじる」では重んじる対象が示せず、文が成り立たない。", "に": "「重んじる」に「に」は使わず、対象は「を」で示す。", "で": "「で」は手段や場所を示すが、「知で重んじる」では対象が示せず不自然。"}, "error_tags": {"と": "並列・共同", "に": "位置・相手", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38544, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「積み重ねる」の対象は「を」で示す。「知を積み重ねてきた」は、知が積み重なる対象として正しい。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示す。「知と積み重ねてきた」では積み重ねる対象が示せず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう先を示す。「知へ積み重ねる」では積み重ねる対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる時の助詞。「知より積み重ねてきた」は比較にならず、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「積み重ねる」の対象は「を」で示す。「知を積み重ねてきた」は、知が積み重なる対象として正しい。", "と": "「と」は相手や並列を示す。「知と積み重ねてきた」では積み重ねる対象が示せず、文が成り立たない。", "へ": "「へ」は向かう先を示す。「知へ積み重ねる」では積み重ねる対象にならない。", "より": "「より」は比べる時の助詞。「知より積み重ねてきた」は比較にならず、意味が通らない。"}, "error_tags": {"と": "並列・共同", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38544, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをわかっていること。", "primary_collocate": null, "pronunciation": "ち", "ipa": "t͡ɕi", "syllable_count": 1, "sentences": [{"text": "人間の心のはたらきは、知・情・意の三つに分けて考えられてきた。", "target_word": "知", "complexity_tier": "T3", "furigana": "人間[にんげん]の心[こころ]のはたらきは、知[ち]・情[じょう]・意[い]の三[みっ]つに分[わ]けて考[かんが]えられてきた。", "sentence_source": "generated"}, {"text": "彼は知を重んじる人で、感情に流されず、物事をよく考えて決める。", "target_word": "知", "complexity_tier": "T3", "furigana": "彼[かれ]は知[ち]を重[おも]んじる人[ひと]で、感情[かんじょう]に流[なが]されず、物事[ものごと]をよく考[かんが]えて決[き]める。", "sentence_source": "generated"}, {"text": "古代ギリシャでは、知を愛することが哲学の始まりだとされた。", "target_word": "知", "complexity_tier": "T3", "furigana": "古代[こだい]ギリシャでは、知[ち]を愛[あい]することが哲学[てつがく]の始[はじ]まりだとされた。", "sentence_source": "generated"}, {"text": "学ぶとは、知を働かせて物事の筋道を見きわめていくことだ。", "target_word": "知", "complexity_tier": "T3", "furigana": "学[まな]ぶとは、知[ち]を働[はたら]かせて物事[ものごと]の筋道[すじみち]を見[み]きわめていくことだ。", "sentence_source": "generated"}, {"text": "知は人を自由にするという言葉を、先生はよく口にした。", "target_word": "知", "complexity_tier": "T3", "furigana": "知[ち]は人[ひと]を自由[じゆう]にするという言葉[ことば]を、先生[せんせい]はよく口[くち]にした。", "sentence_source": "generated"}, {"text": "知を求める気持ちが強い子で、わからないことは必ず調べる。", "target_word": "知", "complexity_tier": "T3", "furigana": "知[ち]を求[もと]める気持[きも]ちが強[つよ]い子[こ]で、わからないことは必[かなら]ず調[しら]べる。", "sentence_source": "generated"}, {"text": "知と行いが一致しなければ、本当にわかったとは言えない。", "target_word": "知", "complexity_tier": "T3", "furigana": "知[ち]と行[おこな]いが一致[いっち]しなければ、本当[ほんとう]にわかったとは言[い]えない。", "sentence_source": "generated"}, {"text": "長い歴史の中で、人類はさまざまな知を積み重ねてきた。", "target_word": "知", "complexity_tier": "T3", "furigana": "長[なが]い歴史[れきし]の中[なか]で、人類[じんるい]はさまざまな知[ち]を積[つ]み重[かさ]ねてきた。", "sentence_source": "generated"}, {"text": "図書館は、町の人々が知にふれるための大切な場所だ。", "target_word": "知", "complexity_tier": "T3", "furigana": "図書館[としょかん]は、町[まち]の人々[ひとびと]が知[ち]にふれるための大切[たいせつ]な場所[ばしょ]だ。", "sentence_source": "generated"}, {"text": "彼女は知と情のバランスがとれた、信頼できるリーダーだ。", "target_word": "知", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は知[ち]と情[じょう]のバランスがとれた、信頼[しんらい]できるリーダーだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "知", "label": "基本形"}], "register": "formal", "sense_fingerprint": "知：物事をわかっているという心のはたらき。知・情・意の「知」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T3: contains vocabulary far above tier T3: 見きわめ (Zipf 1.43)']::text[], '0fa4e591-0cd8-4cce-86d4-2d04b8b274fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38544, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "知", "is_correct": true, "explanation": "「知・情・意」は心のはたらきの三分類で、「知」は物事をわかる働きを指すので文に合う。"}, {"text": "数", "is_correct": false, "explanation": "「数・情・意」は心のはたらきの分類として意味をなさず、文に合わない。"}, {"text": "速さ", "is_correct": false, "explanation": "「速さ・情・意」は心のはたらきの分類にならず、文の流れに合わない。"}, {"text": "地図", "is_correct": false, "explanation": "「地図・情・意」は心のはたらきの分類として不自然で、文に合わない。"}], "explanations": {"知": "「知・情・意」は心のはたらきの三分類で、「知」は物事をわかる働きを指すので文に合う。", "数": "「数・情・意」は心のはたらきの分類として意味をなさず、文に合わない。", "速さ": "「速さ・情・意」は心のはたらきの分類にならず、文の流れに合わない。", "地図": "「地図・情・意」は心のはたらきの分類として不自然で、文に合わない。"}, "sentence_index": 0, "correct_answer": "知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は怒りの知がこみ上げ、声を荒げた。", "explanation": "ここは〈感情〉の意味。怒りなどの気持ちは感情と言い、〈知〉は物事をわかる働きを指すので合わない。"}, {"text": "職人の手の知が見事で、器の仕上がりに皆が驚いた。", "explanation": "ここは〈技術〉の意味。手わざの確かさは技術と言い、〈知〉は物事をわかる働きを指すので合わない。"}, {"text": "昨日、知の結婚式に出席した。", "explanation": "ここは〈知人〉の意味。顔見知りの人は知人と言い、〈知〉は物事をわかる働きを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38544, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "知", "is_correct": true, "explanation": "「知と行い」は、わかることと実際に行うことを対比する文脈に合う。"}, {"text": "色", "is_correct": false, "explanation": "「色と行いが一致」は意味が通らず、一致させるものとして不自然。"}, {"text": "熱", "is_correct": false, "explanation": "「熱と行いが一致」は意味が通らず、文に合わない。"}, {"text": "体重", "is_correct": false, "explanation": "「体重と行い」は、わかったかどうかを言う文脈に合わない。"}], "explanations": {"知": "「知と行い」は、わかることと実際に行うことを対比する文脈に合う。", "色": "「色と行いが一致」は意味が通らず、一致させるものとして不自然。", "熱": "「熱と行いが一致」は意味が通らず、文に合わない。", "体重": "「体重と行い」は、わかったかどうかを言う文脈に合わない。"}, "sentence_index": 6, "correct_answer": "知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "転んでひざを切り、知が止まらなかった。", "explanation": "ここは〈血〉の意味。同じ「ち」の読みで、けがから出るのは血。〈知〉は理解の働きを指すので合わない。"}, {"text": "しびれて、足の知が鈍くなった。", "explanation": "ここは〈感覚〉の意味。身体で感じる働きは感覚と言い、〈知〉は理解の働きを指すので合わない。"}, {"text": "風邪をひいて、知が三十九度まで上がった。", "explanation": "ここは〈体温〉の意味。熱の高さは体温で表し、〈知〉は理解の働きを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38544, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼の知な判断が、チームを救った。", "corrected_sentence": "彼の知的な判断が、チームを救った。", "error_description": "「知」は名詞なので、形容動詞のように「知な」とは言えない。「知的な」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38544, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は議論を通じて知を破り、相手の考えを理解した。", "corrected_sentence": "彼女は議論を通じて知を深め、相手の考えを理解した。", "error_description": "「知」は深めるものであり、「破る」は誤り。「知を深め」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38545, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「現場の知が強みだ」の「が」で、知を主語として示す。文として成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「強みだ」は判断の文で、「を」は使えない。知は主語として「が」で示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は「～になる」などに使うが、ここは「強みだ」と述べる文なので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる時の助詞。ここは比べていないので、「知より強みだ」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「現場の知が強みだ」の「が」で、知を主語として示す。文として成り立つ。", "を": "「強みだ」は判断の文で、「を」は使えない。知は主語として「が」で示す。", "に": "「に」は「～になる」などに使うが、ここは「強みだ」と述べる文なので合わない。", "より": "「より」は比べる時の助詞。ここは比べていないので、「知より強みだ」は意味が通らない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38545, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「役立つ知は少ない」の「は」で、知を主題として示す。文として成り立つ。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。「役立つ知で少ない」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示す。「知と少ない」では主題が示せず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう先を示す。「知へ少ない」は意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "「役立つ知は少ない」の「は」で、知を主題として示す。文として成り立つ。", "で": "「で」は手段や場所を示す。「役立つ知で少ない」は意味が通らない。", "と": "「と」は相手や並列を示す。「知と少ない」では主題が示せず、文が成り立たない。", "へ": "「へ」は向かう先を示す。「知へ少ない」は意味が通らない。"}, "error_tags": {"で": "手段", "と": "並列・共同", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38545, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事について、人や集団がすでに持っている理解・情報・経験にもとづく知見。", "primary_collocate": null, "pronunciation": "ち", "ipa": "t͡ɕi", "syllable_count": 1, "sentences": [{"text": "医師たちは専門の知を持ち寄り、むずかしい病気の治療法を考えた。", "target_word": "知", "complexity_tier": "T3", "furigana": "医師[いし]たちは専門[せんもん]の知[ち]を持[も]ち寄[よ]り、むずかしい病気[びょうき]の治療法[ちりょうほう]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "長年の経験で得た現場の知が、この会社の大きな強みだ。", "target_word": "知", "complexity_tier": "T3", "furigana": "長年[ながねん]の経験[けいけん]で得[え]た現場[げんば]の知[ち]が、この会社[かいしゃ]の大[おお]きな強[つよ]みだ。", "sentence_source": "generated"}, {"text": "研究者は自分の知を惜しまず、若い人たちに教えている。", "target_word": "知", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は自分[じぶん]の知[ち]を惜[お]しまず、若[わか]い人[ひと]たちに教[おし]えている。", "sentence_source": "generated"}, {"text": "災害の時には、地域の人々の知を集めて対策を立てる。", "target_word": "知", "complexity_tier": "T3", "furigana": "災害[さいがい]の時[とき]には、地域[ちいき]の人々[ひとびと]の知[ち]を集[あつ]めて対策[たいさく]を立[た]てる。", "sentence_source": "generated"}, {"text": "祖母の知は本には書かれておらず、暮らしの中で受け継がれてきた。", "target_word": "知", "complexity_tier": "T3", "furigana": "祖母[そぼ]の知[ち]は本[ほん]には書[か]かれておらず、暮[く]らしの中[なか]で受[う]け継[つ]がれてきた。", "sentence_source": "generated"}, {"text": "チーム全員の知を結集して、新しい製品を完成させた。", "target_word": "知", "complexity_tier": "T3", "furigana": "チーム全員[ぜんいん]の知[ち]を結集[けっしゅう]して、新[あたら]しい製品[せいひん]を完成[かんせい]させた。", "sentence_source": "generated"}, {"text": "大学は、社会に新しい知を生み出す場所でもある。", "target_word": "知", "complexity_tier": "T3", "furigana": "大学[だいがく]は、社会[しゃかい]に新[あたら]しい知[ち]を生[う]み出[だ]す場所[ばしょ]でもある。", "sentence_source": "generated"}, {"text": "ネットの情報が増えても、本当に役立つ知は少ないと彼は言う。", "target_word": "知", "complexity_tier": "T3", "furigana": "ネットの情報[じょうほう]が増[ふ]えても、本当[ほんとう]に役立[やくだ]つ知[ち]は少[すく]ないと彼[かれ]は言[い]う。", "sentence_source": "generated"}, {"text": "農業に関する知を持つ人が、村の若者に育て方を教えている。", "target_word": "知", "complexity_tier": "T3", "furigana": "農業[のうぎょう]に関[かん]する知[ち]を持[も]つ人[ひと]が、村[むら]の若者[わかもの]に育[そだ]て方[かた]を教[おし]えている。", "sentence_source": "generated"}, {"text": "博物館で、昔の漁師が持っていた海の知を学んだ。", "target_word": "知", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]で、昔[むかし]の漁師[りょうし]が持[も]っていた海[うみ]の知[ち]を学[まな]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "知", "label": "基本形"}], "register": "formal", "sense_fingerprint": "知：人や集団が持っている理解・情報・経験にもとづく知見", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fa4e591-0cd8-4cce-86d4-2d04b8b274fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38545, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "知", "is_correct": true, "explanation": "「専門の知」は専門家が持つ理解や情報を指し、持ち寄る対象として合う。"}, {"text": "天気", "is_correct": false, "explanation": "「専門の天気を持ち寄り」は意味をなさない。持ち寄れるのは理解や情報で、天気ではない。"}, {"text": "予約", "is_correct": false, "explanation": "予約は持ち寄るものではなく、「専門の予約を持ち寄る」は不自然。"}, {"text": "料金", "is_correct": false, "explanation": "料金は治療法を考える文脈で持ち寄る対象にならず、文に合わない。"}], "explanations": {"知": "「専門の知」は専門家が持つ理解や情報を指し、持ち寄る対象として合う。", "天気": "「専門の天気を持ち寄り」は意味をなさない。持ち寄れるのは理解や情報で、天気ではない。", "予約": "予約は持ち寄るものではなく、「専門の予約を持ち寄る」は不自然。", "料金": "料金は治療法を考える文脈で持ち寄る対象にならず、文に合わない。"}, "sentence_index": 0, "correct_answer": "知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "包丁で指を切り、知がにじんだ。", "explanation": "ここは〈血〉の意味。同じ「ち」の読みで、けがからにじむのは血。〈知〉は理解や情報を指すので合わない。"}, {"text": "旅先で、きれいな知を撮った。", "explanation": "ここは〈写真〉の意味。景色は写真に撮るもので、〈知〉は撮れる物ではないので合わない。"}, {"text": "毎月、家賃の知を払っている。", "explanation": "ここは〈家賃〉の意味。部屋代は家賃として払うもので、〈知〉は持っている理解や情報を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38545, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "知", "is_correct": true, "explanation": "「新しい知を生み出す」は、研究などで新しい理解や情報を作ることを指し、文に合う。"}, {"text": "切符", "is_correct": false, "explanation": "「新しい切符を生み出す」は意味をなさない。切符は作り出す対象として不自然。"}, {"text": "体温", "is_correct": false, "explanation": "「新しい体温を生み出す」は意味をなさない。体温は生み出すものではない。"}, {"text": "天井", "is_correct": false, "explanation": "「新しい天井を生み出す」は不自然で、文の流れに合わない。"}], "explanations": {"知": "「新しい知を生み出す」は、研究などで新しい理解や情報を作ることを指し、文に合う。", "切符": "「新しい切符を生み出す」は意味をなさない。切符は作り出す対象として不自然。", "体温": "「新しい体温を生み出す」は意味をなさない。体温は生み出すものではない。", "天井": "「新しい天井を生み出す」は不自然で、文の流れに合わない。"}, "sentence_index": 6, "correct_answer": "知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅先から、家族に知を書いて送った。", "explanation": "ここは〈手紙〉の意味。文章に書いて送るのは手紙で、〈知〉は理解や情報を指すので合わない。"}, {"text": "駅で、東京行きの知を買った。", "explanation": "ここは〈切符〉の意味。乗るために買うのは切符で、〈知〉は理解や情報を指すので合わない。"}, {"text": "夕食に、焼き魚の知を作った。", "explanation": "ここは〈料理〉の意味。作って食べるのは料理で、〈知〉は理解や情報を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38545, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は長年の経験で得た知に現場で生かしている。", "corrected_sentence": "彼女は長年の経験で得た知を現場で生かしている。", "error_description": "「生かす」の対象は「を」で示す。「知に」は誤りで、「知を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38545, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "農家の人が、村の知を食べて、畑を守っている。", "corrected_sentence": "農家の人が、村の知を受け継いで、畑を守っている。", "error_description": "「知」は食べるものではなく、受け継ぐものである。「食べて」は誤りで、「受け継いで」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33462ef1-3feb-4205-9f14-a4371460f587') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
